11	const baseVersion = rootManifest.pnpm?.overrides?.['@deepseek-ai/dsh-base'];
12	const webAppVersion = rootManifest.pnpm?.overrides?.['@deepseek-ai/dsh-web-app'];
13	if (typeof baseVersion !== 'string') throw new Error('Missing pinned @deepseek-ai/dsh-base version in package.json pnpm.overrides.');
14	if (typeof webAppVersion !== 'string') throw new Error('Missing pinned @deepseek-ai/dsh-web-app version in package.json pnpm.overrides.');
15	const baseSpec = `@deepseek-ai/dsh-base@${baseVersion}`;
16	const webAppSpec = `@deepseek-ai/dsh-web-app@${webAppVersion}`;
17	const home = resolve(process.env.WORKDSH_PREVIEW_HOME ?? join(root, '.test-runtime/preview'));
18	const artifacts = join(root, '.artifacts');
19	const env = { ...process.env, DSH_HOME: home, PATH: `${join(root, 'node_modules/.bin')}:${dirname(process.execPath)}:${process.env.PATH}` };
20	const exec = promisify(execFile);
21	const run = async (tool, args) => {
22	  await exec(process.execPath, [join(root, 'node_modules', tool), ...args], { cwd: root, env, timeout: 60_000, maxBuffer: 8 * 1024 * 1024 });
23	};
24	await mkdir(home, { recursive: true }); await mkdir(artifacts, { recursive: true });
25	const tarballs = [];
26	const packages = [];
27	for (const directory of ['packages/providers/identity-local', 'packages/plugins/audit', 'packages/plugins/access', 'packages/plugins/skills', 'packages/plugins/experts', 'packages/plugins/connectors', 'packages/plugins/office', 'packages/plugins/activity', 'packages/bundle']) {
28	  const manifest = JSON.parse(await readFile(join(root, directory, 'package.json'), 'utf8'));
29	  await access(join(root, directory, manifest.exports['.'].default));
30	  await run('pnpm/bin/pnpm.cjs', ['--filter', manifest.name, 'pack', '--pack-destination', artifacts]);
31	  const packed = join(artifacts, `${manifest.name}-${manifest.version}.tgz`);
32	  // Preview candidates can change before their next release. A stable file:
33	  // address lets the package manager reuse an older archive, even after pack.
34	  // Keep official CLI installation, but address each archive by its content.
35	  const digest = createHash('sha256').update(await readFile(packed)).digest('hex');
36	  const destination = join(artifacts, 'preview', digest);
37	  await mkdir(destination, { recursive: true });
38	  const immutableArchive = join(destination, `${manifest.name}-${manifest.version}.tgz`);
39	  await copyFile(packed, immutableArchive);
40	  tarballs.push(immutableArchive);
41	  packages.push({ directory, manifest });
42	}
43	let initialized = false;
44	try { await access(join(home, 'profiles/preview/package.json')); initialized = true; }
45	catch (error) { if (error.code !== 'ENOENT') throw error; }
46	if (!initialized) await run('@deepseek-ai/dsh/lib/bin.js', ['--profile', 'preview', '--from-default-profile', 'web', '--dump-config']);
47	// Reinstall the pinned official Web bundle as well as the WorkDSH layers. An
48	// existing preview Profile may have been created by an older DSH release; its
49	// bundle list alone does not upgrade the packages that provide newly added Web
50	// surfaces such as Terminal and archived-session recovery.
51	await run('@deepseek-ai/dsh/lib/bin.js', ['plugin', '--profile', 'preview', 'add', baseSpec, webAppSpec, ...tarballs]);
52	const installedBase = JSON.parse(await readFile(join(home, 'profiles/preview/node_modules/@deepseek-ai/dsh-base/package.json'), 'utf8'));
53	if (installedBase.version !== baseVersion) throw new Error(`Installed @deepseek-ai/dsh-base ${installedBase.version} does not match pinned ${baseVersion}.`);
54	const installedWebApp = JSON.parse(await readFile(join(home, 'profiles/preview/node_modules/@deepseek-ai/dsh-web-app/package.json'), 'utf8'));
55	if (installedWebApp.version !== webAppVersion) throw new Error(`Installed @deepseek-ai/dsh-web-app ${installedWebApp.version} does not match pinned ${webAppVersion}.`);
56	// DSH 0.1.6 scopes are module-instance local. Installing only the Web bundle
57	// beside a CLI-provided Base bundle can load two physical dsh-scope copies: the
58	// Agent Loop tags one copy while Agent Presets reads the other, so every new
59	// session fails as an "unscoped context". Resolve both consumers from the
60	// Profile and fail installation unless they share the exact same module file.
61	const profileRequire = createRequire(join(home, 'profiles/preview/package.json'));
62	const resolveProfileDependency = async (consumer, dependency) => {
63	  const consumerManifest = profileRequire.resolve(`${consumer}/package.json`);
64	  const consumerRequire = createRequire(consumerManifest);
65	  return realpath(consumerRequire.resolve(`${dependency}/package.json`));
66	};
67	const loopScope = await resolveProfileDependency('@deepseek-ai/dsh-agent-loop', '@deepseek-ai/dsh-scope');
68	const presetScope = await resolveProfileDependency('@deepseek-ai/dsh-agent-presets', '@deepseek-ai/dsh-scope');
69	if (loopScope !== presetScope) throw new Error(`Preview loaded split @deepseek-ai/dsh-scope instances: agent-loop=${loopScope}; agent-presets=${presetScope}.`);
70	for (const { directory, manifest } of packages) {
71	  for (const face of ['.', './client']) {
72	    const entry = manifest.exports[face]?.default;
73	    if (!entry) continue;
74	    const expected = await readFile(join(root, directory, entry));
75	    const installed = await readFile(join(home, 'profiles/preview/node_modules', manifest.name, entry));
76	    if (!expected.equals(installed)) throw new Error(`Installed ${manifest.name} ${face} differs from the current build; refusing to report a successful preview update.`);
77	  }
78	}
