53	if (installedBase.version !== baseVersion) throw new Error(`Installed @deepseek-ai/dsh-base ${installedBase.version} does not match pinned ${baseVersion}.`);
54	const installedWebApp = JSON.parse(await readFile(join(home, 'profiles/preview/node_modules/@deepseek-ai/dsh-web-app/package.json'), 'utf8'));
55	if (installedWebApp.version !== webAppVersion) throw new Error(`Installed @deepseek-ai/dsh-web-app ${installedWebApp.version} does not match pinned ${webAppVersion}.`);
56	// DSH 0.1.6 scopes are module-instance local. Installing only the Web bundle
57	// beside a CLI-provided Base bundle can load two physical dsh-scope copies: the
58	// Agent Loop tags one copy while Agent Presets reads the other, so every new
59	// session fails as an "unscoped context". Resolve both consumers from the
60	// Profile and fail installation unless they share the exact same module file.
61	const profileRequire = createRequire(join(home, 'profiles/preview/package.json'));
62	const resolveProfileDependency = async (consumer, dependency) => {
63	  const consumerManifest = profileRequire.resolve(`${consumer}/package.json`);
64	  const consumerRequire = createRequire(consumerManifest);
65	  return realpath(consumerRequire.resolve(`${dependency}/package.json`));
66	};
67	const loopScope = await resolveProfileDependency('@deepseek-ai/dsh-agent-loop', '@deepseek-ai/dsh-scope');
68	const presetScope = await resolveProfileDependency('@deepseek-ai/dsh-agent-presets', '@deepseek-ai/dsh-scope');
69	if (loopScope !== presetScope) throw new Error(`Preview loaded split @deepseek-ai/dsh-scope instances: agent-loop=${loopScope}; agent-presets=${presetScope}.`);
70	for (const { directory, manifest } of packages) {
71	  for (const face of ['.', './client']) {
72	    const entry = manifest.exports[face]?.default;
73	    if (!entry) continue;
74	    const expected = await readFile(join(root, directory, entry));
75	    const installed = await readFile(join(home, 'profiles/preview/node_modules', manifest.name, entry));
76	    if (!expected.equals(installed)) throw new Error(`Installed ${manifest.name} ${face} differs from the current build; refusing to report a successful preview update.`);
77	  }
78	}
79	console.log('Installed Skill, Expert, Connector, Office and WorkDSH presentation as separate official Profile layers.');
80	console.log('Start the stopped preview with: corepack pnpm preview');

