1	/**
2	 * MCP连接器 —— web 半区：为图形化「插件市场」提供 HTTP 路由。
3	 *
4	 * 挂载到 ctx.webServer 的同源前缀：
5	 *   - GET  /mcp-connector/ui/*   静态 SPA（单页市场：市场 / 已安装 / 安装 / 卸载）
6	 *   - POST /mcp-connector/api    JSON-RPC 风格调度（method 白名单 → api 门面）
7	 *   - GET  /mcp-connector/events 无敏感数据的实时状态 SSE
8	 *
9	 * 所有路由都过浏览器信任 fence（loopback + 同源），与 better-sidebar 同一策略。
10	 * 本模块只依赖 ctx.webServer / ctx.webRuntime；在非 web 部署（无这两个服务）时
11	 * 调用方应跳过挂载，保证插件仍可用于纯对话工具场景。
12	 */
13	import { dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';
14	import { readFile } from 'node:fs/promises';
15	import { fileURLToPath } from 'node:url';
16	
17	const UI_DIR = join(dirname(fileURLToPath(import.meta.url)), '..', 'ui');
18	
19	/** GET /mcp-connector/api 允许调度的方法 → api 门面（白名单，杜绝任意反射调用）。 */
20	const API_WHITELIST = new Map([
21	  ['versionStatus', (api, p) => api.versionStatus(p?.force === true)],
22	  ['governance', (api) => api.governance()],
23	  ['previewPolicy', (api, p) => api.previewPolicy(p ?? {})],
24	  ['applyPolicy', (api, p) => api.applyPolicy(p ?? {})],
25	  ['rollbackPolicy', (api, p) => api.rollbackPolicy(p?.rollbackRevision, p?.expectedRevision)],
26	  ['scopeContext', (api, p) => api.scopeContext(p?.workspaceId)],
27	  ['previewConnectionScope', (api, p) => api.previewConnectionScope(p ?? {})],
28	  ['applyConnectionScope', (api, p) => api.applyConnectionScope(p ?? {})],
29	  ['previewConnectionScopeRollback', (api, p) => api.previewConnectionScopeRollback(p?.rollbackRevision)],
30	  ['rollbackConnectionScope', (api, p) => api.rollbackConnectionScope(p?.rollbackRevision, p?.expectedRevision)],
31	  ['catalog', (api, p) => api.catalog(p ?? {})],
32	  ['status', (api, p) => api.status(p ?? {})],
33	  ['healthCheck', (api, p) => api.healthCheck(p?.connectorId)],
34	  ['migrationPreview', (api, p) => api.migrationPreview(p ?? {})],
35	  ['migrateLegacy', (api, p) => api.migrateLegacy(p?.candidateIds ?? [])],
36	  ['connect', (api, p) => api.connect(p?.connectorId, p?.serverKey, undefined, p ?? {})],
37	  ['configure', (api, p) => api.configure(p ?? {})],
38	  ['importJson', (api, p) => api.importJson(p?.json, p ?? {})],
39	  ['exportConfig', (api) => api.exportConfig()],
40	  ['listSnapshots', (api) => api.listSnapshots()],
41	  ['createSnapshot', (api, p) => api.createSnapshot(p?.label)],
42	  ['previewSnapshot', (api, p) => api.previewSnapshot(p?.snapshotId)],
43	  ['restoreSnapshot', (api, p) => api.restoreSnapshot(p?.snapshotId)],
44	  ['installFromUrl', (api, p) => api.installFromUrl(p?.url, p ?? {})],
45	  ['renameConnection', (api, p) => api.renameConnection(p?.key, p?.name)],
46	  ['editableConnectionConfig', (api, p) => api.editableConnectionConfig(p?.key)],
47	  ['reconfigureConnection', (api, p) => api.reconfigureConnection(p?.key, p?.json)],
48	  ['disconnect', (api, p) => api.disconnect(p?.key)],
49	  ['setEnabled', (api, p) => api.setEnabled(p?.key, p?.enabled !== false)],
50	  ['refreshCatalog', (api) => api.refreshCatalog()],
51	  ['toolsList', (api, p) => api.toolsList(p?.connectorId, p?.workspaceId, p?.cachedOnly === true, p?.connectionKey)],
52	  ['toolSearch', (api, p) => api.toolSearch(p ?? {})],
53	  ['toolExplorer', (api, p) => api.toolExplorer(p ?? {})],
54	  ['toolExplorerDetail', (api, p) => api.toolExplorerDetail(p ?? {})],
55	  ['toolExplorerAction', (api, p) => api.toolExplorerAction(p ?? {})],
56	  ['toolDetail', (api, p) => api.toolDetail(p ?? {})],
57	]);
58	
59	/* ───────────────────────── 信任 fence ───────────────────────── */
60	
61	function header(headers, name) {
62	  const value = headers?.[name];
63	  if (Array.isArray(value)) return value[0];
64	  return value;
65	}
66	
67	function parseAuthority(host) {
68	  if (typeof host !== 'string' || host.length === 0) return undefined;
69	  try {
70	    const u = new URL(`http://${host}`);
71	    if (!u.hostname) return undefined;
72	    return { hostname: u.hostname, host: u.host, port: u.port };
73	  } catch {
74	    return undefined;
75	  }
76	}
77	
78	function isLoopbackHostname(hostname) {
79	  return (
80	    hostname === 'localhost' ||
81	    hostname === '127.0.0.1' ||
82	    hostname === '::1' ||
83	    hostname === '0:0:0:0:0:0:0:1' ||
84	    hostname.endsWith('.localhost')
85	  );
86	}
87	
88	function isTrustedAuthority(url, trustedHosts) {
89	  for (const raw of trustedHosts ?? []) {
90	    const authority = typeof raw === 'string' ? parseAuthority(raw) : undefined;
91	    if (authority && authority.host === url.host) return true;
92	  }
93	  return false;
94	}
95	
96	/**
97	 * 浏览器信任 fence：Host 必须是本机回环或部署声明的可信域，且请求非跨站、Origin 与 Host 同源。
98	 */
99	export function isTrustedWebRequest(request, trustedHosts = []) {
100	  const host = header(request.headers, 'host');
101	  if (host === undefined) return false;
102	  const hostUrl = parseAuthority(host);
103	  if (hostUrl === undefined) return false;
104	  if (!isLoopbackHostname(hostUrl.hostname) && !isTrustedAuthority(hostUrl, trustedHosts)) return false;
105	  if (header(request.headers, 'sec-fetch-site') === 'cross-site') return false;
106	  const origin = header(request.headers, 'origin');
107	  if (origin === undefined) return true;
108	  try {
109	    return new URL(origin).host === hostUrl.host;
110	  } catch {
111	    return false;
112	  }
113	}
114	
115	/* ───────────────────────── 小工具 ───────────────────────── */
116	
117	function writeJson(res, status, value) {
118	  const body = JSON.stringify(value);
119	  res.writeHead(status, {
120	    'content-type': 'application/json; charset=utf-8',
121	    'cache-control': 'no-store',
122	    'x-content-type-options': 'nosniff',
123	    'referrer-policy': 'no-referrer',
124	    'content-length': Buffer.byteLength(body),
125	  });
126	  res.end(body);
127	}
128	
129	async function readJsonBody(req) {
130	  const chunks = [];
131	  let length = 0;
132	  for await (const chunk of req) {
133	    length += chunk.length;
134	    if (length > 1024 * 1024) throw new Error('请求体不能超过 1 MiB');
135	    chunks.push(chunk);
136	  }
137	  const text = Buffer.concat(chunks).toString('utf8');
138	  if (!text.trim()) return {};
139	  return JSON.parse(text);
140	}
141	
142	const MIME = {
143	  '.html': 'text/html; charset=utf-8',
144	  '.js': 'text/javascript; charset=utf-8',
145	  '.css': 'text/css; charset=utf-8',
146	  '.json': 'application/json; charset=utf-8',
147	  '.svg': 'image/svg+xml',
148	  '.png': 'image/png',
149	  '.ico': 'image/x-icon',
150	};
151	
152	function extOf(pathname) {
153	  const i = pathname.lastIndexOf('.');
154	  return i >= 0 ? pathname.slice(i).toLowerCase() : '';
155	}
156	
157	/** 把 URL pathname 安全地映射到 ui 目录内的文件（防目录穿越）。 */
158	export function splitUiPath(pathname) {
159	  let decoded;
160	  try {
161	    decoded = decodeURIComponent(pathname);
162	  } catch {
163	    return undefined;
164	  }
165	  const segments = decoded.replace(/\\/g, '/').split('/').filter((segment) => segment !== '' && segment !== '.');
166	  if (segments.includes('..')) return undefined;
167	  return segments;
168	}
169	
170	export function resolveUiFile(pathname) {
171	  const segments = splitUiPath(pathname);
172	  if (segments === undefined) return { ok: false };
173	  if (segments.length === 0) return { ok: true, path: join(UI_DIR, 'index.html'), rel: 'index.html' };
