1	import * as React from 'react';
2	import { useCallback, useEffect, useState } from 'react';
3	import type { InjectFace, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots';
4	import { Icon, Modal } from 'workdsh-ui';
5	import type { ConnectorConfigView, ConnectorInput, ConnectorSummary } from '../shared.js';
6	import type { ConnectorManagementClient } from './management.js';
7	import { connectorCss } from './styles.js';
8	
9	type Injected = { toggleNavigation: () => void; management: ConnectorManagementClient; openCapability: (key: string) => void; hasCapability: (key: string) => boolean };
10	type Props = PropsRuntime<'main'> & InjectFace<Injected>;
11	type Draft = { id?: string; title: string; description: string; serverName: string; transport: 'stdio' | 'streamable-http'; command: string; argsText: string; url: string; authorizationToken: string; authorizationConfigured: boolean };
12	const blank = (): Draft => ({ title: '', description: '', serverName: '', transport: 'stdio', command: '', argsText: '', url: '', authorizationToken: '', authorizationConfigured: false });
13	const labels = { ready: '已连接', discovering: '正在连接', offline: '连接异常', disabled: '已停用' } as const;
14	const fromConfig = (row: ConnectorConfigView): Draft => ({ id: row.id, title: row.title, description: row.description, serverName: row.serverName, transport: row.transport, command: row.command ?? '', argsText: (row.args ?? []).join('\n'), url: row.url ?? '', authorizationToken: '', authorizationConfigured: row.authorizationConfigured });
15	
16	export function ConnectorsPanel({ toggleNavigation, management, openCapability, hasCapability }: Props) {
17	  const [rows, setRows] = useState<readonly ConnectorSummary[]>([]); const [query, setQuery] = useState('');
18	  const [busy, setBusy] = useState(true); const [error, setError] = useState(''); const [expanded, setExpanded] = useState<string>();
19	  const [draft, setDraft] = useState<Draft>(); const [removeTarget, setRemoveTarget] = useState<ConnectorSummary>();
20	  const refresh = useCallback(async () => { setBusy(true); setError(''); try { setRows(await management.list()); } catch (cause) { setError(cause instanceof Error ? cause.message : '读取连接器失败。'); } finally { setBusy(false); } }, [management]);
21	  useEffect(() => { void refresh(); }, [refresh]);
22	  const toggle = async (row: ConnectorSummary, enabled: boolean) => { setBusy(true); setError(''); try { await management.setEnabled(row.id, enabled); await refresh(); } catch (cause) { setError(cause instanceof Error ? cause.message : '连接器启停失败。'); setBusy(false); } };
23	  const edit = async (id: string) => { setError(''); try { setDraft(fromConfig(await management.config(id))); } catch (cause) { setError(cause instanceof Error ? cause.message : '无法读取 MCP 配置。'); } };
24	  const save = async () => {
25	    if (!draft) return; setBusy(true); setError('');
26	    const input: ConnectorInput = { title: draft.title, description: draft.description, serverName: draft.serverName, transport: draft.transport,
27	      ...(draft.transport === 'stdio' ? { command: draft.command, args: draft.argsText.split('\n').map(value => value.trim()).filter(Boolean) } : { url: draft.url, ...(draft.authorizationToken.trim() ? { authorizationToken: draft.authorizationToken } : {}) }) };
28	    try { if (draft.id) await management.update(draft.id, input); else await management.create(input); setDraft(undefined); await refresh(); }
29	    catch (cause) { setError(cause instanceof Error ? cause.message : '保存连接器失败。'); setBusy(false); }
30	  };
31	  const remove = async () => { if (!removeTarget) return; setBusy(true); setError(''); try { await management.remove(removeTarget.id); setRemoveTarget(undefined); await refresh(); } catch (cause) { setError(cause instanceof Error ? cause.message : '删除连接器失败。'); setBusy(false); } };
32	  const normalized = query.trim().toLowerCase(); const filtered = rows.filter(row => `${row.title} ${row.description} ${row.serverName} ${row.toolNames.join(' ')}`.toLowerCase().includes(normalized));
33	  const detail = rows.find(row => row.id === expanded);
34	  const capabilityTabs = [['experts', '专家'], ['skills', '技能'], ['connectors', '连接器'], ['apps', '行业应用']] as const;
35	  const capabilityKey: Record<string, string> = { experts: 'workdsh-experts', skills: 'workdsh-skills', connectors: 'workdsh-connectors' };
36	  return <section className="wd-connectors" data-testid="workdsh-connectors"><style>{connectorCss}</style>
37	    <header className="cap-header"><button className="nav-toggle" onClick={toggleNavigation} aria-label="切换导航">导航</button>
38	      {capabilityTabs.map(([key, label]) => { const active = key === 'connectors'; const target = capabilityKey[key]; const enabled = active || Boolean(target && hasCapability(target)); return <button key={key} className={`cap-tab ${active ? 'active' : ''}`} disabled={!enabled} aria-current={active ? 'page' : undefined} onClick={() => { if (!active && target) openCapability(target); }}><Icon name={key} />{label}</button>; })}
39	      <input className="search" aria-label="搜索 MCP" placeholder="搜索 MCP" value={query} onChange={event => setQuery(event.currentTarget.value)} />
40	    </header>
41	    <div className="connector-head"><span className="title-icon"><Icon name="connectors" /></span><div><h1>MCP 服务管理</h1><p>每个连接器都是独立 MCP 实例，由 DSH 官方客户端建立连接</p></div>
42	      <div className="head-actions"><button className="secondary" onClick={() => void refresh()} disabled={busy}>刷新状态</button><button className="primary" onClick={() => setDraft(blank())}>＋ 添加 MCP</button></div></div>
43	    <div className="list-meta"><strong>我的 MCP <span className="count">{rows.length}</span></strong><span className="muted">{rows.filter(row => row.enabled && row.state === 'ready').length} 已连接</span></div>
44	    {error ? <p className="error" role="alert">{error}</p> : null}
45	    {!busy && !filtered.length ? <div className="empty">{rows.length ? '没有匹配的 MCP 服务。' : '尚未配置 MCP 服务，点击“添加 MCP”创建第一个连接。'}</div> : null}
