1	import { randomUUID } from 'node:crypto';
2	import { fileURLToPath } from 'node:url';
3	import { Context, Service } from '@deepseek-ai/cordis';
4	import type { Agent } from '@deepseek-ai/dsh-agent';
5	import { credentialRef } from '@deepseek-ai/dsh-credentials';
6	import * as McpClient from '@deepseek-ai/dsh-mcp-client';
7	import type { KvTable } from '@deepseek-ai/dsh-storage-domain';
8	import type { ConnectorConfigView, ConnectorInput, ConnectorManagementService, ConnectorState, ConnectorSummary } from './shared.js';
9	import { connectorDefinitionSchema, connectorSelectionsDomainSpec, connectorsDomainSpec, type ConnectorDefinition, type ConnectorSelection } from './storage.js';
10	
11	declare module '@deepseek-ai/cordis' { interface Context { workdshConnectors: ConnectorManagementService; } }
12	
13	const serverPath = fileURLToPath(new URL('./example-server.mjs', import.meta.url));
14	type ChildFiber = { dispose(): Promise<void> };
15	type Runtime = { child?: ChildFiber; state: ConnectorState; diagnostic?: string };
16	type JsonRecord = Record<string, unknown>;
17	const record = (value: unknown): JsonRecord | undefined => value !== null && typeof value === 'object' && !Array.isArray(value) ? value as JsonRecord : undefined;
18	const idPart = (value: string) => value.replace(/[^A-Za-z0-9_-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 48);
19	const refFor = (value: string) => credentialRef(value) as unknown as Parameters<Context['credentials']['resolve']>[0];
20	
21	/** Persist connector instances here; delegate protocol, transport, discovery and reconnect to official MCP clients. */
22	export class ConnectorManager extends Service implements ConnectorManagementService {
23	  static inject = ['storageDomain', 'tools', 'mcpResources', 'agents', 'credentials'];
24	  private definitions?: KvTable<string, ConnectorDefinition>;
25	  private selections?: KvTable<string, ConnectorSelection>;
26	  private readonly runtimes = new Map<string, Runtime>();
27	  private readonly restrictions = new WeakMap<Agent, () => void>();
28	  private serial: Promise<void> = Promise.resolve();
29	
30	  constructor(ctx: Context) { super(ctx, 'workdshConnectors'); }
31	
32	  async [Service.init](): Promise<void> {
33	    const domain = await this.ctx.storageDomain.open(connectorsDomainSpec);
34	    this.ctx.effect(() => () => domain.close(), 'workdshConnectors.domainClose');
35	    this.definitions = domain.table('definitions');
36	    const selectionDomain = await this.ctx.storageDomain.open(connectorSelectionsDomainSpec);
37	    this.ctx.effect(() => () => selectionDomain.close(), 'workdshConnectors.selectionDomainClose');
38	    this.selections = selectionDomain.table('selections');
39	    if (!domain.global.get().seededExample) {
40	      const now = new Date().toISOString();
41	      await this.definitions.put('workdsh-example', {
42	        id: 'workdsh-example', title: 'WorkDSH MCP 示例', description: '可查询业务目录，并通过 MCP 资源与 URI 模板读取示例资料。',
43	        serverName: 'workdsh-example', transport: 'stdio', command: process.execPath, args: [serverPath], enabled: true,
44	        createdAt: now, updatedAt: now,
45	      });
46	      await domain.global.set({ seededExample: true });
47	    }
48	    for (const [, definition] of this.table().entries()) {
49	      this.runtimes.set(definition.id, { state: definition.enabled ? 'discovering' : 'disabled' });
50	      if (definition.enabled) void this.start(definition).catch(() => undefined);
51	    }
52	    this.ctx.on('agent/created', ({ agent }) => { this.applyRestriction(agent); return undefined; });
53	    for (const agent of this.ctx.agents.list()) this.applyRestriction(agent);
54	    this.ctx.effect(() => () => this.dispose(), 'workdshConnectors.runtimeClose');
55	  }
56	
57	  async list(signal?: AbortSignal): Promise<readonly ConnectorSummary[]> {
58	    signal?.throwIfAborted(); const rows: ConnectorSummary[] = [];
59	    for (const [, definition] of this.table().entries()) rows.push(await this.summary(definition, signal));
60	    return rows.sort((a, b) => a.title.localeCompare(b.title, 'zh-CN'));
61	  }
62	
63	  async config(id: string): Promise<ConnectorConfigView> {
64	    const row = this.definition(id);
65	    const credential = row.authorizationCredentialRef
66	      ? await this.ctx.credentials.describe(refFor(row.authorizationCredentialRef))
67	      : { configured: false, writable: true };
68	    return { id, title: row.title, description: row.description, serverName: row.serverName, transport: row.transport,
69	      ...(row.command ? { command: row.command } : {}), ...(row.args ? { args: row.args } : {}), ...(row.url ? { url: row.url } : {}),
70	      authorizationConfigured: credential.configured, authorizationWritable: credential.writable, editable: true };
71	  }
72	
73	  async create(input: ConnectorInput): Promise<ConnectorSummary> {
74	    return this.enqueue(async () => {
75	      const normalized = this.normalize(input); this.assertUniqueServer(normalized.serverName);
76	      const base = idPart(normalized.serverName) || 'mcp'; let id = base;
77	      while (this.table().get(id)) id = `${base}-${randomUUID().slice(0, 8)}`;
78	      const now = new Date().toISOString();
79	      const authorizationCredentialRef = input.authorizationToken?.trim() ? this.credentialName(normalized.serverName) : undefined;
80	      if (authorizationCredentialRef) await this.ctx.credentials.set(refFor(authorizationCredentialRef), input.authorizationToken!.trim());
81	      const definition: ConnectorDefinition = { id, ...normalized, ...(authorizationCredentialRef ? { authorizationCredentialRef } : {}), enabled: true, createdAt: now, updatedAt: now };
82	      await this.table().put(id, definition); this.runtimes.set(id, { state: 'discovering' });
83	      await this.start(definition).catch(() => undefined);
84	      this.reapplyRestrictions();
85	      return this.summary(definition);
86	    });
87	  }
88	
89	  async update(id: string, input: ConnectorInput): Promise<ConnectorSummary> {
90	    return this.enqueue(async () => {
91	      const current = this.definition(id); const normalized = this.normalize(input); this.assertUniqueServer(normalized.serverName, id);
92	      await this.stop(id, current.enabled);
93	      const authorizationCredentialRef = current.authorizationCredentialRef ?? (input.authorizationToken?.trim() ? this.credentialName(normalized.serverName) : undefined);
94	      if (authorizationCredentialRef && input.authorizationToken?.trim()) await this.ctx.credentials.set(refFor(authorizationCredentialRef), input.authorizationToken.trim());
95	      const next: ConnectorDefinition = { ...current, ...normalized, command: normalized.command, args: normalized.args, url: normalized.url,
96	        authorizationCredentialRef, updatedAt: new Date().toISOString() };
97	      await this.table().put(id, next); this.runtimes.set(id, { state: next.enabled ? 'discovering' : 'disabled' });
98	      if (next.enabled) await this.start(next).catch(() => undefined);
99	      this.reapplyRestrictions();
100	      return this.summary(next);
101	    });
102	  }
103	
104	  async remove(id: string): Promise<void> {
105	    await this.enqueue(async () => {
106	      this.definition(id); await this.stop(id, false); await this.table().delete(id); this.runtimes.delete(id);
107	      await this.removeFromSelections(id); this.reapplyRestrictions();
108	    });
109	  }
110	
111	  async setEnabled(id: string, enabled: boolean): Promise<ConnectorSummary> {
112	    return this.enqueue(async () => {
113	      const current = this.definition(id); if (enabled === current.enabled) return this.summary(current);
114	      if (!enabled) { await this.stop(id, false); await this.removeFromSelections(id); }
115	      const next = { ...current, enabled, updatedAt: new Date().toISOString() };
116	      await this.table().put(id, next); this.runtimes.set(id, { state: enabled ? 'discovering' : 'disabled' });
117	      if (enabled) await this.start(next).catch(() => undefined);
118	      this.reapplyRestrictions();
119	      return this.summary(next);
120	    });
121	  }
122	
