  console.log('github 详情(前350):', gh.slice(0, 350).replace(/\n+/g, ' / '));
  await page.screenshot({ path: '/tmp/v-bearer.png' });
  await page.locator('.catalog-back').click();
  await page.waitForTimeout(800);
  // oauth 条目（notion）
  await page.locator('.catalog-toolbar .search').fill('notion');
  await page.waitForTimeout(1200);
  await page.locator('.catalog-row').first().click();
  await page.waitForTimeout(1500);
  const nt = await page.locator('.catalog-detail').innerText().catch(() => '(none)');
  console.log('notion 详情(前300):', nt.slice(0, 300).replace(/\n+/g, ' / '));
  await page.screenshot({ path: '/tmp/v-oauth.png' });
  // 手动配置页签 intact + 凭据请求头字段
  await page.keyboard.press('Escape');
  await page.waitForTimeout(800);
  await page.getByText('＋ 添加 MCP', { exact: false }).click({ timeout: 5000 });
  await page.waitForTimeout(1000);
