import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
const TOKEN = process.argv[2];
const browser = await chromium.launch({ channel: 'chrome', headless: true });
try {
  const page = await browser.newPage({ viewport: { width: 1500, height: 950 } });
  await page.goto(`http://127.0.0.1:18989/?token=${TOKEN}`, { waitUntil: 'commit', timeout: 30000 });
  for (let i = 0; i < 90; i++) { await page.waitForTimeout(2000); const t = await page.locator('body').innerText().catch(() => ''); if (!t.includes('Loading plugins')) break; }
  const sidebarBefore = await page.getByText('MCP连接器', { exact: false }).count();
  console.log('侧栏 MCP连接器 入口(关闭前):', sidebarBefore);
  // 设置 → 插件
  await page.getByText('设置', { exact: false }).first().click({ timeout: 8000 });
  for (let i = 0; i < 15; i++) { await page.waitForTimeout(1000); const t = await page.locator('body').innerText().catch(() => ''); if (t.includes('通用设置')) break; }
  await page.locator('button', { hasText: '插件' }).first().click();
  await page.waitForTimeout(4000);
  await page.screenshot({ path: '/tmp/v-settings-plugins.png' });
  // 找 MCP Connector 卡片的开关
  const flipped = await page.evaluate(() => {
    const cards = [...document.querySelectorAll('*')].filter(e => /MCP Connector|MCP 连接器/.test(e.textContent ?? '') && e.querySelector('[role=switch], input[type=checkbox], button'));
    for (const card of cards.slice(0, 6)) {
      const sw = card.querySelector('[role=switch]');
      if (sw) { sw.click(); return 'switch:' + sw.getAttribute('aria-checked'); }
      const cb = card.querySelector('input[type=checkbox]');
      if (cb) { cb.click(); return 'checkbox:' + cb.checked; }
    }
    return 'not-found';
  });
  console.log('开关操作:', flipped);
  await page.waitForTimeout(2500);
  await page.screenshot({ path: '/tmp/v-toggle-off.png' });
  // 关设置，看侧栏
  await page.keyboard.press('Escape');
  await page.waitForTimeout(1500);
  const sidebarAfter = await page.getByText('MCP连接器', { exact: false }).count();
  console.log('侧栏 MCP连接器 入口(关闭后):', sidebarAfter);
} finally { await browser.close(); }
process.exit(0);
