14	    open: `请定位共享技能「${name}」的官方技能目录并使用可用的原生打开能力打开它；如果当前环境不能打开，请返回经过校验的目录路径。`,
15	    disable: `请停用共享技能「${name}」，不要修改它的 SKILL.md。先说明影响范围并确认，再使用 WorkDSH 技能管理能力完成并验证新任务不再加载它。`,
16	    enable: `请重新启用共享技能「${name}」，不要修改它的 SKILL.md，并验证 Harness 官方技能目录能重新发现它。`,
17	    uninstall: `请卸载共享技能「${name}」。先读取资源和依赖影响并让我确认；使用可恢复移除，不要直接永久删除，然后验证 Harness 官方目录不再加载它。`,
18	  } as const;
19	  return `/workdsh-skill-creator ${actions[kind]}`;
20	}
21	
22	export function PendingSkillDraft({ inputActions }: PropsRuntime<'conversation.input.overlay'>) {
23	  useEffect(() => {
24	    const draft = window.sessionStorage.getItem(pendingDraftKey);
25	    if (!draft) return;
26	    const timer = window.setTimeout(() => {
27	      inputActions.setDraft(draft);
28	      window.sessionStorage.removeItem(pendingDraftKey);
29	    }, 0);
30	    return () => window.clearTimeout(timer);
31	  }, [inputActions]);
32	  return null;
33	}
