e(path)}>{path}</button>)}</div> : <p className="muted">暂无附加资源</p>}<div className="new-resource"><input aria-label="新资源路径" placeholder="例如 references/guide.md" value={newResourcePath} onChange={event => setNewResourcePath(event.currentTarget.value)} /><button disabled={!newResourcePath.trim()} onClick={beginResource}>新建资源</button></div></section>}<pre className="skill-document">{selected.document ?? selected.whenToUse ?? selected.description}</pre></>}{error && <p className="error" role="alert">{error}</p>}</div>
