1	import { createHash } from 'node:crypto';
2	import { lstat, readFile, stat } from 'node:fs/promises';
3	import { extname, join, relative, resolve, sep } from 'node:path';
4	import type { SkillCatalogEntry, SkillCatalogIcon, SkillCatalogStatus, SkillCatalogSummary, SkillDiagnostic } from '../shared.js';
5	
6	/**
7	 * Read-only view over the WorkDSH-owned local skill catalog.
8	 *
9	 * The catalog is plain data below the shared Agents home (`catalog.json`,
10	 * `icons/`, `payloads/`). This store owns metadata lookup, icon bytes and
11	 * payload resolution only; installation itself stays in the skill manager's
12	 * import path so Harness remains the discovery and execution owner.
13	 */
14	export const skillCatalogIconPath = '/api/workdsh-skills/icon';
15	const CATALOG_SCHEMA = 1;
16	const CATALOG_KIND = 'workdsh-skill-catalog';
17	const skillNamePattern = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
18	const contentTypes: Record<string, string> = {
19	  '.svg': 'image/svg+xml',
20	  '.png': 'image/png',
21	  '.jpg': 'image/jpeg',
22	  '.jpeg': 'image/jpeg',
23	  '.webp': 'image/webp',
24	};
25	
26	interface CatalogFileEntry {
27	  readonly name: string;
28	  readonly title?: string;
29	  readonly description?: string;
30	  readonly categories?: readonly string[];
31	  readonly version?: string;
32	  readonly examples?: readonly string[];
33	  readonly icon?: string;
34	  readonly payload?: string;
35	  readonly installable?: boolean;
36	  readonly installLimits?: readonly string[];
37	}
38	
39	interface CatalogFile {
40	  readonly schema: number;
41	  readonly kind: string;
42	  readonly generatedAt?: string;
43	  readonly categories?: readonly string[];
44	  readonly entries: readonly CatalogFileEntry[];
45	}
46	
47	interface LoadedCatalog {
48	  readonly status: SkillCatalogStatus;
49	  readonly file?: CatalogFile;
50	  readonly diagnostics: readonly SkillDiagnostic[];
51	}
52	
53	function inside(root: string, target: string): boolean {
54	  const part = relative(resolve(root), resolve(target));
55	  return part !== '' && !part.startsWith(`..${sep}`) && part !== '..' && !part.startsWith(sep);
56	}
57	
58	function isRecord(value: unknown): value is Record<string, unknown> {
59	  return value !== null && typeof value === 'object' && !Array.isArray(value);
