import { chromium } from 'playwright';
import { readFile } from 'node:fs/promises';

const token = process.argv[2];
const base = 'http://127.0.0.1:18989';
const titlesFile = '/Users/apple/.agents/.workdsh-state/skills/titles.json';
const fail = (msg) => { console.log(`FAIL: ${msg}`); process.exit(1); };

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const ctx = await browser.newContext();
const page = await ctx.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
try {
  await page.goto(`${base}/?token=${token}`, { waitUntil: 'commit' });
  let booted = false;
  for (let i = 0; i < 90; i++) {
    const text = await page.evaluate(() => document.body?.innerText ?? '');
    if (text && !text.includes('Loading plugins')) { booted = true; break; }
    await new Promise((r) => setTimeout(r, 2000));
  }
  if (!booted) fail('SPA boot timeout');
  console.log('booted');

  const api = (endpoint, payload) => page.evaluate(async ([e, p]) => {
    const r = await fetch('/api/workdsh-skills', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ endpoint: e, payload: p }) });
    return r.json();
  }, [endpoint, payload]);

  // 1) pick a manageable installed skill
  const list = await api('list', {});
  if (!list.ok) fail(`list: ${JSON.stringify(list.error)}`);
  const target = list.value.find((s) => s.manageable && s.state !== 'invalid');
  if (!target) fail('no manageable skill');
  const originalDisplay = target.title ?? target.name;
  console.log(`target=${target.name} originalDisplay=${originalDisplay}`);

  // 2) API rename
  const renamed = '验证·新显示名';
  const set = await api('set-title', { name: target.name, title: renamed });
  if (!set.ok || set.value.title !== renamed) fail(`set-title: ${JSON.stringify(set)}`);
  const det = await api('detail', { name: target.name });
  if (!det.ok || det.value.title !== renamed) fail(`detail after rename: title=${det.value?.title}`);
  if (det.value.name !== target.name) fail(`identity changed! ${det.value.name}`);
  console.log('api rename ok, identity intact');

  // 3) persistence file
  const stored = JSON.parse(await readFile(titlesFile, 'utf8'));
  if (stored.overrides?.[target.name] !== renamed) fail(`titles.json: ${JSON.stringify(stored)}`);
  console.log('titles.json persisted');

  // 4) UI: skills panel shows renamed title + rename-back through the dialog
  await page.goto(`${base}/`, { waitUntil: 'commit' });
  for (let i = 0; i < 90; i++) {
    const text = await page.evaluate(() => document.body?.innerText ?? '');
    if (text && !text.includes('Loading plugins')) break;
    await new Promise((r) => setTimeout(r, 2000));
  }
  // open 技能 capability via nav
  const navSkills = page.locator('button:has-text("技能"), [role="button"]:has-text("技能")').first();
  await navSkills.click({ timeout: 15000 });
  await page.waitForSelector('[data-testid="workdsh-skills"]', { timeout: 30000 });
  console.log('skills panel open');

  // search by slug, card must show the override title
  await page.fill('input[aria-label="搜索技能"]', target.name);
  const card = page.locator('.card', { hasText: renamed }).first();
  await card.waitFor({ timeout: 15000 });
  console.log('card shows override title');
  await card.locator('.card-open').click();
  await page.waitForSelector('[data-testid="skill-detail"]', { timeout: 15000 });
  const h1 = await page.locator('[data-testid="skill-detail"] .detail-title h1').innerText();
  if (h1.trim() !== renamed) fail(`hero h1=${h1}`);
  console.log('detail hero shows override title');

  // 5) rename back via UI (clear input -> save -> default)
  await page.click('button:has-text("改名")');
  await page.waitForSelector('input[aria-label="技能显示名称"]', { timeout: 8000 });
  await page.fill('input[aria-label="技能显示名称"]', '');
  await page.click('.rename-row button.save');
  await page.waitForSelector('[data-testid="skill-detail"] .detail-title h1', { timeout: 15000 });
  const restored = (await page.locator('[data-testid="skill-detail"] .detail-title h1').innerText()).trim();
  if (restored !== originalDisplay) fail(`restored h1=${restored} expected=${originalDisplay}`);
  console.log('ui clear restores default');

  const after = JSON.parse(await readFile(titlesFile, 'utf8'));
  if (after.overrides?.[target.name]) fail(`override not cleared: ${JSON.stringify(after)}`);
  console.log('titles.json override cleared');

  // 6) rename via UI with a real value, verify hero + card, then clear via API (no residue)
  await page.click('button:has-text("改名")');
  await page.fill('input[aria-label="技能显示名称"]', '界面改名·贝塔');
  await page.click('.rename-row button.save');
  await page.waitForSelector('[data-testid="skill-detail"] .detail-title h1', { timeout: 15000 });
  const beta = (await page.locator('[data-testid="skill-detail"] .detail-title h1').innerText()).trim();
  if (beta !== '界面改名·贝塔') fail(`ui rename h1=${beta}`);
  console.log('ui rename ok');
  const cleared = await api('set-title', { name: target.name, title: null });
  if (!cleared.ok || cleared.value.title) fail(`api clear: ${JSON.stringify(cleared)}`);
  console.log('residue cleared');

  if (errors.length) console.log(`pageerrors(nonfatal): ${errors.slice(0, 3).join(' | ')}`);
  console.log('ALL PASS');
} catch (cause) {
  fail(cause instanceof Error ? cause.message : String(cause));
} finally {
  await browser.close();
  process.exit(0);
}

