1	import * as React from 'react';
2	import type { InjectFace, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots';
3	import { Icon, type IconName } from 'workdsh-ui';
4	import { workbenchPanelCss } from '../styles.js';
5	
6	export type BusinessPanelDefinition = {
7	  readonly id: string;
8	  readonly label: string;
9	  readonly icon: IconName;
10	  readonly order: number;
11	  readonly description?: string;
12	};
13	
14	export const businessPanels = [
15	  { id: 'workdsh-assistant', label: '助理', icon: 'assistant', order: 10, description: '创建和管理面向具体工作的 AI 助理。' },
16	  { id: 'workdsh-projects', label: '项目', icon: 'project', order: 20, description: '组织团队任务、资料、成员和共享能力。' },
17	  { id: 'workdsh-automation', label: '定时任务', icon: 'automation', order: 40, description: '查看和管理周期性工作。' },
18	  { id: 'workdsh-library', label: '资料库', icon: 'library', order: 50, description: '集中管理工作资料与任务成果。' },
19	  { id: 'workdsh-more', label: '更多', icon: 'more', order: 60, description: '进入 WorkDSH 的更多业务能力。' },
20	] as const satisfies readonly BusinessPanelDefinition[];
21	
22	export type BusinessPanelProps = PropsRuntime<'main'> & InjectFace<{
23	  readonly label: string;
24	  readonly description: string;
25	}>;
26	
27	export function BusinessPanel({ label, description }: BusinessPanelProps) {
28	  return (
29	    <section className="wd-workbench-panel">
30	      <style>{workbenchPanelCss}</style>
31	      <p className="wd-workbench-eyebrow">WORKDSH</p>
32	      <h1>{label}</h1>
33	      <p className="wd-workbench-description">{description}</p>
34	      <p className="wd-workbench-boundary">
35	        当前模块尚未接入领域数据。工作区、会话与新任务继续使用 DeepSeek Harness 原生能力。
