import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';

const token = process.argv[2];
if (!token) { console.error('usage: node verify.mjs <token>'); process.exit(2); }
const base = `http://127.0.0.1:18989/?token=${token}`;
const results = [];
const check = (name, ok, detail = '') => { results.push({ name, ok, detail }); console.log(`${ok ? 'PASS' : 'FAIL'} ${name}${detail ? ' — ' + detail : ''}`); };

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage();
await page.goto(base, { waitUntil: 'domcontentloaded', timeout: 60000 });

// SPA boot gate
let booted = false;
for (let i = 0; i < 90; i++) {
  const t = await page.evaluate(() => document.body.innerText || '');
  if (!t.includes('Loading plugins')) { booted = true; break; }
  await page.waitForTimeout(2000);
}
check('SPA boots', booted);

// 1. Brand text + N logo
const brand = await page.evaluate(() => {
  const el = document.querySelector('[data-testid="workdsh-brand"]');
  return el ? el.textContent.trim() : null;
});
check('sidebar brand = NexusOne', brand === 'NexusOne', `got ${JSON.stringify(brand)}`);

const logo = await page.evaluate(() => {
  const el = document.querySelector('[data-testid="workdsh-brand"]')?.closest('*')?.parentElement?.querySelector('svg path');
  const anyN = [...document.querySelectorAll('svg path')].some(p => (p.getAttribute('d') || '').startsWith('M56 194V84'));
  return anyN;
});
check('N-mark SVG present', logo === true);

// 2. Library panel (资料库) — real UI, not placeholder
const navClicked = await page.evaluate(() => {
  const items = [...document.querySelectorAll('nav *, aside *, [class*=nav] *, button, a')];
  const lib = items.find(e => e.textContent.trim() === '资料库' && e.offsetParent !== null);
  if (lib) { lib.click(); return true; }
  return false;
});
check('资料库 nav clickable', navClicked);
if (navClicked) {
  await page.waitForTimeout(4000);
  const libState = await page.evaluate(() => {
    const t = document.body.innerText;
    return { placeholder: t.includes('尚未接入领域数据'), hasLibraryUI: /资料|文件|目录|上传|资源/.test(t) && !t.includes('尚未接入领域数据') };
  });
  check('资料库 shows real library (not placeholder)', libState.hasLibraryUI, libState.placeholder ? 'still placeholder' : 'library UI rendered');
}

// 3. Connectors panel — MCP catalog tab (二开 regression)
const connClicked = await page.evaluate(() => {
  const items = [...document.querySelectorAll('nav *, aside *, [class*=nav] *, button, a')];
  const c = items.find(e => e.textContent.trim() === '连接器' && e.offsetParent !== null);
  if (c) { c.click(); return true; }
  return false;
});
check('连接器 nav clickable', connClicked);
if (connClicked) {
  await page.waitForTimeout(4000);
  const hasCatalog = await page.evaluate(() => {
    const t = document.body.innerText;
    return t.includes('MCP') && /目录|超市|市场/.test(t);
  });
  const hasAddMcp = await page.evaluate(() => [...document.querySelectorAll('button')].some(b => b.textContent.includes('添加MCP') || b.textContent.includes('添加 MCP')));
  check('MCP catalog UI present (二开)', hasCatalog || hasAddMcp, `catalog=${hasCatalog} addBtn=${hasAddMcp}`);
}

// 4. Skills market — Chinese titles (二开 regression)
const skillsClicked = await page.evaluate(() => {
  const items = [...document.querySelectorAll('nav *, aside *, [class*=nav] *, button, a')];
  const s = items.find(e => e.textContent.trim() === '技能市场' && e.offsetParent !== null);
  if (s) { s.click(); return true; }
  return false;
});
check('技能市场 nav clickable', skillsClicked);
if (skillsClicked) {
  await page.waitForTimeout(5000);
  const zh = await page.evaluate(() => {
    const cards = [...document.querySelectorAll('[data-testid*=skill], [class*=card], [class*=Card]')].filter(e => e.offsetParent !== null && e.textContent.trim().length > 3);
    const text = document.body.innerText;
    const cjkCount = (text.match(/[一-鿿]/g) || []).length;
    const hasKnown = text.includes('事实信息抽取') || text.includes('文档解析') || text.includes('实体抽取');
    return { cards: cards.length, cjkCount, hasKnown };
  });
  check('技能市场 shows Chinese titles', zh.hasKnown, `cjkChars=${zh.cjkCount} knownTitle=${zh.hasKnown}`);
}

// 5. Skill detail — rename row (二开 regression)
if (skillsClicked) {
  const opened = await page.evaluate(() => {
    const els = [...document.querySelectorAll('*')].filter(e => e.offsetParent !== null && e.children.length === 0 && (e.textContent.trim() === '事实信息抽取' || e.textContent.trim() === '文档解析'));
    const target = els[0]?.closest('[class*=card], [class*=Card], li, div');
    if (target) { target.click(); return true; }
    return false;
  });
  if (opened) {
    await page.waitForTimeout(3000);
    const renameUI = await page.evaluate(() => {
      const btns = [...document.querySelectorAll('button')].some(b => b.textContent.trim() === '改名');
      const input = !!document.querySelector('input[aria-label="技能显示名称"]');
      return btns || input;
    });
    check('skill detail has rename UI (二开)', renameUI);
  } else {
    check('skill detail has rename UI (二开)', false, 'could not open detail');
  }
}

await browser.close();
const failed = results.filter(r => !r.ok).length;
console.log(`\n=== ${results.length - failed}/${results.length} PASS ===`);
process.exit(failed ? 1 : 0);

