import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';

const token = process.argv[2];
const results = [];
const check = (name, ok, detail = '') => { results.push(ok); console.log(`${ok ? 'PASS' : 'FAIL'} ${name}${detail ? ' — ' + detail : ''}`); };

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage();
await page.goto(`http://127.0.0.1:18989/?token=${token}`, { waitUntil: 'domcontentloaded', timeout: 60000 });
for (let i = 0; i < 90; i++) {
  const t = await page.evaluate(() => document.body.innerText || '');
  if (!t.includes('Loading plugins')) break;
  await page.waitForTimeout(2000);
}
await page.waitForTimeout(2000);

// enter 专家 · 技能 · 连接器
const clickedHub = await page.evaluate(() => {
  const el = [...document.querySelectorAll('a, button, li, [role=tab]')].find(e => e.offsetParent !== null && e.textContent.replace(/\s+/g, ' ').trim() === '专家 · 技能 · 连接器');
  if (el) { el.click(); return true; } return false;
});
check('hub nav clicked', clickedHub);
await page.waitForTimeout(4000);

const hubDump = await page.evaluate(() => {
  const tabs = [...document.querySelectorAll('[role=tab], button, a')].filter(e => e.offsetParent !== null).map(e => e.textContent.replace(/\s+/g, ' ').trim()).filter(t => t && t.length <= 24);
  return [...new Set(tabs)].slice(0, 40);
});
console.log('hub tabs:', JSON.stringify(hubDump));

// connectors tab (二开: MCP catalog)
const clickedConn = await page.evaluate(() => {
  const el = [...document.querySelectorAll('[role=tab], button, a')].find(e => e.offsetParent !== null && /^连接器/.test(e.textContent.replace(/\s+/g, ' ').trim()) && e.textContent.trim().length < 10);
  if (el) { el.click(); return true; } return false;
});
check('连接器 tab clicked', clickedConn);
await page.waitForTimeout(4000);
const connUI = await page.evaluate(() => {
  const t = document.body.innerText;
  return {
    addMcp: [...document.querySelectorAll('button')].some(b => /添加\s*MCP/.test(b.textContent)),
    catalog: /目录|超市/.test(t) && t.includes('MCP'),
    hasContext7: t.includes('Context7'),
  };
});
check('MCP 目录/添加MCP present (二开)', connUI.addMcp || connUI.catalog, JSON.stringify(connUI));

// skills market tab
const clickedSkills = await page.evaluate(() => {
  const el = [...document.querySelectorAll('[role=tab], button, a')].find(e => e.offsetParent !== null && /技能市场/.test(e.textContent));
  if (el) { el.click(); return true; } return false;
});
check('技能市场 tab clicked', clickedSkills);
await page.waitForTimeout(5000);
const skillUI = await page.evaluate(() => {
  const t = document.body.innerText;
  return { known: ['事实信息抽取', '文档解析', '实体抽取'].filter(k => t.includes(k)), latin: /claim-extraction-skill|document-parsing-skill/.test(t) };
});
check('技能市场 Chinese titles', skillUI.known.length > 0 && !skillUI.latin, JSON.stringify(skillUI));

// open a skill detail → rename UI
const openedDetail = await page.evaluate(() => {
  const el = [...document.querySelectorAll('*')].find(e => e.offsetParent !== null && e.children.length <= 2 && e.textContent.trim() === '文档解析');
  const card = el?.closest('[class*=card], [class*=Card], li, [role=button], div');
  if (card) { card.click(); return true; } return false;
});
if (openedDetail) {
  await page.waitForTimeout(3000);
  const renameUI = await page.evaluate(() => ({
    renameBtn: [...document.querySelectorAll('button')].some(b => b.textContent.trim() === '改名'),
    hint: document.body.innerText.includes('显示名称只影响界面展示'),
  }));
  check('skill detail rename UI (二开)', renameUI.renameBtn, JSON.stringify(renameUI));
} else {
  check('skill detail rename UI (二开)', false, 'could not open 文档解析 card');
}

await browser.close();
const failed = results.filter(r => !r).length;
console.log(`\n=== ${results.length - failed}/${results.length} PASS ===`);
process.exit(failed ? 1 : 0);

