import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';

const token = process.argv[2];
const results = [];
const check = (name, ok, detail = '') => { results.push(ok); console.log(`${ok ? 'PASS' : 'FAIL'} ${name}${detail ? ' — ' + detail : ''}`); };

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage();
await page.goto(`http://127.0.0.1:18989/?token=${token}`, { waitUntil: 'domcontentloaded', timeout: 60000 });
for (let i = 0; i < 120; i++) {
  const t = await page.evaluate(() => document.body.innerText || '');
  if (!t.includes('Loading plugins')) break;
  await page.waitForTimeout(2000);
}
await page.waitForTimeout(3000);

// 1. Brand + title
const brand = await page.evaluate(() => ({
  text: document.querySelector('[data-testid="workdsh-brand"]')?.textContent?.trim(),
  title: document.title,
  dsh: document.body.innerText.includes('DeepSeek'),
}));
check('brand = NexusOne', brand.text === 'NexusOne');
check('tab title = NexusOne', brand.title === 'NexusOne', brand.title);
check('no DeepSeek visible', !brand.dsh);

// 2. Sidebar: pending hidden, 项目/资料库 present
const nav = await page.evaluate(() => [...document.querySelectorAll('a, button, li')].filter(e => e.offsetParent !== null).map(e => e.textContent.replace(/\s+/g, ' ').trim()).filter(t => t && t.length < 16));
check('sidebar hides 助理/定时任务/更多', !nav.includes('助理') && !nav.includes('定时任务') && !nav.includes('更多'), nav.slice(0, 12).join('/'));
check('sidebar keeps 项目+资料库', nav.includes('项目') && nav.includes('资料库'));

// 3. 项目 real implementation
await page.evaluate(() => { const el = [...document.querySelectorAll('a, button, li')].find(e => e.offsetParent !== null && e.textContent.replace(/\s+/g, ' ').trim() === '项目'); if (el) el.click(); });
await page.waitForTimeout(4000);
const proj = await page.evaluate(() => ({ placeholder: document.body.innerText.includes('尚未接入领域数据'), text: document.body.innerText.slice(0, 200) }));
check('项目 is real (not placeholder)', !proj.placeholder, proj.text.replace(/\n/g, ' ').slice(0, 80));

// 4. 资料库 still real
await page.evaluate(() => { const el = [...document.querySelectorAll('a, button, li')].find(e => e.offsetParent !== null && e.textContent.replace(/\s+/g, ' ').trim() === '资料库'); if (el) el.click(); });
await page.waitForTimeout(4000);
const lib = await page.evaluate(() => !document.body.innerText.includes('尚未接入领域数据'));
check('资料库 real', lib);

// 5. Hub: connectors 二开 (添加MCP modal)
await page.evaluate(() => { const el = [...document.querySelectorAll('a, button, li')].find(e => e.offsetParent !== null && e.textContent.replace(/\s+/g, ' ').trim() === '专家 · 技能 · 连接器'); if (el) el.click(); });
await page.waitForTimeout(3000);
await page.evaluate(() => { const el = [...document.querySelectorAll('[role=tab], button, a')].find(e => e.offsetParent !== null && e.textContent.replace(/\s+/g, ' ').trim() === '连接器'); if (el) el.click(); });
await page.waitForTimeout(3000);
const mcpBtn = await page.evaluate(() => { const b = [...document.querySelectorAll('button')].find(x => x.offsetParent !== null && /添加\s*MCP/.test(x.textContent)); if (b) { b.click(); return true; } return false; });
check('添加MCP button', mcpBtn);
await page.waitForTimeout(4000);
const catalog = await page.evaluate(() => /目录|超市/.test(document.body.innerText));
check('MCP catalog tab (二开)', catalog);
await page.keyboard.press('Escape');

// 6. Skills: pool categories + Chinese titles + rename UI
await page.waitForTimeout(1000);
await page.evaluate(() => { const el = [...document.querySelectorAll('[role=tab], button, a')].find(e => e.offsetParent !== null && e.textContent.replace(/\s+/g, ' ').trim() === '技能'); if (el) el.click(); });
await page.waitForTimeout(5000);
const skills = await page.evaluate(() => {
  const tabs = [...document.querySelectorAll('.category-tabs button')].map(b => b.textContent.trim());
  const t = document.body.innerText;
  return { tabs, zh: ['数学建模竞赛', '投研认知审计', '文档解析', '事实信息抽取'].filter(k => t.includes(k)) };
});
check('pool category tabs', ['数学建模', '学术科研', '金融投研'].every(c => skills.tabs.includes(c)), skills.tabs.join('/'));
check('Chinese titles (pool+renamed)', skills.zh.length >= 3, skills.zh.join('/'));

const opened = await page.evaluate(() => {
  const el = [...document.querySelectorAll('*')].find(e => e.offsetParent !== null && e.children.length <= 2 && e.textContent.trim() === '文档解析');
  const card = el?.closest('[class*=card], [class*=Card], li, div');
  if (card) { card.click(); return true; } return false;
});
if (opened) {
  await page.waitForTimeout(3000);
  const rename = await page.evaluate(() => [...document.querySelectorAll('button')].some(b => b.textContent.trim() === '改名'));
  check('skill rename UI (二开)', rename);
} else check('skill rename UI (二开)', false, 'card not found');

await browser.close();
const failed = results.filter(r => !r).length;
console.log(`\n=== ${results.length - failed}/${results.length} PASS ===`);
process.exit(failed ? 1 : 0);

import * as React from 'react';
import type { InjectFace, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots';
import { Icon, type IconName } from 'workdsh-ui';
import { workbenchPanelCss } from '../styles.js';

export type BusinessPanelDefinition = {
  readonly id: string;
  readonly label: string;
  readonly icon: IconName;
  readonly order: number;
  readonly description?: string;
  /** 规划中、尚无领域实现的功能：不注册侧栏入口与占位页，实现完成后置 false。 */
  readonly pending: boolean;
};

export const businessPanels = [
  { id: 'workdsh-assistant', label: '助理', icon: 'assistant', order: 10, description: '创建和管理面向具体工作的 AI 助理。', pending: true },
  { id: 'workdsh-projects', label: '项目', icon: 'project', order: 20, description: '组织团队任务、资料、成员和共享能力。', pending: false },
  { id: 'workdsh-automation', label: '定时任务', icon: 'automation', order: 40, description: '查看和管理周期性工作。', pending: true },
  { id: 'workdsh-library', label: '资料库', icon: 'library', order: 50, description: '集中管理工作资料与任务成果。', pending: false },
  { id: 'workdsh-more', label: '更多', icon: 'more', order: 60, description: '进入 NexusOne 的更多业务能力。', pending: true },
] as const satisfies readonly BusinessPanelDefinition[];

export type BusinessPanelProps = PropsRuntime<'main'> & InjectFace<{
  readonly label: string;
  readonly description: string;
}>;

export function BusinessPanel({ label, description }: BusinessPanelProps) {
  return (
    <section className="wd-workbench-panel">
      <style>{workbenchPanelCss}</style>
      <p className="wd-workbench-eyebrow">NEXUSONE</p>
      <h1>{label}</h1>
      <p className="wd-workbench-description">{description}</p>
      <p className="wd-workbench-boundary">
        当前模块尚未接入领域数据。工作区、会话与新任务继续使用 NexusOne 原生能力。
      </p>
    </section>
  );
}

export type BusinessPanelIconProps = InjectFace<{ readonly icon: IconName }>;

export function BusinessPanelIcon({ icon }: BusinessPanelIconProps) {
  return <Icon name={icon} />;
}

import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';

const token = process.argv[2];
const results = [];
const check = (name, ok, detail = '') => { results.push(ok); console.log(`${ok ? 'PASS' : 'FAIL'} ${name}${detail ? ' — ' + detail : ''}`); };

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage();
await page.goto(`http://127.0.0.1:18989/?token=${token}`, { waitUntil: 'domcontentloaded', timeout: 60000 });
for (let i = 0; i < 90; i++) {
  const t = await page.evaluate(() => document.body.innerText || '');
  if (!t.includes('Loading plugins')) break;
  await page.waitForTimeout(2000);
}
await page.waitForTimeout(2000);

// API: catalog endpoint
const api = async (endpoint, payload) => page.evaluate(async ([ep, pl]) => {
  const r = await fetch('/api/workdsh-skills', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ endpoint: ep, payload: pl }) });
  return r.json();
}, [endpoint, payload]);

const cat = await api('catalog', {});
check('catalog ready', cat.ok && cat.value?.status === 'ready', JSON.stringify(cat.value?.status ?? cat.error?.code));
const entries = cat.value?.entries ?? [];
check('8 pool entries', entries.length === 8, `got ${entries.length}: ${entries.map(e => e.name).join(',')}`);
const cats = cat.value?.categories ?? [];
check('3 domain categories', ['数学建模', '学术科研', '金融投研'].every(c => cats.includes(c)), cats.join('/'));

// UI: category tabs visible
await page.evaluate(() => {
  const el = [...document.querySelectorAll('a, button, li')].find(e => e.offsetParent !== null && e.textContent.replace(/\s+/g, ' ').trim() === '专家 · 技能 · 连接器');
  if (el) el.click();
});
await page.waitForTimeout(3000);
await page.evaluate(() => {
  const el = [...document.querySelectorAll('[role=tab], button, a')].find(e => e.offsetParent !== null && e.textContent.replace(/\s+/g, ' ').trim() === '技能');
  if (el) el.click();
});
await page.waitForTimeout(5000);
const ui = await page.evaluate(() => {
  const tabs = [...document.querySelectorAll('.category-tabs button')].map(b => b.textContent.trim());
  const installCards = [...document.querySelectorAll('.market-section [aria-label^="查看技能"] .card-title strong')].map(e => e.textContent.trim());
  return { tabs, installCards };
});
check('UI category tabs include 3 domains', ['数学建模', '学术科研', '金融投研'].every(c => ui.tabs.includes(c)), ui.tabs.join('/'));
check('UI 可安装 cards show pool titles', ['数学建模竞赛', '投研认知审计', '论文深读'].every(t => ui.installCards.includes(t)), `${ui.installCards.length} cards`);

// Install 数学建模竞赛 via UI click
const clickedInstall = await page.evaluate(() => {
  const card = [...document.querySelectorAll('.market-section [aria-label^="查看技能"]')].find(b => b.textContent.includes('数学建模竞赛'));
  const section = card?.closest('.market-section');
  const btn = card?.closest('li, .card, div')?.parentElement?.querySelector('button.install') ?? [...document.querySelectorAll('button.install')].find(b => b.getAttribute('aria-label') === '安装技能 数学建模竞赛');
  if (btn) { btn.click(); return true; }
  return false;
});
check('click ＋ install 数学建模竞赛', clickedInstall);
await page.waitForTimeout(4000);

// Verify installed via API
let list = await api('list', {});
let names = (list.value ?? []).map(s => s.name);
check('math-modeling installed', names.includes('math-modeling'), `${names.length} installed`);

// Install resanity via API (pool activation path)
const inst2 = await api('install-catalog', { name: 'resanity' });
check('resanity install-catalog API', inst2.ok === true, JSON.stringify(inst2.error?.code ?? 'ok'));
list = await api('list', {});
names = (list.value ?? []).map(s => s.name);
check('pool now 28 installed', names.length === 28, `got ${names.length}`);

// Detail + title overlay
const detail = await api('detail', { name: 'math-modeling' });
check('detail title = 数学建模竞赛', detail.value?.title === '数学建模竞赛', JSON.stringify(detail.value?.title));

// 勾选激活语义: disable → enable round-trip
const dis = await api('set-enabled', { name: 'auto-mcm', enabled: false });
// auto-mcm not installed; use math-modeling
const dis2 = await api('set-enabled', { name: 'math-modeling', enabled: false });
check('disable math-modeling', dis2.ok === true, JSON.stringify(dis2.error?.code ?? 'ok'));
const list2 = await api('list', {});
const row = (list2.value ?? []).find(s => s.name === 'math-modeling');
check('state=disabled after disable', row?.state === 'disabled', row?.state);
const en = await api('set-enabled', { name: 'math-modeling', enabled: true });
const list3 = await api('list', {});
const row3 = (list3.value ?? []).find(s => s.name === 'math-modeling');
check('re-enable → enabled', en.ok === true && row3?.state === 'enabled', row3?.state);

// 中文标题 overlay on resanity
const det2 = await api('detail', { name: 'resanity' });
check('resanity title = 投研认知审计', det2.value?.title === '投研认知审计', JSON.stringify(det2.value?.title));

await browser.close();
const failed = results.filter(r => !r).length;
console.log(`\n=== ${results.length - failed}/${results.length} PASS ===`);
process.exit(failed ? 1 : 0);

