const labels = { ready: '已连接', discovering: '正在连接', offline: '连接异常', disabled: '已停用' } as const;
const fromConfig = (row: ConnectorConfigView): Draft => ({ id: row.id, title: row.title, description: row.description, serverName: row.serverName, transport: row.transport, command: row.command ?? '', argsText: (row.args ?? []).join('\n'), url: row.url ?? '', credentialHeader: row.credentialHeader ?? '', authorizationToken: '', authorizationConfigured: row.authorizationConfigured });
