1	import { execFile } from 'node:child_process';
2	import { access, copyFile, mkdir, readFile, realpath } from 'node:fs/promises';
3	import { createHash } from 'node:crypto';
4	import { createRequire } from 'node:module';
5	import { dirname, join, resolve } from 'node:path';
6	import { fileURLToPath } from 'node:url';
7	import { promisify } from 'node:util';
8	
9	const root = fileURLToPath(new URL('..', import.meta.url));
10	const rootManifest = JSON.parse(await readFile(join(root, 'package.json'), 'utf8'));
11	const baseVersion = rootManifest.pnpm?.overrides?.['@deepseek-ai/dsh-base'];
12	const webAppVersion = rootManifest.pnpm?.overrides?.['@deepseek-ai/dsh-web-app'];
13	if (typeof baseVersion !== 'string') throw new Error('Missing pinned @deepseek-ai/dsh-base version in package.json pnpm.overrides.');
14	if (typeof webAppVersion !== 'string') throw new Error('Missing pinned @deepseek-ai/dsh-web-app version in package.json pnpm.overrides.');
15	const baseSpec = `@deepseek-ai/dsh-base@${baseVersion}`;
16	const webAppSpec = `@deepseek-ai/dsh-web-app@${webAppVersion}`;
17	const cliVersion = JSON.parse(await readFile(join(root, 'node_modules/@deepseek-ai/dsh/package.json'), 'utf8')).version;
18	if (cliVersion !== baseVersion) throw new Error('Preview CLI and Base must use the same pinned version.');
19	const home = resolve(process.env.WORKDSH_PREVIEW_HOME ?? join(root, '.test-runtime/preview'));
20	const artifacts = join(root, '.artifacts');
21	const env = { ...process.env, DSH_HOME: home, PATH: `${join(root, 'node_modules/.bin')}:${dirname(process.execPath)}:${process.env.PATH}` };
22	const exec = promisify(execFile);
23	const run = async (tool, args) => {
24	  await exec(process.execPath, [join(root, 'node_modules', tool), ...args], { cwd: root, env, timeout: 180_000, maxBuffer: 8 * 1024 * 1024 });
25	};
26	await mkdir(home, { recursive: true }); await mkdir(artifacts, { recursive: true });
27	const tarballs = [];
28	const packages = [];
29	for (const directory of ['packages/providers/identity-local', 'packages/plugins/audit', 'packages/plugins/access', 'packages/plugins/skills', 'packages/plugins/experts', 'packages/plugins/connectors', 'packages/plugins/office', 'packages/plugins/library', 'packages/plugins/projects', 'packages/plugins/activity', 'packages/bundle']) {
30	  const manifest = JSON.parse(await readFile(join(root, directory, 'package.json'), 'utf8'));
31	  await access(join(root, directory, manifest.exports['.'].default));
32	  await run('pnpm/bin/pnpm.cjs', ['--filter', manifest.name, 'pack', '--pack-destination', artifacts]);
33	  const packed = join(artifacts, `${manifest.name}-${manifest.version}.tgz`);
34	  // Preview candidates can change before their next release. A stable file:
35	  // address lets the package manager reuse an older archive, even after pack.
36	  // Keep official CLI installation, but address each archive by its content.
37	  const digest = createHash('sha256').update(await readFile(packed)).digest('hex');
38	  const destination = join(artifacts, 'preview', digest);
39	  await mkdir(destination, { recursive: true });
40	  const immutableArchive = join(destination, `${manifest.name}-${manifest.version}.tgz`);
41	  await copyFile(packed, immutableArchive);
42	  tarballs.push(immutableArchive);
43	  packages.push({ directory, manifest });
44	}
45	let initialized = false;
46	try { await access(join(home, 'profiles/preview/package.json')); initialized = true; }
47	catch (error) { if (error.code !== 'ENOENT') throw error; }
48	if (!initialized) await run('@deepseek-ai/dsh/lib/bin.js', ['--profile', 'preview', '--from-default-profile', 'web', '--dump-config']);
49	// Reinstall the pinned official Web bundle as well as the WorkDSH layers. An
50	// existing preview Profile may have been created by an older DSH release; its
51	// bundle list alone does not upgrade the packages that provide newly added Web
52	// surfaces such as Terminal and archived-session recovery.
53	await run('@deepseek-ai/dsh/lib/bin.js', ['plugin', '--profile', 'preview', 'add', baseSpec, webAppSpec, ...tarballs]);
54	// Boot and ConfigEditor share module-local registration in dsh-app-boot.
55	// Keep the official CLI in the Profile dependency graph as well: launching the
56	// workspace CLI beside separately installed Profile packages splits that state.
57	// Profiles disable automatic peer installation. The platform account adapter
58	// also needs its declared native account peer in this standalone runtime.
59	await run('pnpm/bin/pnpm.cjs', ['--dir', join(home, 'profiles/preview'), 'add', '--save-exact', `@deepseek-ai/dsh@${cliVersion}`, `@deepseek-ai/dsh-deepseek-account@${cliVersion}`]);
60	const installedBase = JSON.parse(await readFile(join(home, 'profiles/preview/node_modules/@deepseek-ai/dsh-base/package.json'), 'utf8'));
61	if (installedBase.version !== baseVersion) throw new Error(`Installed @deepseek-ai/dsh-base ${installedBase.version} does not match pinned ${baseVersion}.`);
62	const installedWebApp = JSON.parse(await readFile(join(home, 'profiles/preview/node_modules/@deepseek-ai/dsh-web-app/package.json'), 'utf8'));
63	if (installedWebApp.version !== webAppVersion) throw new Error(`Installed @deepseek-ai/dsh-web-app ${installedWebApp.version} does not match pinned ${webAppVersion}.`);
64	// DSH scopes are module-instance local. Installing only the Web bundle
65	// beside a CLI-provided Base bundle can load two physical dsh-scope copies: the
66	// Agent consumers must resolve one shared scope module; otherwise new
67	// session fails as an "unscoped context". Resolve both consumers from the
68	// Profile and fail installation unless they share the exact same module file.
69	const profileRequire = createRequire(join(home, 'profiles/preview/package.json'));
70	const resolveProfileDependency = async (consumer, dependency) => {
71	  const consumerManifest = profileRequire.resolve(`${consumer}/package.json`);
72	  const consumerRequire = createRequire(consumerManifest);
73	  return realpath(consumerRequire.resolve(`${dependency}/package.json`));
74	};
75	const cliBoot = await resolveProfileDependency('@deepseek-ai/dsh', '@deepseek-ai/dsh-app-boot');
76	const settingsBoot = await resolveProfileDependency('@deepseek-ai/dsh-config-editor', '@deepseek-ai/dsh-app-boot');
77	if (cliBoot !== settingsBoot) throw new Error('Preview CLI and ConfigEditor resolve different dsh-app-boot instances; settings cannot persist.');
78	const loopScope = await resolveProfileDependency('@deepseek-ai/dsh-agent-loop', '@deepseek-ai/dsh-scope');
79	const presetScope = await resolveProfileDependency('@deepseek-ai/dsh-agent-preset-registry', '@deepseek-ai/dsh-scope');
80	if (loopScope !== presetScope) throw new Error(`Preview loaded split @deepseek-ai/dsh-scope instances: agent-loop=${loopScope}; agent-preset-registry=${presetScope}.`);
81	for (const { directory, manifest } of packages) {
82	  for (const face of ['.', './client']) {
83	    const entry = manifest.exports[face]?.default;
84	    if (!entry) continue;
85	    const expected = await readFile(join(root, directory, entry));
