done
[ "$code" = "401" ] || { echo "PORT TIMEOUT last=$code"; exit 1; }
token=''
for i in $(seq 1 40); do
  token=$(grep 'dsh web:' ~/Library/Logs/com.workdsh.preview.log | tail -1 | sed -n 's/.*token=\([A-Za-z0-9_-]*\).*/\1/p')
  code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 3 "http://127.0.0.1:18989/?token=$token" 2>/dev/null)
  [ "$code" = "303" ] && { echo "TOKEN VALID ~$((i*5))s"; break; }; sleep 5
done
[ "$code" = "303" ] || { echo "TOKEN TIMEOUT last=$code"; exit 1; }
