for (let i = 0; i < 120; i++) { const t = await page.evaluate(() => document.body.innerText || ''); if (!t.includes('Loading plugins')) break; await page.waitForTimeout(2000); }
await page.waitForTimeout(3000);
const nav = await page.evaluate(() => [...document.querySelectorAll('a, button, li')].filter(e => e.offsetParent !== null).map(e => e.textContent.replace(/\s+/g, ' ').trim()).filter(t => t && t.length < 20));
console.log('sidebar:', nav.slice(0, 14).join(' / '));
const mcp = nav.some(t => t.includes('MCP连接器'));
const ssh = nav.some(t => t.includes('SSH'));
console.log(mcp ? 'FAIL: MCP连接器 still present' : 'PASS: MCP连接器 hidden');
console.log(ssh ? 'PASS: SSH entry intact' : 'WARN: SSH entry missing');
await browser.close();
process.exit(mcp ? 1 : 0);
EOF
node /tmp/probe-sidebar2.mjs

