connection.fetch.register({
  path: '/api/workdsh-plate',
  methods: ['POST'],
  requestBody: 'buffered',
  async fetch(request) {
    const body = await request.json();
    if (body.endpoint === 'ai-smoke') {
      const sel = ctx.agentDefaultModel.currentSelection();
      const prompt = typeof body.prompt === 'string' && body.prompt.trim() ? body.prompt : '用一句话介绍富文本编辑器。';
      const options = {
        provider: sel.provider,
        model: sel.model,
        messages: [{ role: 'user', content: prompt }],
        system: '你是中文写作助手。',
        maxTokens: 512,
      };
      console.log('[workdsh-plate] ai-smoke GenerateOptions', JSON.stringify({...options, messages: '[1]'}));
      const stream = ctx.llm.stream(options as any);
      const encoder = new TextEncoder();
      const readable = new ReadableStream({
        async start(controller) {
          const t0 = Date.now();
          try {
            for await (const chunk of stream) {
              if (chunk.type === 'text-delta') {
                controller.enqueue(encoder.encode(`data: ${JSON.stringify({t: Date.now()-t0, text: chunk.text})}\n\n`));
              } else if (chunk.type === 'usage') {
                controller.enqueue(encoder.encode(`data: ${JSON.stringify({usage: chunk.usage})}\n\n`));
              }
            }
            controller.enqueue(encoder.encode('data: [DONE]\n\n'));
            controller.close();
          } catch (err) {
            controller.enqueue(encoder.encode(`data: ${JSON.stringify({error: String(err)})}\n\n`));
            controller.close();
          }
        }
      });
      return new Response(readable, { headers: { 'content-type': 'text/event-stream; charset=utf-8', 'cache-control': 'no-cache' } });
    }
    return Response.json({ ok: true, name: 'workdsh-plate' });
  },
});
```

