// S4/S5 spike probe: attach a .plate file in a fresh conversation, open it in
// the right-sidebar document preview, assert the Plate editor mounts and edits.
import { chromium } from 'playwright';
import { writeFileSync } from 'node:fs';

const TOKEN = process.argv[2];
if (!TOKEN) { console.error('usage: node plate-probe.mjs <token>'); process.exit(2); }
const BASE = 'http://127.0.0.1:18989';
const out = { consoleErrors: [], pageErrors: [], steps: [] };
const step = (s) => { out.steps.push(s); console.log('STEP', s); };

writeFileSync('/tmp/spike-doc.plate', JSON.stringify({ v: 1, text: 'spike' }));

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('console', (m) => { if (m.type() === 'error') out.consoleErrors.push(m.text().slice(0, 300)); });
page.on('pageerror', (e) => out.pageErrors.push(String(e).slice(0, 300)));

await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 60000 });
await page.waitForTimeout(8000);

// Module loader state: is our client factory registered?
out.loader = await page.evaluate(() => {
  const ml = window.__ModuleLoader__;
  if (!ml) return 'no __ModuleLoader__';
  const keys = [];
  for (const k of Object.keys(ml)) keys.push(k);
  const dump = { keys };
  for (const prop of ['factories', 'loadCache', 'records']) {
    const v = ml[prop];
    if (v instanceof Map) dump[prop] = [...v.keys()].filter((x) => String(x).includes('plate'));
  }
  return dump;
});
step('loader introspected: ' + JSON.stringify(out.loader));

// Fresh conversation
const newChat = page.locator('button:has-text("新会话"), [aria-label*="新会话"], a:has-text("新会话")').first();
await newChat.click({ timeout: 20000 });
await page.waitForTimeout(3000);
step('new conversation opened');

// Attach the .plate file
const fileInput = page.locator('input[type="file"]').first();
await fileInput.setInputFiles('/tmp/spike-doc.plate', { timeout: 15000 });
await page.waitForTimeout(4000);
step('file attached');

// Click the attachment chip to open preview
const chip = page.locator('text=spike-doc.plate').first();
await chip.click({ timeout: 15000 });
step('attachment chip clicked');
await page.waitForTimeout(6000);

// Assert our spike content rendered inside the right sidebar
const spikeText = page.locator('text=Plate spike 渲染成功').first();
const visible = await spikeText.isVisible({ timeout: 15000 }).catch(() => false);
out.editorMounted = visible;
step('editor mounted: ' + visible);

if (visible) {
  await spikeText.click();
  await page.keyboard.type('【已编辑】');
  await page.waitForTimeout(1000);
  out.edited = await page.locator('text=【已编辑】').first().isVisible().catch(() => false);
  step('typed into editor: ' + out.edited);
}
await page.screenshot({ path: '/tmp/plate-spike.png', fullPage: false });
writeFileSync('/tmp/plate-probe-result.json', JSON.stringify(out, null, 2));
console.log('RESULT', JSON.stringify({ mounted: out.editorMounted, edited: out.edited, consoleErrors: out.consoleErrors.length, pageErrors: out.pageErrors.length }));
await browser.close();

