// Control experiment: attach .md (control) + .plate (treatment) in one
// message. Click each chip. If .md opens a preview but .plate doesn't, the
// gap is registration; if neither opens, the gesture is wrong.
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { writeFileSync } from 'node:fs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const out = { steps: [], consoleErrors: [], pageErrors: [] };
const step = (s) => { out.steps.push(s); console.log('STEP', s); };

writeFileSync('/tmp/spike-doc.md', '# 对照组\n\nmarkdown 预览应打开。');
writeFileSync('/tmp/spike-doc.plate', JSON.stringify({ v: 1, text: 'spike' }));

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('console', (m) => { if (m.type() === 'error') out.consoleErrors.push(m.text().slice(0, 300)); });
page.on('pageerror', (e) => out.pageErrors.push(String(e).slice(0, 300)));

const paneState = async (label) => {
  const state = await page.evaluate(() => {
    const text = document.body.innerText;
    return {
      hasPreviewHeader: /重新载入|换行|纯文本|渲染器/.test(text),
      hasMdHeading: text.includes('对照组'),
      hasPlateSpike: text.includes('Plate spike 渲染成功'),
      hasPlainFallback: text.includes('"v": 1') || text.includes('{ "v": 1'),
    };
  });
  step(label + ': ' + JSON.stringify(state));
  return state;
};

try {
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 60000 });
  await page.waitForSelector('text=探索未至之境', { timeout: 60000 });
  await page.waitForTimeout(4000);

  // workspace gate handling (idempotent)
  const gate = page.locator('text=选择一个工作区开始').first();
  if (await gate.isVisible({ timeout: 3000 }).catch(() => false)) {
    await page.locator('text=选择工作区').first().click();
    await page.waitForTimeout(1500);
    await page.locator('[role="option"], [role="menuitem"], li').filter({ hasText: /\S/ }).first().click();
    await page.waitForTimeout(2000);
    step('workspace selected');
  }
  await page.locator(':text("新会话")').first().click({ timeout: 20000 });
  await page.waitForTimeout(3000);

  const fileInput = page.locator('input[type="file"]').first();
  await fileInput.setInputFiles(['/tmp/spike-doc.md', '/tmp/spike-doc.plate'], { timeout: 15000 });
  await page.waitForTimeout(3000);
  const composer = page.locator('[contenteditable="true"], textarea').last();
  await composer.click({ timeout: 10000 });
  await page.keyboard.type('不用处理，放着即可');
  await page.keyboard.press('Enter');
  step('sent with both attachments');
  await page.waitForTimeout(9000);

  // CONTROL: click the .md chip
  await page.locator('text=spike-doc.md').first().click({ timeout: 10000 });
  await page.waitForTimeout(8000);
  out.control = await paneState('control-md');
  await page.screenshot({ path: '/tmp/plate-control-md.png' });

  // TREATMENT: click the .plate chip
  await page.locator('text=spike-doc.plate').first().click({ timeout: 10000 });
  await page.waitForTimeout(8000);
  out.treatment = await paneState('treatment-plate');
  await page.screenshot({ path: '/tmp/plate-treatment.png' });

  console.log('RESULT', JSON.stringify({ control: out.control, treatment: out.treatment, pageErrors: out.pageErrors.length }));
} catch (e) {
  out.fatal = String(e).slice(0, 250);
  await page.screenshot({ path: '/tmp/plate-spike-fatal.png' }).catch(() => {});
  console.log('FATAL', out.fatal);
}
writeFileSync('/tmp/plate-probe-result.json', JSON.stringify(out, null, 2));
await browser.close();

