// Diagnostic: reopen session, click the rightmost topbar icon, dump what appears.
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });

await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 60000 });
await page.waitForSelector('text=探索未至之境', { timeout: 60000 });
await page.waitForTimeout(4000);
await page.locator(':text("不用处理，放着即可")').first().click({ timeout: 20000 });
await page.waitForTimeout(6000);
console.log('session reopened');

// rightmost icon button in the top strip (y < 70)
const icons = await page.locator('button').all();
const candidates = [];
for (const b of icons) {
  const box = await b.boundingBox().catch(() => null);
  if (box && box.y < 70 && box.x > 1200) candidates.push({ b, x: Math.round(box.x), y: Math.round(box.y) });
}
console.log('top-right icon buttons:', candidates.map(c => `x=${c.x}`).join(' '));
candidates.sort((a, b2) => b2.x - a.x);
await candidates[0].b.click();
await page.waitForTimeout(4000);

// dump everything that looks like a pane entry
const dump = await page.evaluate(() => {
  const els = [...document.querySelectorAll('[role="tab"], [role="button"], [role="menuitem"], a, button')]
    .filter((e) => e.offsetParent !== null)
    .map((e) => ({ tag: e.tagName, role: e.getAttribute('role'), text: (e.innerText || e.getAttribute('aria-label') || '').trim().slice(0, 40) }))
    .filter((e) => e.text);
  return els.slice(-40);
});
console.log('ENTRIES', JSON.stringify(dump, null, 1));
await page.screenshot({ path: '/tmp/plate-pane-dump.png' });
await browser.close();

