  const menuPick = page.locator('[role="menu"] :text("团队知识库"), [role="menuitem"]:has-text("团队知识库"), [role="option"]:has-text("团队知识库")').first();
  if (await menuPick.isVisible({ timeout: 2500 }).catch(() => false)) {
    await menuPick.click();
    await page.waitForTimeout(2500);
    step('workspace 团队知识库 selected from menu');
