  const icons = await page.locator('button').all();
  const candidates = [];
  for (const b of icons) {
    const box = await b.boundingBox().catch(() => null);
    if (box && box.y < 70 && box.x > 1200) candidates.push({ b, x: box.x });
  }
  candidates.sort((a, b2) => b2.x - a.x);
  step('top-right icons: ' + candidates.length);
  await candidates[0].b.click();
  await page.waitForTimeout(4000);
  step('pane toggled');

  // Boot page entry: 工作区文件
  const filesEntry = page.locator(':text("工作区文件")').first();
  await filesEntry.click({ timeout: 10000 });
  await page.waitForTimeout(5000);
  step('files tab entered');

  // Tree row → opens preview in the same pane
