  out.editorMounted = await spikeText.isVisible({ timeout: 15000 }).catch(() => false);
  step('editor mounted: ' + out.editorMounted);
  if (out.editorMounted) {
    await spikeText.click();
    await page.keyboard.type('【已编辑】');
    await page.waitForTimeout(1000);
    out.edited = await page.locator('text=【已编辑】').first().isVisible().catch(() => false);
    step('typed into editor: ' + out.edited);
  }
  await page.screenshot({ path: '/tmp/plate-spike.png' });
  console.log('RESULT', JSON.stringify({ mounted: out.editorMounted, edited: out.edited, consoleErrors: out.consoleErrors.length, pageErrors: out.pageErrors.length, firstPageError: out.pageErrors[0] }));
} catch (e) {
  out.fatal = String(e).slice(0, 250);
  await page.screenshot({ path: '/tmp/plate-spike-fatal.png' }).catch(() => {});
  out.bodyTail = await page.evaluate(() => document.body?.innerText?.slice(-500)).catch(() => 'n/a');
  console.log('FATAL', out.fatal);
