export const inject = ['llm', 'agentDefaultModel', 'connection'];  // outer: provides workdshPlate
export async function apply(ctx) {
  await ctx.plugin(PlateDocService);
  await ctx.plugin({
    name: 'workdsh-plate-connection',
    inject: ['connection', 'llm', 'agentDefaultModel', 'workdshPlate'],
    apply(connectionCtx) { registerApi(connectionCtx); },
  });
}
```
The inner plugin entry waits for workdshPlate (provided by outer before this line). The route handler moves into a function taking the inner ctx. The boot log selection probe stays in outer.

Refactor index.ts accordingly.

