// Final S4/S5 + M2 UI probe (clean rewrite):
// session → right pane → 新标签页 picker → 文件 tab → tree → spike-doc.plate
// → our documents panel mounts → 新建文档 → editor types → 保存.
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { writeFileSync } from 'node:fs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const out = { steps: [], consoleErrors: [], pageErrors: [] };
const step = (s) => { out.steps.push(s); console.log('STEP', s); };

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 2400, height: 900 } });
page.on('console', (m) => { if (m.type() === 'error') out.consoleErrors.push(m.text().slice(0, 300)); });
page.on('pageerror', (e) => out.pageErrors.push(String(e).slice(0, 300)));

try {
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForSelector('text=探索未至之境', { timeout: 90000 });
  await page.waitForTimeout(4000);

  // Workspace gate (idempotent)
  const gate = page.locator('text=选择一个工作区开始').first();
  if (await gate.isVisible({ timeout: 5000 }).catch(() => false)) {
    await page.locator('text=选择工作区').first().click();
    await page.waitForTimeout(1500);
    await page.locator('[role="option"]:has-text("团队知识库"), [role="menuitem"]:has-text("团队知识库"), li:has-text("团队知识库")').first().click({ timeout: 10000 });
    await page.waitForTimeout(2500);
    step('workspace selected');
  }

  // Reopen the existing light session
  await page.locator(':text("你好")').first().click({ timeout: 20000 });
  await page.waitForTimeout(9000);
  step('session reopened');

  // Slide the right pane in
  await page.locator('button[data-sidebar-right-toggle]').first().click({ timeout: 15000, force: true });
  await page.waitForTimeout(8000);
  step('right pane slidden in');

  // New-tab picker → 文件 tab → tree
  await page.locator('button:has-text("新标签页")').first().click({ timeout: 12000 });
  await page.waitForTimeout(3000);
  step('new-tab picker opened');
  await page.locator('[role="menuitem"]:has-text("文件"), [role="option"]:has-text("文件"), li:has-text("文件")').first().click({ timeout: 8000 });
  await page.waitForTimeout(9000);
  step('files tab opened');

  // Tree row → preview opens with OUR renderer (workdsh-plate)
  await page.locator('text=spike-doc.plate').first().click({ timeout: 12000 });
  await page.waitForTimeout(10000);
  step('file row clicked');

  // M2 UI assertions
  out.panelMounted = await page.locator('text=AI 富文本文档').first().isVisible({ timeout: 15000 }).catch(() => false);
  step('plate panel mounted: ' + out.panelMounted);
  if (out.panelMounted) {
    await page.locator('text=＋ 新建文档').first().click({ timeout: 10000 });
    await page.waitForTimeout(7000);
    out.editorMounted = await page.locator('text=加粗').first().isVisible({ timeout: 15000 }).catch(() => false);
    step('editor toolbar mounted: ' + out.editorMounted);
    if (out.editorMounted) {
      const content = page.locator('.plate-content, [data-slate-editor]').first();
      await content.click({ timeout: 8000 });
      await page.keyboard.type('S4S5 实测输入【已编辑】');
      await page.waitForTimeout(800);
      out.typed = await page.locator('text=【已编辑】').first().isVisible().catch(() => false);
      step('typed into editor: ' + out.typed);
      await page.locator('text=保存').first().click({ timeout: 8000 });
      await page.waitForTimeout(7000);
      out.saved = await page.locator('text=已保存').first().isVisible().catch(() => false);
      step('saved to revision: ' + out.saved);
    }
  }
  await page.screenshot({ path: '/tmp/plate-spike.png' });
  console.log('RESULT', JSON.stringify({ panel: out.panelMounted, editor: out.editorMounted, typed: out.typed, saved: out.saved, pageErrors: out.pageErrors.length, firstPageError: out.pageErrors[0] }));
} catch (e) {
  out.fatal = String(e).slice(0, 250);
  await page.screenshot({ path: '/tmp/plate-spike-fatal.png' }).catch(() => {});
  console.log('FATAL', out.fatal);
}
writeFileSync('/tmp/plate-probe-result.json', JSON.stringify(out, null, 2));
await browser.close();

