// Diag: after clicking 加粗, does the editor DOM contain <strong>? And what
// does the button's DOM state look like? Distinguishes mark-no-op from
// no-rerender.
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { writeFileSync } from 'node:fs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const out = { steps: [], pageErrors: [] };

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1600, height: 900 } });
page.on('pageerror', (e) => out.pageErrors.push(String(e).slice(0, 300)));

try {
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForSelector('text=探索未至之境', { timeout: 90000 });
  await page.waitForTimeout(4000);
  await page.locator(':text("Plate 文档")').first().click({ timeout: 20000 });
  await page.waitForTimeout(8000);
  await page.locator('text=＋ 新建文档').first().click({ timeout: 10000 });
  await page.waitForTimeout(7000);

  const content = page.locator('.plate-content, [data-slate-editor]').first();
  await content.click({ timeout: 8000 });
  await page.keyboard.type('bold-diag-测试文本');
  await page.keyboard.press('Meta+a');
  await page.locator('button[title="加粗"]').first().click({ timeout: 8000 });
  await page.waitForTimeout(1500);

  out.strongCount = await page.locator('.plate-content strong').count();
  out.buttonAttr = await page.locator('button[title="加粗"]').first().getAttribute('data-active');
  out.buttonOuter = (await page.locator('button[title="加粗"]').first().evaluate((e) => e.outerHTML)).slice(0, 200);
  // leaf html to see mark spans
  out.leafHtml = (await content.evaluate((e) => e.innerHTML)).slice(0, 400);
  console.log('RESULT', JSON.stringify({ ...out, pageErrors: out.pageErrors.length, firstPageError: out.pageErrors[0] }, null, 1));
} catch (e) {
  out.fatal = String(e).slice(0, 250);
  console.log('FATAL', out.fatal);
}
writeFileSync('/tmp/plate-bold-diag-result.json', JSON.stringify(out, null, 2));
await browser.close();

