Streaming client helper:

```ts
async function streamPost(endpoint: string, payload: Record<string, unknown>, onText: (delta: string) => void): Promise<void> {
  const response = await fetch('/api/workdsh-plate', { method: 'POST', credentials: 'same-origin', headers: {'content-type':'application/json'}, body: JSON.stringify({endpoint, ...payload}) });
  if (!response.ok) throw new Error('HTTP ' + response.status);
  const contentType = response.headers.get('content-type') ?? '';
  if (!contentType.includes('text/event-stream')) {
    const body = await response.json(); throw new Error(body.code ?? 'NOT_SSE');
  }
  const reader = response.body!.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    let idx;
    while ((idx = buffer.indexOf('\n\n')) >= 0) {
      const frame = buffer.slice(0, idx); buffer = buffer.slice(idx + 2);
      const line = frame.split('\n').find(l => l.startsWith('data: '));
      if (!line) continue;
      const evt = JSON.parse(line.slice(6));
      if (evt.text) onText(evt.text);
      if (evt.error) throw new Error(String(evt.error));
      // evt.done → ignore
    }
  }
}
```

