```ts
const start = async (action) => {
  const selection = editor.selection;
  const expanded = !!(selection && !editor.api.isCollapsed(selection));
  const text = expanded ? editor.api.string(selection) : editor.api.string({ anchor: editor.api.start(editor, []), focus: editor.api.end(editor, []) });
  if (!text.trim()) { setError('没有可处理的文本'); return; }
  setState({ action, busy: true, text: '', expanded, savedRange: expanded ? selection : null, error: null });
  try { await streamPost('ai-stream', { docId, action, text }, (delta) => setState(s => s ? {...s, text: s.text + delta} : s)); }
  catch (e) { setState(s => s ? {...s, error: String(e), busy: false} : s); return; }
  setState(s => s ? {...s, busy: false} : s);
}
