// M3 probe: nav → 新建文档 → type → select all → AI 润色 → streamed panel
// fills → 替换选区 → editor text equals panel text → auto rev-append (已写入并保存).
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { writeFileSync } from 'node:fs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const out = { steps: [], consoleErrors: [], pageErrors: [] };
const step = (s) => { out.steps.push(s); console.log('STEP', s); };

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1600, height: 900 } });
page.on('console', (m) => { if (m.type() === 'error') out.consoleErrors.push(m.text().slice(0, 300)); });
page.on('pageerror', (e) => out.pageErrors.push(String(e).slice(0, 300)));

try {
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForSelector('text=探索未至之境', { timeout: 90000 });
  await page.waitForTimeout(4000);
  await page.locator(':text("Plate 文档")').first().click({ timeout: 20000 });
  await page.waitForTimeout(8000);
  await page.locator('text=＋ 新建文档').first().click({ timeout: 10000 });
  await page.waitForTimeout(7000);
  step('editor open');

  const content = page.locator('.plate-content, [data-slate-editor]').first();
  await content.click({ timeout: 8000 });
  const ORIGINAL = 'M3 测试文本：人工智能正在改变世界';
  await page.keyboard.type(ORIGINAL);
  await page.waitForTimeout(500);

  // Select the whole paragraph deterministically.
  for (let i = 0; i < 30; i++) await page.keyboard.press('ArrowRight');
  for (let i = 0; i < 30; i++) await page.keyboard.press('Shift+ArrowLeft');

  // Fire AI 润色 (selection is preserved by the button's mousedown preventDefault).
  await page.locator('button[title="AI 润色"]').first().click({ timeout: 8000 });
  out.panelShown = await page.locator('.plate-ai-panel').first().isVisible({ timeout: 15000 }).catch(() => false);
  step('ai panel shown: ' + out.panelShown);

  // Stream: textarea fills while readOnly (busy), then becomes editable.
  await page.waitForFunction(() => {
    const t = document.querySelector('.plate-ai-text');
    return !!t && t.value.length > 5;
  }, { timeout: 180000 });
  step('streamed text arrived');
  await page.waitForFunction(() => {
    const t = document.querySelector('.plate-ai-text');
    return !!t && !t.readOnly;
  }, { timeout: 120000 });
  step('stream finished');
  out.aiText = (await page.locator('.plate-ai-text').first().inputValue()).trim();

  // Replace the selection with the AI result.
  await page.locator('.plate-ai-actions button:has-text("替换选区")').first().click({ timeout: 8000 });
  await page.waitForTimeout(5000);
  out.autoSaved = await page.locator('text=已写入并保存').first().isVisible({ timeout: 15000 }).catch(() => false);
  const editorText = (await content.evaluate((e) => e.innerText)).replace(/\s+/g, '').trim();
  const panelText = out.aiText.replace(/\s+/g, '').trim();
  out.replaced = editorText === panelText && editorText.length > 0;
  out.editorTextHead = editorText.slice(0, 60);
  step('auto-saved: ' + out.autoSaved + ', replaced: ' + out.replaced);

  await page.screenshot({ path: '/tmp/plate-m3.png' });
  console.log('RESULT', JSON.stringify({ panel: out.panelShown, aiTextHead: out.aiText.slice(0, 50), autoSaved: out.autoSaved, replaced: out.replaced, editorTextHead: out.editorTextHead, pageErrors: out.pageErrors.length, firstPageError: out.pageErrors[0] }));
} catch (e) {
  out.fatal = String(e).slice(0, 250);
  await page.screenshot({ path: '/tmp/plate-m3-fatal.png' }).catch(() => {});
  console.log('FATAL', out.fatal);
}
writeFileSync('/tmp/plate-m3-result.json', JSON.stringify(out, null, 2));
await browser.close();

