    anchor.href = url;
    anchor.download = `${result.doc.title.replace(/[\\/:*?"<>|]/g, '_')}.plate`;
    anchor.click();
    URL.revokeObjectURL(url);
  } catch (e) {
    setError(String(e));
  } finally {
    setBusy(false);
  }
};

