// M4 full regression: nav → 新建文档 → type/save → 加粗(选区) →
// AI 润色 → 替换选区 → collapse → AI 缩写 → 插入文末 → 导出 .plate download.
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { writeFileSync } from 'node:fs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const out = { steps: [], consoleErrors: [], pageErrors: [] };
const step = (s) => { out.steps.push(s); console.log('STEP', s); };

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1600, height: 900 } });
page.on('console', (m) => { if (m.type() === 'error') out.consoleErrors.push(m.text().slice(0, 300)); });
page.on('pageerror', (e) => out.pageErrors.push(String(e).slice(0, 300)));

const aiTextArea = page.locator('.plate-ai-text').first();
const waitStreamDone = async () => {
  await page.waitForFunction(() => {
    const t = document.querySelector('.plate-ai-text');
    return !!t && t.value.length > 5;
  }, { timeout: 180000 });
  await page.waitForFunction(() => {
    const t = document.querySelector('.plate-ai-text');
    return !!t && !t.readOnly;
  }, { timeout: 120000 });
};

try {
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForSelector('text=探索未至之境', { timeout: 90000 });
  await page.waitForTimeout(4000);
  await page.locator(':text("Plate 文档")').first().click({ timeout: 20000 });
  await page.waitForTimeout(8000);
  await page.locator('text=＋ 新建文档').first().click({ timeout: 10000 });
  await page.waitForTimeout(7000);
  step('editor open');

  const content = page.locator('.plate-content, [data-slate-editor]').first();
  await content.click({ timeout: 8000 });
  const ORIGINAL = 'M4 全量验证：人工智能正在改变世界';
  await page.keyboard.type(ORIGINAL);
  await page.waitForTimeout(500);
  await page.locator('text=保存').first().click({ timeout: 8000 });
  await page.waitForTimeout(6000);
  out.saved = await page.locator('text=已保存').first().isVisible().catch(() => false);
  step('type+save: ' + out.saved);

  // 1) Marks: select all, bold.
  for (let i = 0; i < 40; i++) await page.keyboard.press('ArrowRight');
  for (let i = 0; i < 40; i++) await page.keyboard.press('Shift+ArrowLeft');
  await page.locator('button[title="加粗"]').first().click({ timeout: 8000 });
  await page.waitForTimeout(1000);
  out.boldActive = await page.locator('button[title="加粗"][data-active="true"]').count();
  out.strongText = (await content.locator('strong').first().innerText().catch(() => '')).trim();
  step('bold: ' + (out.boldActive > 0) + ' strong="' + out.strongText.slice(0, 20) + '"');

  // 2) AI 润色 on the still-selected text → 替换选区.
  await page.locator('button[title="AI 润色"]').first().click({ timeout: 8000 });
  await waitStreamDone();
  out.polishText = (await aiTextArea.inputValue()).trim();
