            scope: 'session';
            owner: DocumentBodyOwner;
            hookContext: UseSidebarRightTabInfo;
            inject: {
                hooks: {
                    tabInfo: SlotHookFactory<'sidebar.right.tab.document', UseSidebarRightTabInfo>;
                };

