The pattern is completely clear now — `DocumentPreviewProps` from `@deepseek-ai/dsh-client-ui-sidebar-documentpreview/client`:
- `props.content` — DocumentContent (kind 'bytes' with data: Uint8Array for our loading mode)
- `props.resourceAddress` — file address
- `props.useTabInfo()` — tab info hook
- `props.sessionId`
- extra injects via slot register `inject: () => ({...})` merged into props

Our plate fix for #26:

```tsx
// sidebar.right.tab.document keyed slot: renderer for .plate files.
ctx.slots.inject('sidebar.right.tab.document', () =>
  ctx.slots.register(
    { name: 'sidebar.right.tab.document', key: 'workdsh-plate' },
    PlateFilePreview,
  ),
);
```

Wait — but currently the SAME key is registered with PlateDocumentsPanel. The keyed slot key 'workdsh-plate' matches the definition id 'workdsh-plate' — the preview owner mounts the component registered under that key. Our previous registration put PlateDocumentsPanel there (wrong component for preview surface). Fix: register PlateFilePreview under the key.

PlateFilePreview:
```tsx
function PlateFilePreview(props: DocumentPreviewProps) {
  const [parsed, setParsed] = useState<{title: string; content: SlateContent} | null>(null);
  const [error, setError] = useState('');
  const [imported, setImported] = useState<string | null>(null); // docId
  const [importing, setImporting] = useState(false);
  const bytes = props.content.kind === 'bytes' ? props.content.data : null;
  useEffect(() => {
    setError(''); setParsed(null); setImported(null);
    if (!bytes) return;
    try {
      const decoder = new TextDecoder();
      const doc = JSON.parse(decoder.decode(bytes));
      if (doc?.format !== 'workdsh-plate' || !Array.isArray(doc.content)) throw new Error('不是有效的 workdsh-plate 文件');
      setParsed({ title: typeof doc.title === 'string' ? doc.title : (decodeURIComponent(props.resourceAddress).split('/').pop() ?? '未命名'), content: doc.content });
    } catch (e) { setError(e instanceof Error ? e.message : String(e)); }
  }, [bytes, props.resourceAddress]);
  const doImport = async () => { if (!parsed) return; setImporting(true);
    try { const r = await post<{doc: DocMeta}>('doc-import', {title: parsed.title, content: parsed.content}); setImported(r.doc.id); }
    catch(e){ setError(String(e)); } finally { setImporting(false); }
  };
  return (
    <div className="plate-file-preview">
      {error ? <div className="plate-error">{error}</div> : null}
      {parsed ? (
        <>
          <div className="plate-file-head">
            <span className="plate-doc-title">{parsed.title}</span>
            <button className="plate-import-btn" disabled={importing} onClick={() => void doImport()}>
              {importing ? '导入中…' : imported ? '已导入到 Plate 文档' : '导入到 Plate 文档'}
            </button>
          </div>
          <PlateReadOnly content={parsed.content} />
        </>
      ) : error ? null : <div className="plate-empty">正在解析文件…</div>}
    </div>
  );
}
```

