// S5-b probe: workspace gate → session → right pane slide-in → Files tree →
// click S5B-plate探针.plate → OUR renderer mounts (title/content visible) →
// 导入到 Plate 文档 → left-nav Plate 文档 lists the imported doc.
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { writeFileSync } from 'node:fs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const out = { steps: [], consoleErrors: [], pageErrors: [] };
const step = (s) => { out.steps.push(s); console.log('STEP', s); };

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 2400, height: 900 } });
page.on('console', (m) => { if (m.type() === 'error') out.consoleErrors.push(m.text().slice(0, 300)); });
page.on('pageerror', (e) => out.pageErrors.push(String(e).slice(0, 300)));

try {
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForSelector('text=探索未至之境', { timeout: 90000 });
  await page.waitForTimeout(4000);

  const gate = page.locator('text=选择一个工作区开始').first();
  if (await gate.isVisible({ timeout: 5000 }).catch(() => false)) {
    await page.locator('text=选择工作区').first().click();
    await page.waitForTimeout(1500);
    await page.locator('[role="option"]:has-text("团队知识库"), [role="menuitem"]:has-text("团队知识库"), li:has-text("团队知识库")').first().click({ timeout: 10000 });
    await page.waitForTimeout(2500);
    step('workspace selected');
  }
  await page.locator(':text("你好")').first().click({ timeout: 20000 });
  await page.waitForTimeout(9000);
  step('session reopened');

  await page.locator('button[data-sidebar-right-toggle]').first().click({ timeout: 15000, force: true });
  await page.waitForTimeout(8000);
  step('right pane slidden in');

  const dumpPane = () => page.evaluate(() => {
    const pane = [...document.querySelectorAll('section, aside, [class*="pane" i]')]
      .map((el) => ({ el, r: el.getBoundingClientRect() }))
      .filter((x) => x.r.x > 850 && x.r.width > 100 && x.r.height > 100)
      .sort((a, b) => b.r.width - a.r.width)[0];
    if (!pane) return { none: true };
    return {
      text: pane.el.innerText.slice(0, 150),
      buttons: [...pane.el.querySelectorAll('button')].map((b) => (b.innerText || '').trim().slice(0, 20)).filter(Boolean).slice(0, 12),
    };
  });

  let treeReady = await page.locator('text=S5B-plate探针.plate').first().isVisible({ timeout: 4000 }).catch(() => false);
  for (let attempt = 0; attempt < 3 && !treeReady; attempt++) {
    const pane = await dumpPane();
    step(`attempt ${attempt} pane: ${JSON.stringify(pane).slice(0, 200)}`);
    if (pane.buttons?.includes('新标签页')) {
      await page.locator('button:has-text("新标签页")').first().click({ timeout: 12000, force: true });
      await page.waitForTimeout(3000);
      await page.locator('[role="menuitem"]:has-text("文件"), [role="option"]:has-text("文件"), li:has-text("文件")').first().click({ timeout: 8000 }).catch(() => {});
      await page.waitForTimeout(10000);
      treeReady = await page.locator('text=S5B-plate探针.plate').first().isVisible({ timeout: 20000 }).catch(() => false);
      step('picker path result: ' + treeReady);
    } else if (pane.buttons && pane.buttons.length === 0 && (pane.text ?? '') === '') {
      // Right pane seems collapsed/absent: toggle slide-in again and retry.
      await page.locator('button[data-sidebar-right-toggle]').first().click({ timeout: 10000, force: true }).catch(() => {});
      await page.waitForTimeout(8000);
      treeReady = await page.locator('text=S5B-plate探针.plate').first().isVisible({ timeout: 8000 }).catch(() => false);
      step('re-toggle result: ' + treeReady);
    } else {
      const clicked = await page.evaluate(() => {
        const leaves = [...document.querySelectorAll('*')].filter((e) => e.children.length === 0 && (e.textContent || '').trim() === '文件');
        const el = leaves.find((e) => { const r = e.getBoundingClientRect(); return r.x > 880 && r.y < 100 && r.width > 0; });
        if (el) { el.click(); return true; }
        return false;
      });
      step('geometry click: ' + clicked);
      await page.waitForTimeout(10000);
      treeReady = await page.locator('text=S5B-plate探针.plate').first().isVisible({ timeout: 20000 }).catch(() => false);
      step('geometry result: ' + treeReady);
    }
  }
  if (!treeReady) {
    out.paneDump = await dumpPane();
    throw new Error('files tree row never appeared; final pane: ' + JSON.stringify(out.paneDump).slice(0, 300));
  }

  await page.locator('text=S5B-plate探针.plate').first().click({ timeout: 12000 });
  await page.waitForTimeout(12000);
  step('file row clicked');

  // Renderer assertions: our PlateFilePreview parsed the bytes and rendered.
  out.renderTitle = await page.locator('text=S5B 文件打开路径实测').first().isVisible({ timeout: 20000 }).catch(() => false);
  out.renderBody = await page.locator('text=从 Files 树点击本文件应渲染此内容').first().isVisible({ timeout: 15000 }).catch(() => false);
  step('renderer mounted: title=' + out.renderTitle + ' body=' + out.renderBody);

  // Import into the Plate docs domain.
  const importBtn = page.locator('button.plate-import-btn').first();
  out.importBtn = await importBtn.isVisible({ timeout: 10000 }).catch(() => false);
  if (out.importBtn) {
    await importBtn.click({ timeout: 8000 });
    await page.waitForTimeout(6000);
    out.imported = await page.locator('text=已导入到 Plate 文档').first().isVisible({ timeout: 15000 }).catch(() => false);
    step('import clicked: ' + out.imported);
  }

  // Cross-check via the left-nav panel: imported doc listed.
  await page.locator(':text("Plate 文档")').first().click({ timeout: 20000 });
  await page.waitForTimeout(8000);
  out.listed = await page.locator('text=S5B 探针文档').first().isVisible({ timeout: 15000 }).catch(() => false);
  step('imported doc listed in panel: ' + out.listed);

  await page.screenshot({ path: '/tmp/plate-s5b.png' });
  console.log('RESULT', JSON.stringify({ renderTitle: out.renderTitle, renderBody: out.renderBody, importBtn: out.importBtn, imported: out.imported, listed: out.listed, pageErrors: out.pageErrors.length, firstPageError: out.pageErrors[0] }));
} catch (e) {
  out.fatal = String(e).slice(0, 250);
  await page.screenshot({ path: '/tmp/plate-s5b-fatal.png' }).catch(() => {});
  console.log('FATAL', out.fatal);
}
writeFileSync('/tmp/plate-s5b-result.json', JSON.stringify(out, null, 2));
await browser.close();

