    await page.waitForTimeout(2500);
    step('workspace selected');
  }
  await page.locator(':text("你好")').first().click({ timeout: 20000 });
  await page.waitForTimeout(9000);
  step('session reopened');

  const paneHas = async (label) => {
    const found = await page.evaluate((l) => {
      const regions = [...document.querySelectorAll('section, aside, [class*="pane" i]')]
        .map((el) => ({ el, r: el.getBoundingClientRect() }))
        .filter((x) => x.r.x > 850 && x.r.width > 100 && x.r.height > 100)
        .sort((a, b) => b.r.width - a.r.width)[0];
      if (!regions) return false;
      return [...regions.el.querySelectorAll('button')].some((b) => (b.innerText || '').includes(l));
    }, label);
    return found;
  };

  // State-aware loop: the toggle is a real toggle and the pane's initial
  // slide state varies per session; flip it until the tab strip shows up.
  let treeReady = await page.locator('text=S5B-plate探针.plate').first().isVisible({ timeout: 4000 }).catch(() => false);
