import { defineDomain, domainTable, type KvTable } from '@deepseek-ai/dsh-storage-domain';
import { z } from 'zod';

const bounded = z.string().min(1).max(256).refine((value) => !/[�-]/.test(value));
const id = z.string().min(8).max(64).regex(/^[a-zA-Z0-9_-]+$/);
const slateNode: z.ZodType<unknown> = z.lazy(() =>
  z.object({}).catchall(z.unknown()),
);
export const slateJson = z
  .array(z.object({ type: z.string().optional(), children: z.array(slateNode), text: z.string().optional() }).passthrough())
  .min(1)
  .max(10000);

export const documentSchema = z.object({
  id: id,
  title: bounded,
  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
  headRevId: id,
});

export const revisionSchema = z.object({
  revId: id,
  docId: id,
  seq: z.number().int().nonnegative(),
  createdAt: z.string().datetime(),
  cause: z.enum(['create', 'edit', 'ai', 'import']),
  slateJson,
});

export type PlateDocument = z.infer<typeof documentSchema>;
export type PlateRevision = z.infer<typeof revisionSchema>;

export const plateDomainSpec = defineDomain({
  name: 'workdsh_plate',
  version: 1,
  layout: 'per-record',
  tables: {
    documents: domainTable<string, PlateDocument>(documentSchema),
    revisions: domainTable<string, PlateRevision>(revisionSchema),
  },
});

export interface PlateStore {
  documents: KvTable<string, PlateDocument>;
  revisions: KvTable<string, PlateRevision>;
}

