// M5 probe: nav → 新建文档 → type → 插图 (setInputFiles on the hidden
// input) → <img src^="data:image"> in the editor → 保存 → saved.
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { writeFileSync } from 'node:fs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const out = { steps: [], consoleErrors: [], pageErrors: [] };
const step = (s) => { out.steps.push(s); console.log('STEP', s); };

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1600, height: 900 } });
page.on('console', (m) => { if (m.type() === 'error') out.consoleErrors.push(m.text().slice(0, 300)); });
page.on('pageerror', (e) => out.pageErrors.push(String(e).slice(0, 300)));

try {
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForSelector('text=探索未至之境', { timeout: 90000 });
  await page.waitForTimeout(4000);
  await page.locator(':text("Plate 文档")').first().click({ timeout: 20000 });
  await page.waitForTimeout(8000);
  await page.locator('text=＋ 新建文档').first().click({ timeout: 10000 });
  await page.waitForTimeout(7000);
  step('editor open');

  const content = page.locator('.plate-content, [data-slate-editor]').first();
  await content.click({ timeout: 8000 });
  await page.keyboard.type('M5 图片测试');
  await page.waitForTimeout(500);

  // Insert image through the hidden file input (same pipeline as the 插图 button).
  await page.locator('input[data-plate-file-input="true"]').first().setInputFiles('/tmp/test-image.png');
  await page.waitForTimeout(3000);
  out.statusText = (await page.locator('.plate-image-status').first().innerText().catch(() => '')).trim();
  out.imgCount = await content.locator('img').count();
  out.imgSrc = (await content.locator('img').first().getAttribute('src').catch(() => ''))?.slice(0, 30);
  step(`image inserted: count=${out.imgCount}, status="${out.statusText}", src=${out.imgSrc}`);

  await page.locator('text=保存').first().click({ timeout: 8000 });
  await page.waitForTimeout(7000);
  out.saved = await page.locator('text=已保存').first().isVisible().catch(() => false);
  step('saved: ' + out.saved);

  await page.screenshot({ path: '/tmp/plate-m5.png' });
  console.log('RESULT', JSON.stringify({ imgCount: out.imgCount, imgDataUrl: out.imgSrc?.startsWith('data:image'), statusText: out.statusText, saved: out.saved, pageErrors: out.pageErrors.length, firstPageError: out.pageErrors[0] }));
} catch (e) {
  out.fatal = String(e).slice(0, 250);
  await page.screenshot({ path: '/tmp/plate-m5-fatal.png' }).catch(() => {});
  console.log('FATAL', out.fatal);
}
writeFileSync('/tmp/plate-m5-result.json', JSON.stringify(out, null, 2));
await browser.close();

import { defineDomain, domainTable, type KvTable } from '@deepseek-ai/dsh-storage-domain';
import { z } from 'zod';

const bounded = z.string().min(1).max(256).refine((value) => !/[�-]/.test(value));
const id = z.string().min(8).max(64).regex(/^[a-zA-Z0-9_-]+$/);
const slateNode: z.ZodType<unknown> = z.lazy(() =>
  z.object({}).catchall(z.unknown()),
);
export const slateJson = z
  .array(z.object({ type: z.string().optional(), children: z.array(slateNode), text: z.string().optional() }).passthrough())
  .min(1)
  .max(10000)
  // 内嵌图片走 data URL：单次修订总字节封顶，防爆库（≈3 张 1.5MB 图）。
  .refine((value) => JSON.stringify(value).length <= 6_000_000, {
    message: '文档内容超过 6MB 上限（内嵌图片请压缩）',
  });

export const documentSchema = z.object({
  id: id,
  title: bounded,
  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
  headRevId: id,
});

export const revisionSchema = z.object({
  revId: id,
  docId: id,
  seq: z.number().int().nonnegative(),
  createdAt: z.string().datetime(),
  cause: z.enum(['create', 'edit', 'ai', 'import']),
  slateJson,
});

export type PlateDocument = z.infer<typeof documentSchema>;
export type PlateRevision = z.infer<typeof revisionSchema>;

export const plateDomainSpec = defineDomain({
  name: 'workdsh_plate',
  version: 1,
  layout: 'per-record',
  tables: {
    documents: domainTable<string, PlateDocument>(documentSchema),
    revisions: domainTable<string, PlateRevision>(revisionSchema),
  },
});

export interface PlateStore {
  documents: KvTable<string, PlateDocument>;
  revisions: KvTable<string, PlateRevision>;
}

// S5-b probe: workspace gate → session → right pane slide-in → Files tree →
// click S5B-plate探针.plate → OUR renderer mounts (title/content visible) →
// 导入到 Plate 文档 → left-nav Plate 文档 lists the imported doc.
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { writeFileSync } from 'node:fs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const out = { steps: [], consoleErrors: [], pageErrors: [] };
const step = (s) => { out.steps.push(s); console.log('STEP', s); };

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 2400, height: 900 } });
page.on('console', (m) => { if (m.type() === 'error') out.consoleErrors.push(m.text().slice(0, 300)); });
page.on('pageerror', (e) => out.pageErrors.push(String(e).slice(0, 300)));

try {
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForSelector('text=探索未至之境', { timeout: 90000 });
  await page.waitForTimeout(4000);

  const gate = page.locator('text=选择一个工作区开始').first();
  if (await gate.isVisible({ timeout: 5000 }).catch(() => false)) {
    await page.locator('text=选择工作区').first().click();
    await page.waitForTimeout(1500);
    await page.locator('[role="option"]:has-text("团队知识库"), [role="menuitem"]:has-text("团队知识库"), li:has-text("团队知识库")').first().click({ timeout: 10000 });
    await page.waitForTimeout(2500);
    step('workspace selected');
  }
  await page.locator(':text("你好")').first().click({ timeout: 20000 });
  await page.waitForTimeout(9000);
  step('session reopened');

  // Diag-proven recipe: one click on data-sidebar-right-toggle slides the
  // pane in and exposes the 新标签页 strip button; drive by text, not region.
  const stripBtn = page.locator('button:has-text("新标签页")').first();
  let treeReady = await page.locator('text=S5B-plate探针.plate').first().isVisible({ timeout: 4000 }).catch(() => false);
  for (let attempt = 0; attempt < 4 && !treeReady; attempt++) {
    if (await stripBtn.isVisible({ timeout: 4000 }).catch(() => false)) {
      await stripBtn.click({ timeout: 12000, force: true });
      await page.waitForTimeout(3000);
      await page.locator('[role="menuitem"]:has-text("文件"), [role="option"]:has-text("文件"), li:has-text("文件")').first().click({ timeout: 8000 }).catch(() => {});
      await page.waitForTimeout(10000);
      treeReady = await page.locator('text=S5B-plate探针.plate').first().isVisible({ timeout: 20000 }).catch(() => false);
      step(`attempt ${attempt}: picker path, tree=${treeReady}`);
    } else {
      await page.locator('button[data-sidebar-right-toggle]').first().click({ timeout: 10000, force: true }).catch(() => {});
      await page.waitForTimeout(10000);
      treeReady = await page.locator('text=S5B-plate探针.plate').first().isVisible({ timeout: 6000 }).catch(() => false);
      const rightButtons = await page.evaluate(() =>
        [...document.querySelectorAll('button')]
          .map((b) => { const r = b.getBoundingClientRect(); return { x: Math.round(r.x), text: (b.innerText || b.title || '').trim().slice(0, 16) }; })
          .filter((x) => x.x > 1200 && x.text)
          .slice(0, 12),
      );
      step(`attempt ${attempt}: toggled, tree=${treeReady}, strip=${await stripBtn.isVisible({ timeout: 3000 }).catch(() => false)}, rightButtons=${JSON.stringify(rightButtons)}`);
    }
  }
  if (!treeReady) {
    throw new Error('files tree row never appeared after 4 attempts');
  }

  await page.locator('text=S5B-plate探针.plate').first().click({ timeout: 12000 });
  await page.waitForTimeout(12000);
  step('file row clicked');

  // Renderer assertions: our PlateFilePreview parsed the bytes and rendered.
  out.renderTitle = await page.locator('text=S5B 文件打开路径实测').first().isVisible({ timeout: 20000 }).catch(() => false);
  out.renderBody = await page.locator('text=从 Files 树点击本文件应渲染此内容').first().isVisible({ timeout: 15000 }).catch(() => false);
  step('renderer mounted: title=' + out.renderTitle + ' body=' + out.renderBody);

  // Import into the Plate docs domain.
  const importBtn = page.locator('button.plate-import-btn').first();
  out.importBtn = await importBtn.isVisible({ timeout: 10000 }).catch(() => false);
  if (out.importBtn) {
    await importBtn.click({ timeout: 8000 });
    await page.waitForTimeout(6000);
    out.imported = await page.locator('text=已导入到 Plate 文档').first().isVisible({ timeout: 15000 }).catch(() => false);
    step('import clicked: ' + out.imported);
  }

  // Cross-check via the left-nav panel: imported doc listed.
  await page.locator(':text("Plate 文档")').first().click({ timeout: 20000 });
  await page.waitForTimeout(8000);
  out.listed = await page.locator('text=S5B 探针文档').first().isVisible({ timeout: 15000 }).catch(() => false);
  step('imported doc listed in panel: ' + out.listed);

  await page.screenshot({ path: '/tmp/plate-s5b.png' });
  console.log('RESULT', JSON.stringify({ renderTitle: out.renderTitle, renderBody: out.renderBody, importBtn: out.importBtn, imported: out.imported, listed: out.listed, pageErrors: out.pageErrors.length, firstPageError: out.pageErrors[0] }));
} catch (e) {
  out.fatal = String(e).slice(0, 250);
  await page.screenshot({ path: '/tmp/plate-s5b-fatal.png' }).catch(() => {});
  console.log('FATAL', out.fatal);
}
writeFileSync('/tmp/plate-s5b-result.json', JSON.stringify(out, null, 2));
await browser.close();

