1	import { useEffect, useRef, useState } from 'react';
2	import type { ChangeEvent, ClipboardEvent } from 'react';
3	import type { Context } from '@deepseek-ai/cordis';
4	import type {} from '@deepseek-ai/dsh-client-ui-renderer/client';
5	import type {} from '@deepseek-ai/dsh-client-ui-sidebar/client';
6	import type { DocumentPreviewProps } from '@deepseek-ai/dsh-client-ui-sidebar-documentpreview/client';
7	import type {} from '@deepseek-ai/dsh-client-ui-sidebar-right/client';
8	import { createPlateEditor, Plate, PlateContent, PlateElement, useEditorVersion } from 'platejs/react';
9	import type { PlateEditor } from 'platejs/react';
10	import {
11	  BaseBasicMarksPlugin,
12	  BaseBasicBlocksPlugin,
13	  BaseBoldPlugin,
14	  BaseItalicPlugin,
15	  BaseUnderlinePlugin,
16	  BaseStrikethroughPlugin,
17	  BaseCodePlugin,
18	  BaseHeadingPlugin,
19	  BaseBlockquotePlugin,
20	  BaseHorizontalRulePlugin,
21	} from '@platejs/basic-nodes';
22	import { insertImage } from '@platejs/media';
23	// v53 渲染挂载 = plugin.withComponent(组件)（core docstring 官方范式），
24	// 不是 render 字段；Image primitive 从 ElementProvider 上下文读 url。
25	import { Image, ImagePlugin } from '@platejs/media/react';
26	
27	const ImageElement = (props: { element: { url?: string }; children?: unknown }) => (
28	  <PlateElement {...props}>
29	    <Image />
30	    {props.children as never}
31	  </PlateElement>
32	);
33	
34	const ImageElementPlugin = ImagePlugin.withComponent(ImageElement as never);
35	
36	export const name = 'workdsh-plate-client';
37	export const inject = ['slots', 'documentPreviews'];
38	
39	const plugins = [
40	  BaseBasicMarksPlugin,
41	  BaseBasicBlocksPlugin,
42	  BaseBoldPlugin,
43	  BaseItalicPlugin,
44	  BaseUnderlinePlugin,
45	  BaseStrikethroughPlugin,
46	  BaseCodePlugin,
47	  BaseHeadingPlugin,
48	  BaseBlockquotePlugin,
49	  BaseHorizontalRulePlugin,
50	  ImageElementPlugin,
51	];
52	
53	type SlateContent = { type?: string; text?: string; children: unknown[] }[];
54	
55	async function post<T>(endpoint: string, payload: Record<string, unknown> = {}): Promise<T> {
56	  const response = await fetch('/api/workdsh-plate', {
57	    method: 'POST',
58	    credentials: 'same-origin',
59	    headers: { 'content-type': 'application/json' },
60	    body: JSON.stringify({ endpoint, ...payload }),
61	  });
62	  const body = await response.json();
63	  if (!response.ok || !body.ok) throw new Error(body.code ?? String(response.status));
64	  return body as T;
65	}
66	
67	// SSE variant of post(): consumes data: frames, feeding text deltas to
68	// onText; throws on an error frame or a non-SSE (JSON) response.
69	async function streamPost(
70	  endpoint: string,
71	  payload: Record<string, unknown>,
72	  onText: (delta: string) => void,
73	): Promise<void> {
74	  const response = await fetch('/api/workdsh-plate', {
75	    method: 'POST',
76	    credentials: 'same-origin',
77	    headers: { 'content-type': 'application/json' },
78	    body: JSON.stringify({ endpoint, ...payload }),
79	  });
80	  const contentType = response.headers.get('content-type') ?? '';
81	  if (!contentType.includes('text/event-stream')) {
82	    const body = await response.json().catch(() => null);
83	    throw new Error(body?.code ?? `HTTP ${response.status}`);
84	  }
85	  const reader = response.body!.getReader();
86	  const decoder = new TextDecoder();
87	  let buffer = '';
88	  for (;;) {
89	    const { done, value } = await reader.read();
90	    if (done) break;
91	    buffer += decoder.decode(value, { stream: true });
92	    let boundary = buffer.indexOf('\n\n');
93	    while (boundary >= 0) {
94	      const frame = buffer.slice(0, boundary);
95	      buffer = buffer.slice(boundary + 2);
96	      const dataLine = frame.split('\n').find((line) => line.startsWith('data: '));
97	      if (dataLine) {
98	        const event = JSON.parse(dataLine.slice(6)) as { text?: string; error?: string };
99	        if (event.error) throw new Error(event.error);
100	        if (event.text) onText(event.text);
101	      }
102	      boundary = buffer.indexOf('\n\n');
103	    }
104	  }
105	}
106	
107	type DocMeta = { id: string; title: string; updatedAt: string };
108	
109	const emptyContent: SlateContent = [{ type: 'p', children: [{ text: '' }] }];
110	
111	function ToolbarButton(props: { label: string; active?: boolean; onClick: () => void }) {
112	  return (
113	    <button
114	      type="button"
115	      className="plate-toolbar-btn"
116	      data-active={props.active ? 'true' : undefined}
117	      onMouseDown={(event) => { event.preventDefault(); props.onClick(); }}
118	      title={props.label}
119	    >
120	      {props.label}
121	    </button>
122	  );
123	}
124	
125	// S5-b：.plate 文件打开路径。documentPreviews 声明由预览 owner 按扩展名
126	// 路由到本组件（keyed slot key === definition id），content.kind 'bytes'
127	// 时拿到完整文件字节；解析后只读渲染 + 一键导入到 Plate 文档域。
128	function PlateReadOnly(props: { content: SlateContent }) {
129	  const editor = useState(() => createPlateEditor({ plugins, value: props.content }))[0];
130	  return (
131	    <div className="plate-file-body">
132	      <Plate editor={editor}>
133	        <PlateContent readOnly className="plate-content" />
134	      </Plate>
135	    </div>
136	  );
137	}
138	
139	function PlateFilePreview(props: DocumentPreviewProps) {
140	  const [parsed, setParsed] = useState<{ title: string; content: SlateContent } | null>(null);
141	  const [error, setError] = useState('');
142	  const [importing, setImporting] = useState(false);
143	  const [imported, setImported] = useState<string | null>(null);
144	  const bytes = props.content.kind === 'bytes' ? props.content.data : null;
145	
146	  useEffect(() => {
147	    setError('');
148	    setParsed(null);
149	    setImported(null);
150	    if (!bytes) return;
151	    try {
152	      const doc = JSON.parse(new TextDecoder().decode(bytes)) as {
153	        format?: string; title?: string; content?: SlateContent;
154	      };
155	      if (doc.format !== 'workdsh-plate' || !Array.isArray(doc.content)) {
156	        throw new Error('不是有效的 workdsh-plate 文件');
157	      }
158	      const name = decodeURIComponent(props.resourceAddress).split('/').pop()?.split(/[?#]/)[0] ?? '未命名';
159	      setParsed({
160	        title: typeof doc.title === 'string' && doc.title.trim() ? doc.title : name.replace(/\.plate$/i, ''),
161	        content: doc.content,
162	      });
163	    } catch (e) {
164	      setError(e instanceof Error ? e.message : String(e));
165	    }
166	  }, [bytes, props.resourceAddress]);
167	
168	  const doImport = async () => {
169	    if (!parsed || importing) return;
170	    setImporting(true);
171	    try {
172	      const result = await post<{ doc: DocMeta }>('doc-import', { title: parsed.title, content: parsed.content });
173	      setImported(result.doc.id);
174	    } catch (e) {
175	      setError(String(e));
176	    } finally {
177	      setImporting(false);
178	    }
179	  };
180	
181	  return (
182	    <div className="plate-file-preview">
183	      {error ? <div className="plate-error">{error}</div> : null}
184	      {parsed ? (
185	        <>
186	          <div className="plate-file-head">
187	            <span className="plate-doc-title">{parsed.title}</span>
188	            <button type="button" className="plate-import-btn" disabled={importing || !!imported} onClick={() => void doImport()}>
189	              {importing ? '导入中…' : imported ? '已导入到 Plate 文档' : '导入到 Plate 文档'}
190	            </button>
191	          </div>
192	          <PlateReadOnly content={parsed.content} />
193	        </>
194	      ) : error ? null : (
195	        <div className="plate-empty">在文件列表中选择一个 .plate 文件查看内容。</div>
196	      )}
197	    </div>
198	  );
199	}
200	
201	// 汉化层 + M3：AI 动作菜单（润色/续写/扩写/缩写/纠错/翻译），全走
202	// ctx.llm.stream（/api/workdsh-plate ai-stream），遵循 agent-default-model。
203	const AI_ACTIONS = [
204	  { key: 'polish', label: '润色' },
205	  { key: 'continue', label: '续写' },
206	  { key: 'expand', label: '扩写' },
207	  { key: 'condense', label: '缩写' },
208	  { key: 'proofread', label: '纠错' },
209	  { key: 'translate', label: '翻译' },
210	] as const;
211	
212	type AiActionKey = (typeof AI_ACTIONS)[number]['key'];
213	
214	function PlateAiSection(props: { editor: PlateEditor; docId: string }) {
215	  const { editor, docId } = props;
216	  const [state, setState] = useState<{
217	    action: AiActionKey;
218	    busy: boolean;
219	    text: string;
220	    expanded: boolean;
221	    savedRange: typeof editor.selection;
222	    inserted: boolean;
223	    error: string | null;
224	  } | null>(null);
225	
226	  const start = async (action: AiActionKey) => {
227	    // Selection is still live here: the buttons preventDefault on mousedown.
228	    const selection = editor.selection;
229	    const expanded = !!selection && !editor.api.isCollapsed(selection);
230	    const text = expanded
231	      ? editor.api.string(selection)
232	      : editor.api.string({ anchor: editor.api.start(editor, []), focus: editor.api.end(editor, []) });
233	    if (!text.trim()) {
234	      setState({ action, busy: false, text: '', expanded, savedRange: expanded ? selection : null, inserted: false, error: '没有可处理的文本，请先输入内容。' });
235	      return;
236	    }
237	    setState({ action, busy: true, text: '', expanded, savedRange: expanded ? selection : null, inserted: false, error: null });
238	    try {
239	      await streamPost('ai-stream', { docId, action, text }, (delta) => {
240	        setState((prev) => (prev ? { ...prev, text: prev.text + delta } : prev));
241	      });
242	      setState((prev) => (prev ? { ...prev, busy: false } : prev));
243	    } catch (error) {
244	      setState((prev) => (prev ? { ...prev, busy: false, error: String(error) } : prev));
245	    }
246	  };
247	
248	  const insert = async () => {
249	    if (!state || state.busy || !state.text) return;
250	    if (state.expanded && state.savedRange) {
251	      editor.tf.select(state.savedRange);
252	      editor.tf.insertText(state.text);
253	    } else {
254	      editor.tf.select(editor.api.end(editor, []));
255	      editor.tf.insertText(`\n${state.text}`);
256	    }
257	    // AI 修改同样进入修订链，cause='ai' 与手动编辑区分。
258	    try {
259	      await post('rev-append', { docId, content: editor.children, cause: 'ai' });
260	      setState((prev) => (prev ? { ...prev, inserted: true } : prev));
261	    } catch (error) {
262	      setState((prev) => (prev ? { ...prev, error: String(error) } : prev));
263	    }
264	  };
265	
266	  const busyLabel = state?.busy ? `${AI_ACTIONS.find((a) => a.key === state.action)?.label}中…` : null;
267	
268	  return (
269	    <>
270	      {AI_ACTIONS.map((a) => (
271	        <button
272	          key={a.key}
273	          type="button"
274	          className="plate-ai-btn"
275	          disabled={state?.busy}
276	          onMouseDown={(event) => { event.preventDefault(); void start(a.key); }}
277	          title={`AI ${a.label}`}
278	        >
279	          {state?.busy && state.action === a.key ? '…' : a.label}
280	        </button>
281	      ))}
282	      {state ? (
283	        <div className="plate-ai-panel">
284	          {busyLabel ? <div className="plate-ai-status">{busyLabel}</div> : null}
285	          {state.error ? <div className="plate-error">{state.error}</div> : null}
286	          <textarea
287	            className="plate-ai-text"
288	            value={state.text}
289	            readOnly={state.busy}
290	            placeholder={state.busy ? 'AI 正在生成…' : 'AI 生成结果（可编辑后再写入）'}
291	            onChange={(event) => setState((prev) => (prev ? { ...prev, text: event.target.value, inserted: false } : prev))}
292	          />
293	          <div className="plate-ai-actions">
294	            <button type="button" disabled={state.busy || !state.text} onClick={() => void insert()}>
295	              {state.expanded ? '替换选区' : '插入文末'}
296	            </button>
297	            <button
298	              type="button"
299	              disabled={!state.text}
300	              onClick={() => { void navigator.clipboard.writeText(state.text).catch(() => {}); }}
301	            >
302	              复制
303	            </button>
304	            <button type="button" onClick={() => setState(null)}>关闭</button>
305	            {state.inserted ? <span className="plate-saved-at">已写入并保存</span> : null}
306	          </div>
307	        </div>
308	      ) : null}
309	    </>
310	  );
311	}
312	
313	// Toolbar buttons must live INSIDE <Plate> so useEditorVersion() can resolve
314	// the Plate store from context and re-render on every editor change; without
315	// the subscription, active marks are evaluated once at mount and never update.
316	function PlateToolbarButtons(props: { editor: PlateEditor }) {
317	  useEditorVersion();
318	  const markActive = (key: string) => (props.editor.api.marks?.() ?? {})[key] === true;
319	  return (
320	    <>
321	      <ToolbarButton label="加粗" active={markActive('bold')} onClick={() => props.editor.tf.toggleMark('bold')} />
322	      <ToolbarButton label="斜体" active={markActive('italic')} onClick={() => props.editor.tf.toggleMark('italic')} />
323	      <ToolbarButton label="下划线" active={markActive('underline')} onClick={() => props.editor.tf.toggleMark('underline')} />
324	      <ToolbarButton label="删除线" active={markActive('strikethrough')} onClick={() => props.editor.tf.toggleMark('strikethrough')} />
325	      <ToolbarButton label="代码" active={markActive('code')} onClick={() => props.editor.tf.toggleMark('code')} />
326	      <span className="plate-toolbar-sep" />
327	      <ToolbarButton label="标题 1" onClick={() => props.editor.tf.toggleBlock('h1')} />
328	      <ToolbarButton label="标题 2" onClick={() => props.editor.tf.toggleBlock('h2')} />
329	      <ToolbarButton label="标题 3" onClick={() => props.editor.tf.toggleBlock('h3')} />
330	      <ToolbarButton label="引用" onClick={() => props.editor.tf.toggleBlock('blockquote')} />
331	      <ToolbarButton label="分隔线" onClick={() => props.editor.tf.toggleBlock('hr')} />
332	    </>
333	  );
334	}
335	
336	// M5：内嵌图片（附件资产 v1）。图片以 data URL 写入 image 节点，文档自
337	// 包含、导出 .plate 自然携带；单图 ≤1.5MB 客户端拦截，修订总上限服务端拦截。
338	const MAX_IMAGE_BYTES = 1_500_000;
339	
340	function readImageFile(file: File, editor: PlateEditor, onStatus: (status: string) => void): void {
341	  if (!file.type.startsWith('image/')) {
342	    onStatus('只支持图片文件');
343	    return;
344	  }
345	  if (file.size > MAX_IMAGE_BYTES) {
346	    onStatus('图片超过 1.5MB 上限');
347	    return;
348	  }
349	  const reader = new FileReader();
350	  reader.onload = () => {
351	    insertImage(editor, String(reader.result));
352	    onStatus(`已插入 ${file.name}`);
353	  };
354	  reader.onerror = () => onStatus('读取图片失败');
355	  reader.readAsDataURL(file);
356	}
357	
358	function PlateImageButton(props: { editor: PlateEditor }) {
359	  const [status, setStatus] = useState('');
360	  const inputRef = useRef<HTMLInputElement>(null);
361	  const onChange = (event: ChangeEvent<HTMLInputElement>) => {
362	    const file = event.target.files?.[0];
363	    event.target.value = ''; // 允许连续选择同一文件
364	    if (file) readImageFile(file, props.editor, setStatus);
365	  };
366	  return (
367	    <>
368	      <button
369	        type="button"
370	        className="plate-ai-btn"
371	        title="插入图片"
372	        onMouseDown={(event) => { event.preventDefault(); inputRef.current?.click(); }}
373	      >
374	        插图
375	      </button>
376	      <input
377	        ref={inputRef}
378	        type="file"
379	        accept="image/*"
380	        style={{ display: 'none' }}
381	        data-plate-file-input="true"
382	        onChange={onChange}
383	      />
384	      {status ? <span className="plate-image-status">{status}</span> : null}
385	    </>
386	  );
387	}
388	
389	function PlateDocEditor(props: { docId: string; title: string; content: SlateContent }) {
390	  const [saving, setSaving] = useState(false);
391	  const [savedAt, setSavedAt] = useState<string | null>(null);
392	  const [imageStatus, setImageStatus] = useState('');
393	  const editor = useState(() => createPlateEditor({ plugins, value: props.content }))[0];
394	
395	  // 粘贴图片：截获剪贴板里的图片文件，走与插图按钮相同的 data URL 管道。
396	  const handlePaste = (event: ClipboardEvent<HTMLDivElement>) => {
397	    const items = event.clipboardData?.items;
398	    if (!items) return;
399	    for (const item of items) {
400	      if (item.kind === 'file' && item.type.startsWith('image/')) {
401	        const file = item.getAsFile();
402	        if (file) {
403	          event.preventDefault();
404	          readImageFile(file, editor, setImageStatus);
405	          return;
406	        }
407	      }
408	    }
409	  };
410	
411	  const save = async () => {
412	    setSaving(true);
413	    try {
414	      await post('rev-append', { docId: props.docId, content: editor.children as SlateContent, cause: 'edit' });
415	      setSavedAt(new Date().toLocaleTimeString('zh-CN'));
416	    } catch (error) {
417	      console.error('[workdsh-plate] save failed', error);
418	    } finally {
419	      setSaving(false);
420	    }
421	  };
422	
423	  return (
424	    <div className="plate-doc-editor">
425	      <Plate editor={editor}>
426	        <div className="plate-toolbar">
427	          <PlateToolbarButtons editor={editor} />
428	          <span className="plate-toolbar-sep" />
429	          <PlateAiSection editor={editor} docId={props.docId} />
430	          <span className="plate-toolbar-sep" />
431	          <PlateImageButton editor={editor} />
432	          <button type="button" className="plate-toolbar-save" disabled={saving} onClick={() => void save()}>
433	            {saving ? '保存中…' : '保存'}
434	          </button>
435	          {savedAt ? <span className="plate-saved-at">已保存 {savedAt}</span> : null}
436	          {imageStatus ? <span className="plate-image-status">{imageStatus}</span> : null}
437	        </div>
438	        <div className="plate-canvas" onPaste={handlePaste}>
439	          <PlateContent placeholder="开始输入…" className="plate-content" />
440	        </div>
441	      </Plate>
442	    </div>
443	  );
444	}
