446	function PlateDocumentsPanel() {
447	  const [docs, setDocs] = useState<DocMeta[]>([]);
448	  const [opened, setOpened] = useState<{ docId: string; title: string; content: SlateContent } | null>(null);
449	  const [error, setError] = useState<string | null>(null);
450	  const [busy, setBusy] = useState(false);
451	
452	  const refresh = async () => {
453	    try {
454	      const result = await post<{ documents: DocMeta[] }>('docs-list');
455	      setDocs(result.documents);
456	    } catch (e) {
457	      setError(String(e));
458	    }
459	  };
460	  useEffect(() => { void refresh(); }, []);
461	
462	  const create = async () => {
463	    setBusy(true);
464	    try {
465	      const result = await post<{ doc: DocMeta; head: { slateJson: SlateContent } }>('doc-create', {
466	        title: '未命名文档',
467	        content: emptyContent,
468	      });
469	      setOpened({ docId: result.doc.id, title: result.doc.title, content: result.head.slateJson });
470	      void refresh();
471	    } catch (e) {
472	      setError(String(e));
473	    } finally {
474	      setBusy(false);
475	    }
476	  };
477	
478	  const open = async (docId: string) => {
479	    setBusy(true);
480	    try {
481	      const result = await post<{ doc: DocMeta; head: { slateJson: SlateContent } }>('doc-open', { docId });
482	      setOpened({ docId: result.doc.id, title: result.doc.title, content: result.head.slateJson });
483	    } catch (e) {
484	      setError(String(e));
485	    } finally {
486	      setBusy(false);
487	    }
488	  };
489	
490	  const exportDoc = async (docId: string) => {
491	    setBusy(true);
492	    try {
493	      const result = await post<{ doc: DocMeta; head: { slateJson: SlateContent } }>('doc-export', { docId });
494	      const payload = {
495	        format: 'workdsh-plate',
496	        version: 1,
497	        exportedAt: new Date().toISOString(),
498	        title: result.doc.title,
499	        content: result.head.slateJson,
500	      };
501	      const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
502	      const url = URL.createObjectURL(blob);
503	      const anchor = document.createElement('a');
504	      anchor.href = url;
505	      anchor.download = `${result.doc.title.replace(/[\\/:*?"<>|]/g, '_')}.plate`;
506	      anchor.click();
507	      URL.revokeObjectURL(url);
508	    } catch (e) {
509	      setError(String(e));
510	    } finally {
511	      setBusy(false);
512	    }
513	  };
514	
515	  if (opened) {
516	    return (
517	      <div className="plate-doc-editor">
518	        <div className="plate-doc-head">
519	          <button type="button" className="plate-back" onClick={() => setOpened(null)}>← 文档列表</button>
520	          <span className="plate-doc-title">{opened.title}</span>
521	          <button type="button" className="plate-export" disabled={busy} onClick={() => void exportDoc(opened.docId)}>导出 .plate</button>
522	        </div>
523	        <PlateDocEditor docId={opened.docId} title={opened.title} content={opened.content} />
524	      </div>
525	    );
526	  }
527	
528	  return (
529	    <div className="plate-docs">
530	      <div className="plate-doc-head">
531	        <span className="plate-doc-title">AI 富文本文档</span>
532	        <button type="button" className="plate-new" disabled={busy} onClick={() => void create()}>
533	          ＋ 新建文档
534	        </button>
535	      </div>
536	      {error ? <div className="plate-error">{error}</div> : null}
537	      {docs.length === 0 ? (
538	        <div className="plate-empty">还没有文档，点「新建文档」开始。</div>
539	      ) : (
540	        <ul className="plate-doc-list">
541	          {docs.map((doc) => (
542	            <li key={doc.id}>
543	              <button type="button" onClick={() => void open(doc.id)}>
544	                <span className="plate-item-title">{doc.title}</span>
545	                <span className="plate-item-time">{new Date(doc.updatedAt).toLocaleString('zh-CN')}</span>
546	              </button>
547	            </li>
548	          ))}
549	        </ul>
550	      )}
551	    </div>
552	  );
553	}
554	
555	// Self-contained styling: the plugin ships no CSS build step, so the bundle
556	// injects one <style> tag at apply time.
557	function injectStyles(): void {
558	  if (document.getElementById('workdsh-plate-style')) return;
559	  const style = document.createElement('style');
560	  style.id = 'workdsh-plate-style';
561	  style.textContent = `
562	.plate-docs { padding: 12px 16px; }
563	.plate-doc-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
564	.plate-doc-title { font-weight: 600; font-size: 15px; }
565	.plate-new, .plate-back, .plate-export { padding: 4px 10px; border: 1px solid #d1d5db; border-radius: 6px; background: #fff; cursor: pointer; }
566	.plate-doc-list { list-style: none; margin: 0; padding: 0; }
567	.plate-doc-list li button { width: 100%; display: flex; justify-content: space-between; align-items: center; padding: 10px 12px; border: 1px solid #e5e7eb; border-radius: 8px; margin-bottom: 8px; background: #fff; cursor: pointer; }
568	.plate-item-time { color: #9ca3af; font-size: 12px; }
569	.plate-empty { color: #9ca3af; padding: 24px 0; text-align: center; }
570	.plate-error { color: #dc2626; margin: 4px 0; }
571	.plate-doc-editor { display: flex; flex-direction: column; min-height: 320px; }
572	.plate-toolbar { display: flex; flex-wrap: wrap; gap: 4px; align-items: center; padding: 6px 8px; border-bottom: 1px solid #e5e7eb; }
573	.plate-toolbar-btn, .plate-ai-btn { padding: 4px 10px; border: 1px solid #d1d5db; border-radius: 6px; background: #fff; cursor: pointer; font-size: 13px; }
574	.plate-toolbar-btn:hover, .plate-ai-btn:hover { background: #f3f4f6; }
575	.plate-toolbar-btn[data-active="true"] { background: #e0e7ff; border-color: #6366f1; color: #4338ca; }
576	.plate-toolbar-sep { width: 1px; height: 18px; background: #e5e7eb; margin: 0 4px; }
577	.plate-toolbar-save { margin-left: auto; padding: 4px 12px; border: 1px solid #6366f1; border-radius: 6px; background: #6366f1; color: #fff; cursor: pointer; }
578	.plate-saved-at { color: #16a34a; font-size: 12px; }
579	.plate-canvas { padding: 16px; overflow-y: auto; }
580	.plate-content { min-height: 260px; outline: none; }
581	.plate-ai-panel { flex-basis: 100%; display: flex; flex-direction: column; gap: 6px; padding: 8px; border: 1px solid #c7d2fe; border-radius: 8px; background: #f8faff; margin-top: 4px; }
582	.plate-ai-text { width: 100%; min-height: 90px; font-size: 13px; line-height: 1.6; border: 1px solid #d1d5db; border-radius: 6px; padding: 8px; box-sizing: border-box; }
583	.plate-ai-actions { display: flex; gap: 6px; align-items: center; }
584	.plate-ai-actions button { padding: 4px 10px; border: 1px solid #d1d5db; border-radius: 6px; background: #fff; cursor: pointer; }
585	.plate-ai-status { font-size: 12px; color: #6366f1; }
586	.plate-file-preview { padding: 12px 16px; display: flex; flex-direction: column; gap: 8px; }
587	.plate-file-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
588	.plate-import-btn { padding: 4px 12px; border: 1px solid #6366f1; border-radius: 6px; background: #6366f1; color: #fff; cursor: pointer; white-space: nowrap; }
589	.plate-import-btn:disabled { background: #c7d2fe; border-color: #c7d2fe; cursor: default; }
590	.plate-file-body { border: 1px solid #e5e7eb; border-radius: 8px; padding: 12px; background: #fff; }
591	.plate-image-status { color: #6366f1; font-size: 12px; }
592	.plate-content img { max-width: 100%; height: auto; border-radius: 6px; }
593	`;
594	  document.head.appendChild(style);
595	}
596	
597	export function apply(ctx: Context): void {
598	  injectStyles();
599	  // S5-a: claim the .plate extension in the document preview registry.
600	  ctx.effect(() =>
601	    ctx.documentPreviews.register({
602	      id: 'workdsh-plate',
603	      extensions: ['plate'],
604	      title: () => 'Plate 文档',
605	      priority: 'builtin',
606	      loading: 'bytes-complete',
607	    }),
608	  );
609	  // S5-b: the document-tab renderer for .plate files (key matches the
610	  // documentPreviews definition id above; the owner delivers file bytes).
611	  ctx.slots.inject('sidebar.right.tab.document', () =>
612	    ctx.slots.register(
613	      { name: 'sidebar.right.tab.document', key: 'workdsh-plate' },
614	      PlateFilePreview,
615	    ),
616	  );
617	  // Deterministic product entry: a left-nav page (main panel + panellist
618	  // entry), the same pattern as the bundle's DiagnosticsPanel.
619	  ctx.slots.inject('main', () =>
620	    ctx.slots.register({ name: 'main', key: 'workdsh-plate' }, PlateDocumentsPanel),
621	  );
622	  ctx.slots.inject('sidebar.panellist', () =>
623	    ctx.slots.register({
624	      name: 'sidebar.panellist', id: 'workdsh-plate', label: 'Plate 文档', order: 70,
625	    }, () => <span className="plate-nav-mark">📝</span>),
626	  );
627	}
