82	function registerApi(ctx: Context) {
83	  const connection = (ctx as Context & { connection: HostConnectionHandle }).connection;
84	
85	  const unregister = connection.fetch.register({
86	    path: '/api/workdsh-plate',
87	    methods: ['POST'],
88	    requestBody: 'buffered',
89	    async fetch(request) {
90	      let raw: unknown;
91	      try {
92	        raw = await request.json();
93	      } catch {
94	        return Response.json({ ok: false, code: 'BAD_JSON' }, { status: 400 });
95	      }
96	      const parsed = requestShape.safeParse(raw);
97	      if (!parsed.success) {
98	        return Response.json({ ok: false, code: 'BAD_SHAPE', message: parsed.error.issues[0]?.message ?? 'invalid request' }, { status: 400 });
99	      }
100	      const body = parsed.data;
101	      if (body.endpoint === 'ping') {
102	        return Response.json({ ok: true, name: 'workdsh-plate' });
103	      }
104	      if (body.endpoint === 'docs-list') {
105	        return Response.json({ ok: true, documents: ctx.workdshPlate.listDocuments() });
106	      }
107	      if (body.endpoint === 'doc-create') {
108	        try {
109	          return Response.json({ ok: true, ...ctx.workdshPlate.createDocument(body.title, body.content) });
110	        } catch (error) {
111	          return Response.json({ ok: false, code: 'CREATE_FAILED', message: String(error) }, { status: 500 });
112	        }
113	      }
114	      if (body.endpoint === 'doc-import') {
115	        // 从 .plate 文件导入：首修订 cause='import'，与手动新建（'create'）区分。
116	        try {
117	          return Response.json({ ok: true, ...ctx.workdshPlate.createDocument(body.title, body.content, 'import') });
118	        } catch (error) {
119	          return Response.json({ ok: false, code: 'IMPORT_FAILED', message: String(error) }, { status: 500 });
120	        }
121	      }
122	      if (body.endpoint === 'doc-open' || body.endpoint === 'doc-export') {
123	        try {
124	          return Response.json({ ok: true, ...ctx.workdshPlate.openDocument(body.docId) });
125	        } catch {
126	          return Response.json({ ok: false, code: 'NOT_FOUND' }, { status: 404 });
127	        }
128	      }
129	      if (body.endpoint === 'rev-append') {
130	        try {
131	          return Response.json({ ok: true, ...ctx.workdshPlate.appendRevision(body.docId, body.content, body.cause) });
132	        } catch {
133	          return Response.json({ ok: false, code: 'NOT_FOUND' }, { status: 404 });
134	        }
135	      }
136	      // ai-smoke / ai-stream: build options from the default model selection
137	      // and stream ctx.llm.stream as SSE text-delta frames.
138	      const prompt = body.endpoint === 'ai-smoke'
139	        ? (body.prompt?.trim() ? body.prompt.trim().slice(0, 4000) : '用一句话介绍富文本编辑器。')
140	        : null;
141	      const aiAction = body.endpoint === 'ai-stream' ? body.action : null;
142	      let options: GenerateOptions;
143	      try {
144	        const selection = ctx.agentDefaultModel.currentSelection();
145	        const template = aiAction ? AI_PROMPTS[aiAction] : null;
146	        const userText = aiAction && body.endpoint === 'ai-stream' ? body.text : prompt!;
147	        options = {
148	          provider: selection.provider,
149	          model: selection.model,
150	          ...(selection.reasoningEffort
151	            ? { reasoningEffort: selection.reasoningEffort as ReasoningEffortId }
152	            : {}),
153	          system: template?.system ?? '你是中文写作助手，回答简洁。',
154	          messages: [{
155	            role: 'user',
156	            content: [{ type: 'text', text: template ? template.user(userText) : userText }],
157	          }],
158	          maxTokens: aiAction ? 2048 : 512,
159	          signal: request.signal,
160	        };
161	      } catch (error) {
162	        return Response.json({ ok: false, code: 'SELECTION_FAILED', message: String(error) }, { status: 500 });
