function flattenSlate(nodes) {
  let parts = [];
  for (const n of nodes ?? []) {
    if (typeof n.text === 'string') parts.push(n.text);
    if (Array.isArray(n.children)) parts.push(flattenSlate(n.children));
  }
  return parts.join('\n');
}

async function createDoc() {
  // run 1 教训：编辑器开着时没有「＋ 新建文档」，必须先回列表。
  const back = page.locator('button.plate-back').first();
  if (await back.isVisible({ timeout: 2000 }).catch(() => false)) {
    await back.click({ timeout: 8000 });
    await page.waitForTimeout(2500);
  }
  const before = new Set(((await api('docs-list')).documents ?? []).map((d) => d.id));
  await page.locator('text=＋ 新建文档').first().click({ timeout: 15000 });
  await page.waitForTimeout(6000);
  const content = page.locator('.plate-content, [data-slate-editor]').first();
  await content.click({ timeout: 8000 });
  await page.keyboard.type(SEED);
  await page.waitForTimeout(600);
  const after = await api('docs-list');
  const docId = (after.documents ?? []).find((d) => !before.has(d.id))?.id ?? null;
  return { content, docId };
}

async function waitStream() {
  await page.waitForFunction(() => {
    const t = document.querySelector('.plate-ai-text');
    return !!t && t.value.length > 5;
  }, { timeout: 240000 });
  await page.waitForFunction(() => {
    const t = document.querySelector('.plate-ai-text');
    return !!t && !t.readOnly;
  }, { timeout: 180000 });
  return (await page.locator('.plate-ai-text').first().inputValue()).trim();
}

try {
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForSelector('text=探索未至之境', { timeout: 90000 });
  await page.waitForTimeout(4000);
  await page.locator(':text("Plate 文档")').first().click({ timeout: 20000 });
  await page.waitForTimeout(8000);
  step('panel open');

  let last = null;
  for (const label of ACTIONS) {
    const round = { label };
    try {
      const { content, docId } = await createDoc();
      round.docId = docId;
      last = { content, docId };
      await content.click({ clickCount: 3, timeout: 8000 });
      await page.waitForTimeout(400);
      await page.locator(`button[title="AI ${label}"]`).first().click({ timeout: 8000 });
      round.panelShown = await page.locator('.plate-ai-panel').first().isVisible({ timeout: 15000 }).catch(() => false);
      round.busySeen = await page.locator('.plate-ai-status', { hasText: `${label}中…` }).first().isVisible({ timeout: 15000 }).catch(() => false);
      const text = await waitStream();
      round.textLen = text.length;
      round.streamStable = await steady(async () =>
        (await page.locator('.plate-ai-text').first().inputValue().catch(() => '')).trim() === text, 800, 10000);
      const replaceBtn = page.locator('.plate-ai-actions button', { hasText: '替换选区' }).first();
      round.replaceLabelSeen = await replaceBtn.isVisible({ timeout: 5000 }).catch(() => false);
      await replaceBtn.click({ timeout: 8000 });
      round.saved = await steady(async () =>
        page.locator('text=已写入并保存').first().isVisible().catch(() => false), 700, 30000);
      const editorText = strip(await content.evaluate((e) => e.innerText));
      round.replaced = editorText === strip(text) && editorText.length > 0;
      round.editorHead = editorText.slice(0, 60);
      await page.locator('.plate-ai-actions button', { hasText: '关闭' }).first().click({ timeout: 8000 });
      step(`${label}: panel=${round.panelShown} busy=${round.busySeen} len=${round.textLen} stable=${round.streamStable} replaceBtn=${round.replaceLabelSeen} saved=${round.saved} replaced=${round.replaced} head="${round.editorHead}"`);
    } catch (e) {
      round.fatal = String(e).slice(0, 200);
      step(`${label} FATAL ${round.fatal}`);
    }
    out.rounds.push(round);
  }

  const opened = await api('doc-open', { docId: last.docId });
  const flat = strip(flattenSlate(opened.head?.slateJson));
  const finalEditor = strip(await last.content.evaluate((e) => e.innerText));
  out.serverPersistence = flat === finalEditor && flat.length > 0;
  step(`server: persist=${out.serverPersistence}`);

  await page.screenshot({ path: '/tmp/plate-ai-missed.png' });
  console.log('RESULT', JSON.stringify({
    rounds: out.rounds.map((r) => ({ label: r.label, panelShown: r.panelShown, busySeen: r.busySeen, textLen: r.textLen, streamStable: r.streamStable, replaceLabelSeen: r.replaceLabelSeen, saved: r.saved, replaced: r.replaced, fatal: r.fatal ?? null })),
    serverPersistence: out.serverPersistence,
    pageErrors: out.pageErrors.length, consoleErrors: out.consoleErrors.length,
    firstPageError: out.pageErrors[0] ?? null,
  }));
} catch (e) {
  out.fatal = String(e).slice(0, 250);
  await page.screenshot({ path: '/tmp/plate-ai-missed-fatal.png' }).catch(() => {});
  console.log('FATAL', out.fatal);
}
writeFileSync('/tmp/plate-ai-missed-result.json', JSON.stringify(out, null, 2));
await browser.close();

