export type DefaultEditor = 'office' | 'plate';
export interface PlatePendingEntry { sessionId: string; documentId: string; requestId: string; }

private defaultEditor: DefaultEditor = 'office';
private readyResolve!: () => void;
readonly ready: Promise<void>;
private pending: PlatePendingEntry[] = [];

constructor: this.ready = new Promise((resolve) => { this.readyResolve = resolve; });

async [Service.init]() {
  ... existing ...
  const { settings } = this.tables();
  const row = settings.get('default-editor');
  if (row && (row.value === 'plate' || row.value === 'office')) this.defaultEditor = row.value;
  this.readyResolve();
}

getDefaultEditor(): DefaultEditor { return this.defaultEditor; }

setDefaultEditor(editor: DefaultEditor): DefaultEditor {
  this.tables().settings.put('default-editor', { key: 'default-editor', value: editor });
  this.defaultEditor = editor;
  return editor;
}

pushPending(entry: PlatePendingEntry): void { this.pending.push(entry); }

takePending(sessionId: string): PlatePendingEntry[] {
  const mine = this.pending.filter((p) => p.sessionId === sessionId);
  this.pending = this.pending.filter((p) => p.sessionId !== sessionId);
  return mine;
}
