ctx.effect(() => ctx.sidebarRightTabs.register({ id: 'workdsh-plate-live', kind: 'workdsh-plate-live', title: () => 'Plate 文档 · 实时编辑', guide: [{ id: 'workdsh-plate-live', order: 46, title: () => 'Plate 文档', description: () => '查看并编辑 AI 正在编写的 Plate 文档' }] }));
ctx.slots.inject('sidebar.right.pane.tab', () => ctx.slots.register({ name: 'sidebar.right.pane.tab', key: 'workdsh-plate-live', inject: () => ({}) }, PlateLivePage));
```

6. Pending poll in apply():
```tsx
const currentSessionId = () => {
  const state = (ctx.sessions as unknown as ISessions).list.getSnapshot();
  return Object.values(state.byId).find((row) => (row.retainedBy.mainView ?? 0) > 0)?.id;
};
ctx.effect(() => {
  let timer: ReturnType<typeof setTimeout>;
  const seen = new Set<string>();
  async function poll() {
    const sessionId = currentSessionId();
    try {
      if (sessionId && document.visibilityState !== 'hidden') {
        const requests = await post<{ requests: { sessionId: string; documentId: string; requestId: string }[] }>('plate-pending', { sessionId: String(sessionId) });
        for (const r of requests.requests) if (!seen.has(r.requestId)) {
          ctx.sidebarRight.openTabIn(sessionId as never, 'workdsh-plate-live', { params: { documentId: r.documentId } });
          seen.add(r.requestId);
        }
      }
    } catch { /* unbound sessions etc. */ } finally {
      if (!lifetime.signal.aborted) timer = setTimeout(poll, document.visibilityState === 'hidden' ? 5000 : 500);
    }
  }
  void poll();
  return () => { lifetime.abort(); clearTimeout(timer); };
});
```
Where lifetime = new AbortController() — need one in apply scope. post() doesn't take signal; fine for v1 (mirror office behavior which passes signal via rpc; ours simpler).

Wait — takePending drains entries per poll; multiple tabs/windows could race, but single-client local deploy — fine.

7. Default editor toggle in PlateDocumentsPanel:
```tsx
const [defaultEditor, setDefaultEditorState] = useState<'office' | 'plate' | null>(null);
const [editorError, setEditorError] = useState('');
useEffect(() => { void post<{ editor: 'office' | 'plate' }>('get-default-editor').then((r) => setDefaultEditorState(r.editor)).catch(() => {}); }, []);
const toggleEditor = async () => {
  if (!defaultEditor) return;
  const next = defaultEditor === 'plate' ? 'office' : 'plate';
  const prev = defaultEditor;
  setDefaultEditorState(next); // 乐观
  setEditorError('');
  try { await post('set-default-editor', { editor: next }); } catch (e) { setDefaultEditorState(prev); setEditorError(String(e)); }
};
```
