const slateNode: z.ZodType<unknown> = z.lazy(() =>
  z.object({}).catchall(z.unknown()),
);
export const slateJson = z
  .array(z.object({ type: z.string().optional(), children: z.array(slateNode), text: z.string().optional() }).passthrough())
  .min(1)
  .max(10000)
  // 内嵌图片走 data URL：单次修订总字节封顶，防爆库（≈3 张 1.5MB 图）。
