const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });

try {
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForSelector('text=探索未至之境', { timeout: 90000 });
  await page.waitForTimeout(4000);
  const gate = page.locator('text=选择一个工作区开始').first();
  if (await gate.isVisible({ timeout: 5000 }).catch(() => false)) {
    await page.locator('text=选择工作区').first().click();
    await page.waitForTimeout(1500);
    await page.locator('[role="option"]:has-text("团队知识库"), [role="menuitem"]:has-text("团队知识库"), li:has-text("团队知识库")').first().click({ timeout: 10000 }).catch(() => {});
    await page.waitForTimeout(3000);
  }
  const dump = await page.evaluate(() => {
    const out = { textareas: [], contenteditable: [], inputs: [], buttons: [] };
    document.querySelectorAll('textarea').forEach((t) => out.textareas.push({ ph: t.placeholder, cls: (t.className || '').slice(0, 60), vis: t.offsetParent !== null }));
    document.querySelectorAll('[contenteditable="true"]').forEach((t) => out.contenteditable.push({ ph: t.getAttribute('data-placeholder') ?? t.getAttribute('placeholder'), cls: (t.className || '').slice(0, 60), text: (t.innerText || '').slice(0, 30) }));
    document.querySelectorAll('input[type="text"], input:not([type])').forEach((i) => out.inputs.push({ ph: i.placeholder, cls: (i.className || '').slice(0, 60) }));
    document.querySelectorAll('button').forEach((b) => {
      const t = (b.innerText || b.title || '').trim().slice(0, 20);
      if (t && (b.offsetParent !== null)) out.buttons.push({ t, cls: (b.className || '').slice(0, 50), aria: b.getAttribute('aria-label') ?? '' });
    });
    return out;
  });
  console.log('DUMP', JSON.stringify(dump, null, 1));
  await page.screenshot({ path: '/tmp/plate-composer-recon.png' });
} catch (e) {
  console.log('FATAL', String(e).slice(0, 300));
  await page.screenshot({ path: '/tmp/plate-composer-fatal.png' }).catch(() => {});
}
await browser.close();

