input.content:
// Agent E2E（缺省编辑器=PlateAI）：新会话 → composer 发「写文档」请求 →
// 断言 agent 走 plate_open/plate_edit：右侧活编辑器出现（.plate-live-page
// 内 .plate-doc-title + .plate-content 有内容）、plate 文档数 +1、
// 对话未用 content_open；0 pageErrors。全部读值双采样稳态。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { writeFileSync } from 'node:fs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const MESSAGE = '请写一份关于人工智能的简短文档，标题用《PlateE2E 测试文档》，包含一个小标题和两段话。';
const out = { steps: [], samples: [], consoleErrors: [], pageErrors: [] };
const step = (s) => { out.steps.push(s); console.log('STEP', s); };

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
page.on('console', (m) => { if (m.type() === 'error') out.consoleErrors.push(m.text().slice(0, 300)); });
page.on('pageerror', (e) => out.pageErrors.push(String(e).slice(0, 300)));

const api = (endpoint, payload = {}) => page.evaluate(async ({ endpoint, payload }) => {
  const r = await fetch('/api/workdsh-plate', {
    method: 'POST', credentials: 'same-origin',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ endpoint, ...payload }),
  });
  return r.json();
}, { endpoint, payload });

async function steady(predicate, gap = 800, timeout = 15000) {
  const deadline = Date.now() + timeout;
  for (;;) {
    if (await predicate()) {
      await page.waitForTimeout(gap);
      if (await predicate()) return true;
    }
    if (Date.now() > deadline) return false;
    await page.waitForTimeout(500);
  }
}

try {
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForSelector('text=探索未至之境', { timeout: 90000 });
  await page.waitForTimeout(4000);
  const gate = page.locator('text=选择一个工作区开始').first();
  if (await gate.isVisible({ timeout: 5000 }).catch(() => false)) {
    await page.locator('text=选择工作区').first().click();
    await page.waitForTimeout(1500);
    await page.locator('[role="option"]:has-text("团队知识库"), [role="menuitem"]:has-text("团队知识库"), li:has-text("团队知识库")').first().click({ timeout: 10000 }).catch(() => {});
    await page.waitForTimeout(3000);
  }
  await page.locator('button[aria-label="新建会话"], button:has-text("新会话")').first().click({ timeout: 10000 });
  await page.waitForTimeout(5000);
  step('new session open');

  const baseline = ((await api('docs-list')).documents ?? []).length;
  out.baselineDocs = baseline;

  // 发消息
  const composer = page.locator('[contenteditable="true"].uV2eYG_input').first();
  await composer.click({ timeout: 10000 });
  await page.keyboard.type(MESSAGE, { delay: 30 });
  await page.waitForTimeout(800);
  await page.locator('button.uV2eYG_primary').first().click({ timeout: 8000 });
  step('message sent');

  // 轮询观察（总预算 300s）：右侧活编辑器 + 对话工具调用痕迹。
  const deadline = Date.now() + 300000;
  let editorMounted = false, titleShown = false, contentWritten = false;
  while (Date.now() < deadline && !(editorMounted && contentWritten)) {
    await page.waitForTimeout(5000);
    editorMounted = await page.locator('.plate-live-page .plate-doc-editor').first().isVisible({ timeout: 3000 }).catch(() => false);
    titleShown = await page.locator('.plate-live-page .plate-doc-title', { hasText: 'PlateE2E 测试文档' }).first().isVisible({ timeout: 3000 }).catch(() => false);
    const text = await page.locator('.plate-live-page .plate-content').first().innerText().catch(() => '');
    contentWritten = text.replace(/\s+/g, '').length > 10;
    const bodyText = (await page.evaluate(() => document.body.innerText)).slice(0, 8000);
    out.samples.push({ t: Math.round((Date.now() - (deadline - 300000)) / 1000), editorMounted, titleShown, contentWritten, plateOpenSeen: bodyText.includes('plate_open'), contentOpenSeen: bodyText.includes('content_open') });
    if (editorMounted) step(`poll: editor=${editorMounted} title=${titleShown} content=${contentWritten}`);
  }

  // 双采样稳态终判
  out.editorMounted = await steady(async () => page.locator('.plate-live-page .plate-doc-editor').first().isVisible({ timeout: 2000 }).catch(() => false));
  out.titleShown = await steady(async () => page.locator('.plate-live-page .plate-doc-title', { hasText: 'PlateE2E 测试文档' }).first().isVisible({ timeout: 2000 }).catch(() => false));
  const finalText = await page.locator('.plate-live-page .plate-content').first().innerText().catch(() => '');
  out.contentWritten = finalText.replace(/\s+/g, '').length > 10;
  out.contentHead = finalText.replace(/\s+/g, '').slice(0, 60);

  const bodyText = (await page.evaluate(() => document.body.innerText));
  out.plateOpenSeen = bodyText.includes('plate_open');
  out.contentOpenSeen = bodyText.includes('content_open');

  const after = ((await api('docs-list')).documents ?? []);
  out.newDocs = after.length - baseline;
  out.newDocTitles = after.filter((d) => d.title === 'PlateE2E 测试文档').length;

  await page.screenshot({ path: '/tmp/plate-agent-e2e-plate.png' });
  console.log('RESULT', JSON.stringify({
    editorMounted: out.editorMounted, titleShown: out.titleShown, contentWritten: out.contentWritten,
    contentHead: out.contentHead, plateOpenSeen: out.plateOpenSeen, contentOpenSeen: out.contentOpenSeen,
    newDocs: out.newDocs, newDocTitles: out.newDocTitles,
    pageErrors: out.pageErrors.length, consoleErrors: out.consoleErrors.length,
    lastSamples: out.samples.slice(-4),
  }));
} catch (e) {
  out.fatal = String(e).slice(0, 300);
  await page.screenshot({ path: '/tmp/plate-agent-e2e-plate-fatal.png' }).catch(() => {});
  console.log('FATAL', out.fatal);
}
writeFileSync('/tmp/plate-agent-e2e-plate-result.json', JSON.stringify(out, null, 2));
await browser.close();

