// UI 开关探针（1.3.3）：打开 Plate 文档面板 → 读「缺省」按钮标签 →
// 点击 → API get-default-editor 应翻转 → 再点回原值 → 按钮标签跟随。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const out = { steps: [], pageErrors: [], consoleErrors: [] };
const step = (s) => { out.steps.push(s); console.log('STEP', s); };

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1600, height: 900 } });
page.on('console', (m) => { if (m.type() === 'error') out.consoleErrors.push(m.text().slice(0, 300)); });
page.on('pageerror', (e) => out.pageErrors.push(String(e).slice(0, 300)));

const api = (endpoint, payload = {}) => page.evaluate(async ({ endpoint, payload }) => {
  const r = await fetch('/api/workdsh-plate', {
    method: 'POST', credentials: 'same-origin',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ endpoint, ...payload }),
  });
  return r.json();
}, { endpoint, payload });

try {
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForSelector('text=探索未至之境', { timeout: 90000 });
  await page.waitForTimeout(4000);
  await page.locator(':text("Plate 文档")').first().click({ timeout: 20000 });
  await page.waitForTimeout(6000);

  const btn = page.locator('.plate-editor-toggle').first();
  await btn.waitFor({ state: 'visible', timeout: 15000 });
  const beforeLabel = (await btn.innerText()).replace(/\s+/g, '');
  const before = (await api('get-default-editor')).editor;
  step(`panel label="${beforeLabel}" api=${before}`);

  await btn.click();
  await page.waitForTimeout(1200);
  const afterFlip = (await api('get-default-editor')).editor;
  const afterLabel = (await btn.innerText()).replace(/\s+/g, '');
  step(`after 1st click label="${afterLabel}" api=${afterFlip}`);

  await btn.click();
  await page.waitForTimeout(1200);
  const restored = (await api('get-default-editor')).editor;
  const restoredLabel = (await btn.innerText()).replace(/\s+/g, '');
  step(`after 2nd click label="${restoredLabel}" api=${restored}`);

  out.flipped = before !== afterFlip && afterFlip === restored;
  out.before = before; out.afterFlip = afterFlip; out.restored = restored;
  out.labels = { beforeLabel, afterLabel, restoredLabel };
  await page.screenshot({ path: '/tmp/plate-toggle.png' });
  console.log('RESULT', JSON.stringify({ flipped: out.flipped, before, afterFlip, restored, labels: out.labels, pageErrors: out.pageErrors.length, consoleErrors: out.consoleErrors.length }));
} catch (e) {
  out.fatal = String(e).slice(0, 300);
  await page.screenshot({ path: '/tmp/plate-toggle-fatal.png' }).catch(() => {});
  console.log('FATAL', out.fatal);
}
await browser.close();

