  const [error, setError] = useState('');
  const [importing, setImporting] = useState(false);
  const [imported, setImported] = useState<string | null>(null);
  const bytes = props.content.kind === 'bytes' ? props.content.data : null;

  useEffect(() => {
    setError('');
    setParsed(null);
    setImported(null);
    if (!bytes) return;
    try {

