79	async function streamPost(
80	  endpoint: string,
81	  payload: Record<string, unknown>,
82	  onText: (delta: string) => void,
83	): Promise<void> {
84	  const response = await fetch('/api/workdsh-plate', {
85	    method: 'POST',
86	    credentials: 'same-origin',
87	    headers: { 'content-type': 'application/json' },
88	    body: JSON.stringify({ endpoint, ...payload }),
89	  });
90	  const contentType = response.headers.get('content-type') ?? '';
91	  if (!contentType.includes('text/event-stream')) {
92	    const body = await response.json().catch(() => null);
93	    throw new Error(body?.code ?? `HTTP ${response.status}`);
94	  }
95	  const reader = response.body!.getReader();
96	  const decoder = new TextDecoder();
97	  let buffer = '';
98	  for (;;) {
99	    const { done, value } = await reader.read();
100	    if (done) break;
101	    buffer += decoder.decode(value, { stream: true });
102	    let boundary = buffer.indexOf('\n\n');
103	    while (boundary >= 0) {
104	      const frame = buffer.slice(0, boundary);
105	      buffer = buffer.slice(boundary + 2);
106	      const dataLine = frame.split('\n').find((line) => line.startsWith('data: '));
107	      if (dataLine) {
108	        const event = JSON.parse(dataLine.slice(6)) as { text?: string; error?: string };
109	        if (event.error) throw new Error(event.error);
110	        if (event.text) onText(event.text);
111	      }
112	      boundary = buffer.indexOf('\n\n');
113	    }
114	  }
115	}
