// 桥接 E2E（1.4.0）：缺省=office → agent 生成 docx → 聊天文件卡点击 → 预览
// 工具条出现原生「用 PlateAI 打开」→ 点击 → 右侧活编辑器出现且内容一致。
// 前置：外部已 set-default-editor office。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { writeFileSync } from 'node:fs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const MESSAGE = '请写一份关于气候变化的简短文档，标题用《桥接E2E 测试文档》，包含一个小标题和两段话。';
const out = { steps: [], samples: [], consoleErrors: [], pageErrors: [] };
const step = (s) => { out.steps.push(s); console.log('STEP', s); };

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
page.on('console', (m) => { if (m.type() === 'error') out.consoleErrors.push(m.text().slice(0, 300)); });
page.on('pageerror', (e) => out.pageErrors.push(String(e).slice(0, 300)));

const api = (endpoint, payload = {}) => page.evaluate(async ({ endpoint, payload }) => {
  const r = await fetch('/api/workdsh-plate', {
    method: 'POST', credentials: 'same-origin',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ endpoint, ...payload }),
  });
  return r.json();
}, { endpoint, payload });

async function steady(predicate, gap = 800, timeout = 15000) {
  const deadline = Date.now() + timeout;
  for (;;) {
    if (await predicate()) {
      await page.waitForTimeout(gap);
      if (await predicate()) return true;
    }
    if (Date.now() > deadline) return false;
    await page.waitForTimeout(500);
  }
}

try {
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForSelector('text=探索未至之境', { timeout: 90000 });
  await page.waitForTimeout(4000);
  const gate = page.locator('text=选择一个工作区开始').first();
  if (await gate.isVisible({ timeout: 5000 }).catch(() => false)) {
    await page.locator('text=选择工作区').first().click();
    await page.waitForTimeout(1500);
    await page.locator('[role="option"]:has-text("团队知识库"), [role="menuitem"]:has-text("团队知识库"), li:has-text("团队知识库")').first().click({ timeout: 10000 }).catch(() => {});
    await page.waitForTimeout(3000);
  }

  // 断言 1：左导航无「Plate 文档」（面板已移除；旧导航图标类不存在）。
  out.navMarkCount = await page.locator('.plate-nav-mark').count();
  step(`nav mark count = ${out.navMarkCount}`);

  const setting = await api('get-default-editor');
  out.defaultEditor = setting.editor;
  step(`default editor = ${setting.editor}`);
  if (setting.editor !== 'office') throw new Error('前置未满足：缺省应为 office');

  await page.locator('button[aria-label="新建会话"], button:has-text("新会话")').first().click({ timeout: 10000 });
  await page.waitForTimeout(5000);
  step('new session open');

  const before = ((await api('docs-list')).documents ?? []).length;
  out.beforeDocs = before;

  const composer = page.locator('[contenteditable="true"].uV2eYG_input').first();
  await composer.click({ timeout: 10000 });
  await page.keyboard.type(MESSAGE, { delay: 30 });
  await page.waitForTimeout(800);
  await page.locator('button.uV2eYG_primary').first().click({ timeout: 8000 });
  step('message sent');

  // 等 agent 生成 docx 并 present 文件卡（总预算 300s）。
  const deadline = Date.now() + 300000;
  let card = null;
  while (Date.now() < deadline && !card) {
    await page.waitForTimeout(5000);
    for (const sel of ['a[href*=".docx"]', 'button:has-text(".docx")', '[class*="file"]:has-text(".docx")', 'text=桥接E2E 测试文档']) {
      const loc = page.locator(sel).first();
      if (await loc.isVisible({ timeout: 1500 }).catch(() => false)) { card = sel; break; }
    }
  }
  if (!card) {
    // 文件卡没找到：dump 候选元素供归因。
    const candidates = await page.evaluate(() =>
      Array.from(document.querySelectorAll('a[href], button, [role="button"]'))
        .filter((el) => /docx|桥接E2E|气候变化/.test(el.textContent ?? ''))
        .slice(0, 8)
        .map((el) => ({ tag: el.tagName, cls: String(el.className).slice(0, 60), text: (el.textContent ?? '').slice(0, 60) })));
    out.cardCandidates = candidates;
    out.cardFound = false;
  } else {
    out.cardFound = true;
    step(`file card found via ${card}`);
    await page.locator(card).first().click({ timeout: 8000 }).catch(() => {});
    await page.waitForTimeout(4000);

    // 断言 2：预览工具条出现原生「用 PlateAI 打开」按钮。
    const btn = page.locator('.plate-open-in-plate').first();
    out.openButtonSeen = await steady(async () => btn.isVisible({ timeout: 2000 }).catch(() => false));
    step(`open button visible = ${out.openButtonSeen}`);

    if (out.openButtonSeen) {
      await btn.click();
      // 断言 3：右侧活编辑器打开，标题与内容落地。
      out.liveEditorMounted = await steady(async () =>
        page.locator('.plate-live-page .plate-doc-editor').first().isVisible({ timeout: 2000 }).catch(() => false), 800, 30000);
      out.liveTitleShown = await steady(async () =>
        page.locator('.plate-live-page .plate-doc-title', { hasText: '桥接E2E 测试文档' }).first().isVisible({ timeout: 2000 }).catch(() => false));
      const text = await page.locator('.plate-live-page .plate-content').first().innerText().catch(() => '');
      out.liveContentLen = text.replace(/\s+/g, '').length;
      out.liveContentHead = text.replace(/\s+/g, '').slice(0, 50);
      step(`live editor mounted=${out.liveEditorMounted} title=${out.liveTitleShown} contentLen=${out.liveContentLen}`);
    }
    const after = ((await api('docs-list')).documents ?? []);
    out.newDocs = after.length - before;
    out.newDocTitles = after.filter((d) => d.title === '桥接E2E 测试文档').length;
  }

  await page.screenshot({ path: '/tmp/plate-bridge-e2e.png' });
  console.log('RESULT', JSON.stringify({
    navMarkCount: out.navMarkCount, defaultEditor: out.defaultEditor, cardFound: out.cardFound,
    openButtonSeen: out.openButtonSeen ?? false, liveEditorMounted: out.liveEditorMounted ?? false,
