  out.fatal = String(e).slice(0, 300);
  await page.screenshot({ path: '/tmp/plate-card-recon-fatal.png' }).catch(() => {});
  console.log('FATAL', out.fatal);
}
writeFileSync('/tmp/plate-card-recon-result.json', JSON.stringify(out, null, 2));
