// 侦察 v2：找 Files 树里的 docx 行（含坐标）→ 点击 → 预览工具条按钮。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { writeFileSync } from 'node:fs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const out = { steps: [], pageErrors: [] };
const step = (s) => { out.steps.push(s); console.log('STEP', s); };

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
page.on('pageerror', (e) => out.pageErrors.push(String(e).slice(0, 300)));

try {
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForSelector('text=探索未至之境', { timeout: 90000 });
  await page.waitForTimeout(8000);

  // 所有可见且文本含 .docx 的元素 + 坐标（判定文件树行 vs 聊天卡）。
  out.docxEls = await page.evaluate(() =>
    Array.from(document.querySelectorAll('*'))
      .filter((el) => (el.textContent ?? '').includes('.docx') && el.getBoundingClientRect().width > 0)
      .slice(-20)
      .map((el) => {
        const r = el.getBoundingClientRect();
        return { tag: el.tagName, cls: String(el.className).slice(0, 60), text: (el.textContent ?? '').slice(0, 60), x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width) };
      }));
  step(`docx elements: ${out.docxEls.length}`);

  // 文件树行：偏左侧（x < 600）的最小文本元素。点它。
  const row = out.docxEls.find((el) => el.x < 600 && el.w < 500);
  if (!row) throw new Error('未找到左侧文件树 docx 行');
  step(`clicking row: ${row.tag} "${row.text}" at x=${row.x},y=${row.y}`);
  await page.mouse.click(row.x + Math.min(row.w / 2, 80), row.y + 10);
  await page.waitForTimeout(5000);

  out.afterClick = await page.evaluate(() => ({
    openBtn: !!document.querySelector('.plate-open-in-plate'),
    plateLive: !!document.querySelector('.plate-live-page'),
    rightPaneText: (Array.from(document.querySelectorAll('[class*="pane"]'))
      .map((el) => (el.textContent ?? '').slice(0, 40))
      .find((t) => t.includes('docx') || t.includes('桥接') || t.includes('用 PlateAI')) ?? ''),
  }));
  step(`openBtn=${out.afterClick.openBtn} rightPaneText="${out.afterClick.rightPaneText.slice(0, 30)}"`);

  // 按钮在就点：完整桥接链验证。
  if (out.afterClick.openBtn) {
    const btn = page.locator('.plate-open-in-plate').first();
    await btn.click();
    await page.waitForTimeout(6000);
    out.liveEditorMounted = await page.locator('.plate-live-page .plate-doc-editor').first().isVisible({ timeout: 8000 }).catch(() => false);
    out.liveTitle = await page.locator('.plate-live-page .plate-doc-title').first().innerText().catch(() => '');
    out.liveContentLen = (await page.locator('.plate-live-page .plate-content').first().innerText().catch(() => '')).replace(/\s+/g, '').length;
    step(`live editor mounted=${out.liveEditorMounted} title="${out.liveTitle}" contentLen=${out.liveContentLen}`);
  }
  await page.screenshot({ path: '/tmp/plate-files-recon.png' });
  console.log('RESULT', JSON.stringify({ docxEls: out.docxEls, afterClick: out.afterClick, liveEditorMounted: out.liveEditorMounted ?? false, liveTitle: out.liveTitle ?? '', liveContentLen: out.liveContentLen ?? 0, pageErrors: out.pageErrors.length }));
} catch (e) {
  out.fatal = String(e).slice(0, 300);
  await page.screenshot({ path: '/tmp/plate-files-recon-fatal.png' }).catch(() => {});
  console.log('FATAL', out.fatal);
}
writeFileSync('/tmp/plate-files-recon-result.json', JSON.stringify(out, null, 2));
await browser.close();

