      : editor.api.string({ anchor: editor.api.start(editor, []), focus: editor.api.end(editor, []) });
    if (!text.trim()) {
      setState({ action, busy: false, text: '', expanded, savedRange: expanded ? selection : null, inserted: false, error: '没有可处理的文本，请先输入内容。' });
