  const editor = useState(() => createPlateEditor({ plugins, value: props.content }))[0];
  return (
    <div className="plate-file-body">
      <Plate editor={editor}>
        <PlateContent readOnly className="plate-content" />
      </Plate>
    </div>
  );
}

