// v1.5.0 原生 AI UI 探针：agent 开活编辑器 → 工具条 AI 按钮 → cmdk 菜单
// ① 润色（选区→edit 建议 diff→Accept→内容变更）
// ② 续写（无选区→insert 模式流式插入→Accept）
// ③ 自由输入 generate 预览（选区+Enter→AIChatEditor 预览→Accept 替换）
// ④ 翻译（选区→edit 建议→Accept→出现英文）
// 全部 stead 双采样 + pageErrors 收集。前置：缺省=plate（外部已设）。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { writeFileSync } from 'node:fs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const MESSAGE = '请写一份关于人工智能伦理的简短文档，标题用《原生AI菜单测试》，两段话。';
const out = { steps: [], consoleErrors: [], pageErrors: [], aiCommands: [] };
const step = (s) => { out.steps.push(s); console.log('STEP', s); };

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
page.on('console', (m) => { if (m.type() === 'error') out.consoleErrors.push(m.text().slice(0, 300)); });
page.on('pageerror', (e) => out.pageErrors.push(String(e).slice(0, 300)));
// ai-command 网络观测：全量记（含成败与字节数），判「LLM 有没有真的流」。
const pending = new Map();
page.on('request', (r) => {
  if (r.url().includes('/api/workdsh-plate')) {
    try {
      const body = JSON.parse(r.postData() ?? '{}');
      if (body.endpoint === 'ai-command') {
        const rec = { started: Date.now(), promptLen: JSON.stringify(body.messages ?? []).length, tool: body.ctx?.toolName ?? null, status: null, bytes: null, ms: null };
        out.aiCommands.push(rec);
        pending.set(r, rec);
      }
    } catch {}
  }
});
page.on('response', (r) => {
  if (r.url().includes('/api/workdsh-plate')) {
    try {
      const body = JSON.parse(r.request().postData() ?? '{}');
      if (body.endpoint === 'ai-command' && pending.has(r.request())) {
        const rec = pending.get(r.request());
        rec.status = r.status();
        rec.bytes = Number(r.headers()['content-length'] ?? 0);
        rec.ms = Date.now() - rec.started;
        pending.delete(r.request());
      }
    } catch {}
  }
});

const api = (endpoint, payload = {}) => page.evaluate(async ({ endpoint, payload }) => {
  const r = await fetch('/api/workdsh-plate', {
    method: 'POST', credentials: 'same-origin',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ endpoint, ...payload }),
  });
  return r.json();
}, { endpoint, payload });

async function steady(predicate, gap = 800, timeout = 30000) {
  const deadline = Date.now() + timeout;
  for (;;) {
    if (await predicate()) {
      await page.waitForTimeout(gap);
      if (await predicate()) return true;
    }
    if (Date.now() > deadline) return false;
    await page.waitForTimeout(500);
  }
}

try {
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForSelector('text=探索未至之境', { timeout: 90000 });
  await page.waitForTimeout(4000);
  const gate = page.locator('text=选择一个工作区开始').first();
  if (await gate.isVisible({ timeout: 5000 }).catch(() => false)) {
    await page.locator('text=选择工作区').first().click();
    await page.waitForTimeout(1500);
    await page.locator('[role="option"]:has-text("团队知识库"), [role="menuitem"]:has-text("团队知识库"), li:has-text("团队知识库")').first().click({ timeout: 10000 }).catch(() => {});
    await page.waitForTimeout(3000);
  }

  const setting = await api('get-default-editor');
  out.defaultEditor = setting.editor;
  if (setting.editor !== 'plate') throw new Error(`前置未满足：缺省应为 plate，实际 ${setting.editor}`);

  // 先试恢复上次会话的活编辑器（右 pane 状态持久化），30s 内出现即复用。
  let restored = false;
  {
    const deadline = Date.now() + 30000;
    while (Date.now() < deadline) {
      const mounted = await page.locator('.plate-live-page .plate-doc-editor').first().isVisible({ timeout: 2000 }).catch(() => false);
      const text = await page.locator('.plate-live-page .plate-content').first().innerText().catch(() => '');
      if (mounted && text.replace(/\s+/g, '').length > 20) { restored = true; break; }
      await page.waitForTimeout(3000);
    }
  }
  if (!restored) {
    await page.locator('button[aria-label="新建会话"], button:has-text("新会话")').first().click({ timeout: 10000 }).catch(() => {});
    await page.waitForTimeout(5000);
    step('new session open');

    const composer = page.locator('[contenteditable="true"].uV2eYG_input').first();
    await composer.click({ timeout: 30000 });
    await page.keyboard.type(MESSAGE, { delay: 30 });
    await page.waitForTimeout(800);
    await page.locator('button.uV2eYG_primary').first().click({ timeout: 8000 });
    step('message sent');

    // 等活编辑器（300s 预算）。
    const deadline = Date.now() + 300000;
    let ready = false;
    while (Date.now() < deadline && !ready) {
      await page.waitForTimeout(5000);
      const mounted = await page.locator('.plate-live-page .plate-doc-editor').first().isVisible({ timeout: 2000 }).catch(() => false);
      const text = await page.locator('.plate-live-page .plate-content').first().innerText().catch(() => '');
      ready = mounted && text.replace(/\s+/g, '').length > 20;
    }
    restored = ready;
  }
  out.editorReady = restored;
  step(`live editor ready = ${restored} (restored=${restored})`);
  if (!restored) throw new Error('活编辑器未就绪');

  const content = () => page.locator('.plate-live-page .plate-content').first();
  const textNow = async () => (await content().innerText().catch(() => '')).replace(/\s+/g, '');
  const aiBtn = () => page.locator('.pltx-ai-btn').first();

  // ① 润色：三连击选区 → AI 菜单 → 润色 → edit 建议 diff → Accept。
  await content().click({ clickCount: 3, timeout: 8000 });
  await aiBtn().click({ timeout: 5000 });
  out.menuShown = await steady(async () => page.locator('.pltx-ai-popover').first().isVisible({ timeout: 2000 }).catch(() => false));
  out.menuInputSeen = await page.locator('.pltx-ai-input').first().isVisible({ timeout: 3000 }).catch(() => false);
  out.menuItemLabels = await page.locator('.pltx-ai-item').allInnerTexts().catch(() => []);
  out.hasPolishItem = out.menuItemLabels.some((t) => t.includes('润色'));
  step(`menu shown=${out.menuShown} items=${JSON.stringify(out.menuItemLabels.slice(0, 8))}`);

  const before = await textNow();
  await page.locator('.pltx-ai-item', { hasText: '润色' }).first().click({ timeout: 5000 });
  out.suggestionsSeen = await steady(async () =>
    (await page.locator('.plate-live-page .pltx-suggestion').count()) > 0, 800, 180000);
  out.suggestionMenuSeen = await steady(async () =>
    page.locator('.pltx-ai-item', { hasText: 'Accept' }).first().isVisible({ timeout: 2000 }).catch(() => false), 800, 30000);
  step(`polish: suggestions=${out.suggestionsSeen} acceptMenu=${out.suggestionMenuSeen}`);

  await page.locator('.pltx-ai-item', { hasText: 'Accept' }).first().click({ timeout: 5000 }).catch(() => {});
  out.polishChanged = await steady(async () => (await textNow()) !== before, 800, 30000);
  step(`polish accepted, content changed = ${out.polishChanged}`);

  // 每轮结束收菜单（Accept 在 chat 模式不自动 hide）：点输入框聚焦后 Esc
  // 走 Popover 的 onEscapeKeyDown → api.aiChat.hide()。
  await page.locator('.pltx-ai-input').first().click({ timeout: 3000 }).catch(() => {});
  await page.keyboard.press('Escape');
  out.menuClosedAfterEsc = await steady(async () =>
    !(await page.locator('.pltx-ai-popover').first().isVisible({ timeout: 2000 }).catch(() => true)), 800, 15000);
  step(`menu closed = ${out.menuClosedAfterEsc}`);

  // ② 续写：光标（无选区）→ AI 菜单 → 续写 → insert 模式流式插入 → Accept。
  await content().click({ timeout: 8000 });
  await aiBtn().click({ timeout: 5000 });
  out.cursorMenuSeen = await steady(async () =>
    page.locator('.pltx-ai-item', { hasText: '续写' }).first().isVisible({ timeout: 2000 }).catch(() => false), 800, 45000);
  if (!out.cursorMenuSeen) {
    out.round2Debug = await page.evaluate(() => ({
      popoverCount: document.querySelectorAll('.pltx-ai-popover').length,
      popoverVisible: !!document.querySelector('.pltx-ai-popover'),
      inputSeen: !!document.querySelector('.pltx-ai-input'),
      items: Array.from(document.querySelectorAll('.pltx-ai-item')).map((el) => (el.textContent ?? '').slice(0, 30)),
      aiBtnVisible: !!document.querySelector('.pltx-ai-btn'),
      bodyHasMenu: document.body.innerText.includes('续写'),
    }));
    step(`round2 debug: ${JSON.stringify(out.round2Debug)}`);
  }
  const beforeInsert = await textNow();
  await page.locator('.pltx-ai-item', { hasText: '续写' }).first().click({ timeout: 5000 });
  out.loadingBarSeen = await page.locator('.pltx-ai-loading').first().isVisible({ timeout: 20000 }).catch(() => false);
  out.insertGrew = await steady(async () => (await textNow()).length > beforeInsert.length + 10, 800, 180000);
  out.aiLeafSeen = await steady(async () =>
    (await page.locator('.plate-live-page .pltx-ai-leaf').count()) > 0, 800, 30000);
  out.insertAcceptSeen = await steady(async () =>
    page.locator('.pltx-ai-item', { hasText: 'Accept' }).first().isVisible({ timeout: 2000 }).catch(() => false), 800, 30000);
  await page.locator('.pltx-ai-item', { hasText: 'Accept' }).first().click({ timeout: 5000 }).catch(() => {});
  step(`continue: loadingBar=${out.loadingBarSeen} grew=${out.insertGrew} aiLeaf=${out.aiLeafSeen} accept=${out.insertAcceptSeen}`);
  await page.locator('.pltx-ai-input').first().click({ timeout: 3000 }).catch(() => {});
  await page.keyboard.press('Escape');
  await page.waitForTimeout(1000);

  // ③ 自由输入 generate 预览：选区 → 输入 → Enter → AIChatEditor 预览 → Accept 替换。
  await content().click({ clickCount: 3, timeout: 8000 });
  await aiBtn().click({ timeout: 5000 });
  await page.locator('.pltx-ai-input').first().fill('把这个段落改写得更简洁', { timeout: 5000 });
  await page.keyboard.press('Enter');
  out.previewShown = await steady(async () =>
    page.locator('.pltx-editor-static-aichat').first().isVisible({ timeout: 2000 }).catch(() => false), 800, 180000);
  out.previewAcceptSeen = await steady(async () =>
    page.locator('.pltx-ai-item', { hasText: 'Accept' }).first().isVisible({ timeout: 2000 }).catch(() => false), 800, 30000);
  await page.locator('.pltx-ai-item', { hasText: 'Accept' }).first().click({ timeout: 5000 }).catch(() => {});
  out.previewReplaced = await steady(async () => (await textNow()).length > 10, 800, 30000);
  step(`generate preview: shown=${out.previewShown} accept=${out.previewAcceptSeen} replaced=${out.previewReplaced}`);
  await page.locator('.pltx-ai-input').first().click({ timeout: 3000 }).catch(() => {});
  await page.keyboard.press('Escape');
  await page.waitForTimeout(1000);

  // ④ 翻译：选区 → 翻译 → edit 建议 → Accept → 内容出现英文。
  await content().click({ clickCount: 3, timeout: 8000 });
  await aiBtn().click({ timeout: 5000 });
  out.translateItemSeen = await steady(async () =>
    page.locator('.pltx-ai-item', { hasText: '翻译' }).first().isVisible({ timeout: 2000 }).catch(() => false));
  await page.locator('.pltx-ai-item', { hasText: '翻译' }).first().click({ timeout: 5000 });
  out.translateSuggestions = await steady(async () =>
    (await page.locator('.plate-live-page .pltx-suggestion').count()) > 0, 800, 180000);
  await steady(async () =>
    page.locator('.pltx-ai-item', { hasText: 'Accept' }).first().isVisible({ timeout: 2000 }).catch(() => false), 800, 30000);
  await page.locator('.pltx-ai-item', { hasText: 'Accept' }).first().click({ timeout: 5000 }).catch(() => {});
  out.translateEnglish = await steady(async () => /[a-zA-Z]{4,}/.test(await textNow()), 800, 30000);
  step(`translate: item=${out.translateItemSeen} suggestions=${out.translateSuggestions} english=${out.translateEnglish}`);

  await page.screenshot({ path: '/tmp/plate-native-ai.png' });
  console.log('RESULT', JSON.stringify({ ...out, steps: undefined, consoleErrors: out.consoleErrors.length, pageErrors: out.pageErrors.length }));
} catch (e) {
  out.fatal = String(e).slice(0, 400);
  await page.screenshot({ path: '/tmp/plate-native-ai-fatal.png' }).catch(() => {});
  console.log('FATAL', out.fatal);
}
writeFileSync('/tmp/plate-native-ai-result.json', JSON.stringify(out, null, 2));
await browser.close();

import type { Context } from '@deepseek-ai/cordis';
import type { HostConnectionHandle } from '@deepseek-ai/dsh-client-connection';
import type {} from '@deepseek-ai/dsh-agent-default-model';
import type { GenerateOptions, ReasoningEffortId } from '@deepseek-ai/dsh-llm';
import { defineTool } from '@deepseek-ai/dsh-tools';
import { createUIMessageStream, createUIMessageStreamResponse } from 'ai';
import { PlateDocService, docIdParam } from './service.js';
import { slateJson } from './storage.js';
import { importDocx } from './docx.js';
import { z } from 'zod';

export const name = 'workdsh-plate';
export const inject = ['llm', 'agentDefaultModel', 'connection', 'tools', 'systemPrompt'];

const PREFIX = '[workdsh-plate]';

const requestShape = z.discriminatedUnion('endpoint', [
  z.object({ endpoint: z.literal('ping') }).strict(),
  z.object({ endpoint: z.literal('ai-smoke'), prompt: z.string().max(4000).optional() }).strict(),
  z.object({ endpoint: z.literal('docs-list') }).strict(),
  z.object({ endpoint: z.literal('doc-create'), title: z.string().min(1).max(256), content: slateJson }).strict(),
  z.object({ endpoint: z.literal('doc-import'), title: z.string().min(1).max(256), content: slateJson }).strict(),
  z.object({ endpoint: z.literal('doc-open'), docId: docIdParam }).strict(),
  z.object({ endpoint: z.literal('doc-export'), docId: docIdParam }).strict(),
  z.object({ endpoint: z.literal('rev-append'), docId: docIdParam, content: slateJson, cause: z.enum(['edit', 'ai', 'import']) }).strict(),
  z.object({
    endpoint: z.literal('ai-command'),
    // AI SDK transport 会在 body 里附带 id 等自有字段，不 strict。
    messages: z.unknown().array().max(64),
    ctx: z.object({
      children: slateJson,
      selection: z.unknown().nullable(),
      toolName: z.enum(['generate', 'edit']),
    }),
  }),
  z.object({ endpoint: z.literal('get-default-editor') }).strict(),
  z.object({ endpoint: z.literal('set-default-editor'), editor: z.enum(['office', 'plate']) }).strict(),
  z.object({ endpoint: z.literal('plate-pending'), sessionId: z.string().max(128) }).strict(),
  z.object({ endpoint: z.literal('docx-import'), path: z.string().min(1).max(1024) }).strict(),
]);

// 「缺省文档编辑器 = PlateAI」时的 agent 写作指南。作为动态 text provider 注册：
// 缺省=office 时返回空串，行为与改前逐字节一致；缺省=plate 时注入本段。
// order 排在 office 指南（TOOL_REPORT）之后，后置+明确禁令覆盖文档类请求；
// PPT/Excel/PDF/HTML 请求仍走 office（content_* 照常）。
const plateGuide = `PlateAI live document writing (the default document editor is PlateAI):
When the user asks you to write a document, report, or Word-style document, use the plate_* tools to write in the live Plate editor on the right. Do NOT use content_* tools for this kind of request; content_* remains only for PPT, Excel, PDF and HTML requests.
First call plate_open with a title and a unique operationId; this immediately opens an empty Plate document on the right. Do this before lengthy planning. Reuse the same operationId on retries. Do not compose the entire report in chat first.
Then call plate_edit to write the title and first useful paragraph, and continue in small meaningful batches so the user sees progress. plate_edit REPLACES the entire document: every call must submit the complete Slate JSON — all previous content plus this batch — never a fragment. Content is Slate editor JSON: an array of nodes, e.g. [{"type":"p","children":[{"text":"标题"}]}]; paragraphs use type "p", headings type "h1".."h3", lists/blocks optional. Keep a single edit under roughly 1 MiB; embedded images are base64 data URLs inside the JSON and count toward the 6 MB document limit, so prefer small images. After a human edit, call plate_read first and re-read the latest content before the next plate_edit; never guess the existing text. Do not fabricate citations, claims or figures.
The deliverable is the live Plate document itself. After finishing, tell the user it is open in the right Plate editor where they can keep editing and click 导出 .plate to download. Do not claim a file was delivered, and do not use Bash/Python or a file-generation skill to build the document.`;

// Tool 参数/输出 schema（镜像 office：string = {type:'string', required:true}）。
const string = { type: 'string', required: true } as const;
const slateContentSchema = {
  type: 'array',
  required: true,
  items: { type: 'object', additionalProperties: true },
} as const;
const render = (_args: unknown, value: unknown) => [
  { type: 'text' as const, text: JSON.stringify(value) },
];
const permissiveOutput = {
  schema: { type: 'object', additionalProperties: true } as const,
  render,
};

function registerTools(ctx: Context) {
  for (const toolName of ['plate_open', 'plate_read', 'plate_edit']) {
    if (ctx.tools.get(toolName)) {
      throw new Error(`Plate tool name already registered: ${toolName}`);
    }
  }
  ctx.effect(() => ctx.tools.register(defineTool({
    name: 'plate_open',
    description:
      'Create a new Plate document and open it in the live right-hand editor immediately. Use this for document/report/Word-style requests (the default document editor is PlateAI); never use content_* for these. Pass a title and a unique operationId; reuse the same operationId on retries. New documents start with one empty paragraph.',
    parameters: { title: string, operationId: string },
    output: permissiveOutput,
    execute: async (args, exec) => {
      exec.signal.throwIfAborted();
      const { doc, head } = ctx.workdshPlate.createDocument(
        args.title,
        [{ type: 'p', children: [{ text: '' }] }],
        'create',
      );
      ctx.workdshPlate.pushPending({
        sessionId: exec.agent ? String(exec.agent.id) : '',
        documentId: doc.id,
        requestId: args.operationId,
      });
      return { documentId: doc.id, title: doc.title, revision: head.seq };
    },
  })));
  ctx.effect(() => ctx.tools.register(defineTool({
    name: 'plate_read',
    description:
      'Read the latest committed content of a Plate document. Re-read after a human edit or before every plate_edit; never guess the existing text. Returns the complete Slate JSON the next plate_edit must be based on.',
    parameters: { documentId: string },
    output: permissiveOutput,
    execute: async (args, exec) => {
      exec.signal.throwIfAborted();
      const { doc, head } = ctx.workdshPlate.openDocument(args.documentId);
      // JSON 往返保证 wire 安全（同 office 的 jsonValue 过滤思路）。
      return { documentId: doc.id, title: doc.title, revision: head.seq, content: JSON.parse(JSON.stringify(head.slateJson)) };
    },
  })));
  ctx.effect(() => ctx.tools.register(defineTool({
    name: 'plate_edit',
    description:
      'Replace the ENTIRE content of a Plate document in one commit: submit the complete Slate JSON — all previous content plus this batch — never a fragment. Use after plate_read, in small meaningful batches (title and first paragraph first), so the user sees progress. Paragraphs are {"type":"p","children":[{"text":"..."}]}; headings {"type":"h1".."h3","children":[...]}. Keep one edit under roughly 1 MiB; the whole document must stay under 6 MB (embedded images are base64 data URLs).',
    parameters: { documentId: string, content: slateContentSchema },
    output: permissiveOutput,
    execute: async (args, exec) => {
      exec.signal.throwIfAborted();
      const { doc, head } = ctx.workdshPlate.appendRevision(
        args.documentId,
        args.content as unknown as z.infer<typeof slateJson>,
        'ai',
      );
      return { documentId: doc.id, revision: head.seq };
    },
  })));
}

export async function apply(ctx: Context) {
  await ctx.plugin(PlateDocService);

  // S1/S2 evidence: the llm service is injectable and the default model
  // selection resolves to a concrete provider/model route.
  try {
    const selection = ctx.agentDefaultModel.currentSelection();
    console.log(`${PREFIX} applied; llm.stream=${typeof ctx.llm?.stream === 'function'} selection=${JSON.stringify(selection)}`);
  } catch (error) {
    console.log(`${PREFIX} applied; selection probe failed: ${String(error)}`);
  }

  // 「缺省文档编辑器」开关的 agent 侧效果：动态段逐次组装求值，读服务端缓存。
  // 根插件不能注入自己提供的 workdshPlate（自注入死锁），提示词段与工具、
  // 连接一样走子插件绕行——否则每次 prompt 组装都会抛 "without inject"。
  await ctx.plugin({
    name: 'workdsh-plate-prompt',
    inject: ['systemPrompt', 'workdshPlate'],
    apply(api: Context) {
      api.effect(() => api.systemPrompt.section({
        name: 'workdsh:plate-authoring',
        order: api.systemPrompt.getSectionOrder('TOOL_REPORT') + 1,
        text: () => (api.workdshPlate.getDefaultEditor() === 'plate' ? plateGuide : ''),
      }));
    },
  });

  // plate_* 工具链：与 office 的 content_* 平行的 agent 入口。
  await ctx.plugin({
    name: 'workdsh-plate-tools',
    inject: ['tools', 'workdshPlate'],
    apply(api: Context) {
      registerTools(api);
    },
  });

  // The API entry is a separate loader entry so it can inject the service
  // this plugin provides above (self-injection would deadlock at boot).
  await ctx.plugin({
    name: 'workdsh-plate-connection',
    inject: ['connection', 'llm', 'agentDefaultModel', 'workdshPlate'],
    apply(api: Context) {
      registerApi(api);
    },
  });
}

function registerApi(ctx: Context) {
  const connection = (ctx as Context & { connection: HostConnectionHandle }).connection;

  const unregister = connection.fetch.register({
    path: '/api/workdsh-plate',
    methods: ['POST'],
    requestBody: 'buffered',
    async fetch(request) {
      let raw: unknown;
      try {
        raw = await request.json();
      } catch {
        return Response.json({ ok: false, code: 'BAD_JSON' }, { status: 400 });
      }
      const parsed = requestShape.safeParse(raw);
      if (!parsed.success) {
        return Response.json({ ok: false, code: 'BAD_SHAPE', message: parsed.error.issues[0]?.message ?? 'invalid request' }, { status: 400 });
      }
      const body = parsed.data;
      if (body.endpoint === 'ping') {
        return Response.json({ ok: true, name: 'workdsh-plate' });
      }
      if (body.endpoint === 'docs-list') {
        return Response.json({ ok: true, documents: ctx.workdshPlate.listDocuments() });
      }
      if (body.endpoint === 'doc-create') {
        try {
          return Response.json({ ok: true, ...ctx.workdshPlate.createDocument(body.title, body.content) });
        } catch (error) {
          return Response.json({ ok: false, code: 'CREATE_FAILED', message: String(error) }, { status: 500 });
        }
      }
      if (body.endpoint === 'doc-import') {
        // 从 .plate 文件导入：首修订 cause='import'，与手动新建（'create'）区分。
        try {
          return Response.json({ ok: true, ...ctx.workdshPlate.createDocument(body.title, body.content, 'import') });
        } catch (error) {
          return Response.json({ ok: false, code: 'IMPORT_FAILED', message: String(error) }, { status: 500 });
        }
      }
      if (body.endpoint === 'doc-open' || body.endpoint === 'doc-export') {
        try {
          return Response.json({ ok: true, ...ctx.workdshPlate.openDocument(body.docId) });
        } catch {
          return Response.json({ ok: false, code: 'NOT_FOUND' }, { status: 404 });
        }
      }
      if (body.endpoint === 'rev-append') {
        try {
          return Response.json({ ok: true, ...ctx.workdshPlate.appendRevision(body.docId, body.content, body.cause) });
        } catch {
          return Response.json({ ok: false, code: 'NOT_FOUND' }, { status: 404 });
        }
      }
      if (body.endpoint === 'get-default-editor') {
        return Response.json({ ok: true, editor: ctx.workdshPlate.getDefaultEditor() });
      }
      if (body.endpoint === 'set-default-editor') {
        ctx.workdshPlate.setDefaultEditor(body.editor);
        return Response.json({ ok: true, editor: ctx.workdshPlate.getDefaultEditor() });
      }
      if (body.endpoint === 'plate-pending') {
        return Response.json({ ok: true, requests: ctx.workdshPlate.takePending(body.sessionId) });
      }
      if (body.endpoint === 'docx-import') {
        // 「用 PlateAI 打开」：读 docx 文件 → 解析成 Slate JSON → 导入 plate 域。
        try {
          const { title, content } = await importDocx(body.path);
          const { doc, head } = ctx.workdshPlate.createDocument(title, content as unknown as z.infer<typeof slateJson>, 'import');
          return Response.json({ ok: true, doc, head: { seq: head.seq } });
        } catch (error) {
          return Response.json({ ok: false, code: 'DOCX_IMPORT_FAILED', message: String(error) }, { status: 400 });
        }
      }
      if (body.endpoint === 'ai-command') {
        // v1.5.0 原生 AI 菜单的命令流：最后一条用户消息是客户端拼好的完整
        // 提示词（模板+选区 Markdown），按 AI SDK UI message stream 协议回码。
        let options: GenerateOptions;
        try {
          const selection = ctx.agentDefaultModel.currentSelection();
          const messages = body.messages as Array<{ parts?: Array<{ type?: string; text?: string }> }>;
          const lastWithText = [...messages].reverse().find((m) => m.parts?.some((p) => p.type === 'text'));
          const prompt = lastWithText?.parts?.find((p) => p.type === 'text')?.text?.trim();
          if (!prompt) {
            return Response.json({ ok: false, code: 'EMPTY_PROMPT' }, { status: 400 });
          }
          options = {
            provider: selection.provider,
            model: selection.model,
            ...(selection.reasoningEffort
              ? { reasoningEffort: selection.reasoningEffort as ReasoningEffortId }
              : {}),
            system: '你是中文写作助手。按用户指令处理文档内容，只输出结果的 Markdown（保留标题、加粗、段落结构），不要任何解释与前后缀。',
            messages: [{
              role: 'user',
              content: [{ type: 'text', text: prompt }],
            }],
            maxTokens: 2048,
            signal: request.signal,
          };
        } catch (error) {
          return Response.json({ ok: false, code: 'SELECTION_FAILED', message: String(error) }, { status: 500 });
        }
        console.log(`${PREFIX} ai-command tool=${body.ctx.toolName} provider=${options.provider} model=${options.model}`);
        return streamUiMessages(ctx, options);
      }
      // ai-smoke: build options from the default model selection and stream
      // ctx.llm.stream as SSE text-delta frames.
      const prompt = body.endpoint === 'ai-smoke'
        ? (body.prompt?.trim() ? body.prompt.trim().slice(0, 4000) : '用一句话介绍富文本编辑器。')
        : null;
      let options: GenerateOptions;
      try {
        const selection = ctx.agentDefaultModel.currentSelection();
        options = {
          provider: selection.provider,
          model: selection.model,
          ...(selection.reasoningEffort
            ? { reasoningEffort: selection.reasoningEffort as ReasoningEffortId }
            : {}),
          system: '你是中文写作助手，回答简洁。',
          messages: [{
            role: 'user',
            content: [{ type: 'text', text: prompt! }],
          }],
          maxTokens: 512,
          signal: request.signal,
        };
      } catch (error) {
        return Response.json({ ok: false, code: 'SELECTION_FAILED', message: String(error) }, { status: 500 });
      }
      console.log(`${PREFIX} ${body.endpoint} provider=${options.provider} model=${options.model}`);
      return streamLlm(ctx, options);
    },
  });
  ctx.effect(() => () => unregister());
}

// v1.5.0：AI SDK UI message stream（text-start/text-delta/text-end/finish）。
// 协议编码交给 ai 包的 createUIMessageStream —— 客户端 DefaultChatTransport
// 解码后走官方 AIChat 流式管线（insert 模式流式插入 / edit 模式建议 diff）。
let uiStreamSeq = 0;
function streamUiMessages(ctx: Context, options: GenerateOptions): Response {
  const stream = createUIMessageStream({
    execute: async ({ writer }) => {
      uiStreamSeq += 1;
      const id = `pltx-${Date.now()}-${uiStreamSeq}`;
      writer.write({ type: 'text-start', id });
      try {
        for await (const chunk of ctx.llm.stream(options)) {
          if (chunk.type === 'text-delta') {
            writer.write({ type: 'text-delta', id, delta: chunk.text });
          }
        }
      } finally {
        writer.write({ type: 'text-end', id });
        writer.write({ type: 'finish', finishReason: 'stop' });
      }
    },
  });
  return createUIMessageStreamResponse({ stream });
}

// Shared SSE pipe: text-delta frames with per-chunk timestamps, a usage frame
// when the model reports it, then a terminal done/error frame.
function streamLlm(ctx: Context, options: GenerateOptions): Response {
  const encoder = new TextEncoder();
  const started = Date.now();
  const readable = new ReadableStream<Uint8Array>({
    async start(controller) {
      const send = (payload: unknown) =>
        controller.enqueue(encoder.encode(`data: ${JSON.stringify(payload)}\n\n`));
      try {
        for await (const chunk of ctx.llm.stream(options)) {
          if (chunk.type === 'text-delta') {
            send({ t: Date.now() - started, text: chunk.text });
          } else if (chunk.type === 'usage') {
            send({ t: Date.now() - started, usage: chunk.usage });
          }
        }
        send({ t: Date.now() - started, done: true });
      } catch (error) {
        send({ t: Date.now() - started, error: String(error) });
      } finally {
        controller.close();
      }
    },
  });
  return new Response(readable, {
    headers: {
      'content-type': 'text/event-stream; charset=utf-8',
      'cache-control': 'no-cache',
    },
  });
}

