// 诊断：恢复的活编辑器里 .plate-content 的真实 DOM 结构
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });

await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 });
await page.waitForSelector('text=探索未至之境', { timeout: 90000 });
await page.waitForTimeout(4000);
const gate = page.locator('text=选择一个工作区开始').first();
if (await gate.isVisible({ timeout: 5000 }).catch(() => false)) {
  await page.locator('text=选择工作区').first().click();
  await page.waitForTimeout(1500);
  await page.locator('[role="option"]:has-text("团队知识库"), [role="menuitem"]:has-text("团队知识库"), li:has-text("团队知识库")').first().click({ timeout: 10000 }).catch(() => {});
  await page.waitForTimeout(3000);
}

// 等活编辑器出现
let mounted = false;
for (let i = 0; i < 15 && !mounted; i += 1) {
  await page.waitForTimeout(3000);
  mounted = await page.locator('.plate-live-page .plate-doc-editor').first().isVisible({ timeout: 2000 }).catch(() => false);
}
const diag = await page.evaluate(() => {
  const all = Array.from(document.querySelectorAll('.plate-live-page .plate-content'));
  return all.map((el) => {
    const kids = Array.from(el.querySelectorAll('[data-slate-node]'));
    const tagCounts = {};
    for (const k of kids) {
      const t = k.tagName.toLowerCase();
      const type = (k.getAttribute && k.getAttribute('data-slate-node') !== 'element' ? '' : k.getAttribute('data-slate-type') ?? (k.textContent ?? '').slice(0, 1) === '#' ? 'heading?' : '?');
      tagCounts[t] = (tagCounts[t] ?? 0) + 1;
    }
    return {
      textLen: (el.textContent ?? '').replace(/\s+/g, '').length,
      tagCounts,
      topTags: kids.slice(0, 6).map((k) => `${k.tagName.toLowerCase()}:${k.getAttribute('data-slate-type') ?? ''}`),
      htmlHead: (el.innerHTML ?? '').slice(0, 300),
    };
  });
});
console.log('DIAG', JSON.stringify(diag, null, 2));
await browser.close();

