    for (const k of kids) {
      const t = k.tagName.toLowerCase();
      const type = (k.getAttribute && k.getAttribute('data-slate-node') !== 'element' ? '' : k.getAttribute('data-slate-type') ?? (k.textContent ?? '').slice(0, 1) === '#' ? 'heading?' : '?');
