      topTags: kids.slice(0, 6).map((k) => `${k.tagName.toLowerCase()}:${k.getAttribute('data-slate-type') ?? ''}`),
      htmlHead: (el.innerHTML ?? '').slice(0, 300),
    };
  });
});
console.log('DIAG', JSON.stringify(diag, null, 2));
await browser.close();

