// P2 回归探针：扩写/缩写/纠错（edit 建议 diff）+ 保存 + 图片 + 默认编辑器切换
// + 旧自研 UI 类名清零扫描。复用主探针的活编辑器脚手架。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { writeFileSync } from 'node:fs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const MESSAGE = '请写一份关于人工智能伦理的简短文档，标题用《P2回归测试》，两段话，每段不少于四十字。';
const out = { steps: [], consoleErrors: [], pageErrors: [] };
const step = (s) => { out.steps.push(s); console.log('STEP', s); };

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
page.on('console', (m) => { if (m.type() === 'error') out.consoleErrors.push(m.text().slice(0, 300)); });
page.on('pageerror', (e) => out.pageErrors.push(String(e).slice(0, 300)));

const api = (endpoint, payload = {}) => page.evaluate(async ({ endpoint, payload }) => {
  const r = await fetch('/api/workdsh-plate', {
    method: 'POST', credentials: 'same-origin',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ endpoint, ...payload }),
  });
  return r.json();
}, { endpoint, payload });

async function steady(predicate, gap = 800, timeout = 30000) {
  const deadline = Date.now() + timeout;
  for (;;) {
    if (await predicate()) {
      await page.waitForTimeout(gap);
      if (await predicate()) return true;
    }
    if (Date.now() > deadline) return false;
    await page.waitForTimeout(500);
  }
}

try {
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForSelector('text=探索未至之境', { timeout: 90000 });
  await page.waitForTimeout(4000);
  const gate = page.locator('text=选择一个工作区开始').first();
  if (await gate.isVisible({ timeout: 5000 }).catch(() => false)) {
    await page.locator('text=选择工作区').first().click();
    await page.waitForTimeout(1500);
    await page.locator('[role="option"]:has-text("团队知识库"), [role="menuitem"]:has-text("团队知识库"), li:has-text("团队知识库")').first().click({ timeout: 10000 }).catch(() => {});
    await page.waitForTimeout(3000);
  }

  let ready = false;
  for (let i = 0; i < 10 && !ready; i += 1) {
    await page.waitForTimeout(3000);
    ready = await page.evaluate(() => {
      const el = document.querySelector('.plate-live-page .plate-content');
      return !!el && (el.textContent ?? '').replace(/\s+/g, '').length > 20;
    }).catch(() => false);
  }
  if (!ready) {
    await page.locator('button[aria-label="新建会话"], button:has-text("新会话")').first().click({ timeout: 10000 }).catch(() => {});
    await page.waitForTimeout(5000);
    const composer = page.locator('[contenteditable="true"].uV2eYG_input').first();
    await composer.click({ timeout: 30000 });
    await page.keyboard.type(MESSAGE, { delay: 30 });
    await page.waitForTimeout(800);
    await page.locator('button.uV2eYG_primary').first().click({ timeout: 8000 });
    const deadline = Date.now() + 300000;
    while (Date.now() < deadline && !ready) {
      await page.waitForTimeout(5000);
      ready = await page.evaluate(() => {
        const el = document.querySelector('.plate-live-page .plate-content');
        return !!el && (el.textContent ?? '').replace(/\s+/g, '').length > 20;
      }).catch(() => false);
    }
  }
  step(`editor ready = ${ready}`);
  if (!ready) throw new Error('活编辑器未就绪');

  const content = () => page.locator('.plate-live-page .plate-content').first();
  const firstPara = () => page.locator('.plate-live-page .plate-content .slate-p').first();
  const textNow = async () => (await content().innerText().catch(() => '')).replace(/\s+/g, '');
  const aiBtn = () => page.locator('.pltx-ai-btn').first();
  const closeMenu = async () => {
    await page.locator('.pltx-ai-input').first().click({ timeout: 3000 }).catch(() => {});
    await page.keyboard.press('Escape');
    await page.waitForTimeout(600);
    await page.keyboard.press('Escape');
    await page.waitForTimeout(800);
  };
  const runEditAction = async (itemName, label) => {
    await firstPara().click({ clickCount: 3, timeout: 8000 });
    await aiBtn().click({ timeout: 5000 });
    await steady(async () =>
      page.locator('.pltx-ai-item', { hasText: itemName }).first().isVisible({ timeout: 2000 }).catch(() => false));
    await page.locator('.pltx-ai-item', { hasText: itemName }).first().click({ timeout: 5000 });
    const ok = await steady(async () =>
      (await page.locator('.plate-live-page .pltx-suggestion').count()) > 0, 800, 180000);
    if (!ok) return false;
    await steady(async () =>
      page.locator('.pltx-ai-item', { hasText: 'Accept' }).first().isVisible({ timeout: 2000 }).catch(() => false), 800, 30000);
    await page.locator('.pltx-ai-item', { hasText: 'Accept' }).first().click({ timeout: 5000 }).catch(() => {});
    await closeMenu();
    return true;
  };

  // ① 扩写：内容变长。
  const len0 = (await textNow()).length;
  out.expandOk = await runEditAction('扩写', 'expand');
  const len1 = (await textNow()).length;
  out.expandGrew = len1 > len0 + 10;
  step(`expand: ok=${out.expandOk} grew=${out.expandGrew} (${len0}->${len1})`);

  // ② 缩写：内容变短。
  const len2 = (await textNow()).length;
  out.shrinkOk = await runEditAction('缩写', 'shrink');
  const len3 = (await textNow()).length;
  out.shrinkShrank = len3 < len2 - 10;
  step(`shrink: ok=${out.shrinkOk} shrank=${out.shrinkShrank} (${len2}->${len3})`);

  // ③ 纠错：出建议并 Accept，无异常。
  const len4 = (await textNow()).length;
  out.fixOk = await runEditAction('纠错', 'fix');
  const len5 = (await textNow()).length;
  out.fixRan = len5 !== len4;
  step(`fix: ok=${out.fixOk} ran=${out.fixRan} (${len4}->${len5})`);

  // ④ 保存按钮 → 「已保存」出现。
  await page.locator('text=保存').first().click({ timeout: 8000 });
  out.savedSeen = await steady(async () =>
    page.locator('.plate-saved-at').first().isVisible({ timeout: 2000 }).catch(() => false), 800, 20000);
  step(`save: savedSeen=${out.savedSeen}`);

  // ⑤ 插图（与 v1.4 相同管道：隐藏 file input → data URL <img>）。
  await content().click({ timeout: 8000 });
  await page.locator('input[data-plate-file-input="true"]').first().setInputFiles('/tmp/test-image.png');
  await page.waitForTimeout(3000);
  out.imgCount = await content().locator('img').count();
  out.imgDataUrl = ((await content().locator('img').first().getAttribute('src').catch(() => '')) ?? '').startsWith('data:image');
  step(`image: count=${out.imgCount} dataUrl=${out.imgDataUrl}`);

  // ⑥ 缺省编辑器 SegmentedControl：Word → office，PlateAI → plate。
  const modeSeg = page.locator('.plate-editor-mode').first();
  await modeSeg.locator('text=Word').first().click({ timeout: 8000 }).catch(() => {});
  await page.waitForTimeout(1200);
  out.modeAfterWord = (await api('get-default-editor')).editor;
  await modeSeg.locator('text=PlateAI').first().click({ timeout: 8000 }).catch(() => {});
  await page.waitForTimeout(1200);
  out.modeAfterPlate = (await api('get-default-editor')).editor;
  step(`default editor switch: word=${out.modeAfterWord} plate=${out.modeAfterPlate}`);

  // ⑦ 旧自研 UI 类名清零扫描（页面内）。
  out.oldClasses = await page.evaluate(() => ({
    panel: document.querySelectorAll('.plate-ai-panel').length,
    toolbarBtn: document.querySelectorAll('.plate-toolbar-btn').length,
    btnActive: document.querySelectorAll('.plate-btn-active').length,
    aiBtnOld: document.querySelectorAll('.plate-ai-btn').length,
  }));
  step(`old classes: ${JSON.stringify(out.oldClasses)}`);

  await page.screenshot({ path: '/tmp/plate-p2.png' });
  console.log('RESULT', JSON.stringify({ ...out, steps: undefined, consoleErrors: out.consoleErrors.length, pageErrors: out.pageErrors.length }));
} catch (e) {
  out.fatal = String(e).slice(0, 300);
  await page.screenshot({ path: '/tmp/plate-p2-fatal.png' }).catch(() => {});
  console.log('FATAL', out.fatal);
}
writeFileSync('/tmp/plate-p2-result.json', JSON.stringify(out, null, 2));
await browser.close();

