const out = { steps: [], consoleErrors: [], pageErrors: [], aiCommands: [] };
const step = (s) => { out.steps.push(s); console.log('STEP', s); };

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
page.on('console', (m) => { if (m.type() === 'error') out.consoleErrors.push(m.text().slice(0, 300)); });
page.on('pageerror', (e) => out.pageErrors.push(String(e).slice(0, 300)));
page.on('request', (r) => {
  if (r.url().includes('/api/workdsh-plate')) {
    try {
      const body = JSON.parse(r.postData() ?? '{}');
      if (body.endpoint === 'ai-command') out.aiCommands.push({ tool: body.ctx?.toolName ?? null });
    } catch {}
  }
});

async function steady(predicate, gap = 800, timeout = 30000) {
  const deadline = Date.now() + timeout;
  for (;;) {
    if (await predicate()) {
      await page.waitForTimeout(gap);
      if (await predicate()) return true;
    }
    if (Date.now() > deadline) return false;
    await page.waitForTimeout(500);
  }
}

try {
  let landed = false;
  for (let loadAttempt = 1; loadAttempt <= 3 && !landed; loadAttempt += 1) {
    await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 }).catch(() => {});
    landed = await page.waitForFunction(() => document.body.innerText.includes('探索未至之境') || document.body.innerText.includes('新会话'), { timeout: 90000 }).catch(() => false);
