  step(`save: savedSeen=${out.savedSeen}`);

  console.log('RESULT', JSON.stringify({ fixSuggestions: out.fixSuggestions, fixRan: out.fixRan, savedSeen: out.savedSeen, aiCommands: out.aiCommands, consoleErrors: out.consoleErrors.length, pageErrors: out.pageErrors.length }));
} catch (e) {
  out.fatal = String(e).slice(0, 300);
  try {
