// 诊断：打开桥接会话，dump 完整消息/思考文本 + 文件卡现状，供归因
// agent 为何在 default=office 时选择 plate_open。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { writeFileSync } from 'node:fs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const out = {};

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
page.on('console', (m) => { if (m.type() === 'error') (out.consoleErrors ??= []).push(m.text().slice(0, 200)); });

try {
  let landed = false;
  for (let i = 1; i <= 5 && !landed; i += 1) {
    await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 }).catch(() => {});
    landed = await page.waitForFunction(() => document.body.innerText.includes('探索未至之境') || document.body.innerText.includes('新会话'), { timeout: 240000 }).catch(() => false);
    if (!landed) { console.log(`load attempt ${i} failed, cooling down`); await page.waitForTimeout(15000); }
  }
  if (!landed) throw new Error('落地页加载失败');
  await page.waitForTimeout(5000);

  // 找桥接会话（历史列表标题行），点开。
  const row = page.locator('text=桥接E2E 测试文档').first();
  out.sessionRowFound = await row.isVisible({ timeout: 8000 }).catch(() => false);
  if (out.sessionRowFound) {
    await row.click({ timeout: 5000 }).catch(() => {});
    await page.waitForTimeout(8000);
    out.urlAfterClick = page.url();
  }

  // dump 聊天区全部文本（含思考块）。按行截断，避免巨型 blob。
  out.chatText = await page.evaluate(() => {
    const main = document.querySelector('main') ?? document.body;
    const text = (main.innerText ?? '').replace(/\n{3,}/g, '\n\n');
    return text.slice(0, 6000);
  }).catch((e) => `ERR: ${String(e)}`);

  // 文件卡现状：docx 链接/文件卡元素。
  out.docxLinks = await page.evaluate(() =>
    Array.from(document.querySelectorAll('a[href]'))
      .filter((el) => /\.docx/.test(el.getAttribute('href') ?? ''))
      .map((el) => ({ href: el.getAttribute('href'), text: (el.textContent ?? '').slice(0, 40) }))
      .slice(0, 6));

  out.thinkingBlocks = await page.evaluate(() =>
    Array.from(document.querySelectorAll('[class*="think"], [class*="reason"]'))
      .map((el) => (el.textContent ?? '').slice(0, 300))
      .slice(0, 6));

  await page.screenshot({ path: '/tmp/plate-session-dump.png' });
  console.log('RESULT', JSON.stringify({ ...out, chatText: undefined }));
  writeFileSync('/tmp/plate-session-chat.txt', out.chatText ?? '');
  console.log('CHAT-TEXT', (out.chatText ?? '').slice(0, 3000));
} catch (e) {
  out.fatal = String(e).slice(0, 300);
  await page.screenshot({ path: '/tmp/plate-session-dump-fatal.png' }).catch(() => {});
  console.log('FATAL', out.fatal);
}
writeFileSync('/tmp/plate-session-dump.json', JSON.stringify(out, null, 2));
await browser.close();

