// 诊断 v2：分别打开「桥接E2E测试文档」(44分钟) 与「气候变化文档生成示例」(14分钟)
// 两个会话，dump 完整消息/思考文本 + docx 链接现状。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { writeFileSync } from 'node:fs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const out = {};

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
page.on('console', (m) => { if (m.type() === 'error') (out.consoleErrors ??= []).push(m.text().slice(0, 200)); });

async function dumpSession(label, matcher) {
  const rec = {};
  const row = page.locator('text=' + label).first();
  rec.rowFound = await row.isVisible({ timeout: 8000 }).catch(() => false);
  if (!rec.rowFound) { out[label] = rec; return; }
  await row.click({ timeout: 5000 }).catch(() => {});
  await page.waitForTimeout(10000);
  rec.urlAfterClick = page.url();
  rec.chatText = await page.evaluate(() => {
    const main = document.querySelector('main') ?? document.body;
    return (main.innerText ?? '').replace(/\n{3,}/g, '\n\n').slice(0, 5000);
  }).catch((e) => `ERR: ${String(e)}`);
  rec.docxLinks = await page.evaluate(() =>
    Array.from(document.querySelectorAll('a[href]'))
      .filter((el) => /\.docx/.test(el.getAttribute('href') ?? ''))
      .map((el) => ({ href: el.getAttribute('href'), text: (el.textContent ?? '').slice(0, 40) }))
      .slice(0, 6));
  rec.toolChips = await page.evaluate(() =>
    Array.from(document.querySelectorAll('[class*="tool"], [class*="Tool"]'))
      .filter((el) => /plate_|content_|write_file|create/.test(el.textContent ?? ''))
      .map((el) => (el.textContent ?? '').replace(/\s+/g, ' ').slice(0, 120))
      .slice(0, 10));
  await page.screenshot({ path: `/tmp/plate-session-${matcher}.png` });
  writeFileSync(`/tmp/plate-session-${matcher}.txt`, rec.chatText ?? '');
  out[label] = { ...rec, chatText: undefined };
  console.log(`SESSION ${label}: rowFound=${rec.rowFound} docxLinks=${JSON.stringify(rec.docxLinks)} toolChips=${JSON.stringify(rec.toolChips)}`);
  console.log(`--- chat text (${label}) ---`);
  console.log((rec.chatText ?? '').slice(0, 4500));
}

try {
  let landed = false;
  for (let i = 1; i <= 5 && !landed; i += 1) {
    await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 }).catch(() => {});
    landed = await page.waitForFunction(() => document.body.innerText.includes('探索未至之境') || document.body.innerText.includes('新会话'), { timeout: 240000 }).catch(() => false);
    if (!landed) { console.log(`load attempt ${i} failed, cooling down`); await page.waitForTimeout(15000); }
  }
  if (!landed) throw new Error('落地页加载失败');
  await page.waitForTimeout(5000);

  await dumpSession('气候变化文档生成示例', 'climate');
  await dumpSession('桥接E2E测试文档', 'bridge-e2e');
  console.log('RESULT', JSON.stringify(out));
} catch (e) {
  out.fatal = String(e).slice(0, 300);
  await page.screenshot({ path: '/tmp/plate-session-dump2-fatal.png' }).catch(() => {});
  console.log('FATAL', out.fatal);
}
writeFileSync('/tmp/plate-session-dump2.json', JSON.stringify(out, null, 2));
await browser.close();

