cat > /tmp/dsh-session-read.mjs << 'EOF'
// 读 dsh 会话 zstd 日志，按标题找会话，dump 指定关键词周边上下文。
import { readFileSync, existsSync, readdirSync, statSync } from 'node:fs';
import { zstdDecompressSync } from 'node:zlib';
import { join } from 'node:path';

const root = '/Users/apple/workdsh/.test-runtime/preview/sessions';
const needle = process.argv[2] ?? 'content_export';
const keyword = process.argv[3] ?? '';

const dirs = [];
for (const proj of readdirSync(root)) {
  const p = join(root, proj);
  if (!statSync(p).isDirectory()) continue;
  for (const s of readdirSync(p)) {
    const f = join(p, s, 'session.v4.jsonl.zstd');
    if (existsSync(f)) dirs.push({ f, m: statSync(f).mtimeMs });
  }
}
dirs.sort((a, b) => b.m - a.m);
console.log('sessions:', dirs.length);

for (const { f, m } of dirs.slice(0, 8)) {
  let text;
  try { text = zstdDecompressSync(readFileSync(f)).toString('utf8'); } catch (e) { console.log('SKIP', f, String(e).slice(0, 80)); continue; }
  if (!text.includes(needle)) continue;
  console.log('=====', f, new Date(m).toISOString(), 'lines=', text.split('\n').length);
  const lines = text.split('\n');
  for (let i = 0; i < lines.length; i += 1) {
    if (!lines[i].includes(needle)) continue;
    // 打印该行前后各 1 行，行内容截断
    for (const j of [i - 1, i, i + 1]) {
      if (lines[j]) console.log(`  [${j}]`, lines[j].slice(0, 1200));
    }
    console.log('  ---');
    if (keyword && !lines[i].includes(keyword)) continue;
  }
}
EOF
node /tmp/dsh-session-read.mjs content_export 2>&1 | head -60

