import { readFileSync, existsSync, readdirSync, statSync } from 'node:fs';
import { zstdDecompressSync } from 'node:zlib';
import { join } from 'node:path';
const root = '/Users/apple/workdsh/.test-runtime/preview/sessions';
const dirs = [];
for (const proj of readdirSync(root)) {
  const p = join(root, proj);
  if (!statSync(p).isDirectory()) continue;
  for (const s of readdirSync(p)) {
    const f = join(p, s, 'session.v4.jsonl.zstd');
    if (existsSync(f)) dirs.push({ f, s, m: statSync(f).mtimeMs });
  }
}
dirs.sort((a, b) => b.m - a.m);
for (const { f, s, m } of dirs.slice(0, 4)) {
  const text = zstdDecompressSync(readFileSync(f)).toString('utf8');
  const lines = text.split('\n').filter(Boolean);
  console.log('=====', s, new Date(m).toISOString(), 'lines=', lines.length, 'bytes=', text.length);
  // 每行的 type 字段统计
  const types = {};
  let firstUser = null;
  for (const l of lines) {
    try { const o = JSON.parse(l); const t = `${o.type ?? '?'}${o.data?.type ? '/' + o.data.type : ''}`; types[t] = (types[t] ?? 0) + 1;
      if (!firstUser && /桥接|docx|content_/.test(l)) firstUser = l.slice(0, 300);
    } catch { types['<unparsed>'] = (types['<unparsed>'] ?? 0) + 1; }
  }
  console.log('  types:', JSON.stringify(types));
  if (firstUser) console.log('  sample:', firstUser);
}
EOF
node /tmp/dsh-session-dump.mjs 2>&1 | head -40

