// 让会话内 agent 原样运行一条诊断命令：测 output/ 下 mkdir/write/link/unlink
// 与 cwd，判 content_export 的 linkSync 写法是否被沙箱拒绝。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { writeFileSync } from 'node:fs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const CMD = "node -e \"const fs=require('node:fs');const o={cwd:process.cwd()};try{fs.mkdirSync('output',{recursive:true});o.mkdir='ok'}catch(e){o.mkdir=String(e)};const t='output/.probe-'+Date.now()+'.tmp';try{fs.writeFileSync(t,Buffer.from('x'),{flag:'wx'});o.write='ok'}catch(e){o.write=String(e)};try{fs.linkSync(t,t+'.lnk');o.link='ok'}catch(e){o.link=String(e)};try{fs.unlinkSync(t);fs.unlinkSync(t+'.lnk')}catch(e){o.clean=String(e)};console.log('PROBE '+JSON.stringify(o))\"";
const MSG = `请用 bash 工具原样运行下面这条命令（一个字都不要改），然后把完整输出贴回来：\n\n${CMD}`;

const out = {};
const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
try {
  let landed = false;
  for (let i = 1; i <= 5 && !landed; i += 1) {
    await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 }).catch(() => {});
    landed = await page.waitForFunction(() => document.body.innerText.includes('探索未至之境') || document.body.innerText.includes('新会话'), { timeout: 240000 }).catch(() => false);
    if (!landed) { console.log(`load attempt ${i} failed`); await page.waitForTimeout(15000); }
  }
  if (!landed) throw new Error('落地失败');
  await page.waitForTimeout(5000);
  await page.locator('text=桥接E2E测试文档').first().click({ timeout: 8000 });
  await page.waitForTimeout(8000);
  const composer = page.locator('[contenteditable="true"].uV2eYG_input').first();
  await composer.click({ timeout: 60000 });
  // 多行文本：先 paste 再回车发送（type 对多行较慢）。
  await page.evaluate(async (text) => {
    const el = document.querySelector('[contenteditable="true"].uV2eYG_input');
    el.focus();
    const dt = new DataTransfer();
    dt.setData('text/plain', text);
    el.dispatchEvent(new ClipboardEvent('paste', { clipboardData: dt, bubbles: true, cancelable: true }));
  }, MSG).catch(() => {});
  await page.waitForTimeout(1500);
  out.typedLen = await page.evaluate(() => (document.querySelector('[contenteditable="true"].uV2eYG_input')?.innerText ?? '').length);
  if (out.typedLen < 20) {
    await composer.click({ timeout: 30000 });
    await page.keyboard.type(MSG, { delay: 10 });
    await page.waitForTimeout(800);
  }
  await page.locator('button.uV2eYG_primary').first().click({ timeout: 8000 });
  console.log('MSG_SENT');
  // 等 PROBE 输出出现（最多 240s）。
  const deadline = Date.now() + 240000;
  let text = '';
  while (Date.now() < deadline) {
    await page.waitForTimeout(5000);
    text = await page.evaluate(() => document.body.innerText);
    if (text.includes('PROBE ')) break;
  }
  const i = text.indexOf('PROBE ');
  out.probeLine = i >= 0 ? text.slice(i, i + 700).replace(/\n+/g, ' ') : '';
  out.found = i >= 0;
  // 也 dump 尾部，便于诊断
  out.tail = text.replace(/\s+/g, ' ').slice(-1200);
  console.log('FOUND', out.found);
  console.log('PROBE', out.probeLine);
  console.log('TAIL', out.tail);
  writeFileSync('/tmp/plate-linktest.txt', text);
} catch (e) {
  out.fatal = String(e).slice(0, 300);
  console.log('FATAL', out.fatal);
}
writeFileSync('/tmp/plate-linktest.json', JSON.stringify(out, null, 2));
await browser.close();

