// 轻量 API 校验：拦掉 SPA 资源请求，只借 ?token= 拿 cookie，然后直接打
// /api/workdsh-plate。用于高负载下免等 70MB 组合包的契约级验证。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';

const TOKEN = process.argv[2];
const DOCX = process.argv[3];
const BASE = 'http://127.0.0.1:18989';

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
// 拦掉一切重资产，只让文档请求通过（cookie 由 ?token= 的响应种下）。
await page.route('**/*', (route) => {
  const type = route.request().resourceType();
  if (['script', 'stylesheet', 'font', 'image', 'media', 'xhr', 'fetch', 'other'].includes(type)) return route.abort().catch(() => {});
  return route.continue().catch(() => {});
});

const api = (endpoint, payload = {}) => page.evaluate(async ({ endpoint, payload }) => {
  const r = await fetch('/api/workdsh-plate', {
    method: 'POST', credentials: 'same-origin',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ endpoint, ...payload }),
  });
  return { status: r.status, body: await r.json().catch(() => null) };
}, { endpoint, payload });

try {
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'commit', timeout: 60000 });
  await page.waitForTimeout(1500);
  const ping = await api('ping');
  console.log('PING', JSON.stringify(ping));
  if (!ping.body?.ok) throw new Error('auth 未生效（ping 未返回 ok）');

  const docsList = await api('docs-list');
  console.log('DOCS', docsList.status, 'count=', (docsList.body?.documents ?? []).length);

  if (DOCX) {
    const imported = await api('docx-import', { path: DOCX });
    const b = imported.body ?? {};
    const head = b.head ?? {};
    console.log('DOCX-IMPORT', imported.status, JSON.stringify({ ok: b.ok, code: b.code, message: String(b.message ?? '').slice(0, 160), docId: b.doc?.id, title: b.doc?.title, seq: head.seq }));
  }
} catch (e) {
  console.log('FATAL', String(e).slice(0, 300));
}
await browser.close();

