// 轻量 API 校验：只放行 document 与 /api/ 请求，拦掉 SPA 重资产，
// 借 ?token= 拿 cookie 后直接打 /api/workdsh-plate。
// 共享机高负载：Chrome 冷启可达 150s+，超时按此放宽。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';

const TOKEN = process.argv[2];
const DOCX = process.argv[3];
const BASE = 'http://127.0.0.1:18989';

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 600000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
await page.route('**/*', (route) => {
  const url = route.request().url();
  const type = route.request().resourceType();
  if (type === 'document' || url.includes('/api/')) return route.continue().catch(() => {});
  return route.abort().catch(() => {});
});

const api = (endpoint, payload = {}) => page.evaluate(async ({ endpoint, payload }) => {
  const r = await fetch('/api/workdsh-plate', {
    method: 'POST', credentials: 'same-origin',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ endpoint, ...payload }),
  });
  return { status: r.status, body: await r.json().catch(() => null) };
}, { endpoint, payload });

try {
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'commit', timeout: 300000 }).catch((e) => console.log('goto:', String(e).split('\n')[0]));
  const origin = await page.evaluate(() => location.origin).catch(() => null);
  console.log('PAGE_ORIGIN', origin);
  if (origin !== 'http://127.0.0.1:18989') throw new Error('页面未就绪');

  const ping = await api('ping');
  console.log('PING', JSON.stringify(ping));

  const docsList = await api('docs-list');
  console.log('DOCS', docsList.status, 'count=', (docsList.body?.documents ?? []).length);

  if (DOCX) {
    const imported = await api('docx-import', { path: DOCX });
    const b = imported.body ?? {};
    console.log('DOCX-IMPORT', imported.status, JSON.stringify({ ok: b.ok, code: b.code, message: String(b.message ?? '').slice(0, 160), docId: b.doc?.id, title: b.doc?.title, seq: b.head?.seq }));
  }
} catch (e) {
  console.log('FATAL', String(e).split('\n')[0]);
}
await browser.close();

import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
const t0 = Date.now();
try {
  const b = await chromium.launch({ channel: 'chrome', headless: true, timeout: 120000 });
  const p = await b.newPage();
  await p.goto('about:blank');
  console.log('CHROME_OK ms=', Date.now() - t0);
  await b.close();
} catch (e) {
  console.log('CHROME_FAIL ms=', Date.now() - t0, String(e).split('\n')[0]);
}

