import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { execFileSync } from 'node:child_process';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });

async function setDefault(editor) {
  let ok = false;
  for (let attempt = 1; attempt <= 3 && !ok; attempt += 1) {
    await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 90000 }).catch(() => {});
    ok = await page.waitForFunction(() => document.body.innerText.includes('新会话') || document.body.innerText.includes('探索未至之境'), { timeout: 90000 }).catch(() => false);
    if (!ok) await page.reload({ waitUntil: 'domcontentloaded', timeout: 60000 }).catch(() => {});
  }
  const r = await page.evaluate(async (editor) => {
    const res = await fetch('/api/workdsh-plate', {
      method: 'POST', credentials: 'same-origin',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ endpoint: 'set-default-editor', editor }),
    });
    return res.json();
  }, editor);
  console.log('set-default-editor', editor, '->', JSON.stringify(r));
}
await setDefault('office');
await browser.close();

