// 侦察：左侧会话列表行的可点击元素、文本是否被截断、有无 title 属性。
// 目的：为「重放桥接链」找一个只按内容就能点中的选择器。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 600000 });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch((e) => console.log('goto:', String(e).split('\n')[0]));
await page.waitForFunction(() => document.body.innerText.includes('新会话'), { timeout: 120000 }).catch(() => {});
await page.waitForTimeout(3000);

const rows = await page.evaluate(() => {
  const out = [];
  for (const el of document.querySelectorAll('a, button, [role="button"], [role="option"], li, div')) {
    const t = (el.textContent ?? '').replace(/\s+/g, ' ').trim();
    if (!t || t.length > 200) continue;
    if (!/桥接E2E/.test(t)) continue;
    // 只保留「最内层」命中：若子元素也命中同一段文本则跳过
    const inner = Array.from(el.querySelectorAll('*')).some((c) => /桥接E2E/.test(c.textContent ?? ''));
    if (inner) continue;
    const cs = getComputedStyle(el);
    out.push({
      tag: el.tagName,
      cls: String(el.className).slice(0, 50),
      title: el.getAttribute('title') ?? null,
      aria: el.getAttribute('aria-label') ?? null,
      text: t.slice(0, 90),
      scrollW: el.scrollWidth,
      clientW: el.clientWidth,
      overflow: cs.textOverflow + '/' + cs.overflow,
      clickable: !!(el.onclick || el.closest('a,button,[role="button"]')),
    });
  }
  return out.slice(0, 12);
});
console.log('ROWS', JSON.stringify(rows, null, 1));
await browser.close();

