// 侦察 3：定位承载「桥接E2E测试文档-784428」的那一行到底是什么元素、可不可见。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const NEEDLE = process.argv[3] ?? '784428';

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 600000 });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await page.waitForTimeout(6000);

const hits = await page.evaluate((needle) => {
  const res = [];
  for (const el of document.querySelectorAll('*')) {
    const t = (el.textContent ?? '').replace(/\s+/g, ' ').trim();
    if (!t.includes(needle)) continue;
    const inner = Array.from(el.children).some((c) => (c.textContent ?? '').includes(needle));
    if (inner) continue; // 只留最内层
    const r = el.getBoundingClientRect();
    const cs = getComputedStyle(el);
    res.push({
      tag: el.tagName, cls: String(el.className).slice(0, 60),
      role: el.getAttribute('role'), tabindex: el.getAttribute('tabindex'),
      text: t.slice(0, 70),
      rect: [Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height)],
      vis: cs.visibility, disp: cs.display, op: cs.opacity,
      ancestorClickable: el.closest('a,button,[role="button"],[role="option"]')?.tagName ?? null,
      ancestorClass: String(el.closest('a,button,[role="button"],[role="option"]')?.className ?? '').slice(0, 50),
    });
  }
  return res.slice(0, 10);
}, NEEDLE);
console.log('HITS', JSON.stringify(hits, null, 1));

// Playwright 视角：各常见选择器对该文本的可见性命中
const probes = {
  'text=' + NEEDLE: `text=${NEEDLE}`,
  'getByText': null,
};
for (const [label, sel] of Object.entries(probes)) {
  if (!sel) continue;
  const n = await page.locator(sel).count();
  const vis = n ? await page.locator(sel).first().isVisible().catch(() => false) : false;
  console.log('PW', label, 'count=', n, 'firstVisible=', vis);
}
const g = page.getByText(NEEDLE, { exact: false });
console.log('PW getByText count=', await g.count(), 'firstVisible=', await g.count() ? await g.first().isVisible().catch(() => false) : false);
await browser.close();

