toolUseResult.originalFile:
// 桥接链重放：不重新跑 agent（省 LLM、避开 agent 导出抖动），
// 直接打开已有会话（run 10 / tag 784428，磁盘上确有导出 docx），
// 走：文件卡 → 预览 → 原生「用 PlateAI 打开」→ 活编辑器落地。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';

const TOKEN = process.argv[2];
const TAG = process.argv[3] ?? '784428';
const BASE = 'http://127.0.0.1:18989';
const DOC_TITLE = `桥接E2E 测试文档-${TAG}`;

const out = { tag: TAG, sessionOpened: false, cardFound: false, openButtonSeen: false,
  liveEditorMounted: false, liveTitleShown: false, liveContentLen: 0, liveContentHead: '',
  cardCandidates: [], pageErrors: [], consoleErrors: [] };

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 600000 });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
page.on('pageerror', (e) => out.pageErrors.push(String(e).slice(0, 200)));
page.on('console', (m) => { if (m.type() === 'error') out.consoleErrors.push(m.text().slice(0, 200)); });

const step = (s) => console.log('STEP', s);
// 稳态等待：两次采样同值才认（防动画/流式中间态）。
async function steady(fn, gap = 800, budget = 30000) {
  const t0 = Date.now();
  while (Date.now() - t0 < budget) {
    if (!(await fn())) return false;
    await page.waitForTimeout(gap);
    if (await fn()) return true;
  }
  return false;
}

await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch((e) => console.log('goto:', String(e).split('\n')[0]));
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await page.waitForTimeout(4000);

// 1) 打开目标会话：按会话列表行的内容点。
// 陷阱：会话标题是 LLM 生成的，会吃掉标题里的空格（「桥接E2E测试文档-784428」），
// 拿带空格的 DOC_TITLE 去匹配必然落空——只按唯一 tag 匹配。
// 会话行本体是 <span class="*_title">，点击处理器挂在无 role 的 div 上——
// 语义选择器（button/[role=button]）计数为 0，只能按文本取。
const row = page.getByText(TAG, { exact: false }).first();
out.sessionOpened = await steady(async () => row.isVisible({ timeout: 2000 }).catch(() => false), 600, 20000);
step(`session row visible = ${out.sessionOpened}`);
if (out.sessionOpened) {
  await row.click().catch((e) => console.log('row click:', String(e).split('\n')[0]));
  await page.waitForTimeout(5000);
}

// 2) 聊天区的 docx 文件卡（<button class="_fileLink_*">，哈希随构建变，禁写死）。
//    同会话可能有多个同名卡，取第一个可见的。
// 实测 DOM：聊天区文件卡 = div.nyYjTG_file > div.nyYjTG_fileBody > span.nyYjTG_fileName，
// 名字是**带 office 导出后缀的原始文件名**（含我们的 tag）。class 前缀哈希随构建变，用 [class*="_file"]。
const cardSels = [
  `[class*="_file"]:has-text("${DOC_TITLE}")`,
  `[class*="_fileLink_"]:has-text("${DOC_TITLE}")`,
  `[class*="_fileMention_"]:has-text("${DOC_TITLE}")`,
  `button:has-text("${DOC_TITLE}")`,
];
const deadline = Date.now() + 90000;
let card = null;
while (Date.now() < deadline && !card) {
  await page.waitForTimeout(3000);
  for (const sel of cardSels) {
    if (await page.locator(sel).first().isVisible({ timeout: 1500 }).catch(() => false)) { card = sel; break; }
  }
}
if (!card) {
  out.cardCandidates = await page.evaluate(() =>
    Array.from(document.querySelectorAll('a[href], button, [role="button"]'))
      .filter((el) => /docx|桥接E2E/.test(el.textContent ?? ''))
      .slice(0, 8)
      .map((el) => ({ tag: el.tagName, cls: String(el.className).slice(0, 60), text: (el.textContent ?? '').slice(0, 60) })));
} else {
  out.cardFound = true;
  step(`file card found via ${card}`);
  await page.locator(card).first().click({ timeout: 8000 }).catch(() => {});
  await page.waitForTimeout(5000);

  // 3) 预览工具条上的原生桥接按钮。
  const btn = page.locator('.plate-open-in-plate').first();
  out.openButtonSeen = await steady(async () => btn.isVisible({ timeout: 2000 }).catch(() => false), 800, 30000);
  step(`open button visible = ${out.openButtonSeen}`);

  if (out.openButtonSeen) {
    await btn.click();
    // 4) 活编辑器挂载 + 标题 + 内容落地。
    out.liveEditorMounted = await steady(async () =>
      page.locator('.plate-live-page .plate-doc-editor').first().isVisible({ timeout: 2000 }).catch(() => false), 800, 40000);
    out.liveTitleShown = await steady(async () =>
      page.locator('.plate-live-page .plate-doc-title', { hasText: DOC_TITLE }).first().isVisible({ timeout: 2000 }).catch(() => false));
    const text = await page.locator('.plate-live-page .plate-content').first().innerText().catch(() => '');
    out.liveContentLen = text.replace(/\s+/g, '').length;
    out.liveContentHead = text.replace(/\s+/g, '').slice(0, 60);
    step(`live editor mounted=${out.liveEditorMounted} title=${out.liveTitleShown} contentLen=${out.liveContentLen}`);
  }
}

await page.screenshot({ path: '/tmp/plate-bridge-replay.png' });
console.log('RESULT', JSON.stringify({ ...out, pageErrors: out.pageErrors.length, consoleErrors: out.consoleErrors.length,
  pageErrorSample: out.pageErrors.slice(0, 3) }));
await browser.close();

