page.on('console', (m) => { if (m.type() === 'error') out.consoleErrors.push(m.text().slice(0, 200)); });
page.on('response', (r) => {
  if (r.status() < 400) return;
  const body = (() => { try { return String(r.request().postData() ?? '').slice(0, 220); } catch { return ''; } })();
  (out.badResponses ??= []).push(`${r.status()} ${r.url().slice(0, 90)} :: ${body}`);
});
// 时序取证：谁在什么时候打了哪个端点（定位 404 出现在链条哪一步）。
const T0 = Date.now();
const stamp = (r) => {
  const b = (() => { try { return String(r.postData() ?? ''); } catch { return ''; } })();
  const ep = (b.match(/"endpoint":"([a-z-]+)"/) ?? [])[1] ?? '?';
  const id = (b.match(/"docId":"([0-9a-f-]{8})/) ?? [])[1] ?? '';
  return `${ep}${id ? ':' + id : ''}`;
};
page.on('request', (r) => { if (r.url().includes('/api/workdsh-plate')) (out.apiTimeline ??= []).push(`+${Date.now() - T0}ms REQ ${stamp(r)}`); });
page.on('response', (r) => { if (r.url().includes('/api/workdsh-plate')) (out.apiTimeline ??= []).push(`+${Date.now() - T0}ms RES ${r.status()} ${stamp(r.request())}`); });

const step = (s) => console.log('STEP', s);
