const row = page.getByText(TAG, { exact: false }).first();
out.sessionOpened = await steady(async () => row.isVisible({ timeout: 2000 }).catch(() => false), 600, 20000);
step(`session row visible = ${out.sessionOpened}`);
if (out.sessionOpened) {
