// 契约级复现：docx-import 刚返回的 docId，立刻 doc-open 会不会 404？
// 免浏览器：手工取 cookie，之后纯 fetch。
const BASE = 'http://127.0.0.1:18989';
const TOKEN = process.argv[2];
const DOCX = process.argv[3];

// 1) 用 ?token= 换 cookie
const r0 = await fetch(`${BASE}/?token=${TOKEN}`, { redirect: 'manual' });
const raw = r0.headers.getSetCookie?.() ?? [];
const cookie = raw.map((c) => c.split(';')[0]).join('; ');
console.log('cookie_headers=', raw.length, 'cookie=', cookie.slice(0, 60));

const api = async (endpoint, extra = {}) => {
  const t = Date.now();
  const r = await fetch(`${BASE}/api/workdsh-plate`, {
    method: 'POST',
    headers: { 'content-type': 'application/json', cookie },
    body: JSON.stringify({ endpoint, ...extra }),
  });
  const body = await r.json().catch(() => null);
  return { status: r.status, body, ms: Date.now() - t };
};

for (let round = 1; round <= 3; round += 1) {
  const imp = await api('docx-import', { path: DOCX });
  const docId = imp.body?.doc?.id;
  console.log(`--- round ${round}: import ${imp.status} in ${imp.ms}ms docId=${docId}`);
  if (!docId) { console.log('  import body:', JSON.stringify(imp.body).slice(0, 200)); continue; }
  for (const wait of [0, 50, 100, 250, 500, 1000, 2000]) {
    if (wait) await new Promise((res) => setTimeout(res, wait));
    const o = await api('doc-open', { docId });
    console.log(`  +${wait}ms open -> ${o.status} ${o.status === 200 ? 'ok' : JSON.stringify(o.body)}`);
    if (o.status === 200) break;
  }
}

