         <ToolbarPrimitive.ToggleGroup disabled={props.disabled} type="single" value="single">
           <ToolbarPrimitive.ToggleItem
             className={clsx('pltx-tlb-btn', sizeClass, isDropdown && 'pltx-tlb-dropdown', className)}
             value={pressed ? 'single' : ''}
             {...props}
           >
             {isDropdown ? (<><div className="pltx-tlb-dropdown-label">{children}</div>
               <div><ChevronDownIcon className="pltx-tlb-chevron" data-icon /></div></>) : (children)}
           </ToolbarPrimitive.ToggleItem>
         </ToolbarPrimitive.ToggleGroup>
       ) : (
         <ToolbarPrimitive.Button className={clsx('pltx-tlb-btn', sizeClass, isDropdown && 'pltx-tlb-dropdown', className)} {...props}>
           {children}
         </ToolbarPrimitive.Button>
       );
     });

     export function MarkToolbarButton({ clear, nodeType, ...props }: ...) {
       const state = useMarkToolbarButtonState({ clear, nodeType });
       const { props: buttonProps } = useMarkToolbarButton(state);
       return <ToolbarButton {...props} {...buttonProps} />;
     }

     export function AIToolbarButton() {
       const { api } = useEditorPlugin(AIChatPlugin);
       return (
         <ToolbarButton onClick={() => api.aiChat.show()} tooltip="AI 命令">
           <WandSparklesIcon />
         </ToolbarButton>
       );
     }
     ```
