// 判定「用户看到旧 UI」是浏览器缓存还是服务端发旧包：
// 记录浏览器实际收到的插件 bundle 请求/响应头，并直接在收到的字节里查新旧 UI 标记。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';

const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 600000 });
const page = await browser.newPage({ viewport: { width: 1600, height: 900 } });

const hits = [];
page.on('response', async (r) => {
  const u = r.url();
  if (!/plugin/i.test(u)) return;
  let body = '';
  try { body = await r.text(); } catch { /* 非文本 */ }
  hits.push({
    url: u.replace(BASE, '').slice(0, 400),
    hasRev: /[?&]rev=/.test(u),
    rev: (u.match(/[?&]rev=([0-9a-f]+)/) ?? [])[1] ?? null,
    status: r.status(),
    cacheControl: (r.headers()['cache-control'] ?? '').slice(0, 60),
    etag: (r.headers()['etag'] ?? '').slice(0, 30),
    len: body.length,
    oldUI: (body.match(/plate-ai-panel|PlateAiSection|plate-toolbar-btn/g) ?? []).length,
    newUI: (body.match(/cmdk|AIMenu/g) ?? []).length,
    fromCache: r.fromServiceWorker(),
  });
});

await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch((e) => console.log('goto:', String(e).split('\n')[0]));
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await page.waitForTimeout(6000);

console.log('PLUGIN_RESPONSES', JSON.stringify(hits.filter((h) => h.len > 5000), null, 1));
await browser.close();

