// 几何取证：菜单是 Portal 到 body 的，报「outside of viewport」时要把真实坐标和
// 祖先 transform 链一起抓出来（position:fixed 遇上有 transform 的祖先会改基准）。
out.menuGeom = await page.evaluate(() => {
  const el = document.querySelector('.pltx-tlb-menu');
  if (!el) return null;
  const r = el.getBoundingClientRect();
  const cs = getComputedStyle(el);
  const chain = [];
  let n = el.parentElement;
  while (n && chain.length < 8) {
    const s = getComputedStyle(n);
    if (s.transform !== 'none' || s.filter !== 'none' || s.perspective !== 'none' || s.contain !== 'none') {
      chain.push({ tag: n.tagName, cls: String(n.className).slice(0, 40), transform: s.transform, contain: s.contain, filter: s.filter });
    }
    n = n.parentElement;
  }
  return {
    rect: { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) },
    position: cs.position, transform: cs.transform,
    parent: el.parentElement ? el.parentElement.tagName : '', parentCls: el.parentElement ? String(el.parentElement.className).slice(0, 40) : '',
    viewport: { w: innerWidth, h: innerHeight },
    transformedAncestors: chain,
  };
}).catch(() => null);
await page.screenshot({ path: '/tmp/plate-menu-open.png' });

