// v1.6.0 官方工具栏移植的端上核验：
// 走桥接重放（文件卡 → 预览 → 「用 PlateAI 打开」）拿到活编辑器，然后断言
//   • 工具栏是 Radix 原语版（role=toolbar，官方 playground 的编排）
//   • 五个 mark 图标按钮 + 「转换为」下拉 + 插图/分隔线 + AI
//   • 「转换为」菜单出条目、点「标题 1」真的落成 h1
//   • 悬浮出提示
//   • 「导出 .plate」已从页面消失
//   • 零 pageErrors / 零 consoleErrors
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';

const TOKEN = process.argv[2];
const TAG = process.argv[3] ?? '784428';
const BASE = 'http://127.0.0.1:18989';
const DOC_TITLE = `桥接E2E 测试文档-${TAG}`;

const out = {
  tag: TAG,
  liveEditorMounted: false,
  toolbarIsRadix: false,
  toolbarRole: '',
  groupCount: 0,
  markButtons: 0,
  turnIntoSeen: false,
  turnIntoLabel: '',
  menuOpened: false,
  menuItems: [],
  appliedHeading: '',
  headingTagAfter: '',
  tooltipText: '',
  boldPressed: false,
  imageButton: false,
  hrButton: false,
  aiButton: false,
  saveButton: false,
  exportPlateGone: true,
  oldToolbarLeftover: 0,
  pageErrors: [],
  consoleErrors: [],
  badResponses: [],
};
const step = (s) => console.log('STEP', s);

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 600000 });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
page.on('pageerror', (e) => out.pageErrors.push(String(e).slice(0, 200)));
page.on('console', (m) => { if (m.type() === 'error') out.consoleErrors.push(m.text().slice(0, 200)); });
page.on('response', (r) => {
  if (r.status() < 400) return;
  out.badResponses.push(`${r.status()} ${r.url().slice(0, 90)}`);
});

// 稳态等待：先轮询到首次为真，再隔一拍复采确认（防流式/动画中间态；勿写成瞬时判据）。
async function steady(fn, gap = 800, budget = 30000) {
  const t0 = Date.now();
  let seen = false;
  while (Date.now() - t0 < budget) {
    if (await fn()) { seen = true; break; }
    await page.waitForTimeout(gap);
  }
  if (!seen) return false;
  await page.waitForTimeout(gap);
  return !!(await fn());
}

await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch((e) => console.log('goto:', String(e).split('\n')[0]));
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await page.waitForTimeout(4000);

// 1) 会话行（按唯一 tag 取；标题里的空格会被 LLM 吃掉，行本体是无 role 的 div）
const row = page.getByText(TAG, { exact: false }).first();
if (await steady(async () => row.isVisible({ timeout: 2000 }).catch(() => false), 600, 20000)) {
  await row.click().catch(() => {});
  await page.waitForTimeout(5000);
  step('session opened');
}

// 2) 文件卡 → 预览 → 桥接按钮
const cardSels = [`[class*="_file"]:has-text("${DOC_TITLE}")`, `button:has-text("${DOC_TITLE}")`];
let card = null;
const deadline = Date.now() + 90000;
while (Date.now() < deadline && !card) {
  await page.waitForTimeout(3000);
  for (const sel of cardSels) {
    if (await page.locator(sel).first().isVisible({ timeout: 1500 }).catch(() => false)) { card = sel; break; }
  }
}
if (card) {
  await page.locator(card).first().click({ timeout: 8000 }).catch(() => {});
  await page.waitForTimeout(5000);
  const btn = page.locator('.plate-open-in-plate').first();
  if (await steady(async () => btn.isVisible({ timeout: 2000 }).catch(() => false), 800, 30000)) {
    await btn.click();
    out.liveEditorMounted = await steady(async () =>
      page.locator('.plate-live-page .plate-doc-editor').first().isVisible({ timeout: 2000 }).catch(() => false), 800, 40000);
    step(`live editor mounted = ${out.liveEditorMounted}`);
  }
}
if (!out.liveEditorMounted) {
  out.cardFound = !!card;
  out.bodyText = (await page.evaluate(() => document.body.innerText)).replace(/\s+/g, ' ').slice(0, 700);
  out.fileish = await page.evaluate(() =>
    Array.from(document.querySelectorAll('a[href], button, [role="button"], [class*="_file"]'))
      .filter((el) => /docx|桥接|plate/i.test(el.textContent ?? ''))
      .slice(0, 10)
      .map((el) => ({ tag: el.tagName, cls: String(el.className).slice(0, 70), text: (el.textContent ?? '').slice(0, 70) })));
  console.log('RESULT', JSON.stringify({
    ...out,
    pageErrors: out.pageErrors.length,
    consoleErrors: out.consoleErrors.length,
    pageErrorSample: out.pageErrors.slice(0, 3),
    consoleErrorSample: out.consoleErrors.slice(0, 6),
  }));
  await page.screenshot({ path: '/tmp/plate-toolbar-native-FAIL.png' });
  await browser.close();
  process.exit(0);
}

await page.waitForTimeout(2500);

// 3) 工具栏本体：是不是 Radix Toolbar.Root（官方 playground 的 pltx-tlb-root）
const tb = page.locator('.plate-live-page .plate-toolbar').first();
out.toolbarIsRadix = await page.locator('.plate-live-page .plate-toolbar [role="toolbar"].pltx-tlb-root').count() > 0;
out.toolbarRole = await page.locator('.plate-live-page .plate-toolbar [role="toolbar"]').first().getAttribute('role').catch(() => '') ?? '';
out.groupCount = await page.locator('.plate-live-page .pltx-tlb-group').count();
out.markButtons = await page.locator('.plate-live-page .pltx-tlb-btn[aria-checked]').count();
out.turnIntoSeen = await page.locator('.plate-live-page .pltx-tlb-turninto').first().isVisible().catch(() => false);
out.turnIntoLabel = (await page.locator('.plate-live-page .pltx-tlb-turninto').first().innerText().catch(() => '')).replace(/\s+/g, ' ').trim();
out.imageButton = await page.locator('.plate-live-page .pltx-tlb-btn').filter({ has: page.locator('svg.lucide-image, svg[class*="image"]') }).count() > 0;
out.hrButton = await page.locator('.plate-live-page .pltx-tlb-btn').filter({ has: page.locator('svg.lucide-minus, svg[class*="minus"]') }).count() > 0;
out.aiButton = await page.locator('.plate-live-page .pltx-tlb-btn').filter({ has: page.locator('svg.lucide-wand-sparkles, svg[class*="wand"]') }).count() > 0;
out.saveButton = await tb.getByText('保存', { exact: true }).count() > 0;
out.exportPlateGone = (await page.getByText('导出 .plate', { exact: false }).count()) === 0;
out.oldToolbarLeftover = await page.locator('.plate-live-page .pltx-tb, .plate-live-page .plate-toolbar-btn').count();
step(`radix=${out.toolbarIsRadix} groups=${out.groupCount} marks=${out.markButtons} turnInto=${out.turnIntoSeen}(${out.turnIntoLabel}) ai=${out.aiButton} img=${out.imageButton} hr=${out.hrButton} save=${out.saveButton} exportGone=${out.exportPlateGone}`);

// 4) 悬浮提示：悬停「转换为」应出 .pltx-tlb-tip
await page.locator('.plate-live-page .pltx-tlb-turninto').first().hover().catch(() => {});
out.tooltipText = await steady(async () => {
  const t = await page.locator('.pltx-tlb-tip').first().innerText().catch(() => '');
  return t.trim();
}, 400, 6000) ? (await page.locator('.pltx-tlb-tip').first().innerText().catch(() => '')).trim() : '';
step(`tooltip = "${out.tooltipText}"`);
await page.mouse.move(5, 5);
await page.waitForTimeout(500);

// 5) 加粗按钮：无选区点一下 → pending mark，aria-checked 应为 true
const bold = page.locator('.plate-live-page .pltx-tlb-btn[aria-checked]').first();
const box = await bold.boundingBox().catch(() => null);
if (box) {
  await page.mouse.click(box.x + box.width / 2, box.y + box.height / 2);
  await page.waitForTimeout(600);
  out.boldPressed = (await bold.getAttribute('aria-checked').catch(() => '')) === 'true';
  await page.mouse.click(box.x + box.width / 2, box.y + box.height / 2); // 复位
  await page.waitForTimeout(400);
}
step(`bold aria-checked after click = ${out.boldPressed}`);

// 6) 「转换为」：点开 → 出条目 → 点「标题 1」→ 光标所在段落应变 h1
await page.locator('.plate-live-page .pltx-tlb-turninto').first().click().catch(() => {});
out.menuOpened = await steady(async () => page.locator('.pltx-tlb-menu').first().isVisible({ timeout: 1500 }).catch(() => false), 400, 10000);
if (out.menuOpened) {
  out.menuItems = await page.locator('.pltx-tlb-menu .pltx-tlb-menu-item').allInnerTexts().catch(() => []);
  out.menuBox = await page.locator('.pltx-tlb-menu').first().boundingBox().catch(() => null);
  out.triggerBox = await page.locator('.plate-live-page .pltx-tlb-turninto').first().boundingBox().catch(() => null);
  await page.screenshot({ path: '/tmp/plate-menu-open.png' });
  const h1 = page.locator('.pltx-tlb-menu .pltx-tlb-menu-item', { hasText: '标题 1' }).first();
  out.h1Box = await h1.boundingBox().catch(() => null);
  if (await h1.isVisible().catch(() => false)) {
    out.appliedHeading = '标题 1';
    try {
      await h1.click({ timeout: 5000 });
    } catch (e) {
      out.clickError = String(e).split('\n')[0];
      // 兜底：Radix RadioGroup 支持方向键 + Enter（不进鼠标命中测试）
      await page.keyboard.press('ArrowDown').catch(() => {});
      await page.waitForTimeout(300);
      await page.keyboard.press('Enter').catch(() => {});
      out.appliedHeading = '标题 1 (keyboard)';
    }
    await page.waitForTimeout(1200);
    // 光标默认落在第一个块；转换后该块应是 h1
    out.headingTagAfter = await page.evaluate(() => {
      const p = document.querySelector('.plate-live-page .plate-content');
      if (!p) return '';
      return String(p.querySelector('h1')?.tagName ?? p.firstElementChild?.firstElementChild?.tagName ?? '');
    });
  }
  // 复位：转回正文，不落保存（活编辑器不自动保存，磁盘不受影响）
  await page.locator('.plate-live-page .pltx-tlb-turninto').first().click().catch(() => {});
  await page.waitForTimeout(600);
  const p0 = page.locator('.pltx-tlb-menu .pltx-tlb-menu-item', { hasText: '正文' }).first();
  if (await p0.isVisible().catch(() => false)) { await p0.click(); await page.waitForTimeout(800); }
}
step(`menu opened=${out.menuOpened} items=${JSON.stringify(out.menuItems)} headingTag=${out.headingTagAfter}`);

await page.screenshot({ path: '/tmp/plate-toolbar-native.png' });
console.log('RESULT', JSON.stringify({
  ...out,
  pageErrors: out.pageErrors.length,
  consoleErrors: out.consoleErrors.length,
  pageErrorSample: out.pageErrors.slice(0, 3),
  consoleErrorSample: out.consoleErrors.slice(0, 3),
  badResponses: out.badResponses.slice(0, 5),
}));
await browser.close();

