// 复现用户路径并如实记录「屏幕上到底出现了什么」：
// 会话 → docx 文件卡 → 预览（右 pane）→ 逐帧 dump：打开的 tab 名、右 pane 里的按钮、
// 面板 class、是否出现 Word 编辑器特征；再点「用 PlateAI 打开」重复 dump。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';

const TOKEN = process.argv[2];
const TAG = process.argv[3] ?? '784428';
const BASE = 'http://127.0.0.1:18989';
const DOC_TITLE = `桥接E2E 测试文档-${TAG}`;

const out = { tag: TAG, frames: [] };
const shot = async (page, name) => page.screenshot({ path: `/tmp/user-sees-${name}.png` }).catch(() => {});

// 一帧的「所见」快照
const snapshot = (page) => page.evaluate(() => {
  const txt = (el) => (el?.textContent ?? '').replace(/\s+/g, ' ').trim().slice(0, 80);
  const tabs = Array.from(document.querySelectorAll('[role="tab"], [data-tab-id], [class*="_tab"]'))
    .map((el) => ({ cls: String(el.className).slice(0, 50), text: txt(el), sel: el.getAttribute('aria-selected') }))
    .filter((t) => t.text)
    .slice(0, 14);
  const rightPane = document.querySelector('[class*="sidebarRight"], [class*="_right"], aside');
  const buttons = Array.from(document.querySelectorAll('button')).map((b) => txt(b)).filter((t) => t && t.length < 30);
  const panelClasses = Array.from(document.querySelectorAll('[class*="_pane"], [class*="_tab"]'))
    .map((el) => String(el.className).split(/\s+/).find((c) => /_/.test(c)) ?? '')
    .filter(Boolean).slice(0, 20);
  return {
    tabTitles: tabs,
    buttons: [...new Set(buttons)].slice(0, 30),
    panelClasses: [...new Set(panelClasses)],
    hasWordEditor: !!document.querySelector('[class*="office"], [class*="docx"], [class*="word"]'),
    hasPlateEditor: !!document.querySelector('.plate-doc-editor, .plate-live-page, .plate-file-preview'),
    hasPlateLive: !!document.querySelector('.plate-live-page'),
    hasPlateReadOnly: !!document.querySelector('.plate-file-preview'),
    rightPaneFirst: txt(rightPane),
    bodyHead: document.body.innerText.replace(/\s+/g, ' ').slice(0, 220),
  };
});

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 600000 });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
out.errors = [];
page.on('pageerror', (e) => out.errors.push(String(e).slice(0, 160)));
page.on('console', (m) => { if (m.type() === 'error') out.errors.push('console: ' + m.text().slice(0, 160)); });

async function steady(fn, gap = 800, budget = 30000) {
  const t0 = Date.now();
  let seen = false;
  while (Date.now() - t0 < budget) {
    if (await fn()) { seen = true; break; }
    await page.waitForTimeout(gap);
  }
  if (!seen) return false;
  await page.waitForTimeout(gap);
  return !!(await fn());
}

await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await page.waitForTimeout(4000);

const row = page.getByText(TAG, { exact: false }).first();
if (await steady(async () => row.isVisible({ timeout: 2000 }).catch(() => false), 600, 20000)) {
  await row.click().catch(() => {});
  await page.waitForTimeout(5000);
  out.frames.push({ step: '1-session-open', ...(await snapshot(page)) });
  await shot(page, '1-session');
}

// 找文件卡
const cardSels = [`[class*="_file"]:has-text("${DOC_TITLE}")`, `button:has-text("${DOC_TITLE}")`];
let card = null;
const deadline = Date.now() + 90000;
while (Date.now() < deadline && !card) {
  await page.waitForTimeout(3000);
  for (const sel of cardSels) {
    if (await page.locator(sel).first().isVisible({ timeout: 1500 }).catch(() => false)) { card = sel; break; }
  }
}
if (!card) { console.log('RESULT', JSON.stringify({ ...out, noCard: true })); await browser.close(); process.exit(0); }

await page.locator(card).first().click({ timeout: 8000 }).catch(() => {});
await page.waitForTimeout(6000);
out.frames.push({ step: '2-file-preview', ...(await snapshot(page)) });
await shot(page, '2-preview');

// 「用 PlateAI 打开」按钮在不在？在哪个容器里？
out.openBtnInfo = await page.evaluate(() => {
  const b = document.querySelector('.plate-open-in-plate');
  if (!b) return { found: false };
  const r = b.getBoundingClientRect();
  const chain = [];
  let n = b.parentElement;
  while (n && chain.length < 6) { chain.push(`${n.tagName}.${String(n.className).split(/\s+/)[0] ?? ''}`); n = n.parentElement; }
  return { found: true, text: (b.textContent ?? '').trim(), rect: { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width) }, chain };
});

const btn = page.locator('.plate-open-in-plate').first();
if (await steady(async () => btn.isVisible({ timeout: 2000 }).catch(() => false), 800, 30000)) {
  await btn.click();
  await page.waitForTimeout(4000);
  out.frames.push({ step: '3-after-open-click', ...(await snapshot(page)) });
  await shot(page, '3-after-open');
  await page.waitForTimeout(4000);
  out.frames.push({ step: '4-settled', ...(await snapshot(page)) });
  await shot(page, '4-settled');
} else {
  out.openBtnMissing = true;
}

console.log('RESULT', JSON.stringify({ ...out, errors: out.errors.slice(0, 5) }, null, 1));
await browser.close();

