cd /tmp && cat > /tmp/plate-probe-live-open.mjs <<'EOF'
// 活路径复现：开着会话 → 让 agent 建 plate 文档（plate_open）→
// 客户端 pending 轮询命中应 openTabIn 活编辑器。逐帧记录右 pane 到底出现了什么。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
const TOKEN = process.argv[2];
const SESSION_TITLE = process.argv[3] ?? '生成20字文档用plateai打开';
const BASE = 'http://127.0.0.1:18989';
const out = { frames: [], api: [], errors: [] };
const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 900000 });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
page.on('pageerror', (e) => out.errors.push(String(e).slice(0, 160)));
page.on('console', (m) => { if (m.type() === 'error') out.errors.push('console: ' + m.text().slice(0, 160)); });
const T0 = Date.now();
page.on('request', (r) => {
  if (r.url().includes('/api/workdsh-plate')) {
    const ep = (String(r.postData() ?? '').match(/"endpoint":"([a-z-]+)"/) ?? [])[1] ?? '?';
    out.api.push(`+${Date.now() - T0}ms REQ ${ep}`);
  }
});
page.on('response', (r) => {
  if (r.url().includes('/api/workdsh-plate')) {
    const ep = (String(r.request().postData() ?? '').match(/"endpoint":"([a-z-]+)"/) ?? [])[1] ?? '?';
    out.api.push(`+${Date.now() - T0}ms RES ${r.status()} ${ep}`);
  }
});
const shot = (n) => page.screenshot({ path: `/tmp/live-open-${n}.png` }).catch(() => {});
const snap = () => page.evaluate(() => ({
  plateLive: !!document.querySelector('.plate-live-page'),
  plateEditor: !!document.querySelector('.plate-doc-editor'),
  plateContent: (document.querySelector('.plate-live-page .plate-content')?.innerText ?? '').replace(/\s+/g, '').slice(0, 40),
  officeLive: !!document.querySelector('[class*="office"], [class*="_word"], [class*="_docx"]'),
  rightTabs: Array.from(document.querySelectorAll('[role="tab"]')).map((e) => (e.textContent ?? '').trim().slice(0, 40)).filter(Boolean).slice(0, 8),
  rightPaneHead: (document.querySelector('section[class*="tabHost"]')?.innerText ?? '').replace(/\s+/g, ' ').slice(0, 200),
}));

await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await page.waitForTimeout(4000);
const row = page.getByText(SESSION_TITLE, { exact: false }).first();
for (let i = 0; i < 20 && !(await row.isVisible({ timeout: 1500 }).catch(() => false)); i++) await page.waitForTimeout(800);
await row.click().catch(() => {});
await page.waitForTimeout(6000);
out.frames.push({ step: 'before', ...(await snap()) });
await shot('0-before');

// 发消息
const box = page.locator('textarea, [contenteditable="true"]').last();
await box.click().catch(() => {});
await box.type('再生成一个 20 个字的文档，用 plateai 打开', { delay: 25 }).catch(() => {});
await page.waitForTimeout(600);
await page.keyboard.press('Enter').catch(() => {});
console.log('STEP sent');

// 等 agent 干完 + 客户端 pending 轮询命中
for (let i = 0; i < 30; i++) {
  await page.waitForTimeout(6000);
  const s = await snap();
  const done = s.plateLive && s.plateContent.length > 0;
  out.frames.push({ step: `t+${(i + 1) * 6}s`, ...s });
  if (done) break;
}
await shot('1-after');
console.log('RESULT', JSON.stringify({
  frames: out.frames.filter((f, i) => i === 0 || i === out.frames.length - 1).concat(out.frames.slice(-3)),
  api: out.api.filter((l) => !/plate-pending/.test(l)),
  pendingPolls: out.api.filter((l) => /plate-pending/.test(l)).length,
  errors: out.errors.slice(0, 4),
}, null, 1));
await browser.close();
EOF
