// 打开用户那条会话，如实 dump：agent 调了哪些工具、产出了什么文件卡、
// 点开文件卡后右 pane 出现的是哪个编辑器。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
const TOKEN = process.argv[2];
const TITLE = process.argv[3] ?? '生成20字文档用plateai打开';
const BASE = 'http://127.0.0.1:18989';
const out = { title: TITLE, steps: [] };
const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 600000 });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
const errs = [];
page.on('pageerror', (e) => errs.push(String(e).slice(0, 160)));
page.on('console', (m) => { if (m.type() === 'error') errs.push('console: ' + m.text().slice(0, 160)); });
const shot = (n) => page.screenshot({ path: `/tmp/user-session-${n}.png` }).catch(() => {});

async function steady(fn, gap = 800, budget = 25000) {
  const t0 = Date.now(); let seen = false;
  while (Date.now() - t0 < budget) { if (await fn()) { seen = true; break; } await page.waitForTimeout(gap); }
  if (!seen) return false;
  await page.waitForTimeout(gap);
  return !!(await fn());
}

await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await page.waitForTimeout(4000);

const row = page.getByText(TITLE, { exact: false }).first();
const seen = await steady(async () => row.isVisible({ timeout: 2000 }).catch(() => false), 600, 25000);
out.sessionFound = seen;
if (seen) {
  await row.click().catch(() => {});
  await page.waitForTimeout(7000);
  await shot('1-open');
  out.transcript = await page.evaluate(() => {
    const t = (el) => (el?.textContent ?? '').replace(/\s+/g, ' ').trim();
    const rows = Array.from(document.querySelectorAll('[class*="_row"]')).map(t).filter(Boolean);
    const files = Array.from(document.querySelectorAll('[class*="_file"], [class*="_fileBody"]')).map((el) => ({
      cls: String(el.className).slice(0, 40), text: t(el).slice(0, 90),
    }));
    const firstUser = Array.from(document.querySelectorAll('[class*="_row"]')).slice(0, 4).map(t);
    return { rows: rows.slice(0, 24), files: files.slice(0, 6), firstUser };
  });
  // 点第一个文件卡
  const card = page.locator('[class*="_file"]').first();
  if (await card.isVisible().catch(() => false)) {
    await card.click().catch(() => {});
    await page.waitForTimeout(6000);
    await shot('2-card-clicked');
    out.afterCard = await page.evaluate(() => ({
      bodyHead: document.body.innerText.replace(/\s+/g, ' ').slice(0, 300),
      hasPlateLive: !!document.querySelector('.plate-live-page'),
      hasPlatePreview: !!document.querySelector('.plate-file-preview'),
      openInPlateBtn: !!document.querySelector('.plate-open-in-plate'),
      tabTexts: Array.from(document.querySelectorAll('[role="tab"]')).map((e) => (e.textContent ?? '').trim().slice(0, 60)).filter(Boolean).slice(0, 8),
    }));
  }
}
out.errors = errs.slice(0, 5);
console.log('RESULT', JSON.stringify(out, null, 1));
await browser.close();

