input.content:
// 判据：用户那条会话里，右 pane 到底是「关着的」还是「开着但显示 Word」。
// 步骤：开会话 → dump 右 pane 可见性/宽度 → 找并点右栏 toggle → dump 所有 tab 的
// aria-selected + 渲染出的编辑器类型（plate 特征 vs office/word 特征）→ 截图。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';

const TOKEN = process.argv[2];
const TITLE = process.argv[3] ?? '生成20字文档用plateai打开';
const BASE = 'http://127.0.0.1:18989';
const out = { title: TITLE, steps: [] };

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 600000 });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
const errs = [];
page.on('pageerror', (e) => errs.push(String(e).slice(0, 200)));
page.on('console', (m) => { if (m.type() === 'error') errs.push('console: ' + m.text().slice(0, 200)); });
const shot = (n) => page.screenshot({ path: `/tmp/rpane-${n}.png` }).catch(() => {});

const dump = () => page.evaluate(() => {
  const txt = (el) => (el?.textContent ?? '').replace(/\s+/g, ' ').trim();
  const rightPane = document.querySelector('aside, [class*="sidebarRight"], [class*="_rightPane"], [data-sidebar-right]');
  const rr = rightPane?.getBoundingClientRect();
  const tabs = Array.from(document.querySelectorAll('[role="tab"]'))
    .map((el) => ({ id: el.id, text: txt(el).slice(0, 40), sel: el.getAttribute('aria-selected'), x: Math.round(el.getBoundingClientRect().x) }))
    .filter((t) => t.text);
  const byCls = (frag) => Array.from(document.querySelectorAll(`[class*="${frag}"]`)).map((e) => String(e.className).slice(0, 60)).slice(0, 6);
  const toggle = document.querySelector('[data-sidebar-right-toggle]');
  const tr = toggle?.getBoundingClientRect();
  return {
    rightPane: rightPane ? { tag: rightPane.tagName, cls: String(rightPane.className).slice(0, 70), x: Math.round(rr.x), w: Math.round(rr.width), visible: rr.width > 0 } : null,
    toggle: toggle ? { tag: toggle.tagName, x: Math.round(tr.x), w: Math.round(tr.width), cls: String(toggle.className).slice(0, 60) } : null,
    tabs,
    plateLive: !!document.querySelector('.plate-live-page'),
    platePreview: !!document.querySelector('.plate-file-preview'),
    plateEditor: !!document.querySelector('.plate-doc-editor'),
    plateToolbarRoot: document.querySelectorAll('.pltx-tlb-root').length,
    // office/word 编辑器的特征：office 插件自己的类名前缀（保守取多个片段）
    officeCls: [...byCls('office'), ...byCls('docx'), ...byCls('wd-doc')],
    openInPlateBtn: !!document.querySelector('.plate-open-in-plate'),
    segmented: (() => {
      const el = document.querySelector('.plate-editor-mode');
      if (!el) return null;
      return {
        style: el.getAttribute('style'),
        opts: Array.from(el.querySelectorAll('[role="tab"]')).map((b) => ({ id: b.id, text: txt(b), sel: b.getAttribute('aria-selected') })),
      };
    })(),
    bodyHead: document.body.innerText.replace(/\s+/g, ' ').slice(0, 200),
  };
});

await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await page.waitForTimeout(5000);

const row = page.getByText(TITLE, { exact: false }).first();
for (let i = 0; i < 25 && !(await row.isVisible({ timeout: 2000 }).catch(() => false)); i++) await page.waitForTimeout(600);
out.sessionFound = await row.isVisible({ timeout: 3000 }).catch(() => false);
if (out.sessionFound) {
  await row.click().catch(() => {});
  await page.waitForTimeout(8000);
  out.steps.push({ step: '1-as-opened', ...(await dump()) });
  await shot('1-as-opened');

  // 点右栏 toggle（若在），把右 pane 拉出来
  const tg = page.locator('[data-sidebar-right-toggle]').first();
  out.toggleVisible = await tg.isVisible({ timeout: 4000 }).catch(() => false);
  if (out.toggleVisible) {
    await tg.click().catch(() => {});
    await page.waitForTimeout(3500);
    out.steps.push({ step: '2-after-toggle', ...(await dump()) });
    await shot('2-after-toggle');
  }
}
out.errors = errs.slice(0, 6);
console.log('RESULT', JSON.stringify(out, null, 1));
await browser.close();

