// 抓「Sidebar Session opening failed」的完整文本 + 完整 stack（定位到具体 bundle 文件）。
// 对照：先开目标会话，再开另一条会话，看这条错误是否只在某类会话出现。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';

const TOKEN = process.argv[2];
const A = process.argv[3] ?? '生成20字文档用plateai打开';
const B = process.argv[4] ?? '桥接E2E 测试文档-784428';
const BASE = 'http://127.0.0.1:18989';

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 600000 });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
const errs = [];
page.on('console', (m) => { if (m.type() === 'error') errs.push({ text: m.text(), loc: m.location() }); });
page.on('pageerror', (e) => errs.push({ text: 'PAGEERROR ' + String(e.stack ?? e), loc: {} }));

await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await page.waitForTimeout(5000);

const openSession = async (title, phase) => {
  const before = errs.length;
  const row = page.getByText(title, { exact: false }).first();
  for (let i = 0; i < 25 && !(await row.isVisible({ timeout: 2000 }).catch(() => false)); i++) await page.waitForTimeout(600);
  const found = await row.isVisible({ timeout: 3000 }).catch(() => false);
  if (found) { await row.click().catch(() => {}); await page.waitForTimeout(8000); }
  return { phase, found, newErrors: errs.slice(before) };
};

const r1 = await openSession(A, 'A-target');
const r2 = await openSession(B, 'B-other');
console.log('RESULT', JSON.stringify({ r1, r2, totalErrors: errs.length }, null, 1));
await browser.close();

