132	    const previous = revisions.get(doc.headRevId);
133	    if (!previous) throw new Error('HEAD_REVISION_MISSING');
134	    const revId = randomUUID();
135	    const now = new Date().toISOString();
136	    const head = revisionSchema.parse({
