142	      slateJson: content,
143	    });
144	    const updated = documentSchema.parse({ ...doc, headRevId: revId, updatedAt: now });
145	    await Promise.all([revisions.put(revId, head), documents.put(docId, updated)]);
146	    return { doc: updated, head };
