// 最小桥接判定：开会话 → 点文件卡 → 断言活编辑器挂载 + 官方工具栏在位。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
const TOKEN = process.argv[2];
const TAG = process.argv[3] ?? '784428';
const BASE = 'http://127.0.0.1:18989';
const out = { tag: TAG, steps: [] };
const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 600000 });
const page = await browser.newPage({ viewport: { width: 2400, height: 1080 } });
const errs = [];
page.on('pageerror', (e) => errs.push('PAGEERROR ' + String(e).slice(0, 200)));
page.on('console', (m) => { if (m.type() === 'error') errs.push('console: ' + m.text().slice(0, 200)); });
page.on('response', (r) => { if (r.status() >= 400) errs.push(`HTTP ${r.status()} ${r.url().slice(0, 90)}`); });

await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await page.waitForTimeout(5000);

const row = page.getByText(TAG, { exact: false }).first();
for (let i = 0; i < 25 && !(await row.isVisible({ timeout: 2000 }).catch(() => false)); i++) await page.waitForTimeout(600);
out.sessionFound = await row.isVisible({ timeout: 3000 }).catch(() => false);
if (out.sessionFound) await row.click().catch(() => {});
await page.waitForTimeout(8000);

const snap = () => page.evaluate(() => ({
  live: !!document.querySelector('.plate-live-page'),
  editor: !!document.querySelector('.plate-doc-editor'),
  tlb: document.querySelectorAll('.pltx-tlb-root').length,
  btns: document.querySelectorAll('.pltx-tlb-btn').length,
  exportBtn: document.querySelectorAll('.plate-export-btn, [data-plate-export]').length,
  tabs: Array.from(document.querySelectorAll('[role="tab"]')).map((e) => (e.textContent ?? '').trim().slice(0, 30)).filter(Boolean).slice(0, 8),
  segmented: (() => { const el = document.querySelector('.plate-editor-mode'); return el ? Array.from(el.querySelectorAll('[role="tab"]')).map((b) => `${b.textContent}:${b.getAttribute('aria-selected')}`) : null; })(),
  wordEditor: !!document.querySelector('[class*="office"], [class*="docx"]'),
  head: document.body.innerText.replace(/\s+/g, ' ').slice(0, 160),
}));

// 点文件卡（放宽：任意 _file 卡片，取最后一个 = 最新导出）
const cards = page.locator('[class*="_file"]');
const n = await cards.count().catch(() => 0);
out.cardCount = n;
if (n > 0) {
  await cards.last().click({ timeout: 10000 }).catch((e) => { out.cardClickErr = String(e).slice(0, 120); });
  await page.waitForTimeout(9000);
}
out.after = await snap();
await page.screenshot({ path: `/tmp/bridge-min-${TAG}.png` }).catch(() => {});

// 「用 PlateAI 打开」
const b = page.locator('.plate-open-in-plate').first();
if (await b.isVisible({ timeout: 5000 }).catch(() => false)) {
  await b.click().catch(() => {});
  await page.waitForTimeout(9000);
  out.afterOpenInPlate = await snap();
  await page.screenshot({ path: `/tmp/bridge-min-open-${TAG}.png` }).catch(() => {});
} else out.openBtnMissing = true;

out.errors = errs.slice(0, 8);
console.log('RESULT', JSON.stringify(out, null, 1));
await browser.close();

