// ---------------------------------------------------------------------------
// "/" 菜单条目（蓝本 slash-node.tsx，裁剪到本插件已装的 block）
// 第一组必须是 AI：这是官方编辑器表明自己"是 AI 编辑器"的地方。
type Group = {
  group: string;
  items: {
    icon: React.ReactNode;
    value: string;
    onSelect: (editor: ReturnType<typeof useEditorRef>, value: string) => void;
    focusEditor?: boolean;
    keywords?: string[];
    label?: string;
  }[];
};

const groups: Group[] = [
  {
    group: 'AI',
    items: [
      {
        focusEditor: false,
        icon: <SparklesIcon />,
        keywords: ['ai', '写作', '润色', '续写', '扩写', '缩写', '纠错', '翻译'],
        label: 'AI 写作',
        value: 'AI',
        onSelect: (editor) => {
          editor.getApi(AIChatPlugin).aiChat.show();
        },
      },
    ],
  },
  {
    group: '基本块',
    items: [
      {
        icon: <PilcrowIcon />,
        keywords: ['正文', '段落', 'paragraph', 'text'],
        label: '正文',
        value: KEYS.p,
        onSelect: (editor, value) => setBlock(editor, value),
      },
      {
        icon: <Heading1Icon />,
        keywords: ['标题', 'title', 'h1'],
        label: '标题 1',
        value: KEYS.h1,
        onSelect: (editor, value) => setBlock(editor, value),
      },
      {
        icon: <Heading2Icon />,
        keywords: ['标题', 'subtitle', 'h2'],
        label: '标题 2',
        value: KEYS.h2,
        onSelect: (editor, value) => setBlock(editor, value),
      },
      {
        icon: <Heading3Icon />,
        keywords: ['标题', 'subtitle', 'h3'],
        label: '标题 3',
        value: KEYS.h3,
        onSelect: (editor, value) => setBlock(editor, value),
      },
      {
        icon: <QuoteIcon />,
        keywords: ['引用', 'citation', 'blockquote', 'quote', '>'],
        label: '引用',
        value: KEYS.blockquote,
        onSelect: (editor, value) => setBlock(editor, value),
      },
      {
        icon: <MinusIcon />,
        keywords: ['分隔线', 'hr', 'divider', '---'],
        label: '分隔线',
        value: KEYS.hr,
        onSelect: (editor, value) => setBlock(editor, value),
      },
    ],
  },
];

/**
 * 把光标所在块转成目标类型。
 * InlineComboboxItem 已先 removeInput()，slash_input 节点此时不在树里，
 * 这里直接复用工具栏那套 setBlockType 语义即可（blockquote 走 wrap）。
 */
function setBlock(
  editor: ReturnType<typeof useEditorRef>,
  type: string,
  {
    at,
  }: { at?: Parameters<typeof editor.tf.toggleBlock>[1] extends infer _ ? never : never } = {},
) {
  void at;
  if (type === KEYS.hr) {
    editor.tf.toggleBlock(KEYS.hr);
    return;
  }
  if (type === KEYS.blockquote) {
    if (editor.api.some({ match: { type } })) return;
    editor.tf.toggleBlock(type, { wrap: true });
    return;
  }
  editor.tf.setNodes({ type }, { at: editor.api.blocks({ mode: 'lowest' })[0]?.[1] });
  editor.tf.focus();
}

export function SlashInputElement(
  props: PlateElementProps<TElement>,
) {
  const { editor, element } = props;

  return (
    <PlateElement {...props} as="span">
      <InlineCombobox element={element} trigger="/">
        <InlineComboboxInput />

        <InlineComboboxContent>
          <InlineComboboxEmpty>没有匹配项</InlineComboboxEmpty>

          {groups.map(({ group, items }) => (
            <InlineComboboxGroup key={group}>
              <InlineComboboxGroupLabel>{group}</InlineComboboxGroupLabel>

              {items.map(({ focusEditor, icon, keywords, label, value, onSelect }) => (
                <InlineComboboxItem
                  focusEditor={focusEditor}
                  group={group}
                  key={value}
                  keywords={keywords}
                  label={label}
                  onClick={() => onSelect(editor, value)}
                  value={value}
                >
                  <div className="slx-item-icon">{icon}</div>
                  {label ?? value}
                </InlineComboboxItem>
              ))}
            </InlineComboboxGroup>
          ))}
        </InlineComboboxContent>
      </InlineCombobox>
    </PlateElement>
  );
}

