.slx-item:hover, .slx-item[data-active-item="true"] { background: #f4f4f5; color: #18181b; }
.slx-item-static { cursor: default; color: #a1a1aa; }
.slx-item-icon { display: flex; margin-right: 8px; color: #71717a; }
