// 官方 "/" 斜杠菜单核验：桥接重放拿到活编辑器 → 文末回车开空段落 → 敲 "/"
// 断言：菜单出现 / 首组是 AI / 条目在本插件已装范围内 / 点 AI 项能开 AI 菜单 /
// 点「标题 1」真把块转成 H1。另记录 pageErrors / consoleErrors / 4xx。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';

const TOKEN = process.argv[2];
const TAG = process.argv[3] ?? '784428';
const BASE = 'http://127.0.0.1:18989';
const DOC_TITLE = `桥接E2E 测试文档-${TAG}`;
const out = { tag: TAG, steps: [] };
const step = (s) => { out.steps.push(s); console.log('STEP', s); };

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 600000 });
const page = await browser.newPage({ viewport: { width: 2400, height: 1080 } });
const errs = [];
page.on('pageerror', (e) => errs.push('PAGEERROR ' + String(e).slice(0, 200)));
page.on('console', (m) => { if (m.type() === 'error') errs.push('console: ' + m.text().slice(0, 200)); });
page.on('response', (r) => { if (r.status() >= 400) errs.push(`HTTP ${r.status()} ${r.url().slice(0, 90)}`); });

async function steady(fn, gap = 700, budget = 30000) {
  const t0 = Date.now();
  let seen = false;
  while (Date.now() - t0 < budget) { if (await fn()) { seen = true; break; } await page.waitForTimeout(gap); }
  if (!seen) return false;
  await page.waitForTimeout(gap);
  return !!(await fn());
}

await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await page.waitForTimeout(5000);

// 1) 开会话
const row = page.getByText(TAG, { exact: false }).first();
for (let i = 0; i < 25 && !(await row.isVisible({ timeout: 2000 }).catch(() => false)); i++) await page.waitForTimeout(600);
await row.click().catch(() => {});
await page.waitForTimeout(8000);

// 2) 点文件卡 → 预览
let card = null;
for (const sel of [`[class*="_file"]:has-text("${DOC_TITLE}")`, `[class*="_file"]`]) {
  const l = page.locator(sel).first();
  if (await l.isVisible({ timeout: 3000 }).catch(() => false)) { card = l; break; }
}
out.cardFound = !!card;
if (card) { await card.click({ timeout: 8000 }).catch(() => {}); await page.waitForTimeout(7000); }

// 3) 「用 PlateAI 打开」
const btn = page.locator('.plate-open-in-plate').first();
if (await steady(async () => btn.isVisible({ timeout: 2000 }).catch(() => false), 800, 30000)) {
  await btn.click().catch(() => {});
  out.liveEditorMounted = await steady(async () =>
    page.locator('.plate-live-page .plate-doc-editor').first().isVisible({ timeout: 2000 }).catch(() => false), 800, 40000);
} else {
  out.openBtnMissing = true;
  out.liveEditorMounted = await page.locator('.plate-live-page .plate-doc-editor').first().isVisible({ timeout: 3000 }).catch(() => false);
}
step(`live editor mounted = ${out.liveEditorMounted}`);
if (!out.liveEditorMounted) {
  out.bodyAtFail = (await page.evaluate(() => document.body.innerText)).replace(/\s+/g, ' ').slice(0, 400);
  await page.screenshot({ path: '/tmp/slash-FAIL.png' }).catch(() => {});
  out.errors = errs.slice(0, 8);
  console.log('RESULT', JSON.stringify(out, null, 1));
  await browser.close();
  process.exit(0);
}

// 4) 文末开一个空段落，敲 "/"
out.cursorToEnd = await page.evaluate(() => window.__workdshPlateProbe?.cursorToEnd?.() ?? 'no-hook');
await page.waitForTimeout(400);
await page.locator('.plate-live-page .plate-content').first().click().catch(() => {});
await page.waitForTimeout(300);
await page.evaluate(() => window.__workdshPlateProbe?.cursorToEnd?.());
await page.waitForTimeout(400);
await page.keyboard.press('Enter').catch(() => {});
await page.waitForTimeout(500);
await page.keyboard.type('/', { delay: 60 }).catch(() => {});

out.menuOpened = await steady(async () =>
  page.locator('.slx-pop').first().isVisible({ timeout: 1500 }).catch(() => false), 500, 12000);
step(`slash menu opened = ${out.menuOpened}`);

out.slash = await page.evaluate(() => {
  const pop = document.querySelector('.slx-pop');
  if (!pop) return null;
  const groups = Array.from(pop.querySelectorAll('.slx-group')).map((g) => ({
    label: (g.querySelector('.slx-group-label')?.textContent ?? '').trim(),
    items: Array.from(g.querySelectorAll('[role="option"]')).map((i) => (i.textContent ?? '').trim()),
