// 只看一件事：浏览器实际拉的是哪个 /plugins/ bundle URL、响应头怎么缓存、字节里有没有
// 新加的斜杠菜单。用来判定"用户没看到变化"是缓存旧包还是真没生效。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
const TOKEN = process.argv[2];
const BASE = 'http://127.0.0.1:18989';
const out = { requests: [], headers: [], markers: {} };

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 300000 });
const page = await browser.newPage({ viewport: { width: 1600, height: 900 } });
page.on('request', (r) => { const u = r.url(); if (u.includes('/plugins/')) out.requests.push(u); });
page.on('response', async (r) => {
  const u = r.url();
  if (!u.includes('/plugins/')) return;
  const h = r.headers();
  out.headers.push({ status: r.status(), url: u.slice(0, 220), cacheControl: h['cache-control'] ?? '', etag: h['etag'] ?? '', lastModified: h['last-modified'] ?? '' });
  try {
    const body = await r.text();
    out.markers[u.slice(0, 80)] = {
      bytes: body.length,
      slxItemIcon: body.includes('slx-item-icon'),
      slashInput: body.includes('slash_input') || body.includes('SlashInput'),
    };
  } catch { /* 有些响应体拿不到 */ }
});
await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
