  if (await l.isVisible({ timeout: 3000 }).catch(() => false)) { card = l; break; }
}
out.cardFound = !!card;
if (card) { await card.click({ timeout: 8000 }).catch(() => {}); await page.waitForTimeout(7000); }

// 3) 「用 PlateAI 打开」
