// 复现用户报的两件事：
//   ① 敲 "/" → 「AI 写作」后，AI 菜单里到底有几项（用户说只有「续写」）
//   ② 「续写」流式写完后文字消失（用户说无法持久化）
// 手法：装一条 250ms 的页面内采样器，记录编辑器文本长度/AI 叶/锚点的完整时间线，
// 免得只在几个时点上看而错过"先出现后消失"的瞬时态；网络全量记（含 rev-append）。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';

const TOKEN = process.argv[2];
const TAG = process.argv[3] ?? '784428';
const BASE = 'http://127.0.0.1:18989';
const out = { tag: TAG, steps: [] };
const step = (s) => { out.steps.push(s); console.log('STEP', s); };

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 900000 });
const page = await browser.newPage({ viewport: { width: 2400, height: 1080 } });
const errs = [];
const net = [];
page.on('pageerror', (e) => errs.push('PAGEERROR ' + String(e).slice(0, 220)));
page.on('console', (m) => { if (m.type() === 'error') errs.push('console: ' + m.text().slice(0, 220)); });
page.on('request', (r) => {
  const u = r.url();
  if (u.includes('/api/workdsh-plate') || u.includes('ai-command') || u.includes('rev-append')) {
    let body = '';
    try { body = (r.postData() ?? '').slice(0, 200); } catch { /* ignore */ }
    net.push({ t: Date.now(), dir: 'req', url: u.replace(BASE, '').slice(0, 70), body });
  }
});
page.on('response', async (r) => {
  const u = r.url();
  if (u.includes('/api/workdsh-plate') || u.includes('rev-append')) {
    net.push({ t: Date.now(), dir: 'res', status: r.status(), url: u.replace(BASE, '').slice(0, 70) });
  }
  if (r.status() >= 400) errs.push(`HTTP ${r.status()} ${u.slice(0, 100)}`);
});

async function steady(fn, gap = 800, budget = 45000) {
  const t0 = Date.now();
  let seen = false;
  while (Date.now() - t0 < budget) { if (await fn()) { seen = true; break; } await page.waitForTimeout(gap); }
  if (!seen) return false;
  await page.waitForTimeout(gap);
  return !!(await fn());
}

await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await page.waitForTimeout(5000);

const row = page.getByText(TAG, { exact: false }).first();
for (let i = 0; i < 25 && !(await row.isVisible({ timeout: 2000 }).catch(() => false)); i++) await page.waitForTimeout(600);
await row.click().catch(() => {});
await page.waitForTimeout(8000);

const cards = await page.evaluate(() => Array.from(document.querySelectorAll('[class*="_file"]')).map((e) => (e.textContent ?? '').trim()).filter(Boolean).slice(0, 20));
const card = page.locator(`[class*="_file"]:has-text("${cards.find((t) => t.includes(TAG)) ?? cards[0] ?? TAG}")`).first();
await card.click().catch(() => {});
await page.waitForTimeout(7000);

const btn = page.locator('.plate-open-in-plate').first();
if (await steady(async () => btn.isVisible({ timeout: 2000 }).catch(() => false), 800, 30000)) await btn.click().catch(() => {});
out.liveEditorMounted = await steady(async () => page.locator('.plate-live-page .plate-doc-editor').first().isVisible({ timeout: 2000 }).catch(() => false), 900, 60000);
step(`live editor mounted = ${out.liveEditorMounted}`);
if (!out.liveEditorMounted) { out.bodyAtFail = (await page.evaluate(() => document.body.innerText)).replace(/\s+/g, ' ').slice(0, 300); out.errors = errs.slice(0, 8); console.log('RESULT', JSON.stringify(out, null, 1)); await browser.close(); process.exit(0); }

// ---- 页面内采样器：250ms 一条，记录文本长度 / AI 叶 / AI 锚点 / 内容指纹 ----
await page.evaluate(() => {
  const w = window;
  w.__aiTimeline = [];
  const t0 = performance.now();
  const snap = () => {
    const c = document.querySelector('.plate-live-page .plate-content');
    const txt = (c?.textContent ?? '').replace(/\s+/g, ' ');
    w.__aiTimeline.push({
      t: Math.round(performance.now() - t0),
      len: txt.length,
      tail: txt.slice(-40),
      aiLeaf: c ? c.querySelectorAll('[class*="pltx-ai-leaf"]').length : 0,
      aiAnchor: c ? c.querySelectorAll('.pltx-ai-anchor').length : 0,
      blocks: c ? c.querySelectorAll('[data-slate-node="element"]').length : 0,
    });
  };
  snap();
  w.__aiTimer = setInterval(snap, 250);
});

// 1) 文末开空段落，敲 "/"
await page.locator('.plate-live-page .plate-content').first().click().catch(() => {});
await page.waitForTimeout(300);
await page.evaluate(() => window.__workdshPlateProbe?.cursorToEnd?.());
await page.waitForTimeout(400);
await page.keyboard.press('Enter').catch(() => {});
await page.waitForTimeout(500);
await page.keyboard.type('/', { delay: 60 }).catch(() => {});
out.slashOpened = await steady(async () => page.locator('.slx-pop').first().isVisible({ timeout: 1500 }).catch(() => false), 500, 12000);
step(`slash opened = ${out.slashOpened}`);
out.slashGroups = await page.evaluate(() => Array.from(document.querySelectorAll('.slx-pop .slx-group')).map((g) => ({
  label: (g.querySelector('.slx-group-label')?.textContent ?? '').trim(),
  items: Array.from(g.querySelectorAll('[role="option"]')).map((i) => (i.textContent ?? '').trim()),
})));

// 2) 点「AI 写作」→ 官方 AI 菜单
const aiItem = page.locator('.slx-pop [role="option"]').first();
out.aiItemText = (await aiItem.innerText().catch(() => '')).trim();
await aiItem.click({ timeout: 6000 }).catch((e) => { out.aiClickErr = String(e).slice(0, 120); });
out.aiMenuOpened = await steady(async () => page.locator('[cmdk-root]').first().isVisible({ timeout: 1500 }).catch(() => false), 500, 12000);
step(`AI 写作 -> ai menu = ${out.aiMenuOpened}`);

// === 用户报的 ① ：AI 菜单里到底有哪些项 ===
out.aiMenuItems = await page.evaluate(() => Array.from(document.querySelectorAll('.pltx-ai-item')).map((e) => (e.textContent ?? '').trim()));
step(`AI 菜单项 = ${JSON.stringify(out.aiMenuItems)}`);

if (!out.aiMenuOpened) { out.errors = errs.slice(0, 8); console.log('RESULT', JSON.stringify(out, null, 1)); await browser.close(); process.exit(0); }

// 3) 点「续写」（用户报的 ②：写完文字消失）
const cont = page.locator('.pltx-ai-item', { hasText: '续写' }).first();
out.continueVisible = await cont.isVisible({ timeout: 3000 }).catch(() => false);
await cont.click({ timeout: 6000 }).catch((e) => { out.contClickErr = String(e).slice(0, 120); });
step(`续写 clicked = ${out.continueVisible}`);

// 4) 采样 45s，抓"先出现后消失"
await page.waitForTimeout(45000);
out.timeline = await page.evaluate(() => { clearInterval(window.__aiTimer); return window.__aiTimeline; });

// 5) 时间线分析：长度峰值、是否回落到起点
{
  const tl = out.timeline ?? [];
