  const d = r.postData() ?? '';
  if (d.includes('"endpoint":"rev-append"')) revAppends.push({ t: Date.now(), body: d.slice(0, 150) });
});
page.on('response', (r) => { if (r.status() >= 400) errs.push(`HTTP ${r.status()} ${r.url().slice(0, 100)}`); });

async function steady(fn, gap = 800, budget = 45000) {
  const t0 = Date.now();
  let seen = false;
  while (Date.now() - t0 < budget) { if (await fn()) { seen = true; break; } await page.waitForTimeout(gap); }
  if (!seen) return false;
  await page.waitForTimeout(gap);
  return !!(await fn());
}
const bodyText = () => page.evaluate(() => (document.querySelector('.plate-live-page .plate-content')?.textContent ?? '').replace(/\s+/g, ' '));

// 打开会话 → 文档卡 → 活编辑器（这段与其它探针同路，封装起来好复用）
async function openLiveEditor() {
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
  await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
  await page.waitForTimeout(5000);
  const row = page.getByText(TAG, { exact: false }).first();
  for (let i = 0; i < 25 && !(await row.isVisible({ timeout: 2000 }).catch(() => false)); i++) await page.waitForTimeout(600);
  // 会话行点击偶发不生效（右 pane 滑动状态按会话持久化的老毛病）——点到文件卡
  // 真的出现为止，最多试 4 次，别把一次空点击当成"活编辑器打不开"。
  let cards = [];
  for (let attempt = 0; attempt < 4; attempt++) {
    await row.click({ timeout: 8000 }).catch(() => {});
    await page.waitForTimeout(7000);
    cards = await page.evaluate(() => Array.from(document.querySelectorAll('[class*="_file"]')).map((e) => (e.textContent ?? '').trim()).filter(Boolean).slice(0, 20));
    if (cards.length > 0) break;
    step(`会话行第 ${attempt + 1} 次点击后仍无文件卡，重试`);
  }
  const name = cards.find((t) => t.includes(TAG)) ?? cards[0] ?? TAG;
  await page.locator(`[class*="_file"]:has-text("${name}")`).first().click().catch(() => {});
  await page.waitForTimeout(7000);
  const btn = page.locator('.plate-open-in-plate').first();
  if (await steady(async () => btn.isVisible({ timeout: 2000 }).catch(() => false), 800, 30000)) await btn.click().catch(() => {});
  return steady(async () => page.locator('.plate-live-page .plate-doc-editor').first().isVisible({ timeout: 2000 }).catch(() => false), 900, 60000);
}

out.liveEditorMounted = await openLiveEditor();
step(`live editor mounted = ${out.liveEditorMounted}`);
if (!out.liveEditorMounted) { out.bodyAtFail = (await page.evaluate(() => document.body.innerText)).replace(/\s+/g, ' ').slice(0, 300); out.errors = errs.slice(0, 8); console.log('RESULT', JSON.stringify(out, null, 1)); await browser.close(); process.exit(0); }

