// 在同一个浏览器 context 里连开两次页面，用 CDP 的 fromDiskCache / encodedDataLength
// 分别读第二次的插件包到底走没走缓存。
//   预期：同一次部署内第二次刷新 = 命中磁盘缓存（0 字节网络）
//   对照：每次 dsh plugin add 后 rev 变 → URL 变 → 必然整包重下
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { readFileSync } from 'node:fs';

const TOKEN = readFileSync('/tmp/.plate-token', 'utf8').trim();
const BASE = 'http://127.0.0.1:18989';
const out = { loads: [] };

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 900000 });
const context = await browser.newContext({ viewport: { width: 1920, height: 1080 } });

async function measure(label) {
  const page = await context.newPage();
  const cdp = await context.newCDPSession(page);
  await cdp.send('Network.enable');
  const hits = new Map(); // requestId -> info
  cdp.on('Network.responseReceived', (e) => {
    const u = e.response.url;
    if (u.includes('/plugins/') || u.includes('client.browser.js')) {
      hits.set(e.requestId, {
        url: u.slice(0, 200),
        status: e.response.status,
        fromDiskCache: !!e.response.fromDiskCache,
        fromServiceWorker: !!e.response.fromServiceWorker,
      });
    }
  });
  cdp.on('Network.loadingFinished', (e) => {
    const h = hits.get(e.requestId);
    if (h) h.encodedDataLength = e.encodedDataLength;
  });
  const t0 = Date.now();
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 600000 }).catch(() => {});
  await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 600000 }).catch(() => {});
  // 再稳一会儿，让组合包请求收尾
  await page.waitForTimeout(8000);
  const reqs = [...hits.values()];
  const total = reqs.reduce((a, r) => a + (r.encodedDataLength ?? 0), 0);
  const rec = {
    label,
    seconds: Math.round((Date.now() - t0) / 1000),
    requestCount: reqs.length,
    totalEncodedBytes: total,
    totalEncodedMB: +(total / 1048576).toFixed(2),
    fromDiskCacheCount: reqs.filter((r) => r.fromDiskCache).length,
    fromNetworkCount: reqs.filter((r) => !r.fromDiskCache).length,
    sample: reqs.slice(0, 3),
  };
  out.loads.push(rec);
  console.log(`[${label}] ${rec.seconds}s  请求${rec.requestCount}个  ${rec.totalEncodedMB}MB  磁盘缓存命中${rec.fromDiskCacheCount}/网络${rec.fromNetworkCount}`);
  await page.close();
  return rec;
}

await measure('第一次（冷加载）');
await measure('第二次（同 context 刷新）');

const [a, b] = out.loads;
out.verdict = {
  第二次是否走缓存: b.fromDiskCacheCount > 0,
  第二次网络字节MB: b.totalEncodedMB,
  第一次网络字节MB: a.totalEncodedMB,
  省下MB: +(a.totalEncodedMB - b.totalEncodedMB).toFixed(2),
  URL里的rev: (a.sample?.[0]?.url ?? '').match(/rev=([a-f0-9]+)/)?.[1]?.slice(0, 12) ?? null,
  两次rev是否同: (a.sample?.[0]?.url ?? '') === (b.sample?.[0]?.url ?? ''),
};
console.log('RESULT', JSON.stringify(out, null, 1));
