  const h1=(txt.match(/^#\s+(.+)$/m)||[])[1];
  if(!nm||nm.trim()!==d){ console.log("  !! name 与目录名不符: "+d+" vs "+nm); continue; }
  added.push({name:d,title:(h1||d).trim(),description:(de||"").trim().replace(/^"|"$/g,""),categories:["知识处理"],version:"1.0.0",examples:[],payload:"payloads/"+d});
}
cat.entries.push(...added);
if(added.length && !cat.categories.includes("知识处理")) cat.categories.push("知识处理");
cat.generatedAt="2026-09-30T00:00:00+08:00";
fs.writeFileSync("market/catalog.json",JSON.stringify(cat,null,2)+"\n");
console.log("新增条目 "+added.length+" 个；catalog 现共 "+cat.entries.length+" 条；分类 "+JSON.stringify(cat.categories));
