//   ① 选中文字后弹出官方浮动工具条（含 AI 按钮），点 AI 展开 AI 菜单
//   ② "/" 在中文句子中间也能触发斜杠菜单（官方默认要求前一字符是空白）
// 判据： ① .pltx-ftb-root 出现在选区上方，点它里面的 AI 按钮后 [cmdk-root] 出现
//        ② 在中文后敲 / → .slx-pop 出现；对照：英文 "http:" 后敲 / → 不出现
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { readFileSync } from 'node:fs';

const TOKEN = readFileSync('/tmp/.plate-token', 'utf8').trim();
const TAG = process.argv[2] ?? '784428';
const BASE = 'http://127.0.0.1:18989';
const out = {};
const step = (s) => { console.log('STEP', s); };

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 900000 });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
const errs = [];
page.on('pageerror', (e) => errs.push('PAGEERROR ' + String(e).slice(0, 200)));
page.on('console', (m) => { if (m.type() === 'error') errs.push('console: ' + m.text().slice(0, 200)); });

async function steady(fn, gap = 700, budget = 40000) {
  const t0 = Date.now();
  let seen = false;
  while (Date.now() - t0 < budget) { if (await fn()) { seen = true; break; } await page.waitForTimeout(gap); }
  if (!seen) return false;
  await page.waitForTimeout(gap);
  return !!(await fn());
}
const vis = (sel) => page.locator(sel).first().isVisible({ timeout: 1500 }).catch(() => false);

// 打开活编辑器（与既有探针同路）
await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await page.waitForTimeout(5000);
const row = page.getByText(TAG, { exact: false }).first();
for (let i = 0; i < 25 && !(await row.isVisible({ timeout: 2000 }).catch(() => false)); i++) await page.waitForTimeout(600);
let cards = [];
for (let a = 0; a < 4; a++) {
  await row.click({ timeout: 8000 }).catch(() => {});
  await page.waitForTimeout(7000);
  cards = await page.evaluate(() => Array.from(document.querySelectorAll('[class*="_file"]')).map((e) => (e.textContent ?? '').trim()).filter(Boolean).slice(0, 20));
  if (cards.length > 0) break;
}
const name = cards.find((t) => t.includes(TAG)) ?? cards[0] ?? TAG;
await page.locator(`[class*="_file"]:has-text("${name}")`).first().click().catch(() => {});
await page.waitForTimeout(7000);
const btn = page.locator('.plate-open-in-plate').first();
if (await steady(async () => btn.isVisible({ timeout: 2000 }).catch(() => false), 800, 30000)) await btn.click().catch(() => {});
out.liveEditorMounted = await steady(() => vis('.plate-live-page .plate-doc-editor'), 900, 60000);
step(`活编辑器 = ${out.liveEditorMounted}`);
if (!out.liveEditorMounted) { out.errors = errs.slice(0, 6); console.log('RESULT', JSON.stringify(out, null, 1)); await browser.close(); process.exit(0); }

const content = page.locator('.plate-live-page .plate-content').first();

// ── ② 斜杠：中文后触发 / 英文 http: 后不触发 ──────────────────────────────
await content.click().catch(() => {});
await page.waitForTimeout(300);
await page.evaluate(() => window.__workdshPlateProbe?.cursorToEnd?.());
await page.waitForTimeout(400);
await page.keyboard.press('Enter').catch(() => {});
await page.waitForTimeout(500);

// 阴性对照：英文 http: 后敲 /
await page.keyboard.type('http:', { delay: 40 }).catch(() => {});
await page.waitForTimeout(300);
await page.keyboard.type('/', { delay: 60 }).catch(() => {});
await page.waitForTimeout(2500);
out.slashAfterAscii = await vis('.slx-pop');
step(`对照 http:/ 触发 = ${out.slashAfterAscii}（期望 false）`);
// 清掉这一行
await page.keyboard.press('Escape').catch(() => {});
for (let i = 0; i < 6; i++) await page.keyboard.press('Backspace').catch(() => {});
await page.waitForTimeout(400);

// 阳性：中文后敲 /
await page.keyboard.type('这是一句中文测试', { delay: 40 }).catch(() => {});
await page.waitForTimeout(400);
await page.keyboard.type('/', { delay: 60 }).catch(() => {});
out.slashAfterCjk = await steady(() => vis('.slx-pop'), 600, 15000);
step(`中文后 / 触发 = ${out.slashAfterCjk}（期望 true）`);
await page.keyboard.press('Escape').catch(() => {});
await page.waitForTimeout(500);

// ── ① 选中 → 浮动工具条 → 点 AI → 菜单 ────────────────────────────────────
await page.evaluate(() => window.__workdshPlateProbe?.cursorToEnd?.());
await page.waitForTimeout(300);
// 三连击选中当前段落（既有经验：防塌缩用三连击）
await content.click({ clickCount: 3 }).catch(() => {});
await page.waitForTimeout(1500);
out.floatingToolbar = await steady(() => vis('.pltx-ftb-root'), 600, 15000);
step(`选中后浮动工具条 = ${out.floatingToolbar}（期望 true）`);

out.floatingHasAiBtn = await page.locator('.pltx-ftb-root button').first().isVisible({ timeout: 3000 }).catch(() => false);
// 点浮动工具条里的 AI 按钮（第一个分组就是它）
await page.locator('.pltx-ftb-root button').first().click({ timeout: 6000 }).catch(() => {});
out.aiMenuOpened = await steady(() => vis('[cmdk-root]'), 700, 15000);
step(`点 AI 后菜单 = ${out.aiMenuOpened}（期望 true）`);
out.aiMenuItems = await page.evaluate(() => Array.from(document.querySelectorAll('.pltx-ai-item')).map((e) => (e.textContent ?? '').trim()));
step(`菜单项 = ${JSON.stringify(out.aiMenuItems)}`);

// 浮动工具条是否在 AI 菜单打开时收起（官方行为）
out.toolbarHiddenWhenAiOpen = !(await vis('.pltx-ftb-root'));

out.errors = errs.slice(0, 8);
console.log('RESULT', JSON.stringify(out, null, 1));
await browser.close();

/**
 * 官方 playground 浮动工具条移植层（选中文字即弹出）。
 *
 * 蓝本（udecode/plate-playground-template@main，与本地 platejs 53.3.14 同代）：
 *   src/components/ui/floating-toolbar.tsx         → FloatingToolbar
 *   src/components/ui/floating-toolbar-buttons.tsx → FloatingToolbarButtons
 *
 * 为什么需要它：官方 AIChatPlugin 的 useEditorChat 依赖数组**只有 [open]**
 * （@platejs/ai/dist/react/index.js:793 原文），三个回调是菜单「已经打开后」
 * 重新挂锚点用的——选中文字本身不会打开 AI 菜单。官方 playground 的做法是
 * 选中先弹这条浮动工具条，点其中的 AI 按钮再展开菜单。本文件照此实现。
 *
 * 与官方的落地差异（宿主限制，非设计选择）：
 *   ① 宿主无 @udecode/cn → useComposedRef 就地内联实现（行为等价）；
 *   ② 类名落 `pltx-ftb-*` 自包含 CSS（视觉等价）；
 *   ③ 按钮裁剪到本插件真装了的标记：AI / 加粗 / 斜体 / 下划线 / 删除线 /
 *      行内码。官方的链接、行内公式、评论、建议、更多 依赖未安装的插件，不列。
 */
import {
  type FloatingToolbarState,
  flip,
  offset,
  useFloatingToolbar,
  useFloatingToolbarState,
} from '@platejs/floating';
import { AIChatPlugin } from '@platejs/ai/react';
import { BoldIcon, Code2Icon, ItalicIcon, StrikethroughIcon, UnderlineIcon } from 'lucide-react';
import { KEYS } from 'platejs';
import {
  useEditorId,
  useEditorReadOnly,
  useEventEditorValue,
  usePluginOption,
} from 'platejs/react';
import React from 'react';
import clsx from 'clsx';

import { AIToolbarButton, MarkToolbarButton, Toolbar, ToolbarGroup } from './toolbar-native.js';

/**
 * 官方用 @udecode/cn 的 useComposedRef；宿主没装那个包，
 * 这里就地实现等价语义：把内层与传入的 ref 一起挂到同一个节点上。
 */
function useComposedRef<T>(
  ...refs: Array<React.Ref<T> | undefined>
): (node: T | null) => void {
  return React.useCallback((node: T | null) => {
    for (const ref of refs) {
      if (!ref) continue;
      if (typeof ref === 'function') ref(node);
      else (ref as React.MutableRefObject<T | null>).current = node;
    }
    // refs 每次渲染都是新数组字面量，用展开长度+逐项比对太重；
    // 官方同样是「每次渲染重建」，这里保持一致。
  }, refs);
}

export function FloatingToolbar({
  children,
  className,
  state,
  ...props
}: React.ComponentProps<typeof Toolbar> & { state?: FloatingToolbarState }) {
  const editorId = useEditorId();
  const focusedEditorId = useEventEditorValue('focus');
  // AI 菜单打开时收起工具条，避免两层浮层打架（官方同款判定）
  const isAIChatOpen = usePluginOption(AIChatPlugin, 'open');

  const floatingToolbarState = useFloatingToolbarState({
    editorId,
    focusedEditorId,
    hideToolbar: isAIChatOpen,
    ...state,
    floatingOptions: {
      middleware: [
        offset(12),
        flip({
          fallbackPlacements: [
            'top-start',
            'top-end',
            'bottom-start',
            'bottom-end',
          ],
          padding: 12,
        }),
      ],
      placement: 'top',
      ...state?.floatingOptions,
    },
  });

  const {
    clickOutsideRef,
    hidden,
    props: rootProps,
    ref: floatingRef,
  } = useFloatingToolbar(floatingToolbarState);

  const ref = useComposedRef<HTMLDivElement>(props.ref, floatingRef);

  if (hidden) return null;

  return (
    <div ref={clickOutsideRef}>
      <Toolbar
        {...props}
        {...rootProps}
        className={clsx('pltx-ftb-root', className)}
        ref={ref}
      >
        {children}
      </Toolbar>
    </div>
  );
}

export function FloatingToolbarButtons() {
  const readOnly = useEditorReadOnly();

  if (readOnly) return null;

  return (
    <>
      <ToolbarGroup>
        <AIToolbarButton />
      </ToolbarGroup>

      <ToolbarGroup>
        <MarkToolbarButton nodeType={KEYS.bold} tooltip="加粗 (⌘+B)">
          <BoldIcon />
        </MarkToolbarButton>

        <MarkToolbarButton nodeType={KEYS.italic} tooltip="斜体 (⌘+I)">
          <ItalicIcon />
        </MarkToolbarButton>

        <MarkToolbarButton nodeType={KEYS.underline} tooltip="下划线 (⌘+U)">
          <UnderlineIcon />
        </MarkToolbarButton>

        <MarkToolbarButton
          nodeType={KEYS.strikethrough}
          tooltip="删除线 (⌘+⇧+M)"
        >
          <StrikethroughIcon />
        </MarkToolbarButton>

        <MarkToolbarButton nodeType={KEYS.code} tooltip="行内代码 (⌘+E)">
          <Code2Icon />
        </MarkToolbarButton>
      </ToolbarGroup>
    </>
  );
}

// ---------------------------------------------------------------------------
// 自包含样式（宿主无 tailwind：官方类名的等价落地）
export const floatingToolbarNativeCss = `
.pltx-ftb-root {
  position: absolute;
  z-index: 50;
  max-width: 80vw;
  overflow-x: auto;
  white-space: nowrap;
  border-radius: 6px;
  border: 1px solid var(--ds-border, rgba(0,0,0,.12));
  background: var(--ds-bg-elevated, #fff);
  padding: 4px;
  box-shadow: 0 4px 12px rgba(0,0,0,.12);
  flex-wrap: nowrap;
  opacity: 1;
}
`;

'use client';

import {
  BoldIcon,
  Code2Icon,
  ItalicIcon,
  StrikethroughIcon,
  UnderlineIcon,
  WandSparklesIcon,
} from 'lucide-react';
import { KEYS } from 'platejs';
import { useEditorReadOnly } from 'platejs/react';

import { AIToolbarButton } from './ai-toolbar-button';
import { CommentToolbarButton } from './comment-toolbar-button';
import { InlineEquationToolbarButton } from './equation-toolbar-button';
import { LinkToolbarButton } from './link-toolbar-button';
import { MarkToolbarButton } from './mark-toolbar-button';
import { MoreToolbarButton } from './more-toolbar-button';
import { SuggestionToolbarButton } from './suggestion-toolbar-button';
import { ToolbarGroup } from './toolbar';
import { TurnIntoToolbarButton } from './turn-into-toolbar-button';

export function FloatingToolbarButtons() {
  const readOnly = useEditorReadOnly();

  return (
    <>
      {!readOnly && (
        <>
          <ToolbarGroup>
            <AIToolbarButton tooltip="AI commands">
              <WandSparklesIcon />
              Ask AI
            </AIToolbarButton>
          </ToolbarGroup>

          <ToolbarGroup>
            <TurnIntoToolbarButton />

            <MarkToolbarButton nodeType={KEYS.bold} tooltip="Bold (⌘+B)">
              <BoldIcon />
            </MarkToolbarButton>

            <MarkToolbarButton nodeType={KEYS.italic} tooltip="Italic (⌘+I)">
              <ItalicIcon />
            </MarkToolbarButton>

            <MarkToolbarButton
              nodeType={KEYS.underline}
              tooltip="Underline (⌘+U)"
            >
              <UnderlineIcon />
            </MarkToolbarButton>

            <MarkToolbarButton
              nodeType={KEYS.strikethrough}
              tooltip="Strikethrough (⌘+⇧+M)"
            >
              <StrikethroughIcon />
            </MarkToolbarButton>

            <MarkToolbarButton nodeType={KEYS.code} tooltip="Code (⌘+E)">
              <Code2Icon />
            </MarkToolbarButton>

            <InlineEquationToolbarButton />

            <LinkToolbarButton />
          </ToolbarGroup>
        </>
      )}

      <ToolbarGroup>
        <CommentToolbarButton />
        <SuggestionToolbarButton />

        {!readOnly && <MoreToolbarButton />}
      </ToolbarGroup>
    </>
  );
}

