function useComposedRef<T>(
  ...refs: Array<React.Ref<T> | undefined>
): (node: T | null) => void {
  return React.useCallback((node: T | null) => {
    for (const ref of refs) {
      if (!ref) continue;
      if (typeof ref === 'function') ref(node);
      else (ref as React.MutableRefObject<T | null>).current = node;
