const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
const errs = [];
page.on('pageerror', (e) => errs.push('PAGEERROR ' + String(e).slice(0, 200)));

const vis = (sel) => page.locator(sel).first().isVisible({ timeout: 1500 }).catch(() => false);
async function steady(fn, gap = 700, budget = 30000) {
  const t0 = Date.now(); let seen = false;
  while (Date.now() - t0 < budget) { if (await fn()) { seen = true; break; } await page.waitForTimeout(gap); }
  if (!seen) return false;
  await page.waitForTimeout(gap);
  return !!(await fn());
}

// 分栏：删除标记 / 新增标记 / 重建结果串
const split = () => page.evaluate(() => {
  const root = document.querySelector('.plate-live-page .plate-content');
  if (!root) return null;
  const removes = Array.from(root.querySelectorAll('.pltx-suggestion-remove')).map((e) => (e.textContent ?? '').trim()).filter(Boolean);
  const keeps = Array.from(root.querySelectorAll('.pltx-suggestion:not(.pltx-suggestion-remove)')).map((e) => (e.textContent ?? '').trim()).filter(Boolean);
  // 重建「接受后」的正文：递归遍历，遇到删除标记整棵子树跳过
  let result = '';
  const walk = (n) => {
    if (n.nodeType === 3) { result += n.textContent; return; }
    if (n.nodeType !== 1) return;
    if (n.classList?.contains('pltx-suggestion-remove')) return;
    for (const c of n.childNodes) walk(c);
  };
  walk(root);
  return { removes, keeps, result, raw: root.textContent };
});

await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await page.waitForTimeout(5000);
const row = page.getByText(TAG, { exact: false }).first();
for (let i = 0; i < 25 && !(await row.isVisible({ timeout: 2000 }).catch(() => false)); i++) await page.waitForTimeout(600);
let cards = [];
for (let a = 0; a < 4; a++) {
  await row.click({ timeout: 8000 }).catch(() => {});
  await page.waitForTimeout(7000);
  cards = await page.evaluate(() => Array.from(document.querySelectorAll('[class*="_file"]')).map((e) => (e.textContent ?? '').trim()).filter(Boolean).slice(0, 20));
  if (cards.length) break;
}
const name = cards.find((t) => t.includes(TAG)) ?? cards[0] ?? TAG;
await page.locator(`[class*="_file"]:has-text("${name}")`).first().click().catch(() => {});
await page.waitForTimeout(7000);
const btn = page.locator('.plate-open-in-plate').first();
if (await steady(async () => btn.isVisible({ timeout: 2000 }).catch(() => false), 800, 30000)) await btn.click().catch(() => {});
out.liveEditorMounted = await steady(() => vis('.plate-live-page .plate-doc-editor'), 900, 60000);
step(`活编辑器 = ${out.liveEditorMounted}`);
if (!out.liveEditorMounted) { out.errors = errs.slice(0, 6); console.log('RESULT', JSON.stringify(out, null, 1)); await browser.close(); process.exit(0); }
const content = page.locator('.plate-live-page .plate-content').first();

await content.click({ clickCount: 3 }).catch(() => {});
await page.waitForTimeout(1200);
out.selText = await page.evaluate(() => window.getSelection()?.toString() ?? '');
await steady(() => vis('.pltx-ftb-root'), 600, 15000);
await page.locator('.pltx-ftb-root button').first().click({ timeout: 8000 }).catch(() => {});
await steady(() => vis('[cmdk-root]'), 700, 15000);
const item = page.locator('.pltx-ai-item', { hasText: '缩写' }).first();
if (await item.isVisible({ timeout: 4000 }).catch(() => false)) await item.click({ timeout: 8000 }).catch(() => {});
step(`选中 ${out.selText.length} 字，已点「缩写」`);

await steady(async () => ((await split())?.removes?.length ?? 0) + ((await split())?.keeps?.length ?? 0) > 0, 1000, 90000);
let a1 = await split();
await page.waitForTimeout(12000);
let a2 = await split();
out.stable = JSON.stringify(a1) === JSON.stringify(a2);
out.removes = a2.removes;
out.keeps = a2.keeps;
out.resultText = a2.result;
out.resultLen = a2.result.length;
step(`稳态=${out.stable} 删除${out.removes.length}段/新增${out.keeps.length}段`);
step(`接受后正文(${out.resultLen}字)：${out.resultText}`);
step(`删除片段：${JSON.stringify(out.removes)}`);
step(`新增片段：${JSON.stringify(out.keeps)}`);

out.errors = errs.slice(0, 8);
console.log('RESULT', JSON.stringify(out, null, 1));
await browser.close();

