72-for (let i = 0; i < 6; i++) await page.keyboard.press('Backspace').catch(() => {});
73-await page.waitForTimeout(400);
74-
75-// 阳性：中文后敲 /
76-await page.keyboard.type('这是一句中文测试', { delay: 40 }).catch(() => {});
77-await page.waitForTimeout(400);
78-await page.keyboard.type('/', { delay: 60 }).catch(() => {});
79:out.slashAfterCjk = await steady(() => vis('.slx-pop'), 600, 15000);
80:step(`中文后 / 触发 = ${out.slashAfterCjk}（期望 true）`);
81-await page.keyboard.press('Escape').catch(() => {});
