83-
84-// ── ① 选中 → 浮动工具条 → 点 AI → 菜单 ────────────────────────────────────
85-await page.evaluate(() => window.__workdshPlateProbe?.cursorToEnd?.());
86-await page.waitForTimeout(300);
87-// 三连击选中当前段落（既有经验：防塌缩用三连击）
88-await content.click({ clickCount: 3 }).catch(() => {});
89-await page.waitForTimeout(1500);
90-out.floatingToolbar = await steady(() => vis('.pltx-ftb-root'), 600, 15000);
91-step(`选中后浮动工具条 = ${out.floatingToolbar}（期望 true）`);
92-
93-// 定位判据：浮层必须真的被 floating-ui 摆到选区附近，
94-// 不能停在未定位位（本机历史故障：元素在但 translate(0,-200%)）。
95-out.toolbarRect = await page.evaluate(() => {
96-  const el = document.querySelector('.pltx-ftb-root');
97-  if (!el) return null;
98-  const r = el.getBoundingClientRect();
99-  const s = getComputedStyle(el);
100-  return { top: Math.round(r.top), left: Math.round(r.left), w: Math.round(r.width), h: Math.round(r.height), position: s.position, transform: s.transform };
101-});
