await page.keyboard.type('/', { delay: 60 }).catch(() => {});
out.C_secondSlash = await steady(() => vis('.slx-pop'), 600, 15000);
step(`   C(连敲第二个 /) = ${out.C_secondSlash}`);

// 真正的基线对照：Enter 开新空块 → 块首敲 /
await page.keyboard.press('Escape').catch(() => {});
await page.waitForTimeout(400);
await page.keyboard.press('Enter').catch(() => {});
await page.waitForTimeout(500);
await page.keyboard.type('/', { delay: 60 }).catch(() => {});
out.D_freshBlockSlash = await steady(() => vis('.slx-pop'), 600, 15000);
step(`   D(新空块块首 /) = ${out.D_freshBlockSlash}`);

out.verdict = out.D_freshBlockSlash
  ? (out.B_cjkSlash ? '产品绿：中文后与块首均触发' : '序列污染：块首触发但 1776 序列下不触发')
