// 只回答一件事：浏览器加载页面时到底哪些 URL 真的失败了（记全量 URL，不只记失败计数）。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { readFileSync } from 'node:fs';

const TOKEN = readFileSync('/tmp/.plate-token', 'utf8').trim();
const browser = await chromium.launch({ channel: 'chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });

const bad = [];
const consoleErrs = [];
page.on('response', (r) => { if (r.status() >= 400) bad.push({ status: r.status(), url: r.url() }); });
page.on('requestfailed', (r) => bad.push({ status: 'FAILED', url: r.url(), err: r.failure()?.errorText }));
page.on('pageerror', (e) => consoleErrs.push('PAGEERROR ' + String(e).slice(0, 160)));
page.on('console', (m) => { if (m.type() === 'error') consoleErrs.push('console: ' + m.text().slice(0, 160)); });

await page.goto('http://127.0.0.1:18989/?token=' + TOKEN, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await page.waitForTimeout(20000);   // 让懒加载/预取都发完

const norm = (u) => u.replace(/^https?:\/\/127\.0\.0\.1:18989/, '');
const byUrl = new Map();
for (const b of bad) {
  const k = `${b.status} ${norm(b.url).slice(0, 150)}`;
  byUrl.set(k, (byUrl.get(k) ?? 0) + 1);
}
console.log('=== 失败请求（去重计数） ===');
for (const [k, n] of [...byUrl].sort()) console.log('  x' + n, k);
console.log('  合计去重条目 =', byUrl.size, ' 原始失败数 =', bad.length);
console.log('=== 控制台错误 ===');
console.log('  ' + (consoleErrs.length ? [...new Set(consoleErrs)].slice(0, 6).join('\n  ') : '无'));
await browser.close();

