// 终结「/ 在中文后到底触不触发」的争议：任何斜杠结论之前，先证明「键盘输入真的进了文档」。
// 每个用例都要求：① 打的字出现在 blockText 里（输入管道阳性对照）→ 才有资格判斜杠。
//   用例1 块首空块敲 /           → 阴性/阳性基线（官方行为，必须 true）
//   用例2 中文句子中间敲 /        → 用户报的修复目标（期望 true）
//   用例3 http: 之后敲 /         → 不该触发（期望 false）
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { readFileSync } from 'node:fs';

const TOKEN = readFileSync('/tmp/.plate-token', 'utf8').trim();
const TAG = process.argv[2] ?? '784428';
const BASE = 'http://127.0.0.1:18989';
const out = {};
const step = (s) => console.log('STEP', s);

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 900000 });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
const errs = [];
page.on('pageerror', (e) => errs.push('PAGEERROR ' + String(e).slice(0, 200)));

const vis = (sel) => page.locator(sel).first().isVisible({ timeout: 1200 }).catch(() => false);
async function steady(fn, gap = 600, budget = 15000) {
  const t0 = Date.now(); let seen = false;
  while (Date.now() - t0 < budget) { if (await fn()) { seen = true; break; } await page.waitForTimeout(gap); }
  if (!seen) return false;
  await page.waitForTimeout(gap);
  return !!(await fn());
}
// 光标所在块全文 + 是否在编辑器里
const ctx = () => page.evaluate(() => {
  const sel = window.getSelection();
  const node = sel?.anchorNode;
  const el = node?.nodeType === 3 ? node.parentElement : node;
  const block = el?.closest?.('p,h1,h2,h3,li,blockquote,div[data-slate-node]');
  return { blockText: block?.textContent ?? null, offset: sel?.anchorOffset ?? -1, inEditor: !!el?.closest?.('.plate-content') };
});
const menuOpen = () => vis('.slx-pop');
// 输入守卫：打完这段字必须出现在光标所在块里，否则本用例作废（不拿它下结论）
async function typeVerified(text, label) {
  const before = await ctx();
  await page.keyboard.type(text, { delay: 40 }).catch(() => {});
  await page.waitForTimeout(500);
  const after = await ctx();
  const landed = !!after.blockText && after.blockText.includes(text.replace(/\/$/, '').slice(0, 4));
  step(`   [输入守卫] ${label}: 打字前块="${(before.blockText ?? '').slice(0, 24)}" 打字后块="${(after.blockText ?? '').slice(0, 24)}" 落地=${landed}`);
  return landed;
}

await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await page.waitForTimeout(5000);
const row = page.getByText(TAG, { exact: false }).first();
for (let i = 0; i < 25 && !(await row.isVisible({ timeout: 2000 }).catch(() => false)); i++) await page.waitForTimeout(600);
let cards = [];
for (let a = 0; a < 4; a++) {
  await row.click({ timeout: 8000 }).catch(() => {});
  await page.waitForTimeout(7000);
  cards = await page.evaluate(() => Array.from(document.querySelectorAll('[class*="_file"]')).map((e) => (e.textContent ?? '').trim()).filter(Boolean).slice(0, 20));
  if (cards.length) break;
}
const name = cards.find((t) => t.includes(TAG)) ?? cards[0] ?? TAG;
await page.locator(`[class*="_file"]:has-text("${name}")`).first().click().catch(() => {});
await page.waitForTimeout(7000);
const btn = page.locator('.plate-open-in-plate').first();
if (await steady(async () => btn.isVisible({ timeout: 2000 }).catch(() => false), 800, 30000)) await btn.click().catch(() => {});
out.liveEditorMounted = await steady(() => vis('.plate-live-page .plate-doc-editor'), 900, 60000);
step(`活编辑器 = ${out.liveEditorMounted}`);
if (!out.liveEditorMounted) { out.errors = errs.slice(0, 6); console.log('RESULT', JSON.stringify(out, null, 1)); await browser.close(); process.exit(0); }

const content = page.locator('.plate-live-page .plate-content').first();
// 每次用例前重新点回编辑器（Escape 可能让编辑器失焦，必须重聚焦）
async function focusEditor() {
  await content.click({ clickCount: 3 }).catch(() => {});   // 三连击选中整段
  await page.waitForTimeout(600);
  await page.keyboard.press('End').catch(() => {});
  await page.waitForTimeout(300);
}

// ── 用例 1：块首空块敲 /（官方基线） ───────────────────────────────
await focusEditor();
await page.keyboard.press('Enter').catch(() => {});
await page.waitForTimeout(600);
const c1 = await ctx();
step(`用例1 起始块="${(c1.blockText ?? '').slice(0, 20)}"（应为空）`);
if (await typeVerified('/', '用例1')) {
  out.case1_blockStart = await steady(menuOpen, 600, 15000);
} else { out.case1_blockStart = null; out.case1_note = '输入未落地，作废'; }
step(`用例1 块首敲 / = ${out.case1_blockStart}（期望 true）`);
await page.keyboard.press('Escape').catch(() => {});
await page.waitForTimeout(400);

// ── 用例 2：中文句子中间敲 /（用户报的修复目标） ─────────────────────
await focusEditor();
await page.keyboard.press('Enter').catch(() => {});
await page.waitForTimeout(400);
if (await typeVerified('这是一句中文测试', '用例2 前置中文')) {
  out.case2_ctxBefore = await ctx();
  if (await typeVerified('/', '用例2 斜杠')) {
    out.case2_midCjk = await steady(menuOpen, 600, 15000);
  } else { out.case2_midCjk = null; }
} else { out.case2_midCjk = null; out.case2_note = '中文没打进去，作废'; }
out.case2_ctxAfter = await ctx();
step(`用例2 中文后敲 / = ${out.case2_midCjk}（期望 true）`);
if (out.case2_midCjk) out.case2_menuItems = await page.evaluate(() => Array.from(document.querySelectorAll('.slx-pop [role="option"], .slx-pop [cmdk-item]')).map((e) => (e.textContent ?? '').trim()).filter(Boolean).slice(0, 10));
if (out.case2_midCjk) step(`   菜单项 = ${JSON.stringify(out.case2_menuItems)}`);
await page.keyboard.press('Escape').catch(() => {});
await page.waitForTimeout(400);

// ── 用例 3：http: 之后敲 /（不该触发） ─────────────────────────────
await focusEditor();
await page.keyboard.press('Enter').catch(() => {});
await page.waitForTimeout(400);
if (await typeVerified('http:', '用例3 前置 ascii')) {
  if (await typeVerified('/', '用例3 斜杠')) {
    await page.waitForTimeout(2500);
    out.case3_afterAscii = await menuOpen();
  } else { out.case3_afterAscii = null; }
} else { out.case3_afterAscii = null; out.case3_note = 'ascii 没打进去，作废'; }
step(`用例3 http: 后敲 / = ${out.case3_afterAscii}（期望 false）`);

out.verdict = (out.case1_blockStart === true && out.case2_midCjk === true && out.case3_afterAscii === false)
  ? '全绿：基线触发、中文中间触发、ascii 后不触发'
  : `需人工判读 case1=${out.case1_blockStart} case2=${out.case2_midCjk} case3=${out.case3_afterAscii}`;
step(`判定 = ${out.verdict}`);
out.errors = errs.slice(0, 6);
console.log('RESULT', JSON.stringify(out, null, 1));
await browser.close();

