const vis = (sel) => page.locator(sel).first().isVisible({ timeout: 1200 }).catch(() => false);
async function steady(fn, gap = 800, budget = 40000) {
  const t0 = Date.now(); let seen = false;
  while (Date.now() - t0 < budget) { if (await fn()) { seen = true; break; } await page.waitForTimeout(gap); }
  if (!seen) return false;
  await page.waitForTimeout(gap); return !!(await fn());
}
const ctx = () => page.evaluate(() => {
  const sel = window.getSelection(); const node = sel?.anchorNode;
  const el = node?.nodeType === 3 ? node.parentElement : node;
  const block = el?.closest?.('p,h1,h2,h3,li,blockquote,div[data-slate-node]');
  return { blockText: block?.textContent ?? null, inEditor: !!el?.closest?.('.plate-content') };
});

await page.goto('http://127.0.0.1:18989/?token=' + TOKEN, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await page.waitForTimeout(5000);
const row = page.getByText(TAG, { exact: false }).first();
for (let i = 0; i < 25 && !(await row.isVisible({ timeout: 2000 }).catch(() => false)); i++) await page.waitForTimeout(600);
await row.click({ timeout: 8000 }).catch(() => {});
await page.waitForTimeout(7000);
const cards = await page.evaluate(() => Array.from(document.querySelectorAll('[class*="_file"]')).map((e) => (e.textContent ?? '').trim()).filter(Boolean).slice(0, 20));
const name = cards.find((t) => t.includes(TAG)) ?? cards[0] ?? TAG;
await page.locator(`[class*="_file"]:has-text("${name}")`).first().click().catch(() => {});
await page.waitForTimeout(7000);
const btn = page.locator('.plate-open-in-plate').first();
if (await steady(async () => btn.isVisible({ timeout: 2000 }).catch(() => false), 800, 30000)) await btn.click().catch(() => {});
const mounted = await steady(() => vis('.plate-live-page .plate-doc-editor'), 900, 60000);
step(`活编辑器 = ${mounted}`);
const content = page.locator('.plate-live-page .plate-content').first();
await content.click({ clickCount: 3 }).catch(() => {});
await page.waitForTimeout(600);
await page.keyboard.press('End').catch(() => {});
await page.keyboard.press('Enter').catch(() => {});
await page.waitForTimeout(500);

// 1) Escape 前打字
await page.keyboard.type('AAA', { delay: 40 }).catch(() => {});
await page.waitForTimeout(500);
const before = await ctx();
step(`Escape 前打字后块="${(before.blockText ?? '').slice(0, 30)}" inEditor=${before.inEditor} → 落地=${!!before.blockText?.includes('AAA')}`);

// 2) 按 Escape（此时并没有菜单开着 —— 复刻 1776 里「没触发菜单后仍按 Escape」的情形）
await page.keyboard.press('Escape').catch(() => {});
await page.waitForTimeout(600);
const afterEsc = await ctx();
step(`Escape 后 inEditor=${afterEsc.inEditor}`);

// 3) Escape 后再打字，看还进不进文档
await page.keyboard.type('BBB', { delay: 40 }).catch(() => {});
await page.waitForTimeout(600);
const after = await ctx();
step(`Escape 后打字后块="${(after.blockText ?? '').slice(0, 30)}" inEditor=${after.inEditor} → 落地=${!!after.blockText?.includes('BBB')}`);

// 4) 重新点回编辑器再打字（恢复对照）
await content.click({ clickCount: 3 }).catch(() => {});
await page.waitForTimeout(600);
await page.keyboard.press('End').catch(() => {});
await page.keyboard.type('CCC', { delay: 40 }).catch(() => {});
await page.waitForTimeout(600);
const afterReclick = await ctx();
step(`重新点击后打字 → 落地=${!!afterReclick.blockText?.includes('CCC')}`);

console.log('RESULT', JSON.stringify({
  beforeEscapeLanded: !!before.blockText?.includes('AAA'),
  inEditorAfterEscape: afterEsc.inEditor,
  afterEscapeLanded: !!after.blockText?.includes('BBB'),
  afterReclickLanded: !!afterReclick.blockText?.includes('CCC'),
  blockAfter: after.blockText,
}, null, 1));
await browser.close();

