// 界面上逐个确认"本次更新说有的东西"是否真的可见/可用。
// 原则：只记录屏幕上真实存在的文本与状态，每一项都给"看到什么"的原始读数。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { readFileSync } from 'node:fs';

const TOKEN = readFileSync('/tmp/.plate-token', 'utf8').trim();
const BASE = 'http://127.0.0.1:18989';
const log = (k, v) => console.log(`RESULT ${k} = ${typeof v === 'string' ? v : JSON.stringify(v)}`);
const step = (s) => console.log('STEP', s);

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 900000 });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
const pageerrors = [];
const httpFail = [];
page.on('pageerror', (e) => pageerrors.push(String(e).slice(0, 200)));
page.on('response', (r) => { if (r.status() >= 400) httpFail.push(r.status() + ' ' + r.url().replace(BASE, '')); });

const vis = (sel) => page.locator(sel).first().isVisible({ timeout: 1500 }).catch(() => false);
const text = async (sel) => page.locator(sel).first().innerText({ timeout: 3000 }).catch(() => '');
async function steady(fn, gap = 800, budget = 40000) {
  const t0 = Date.now(); let seen = false;
  while (Date.now() - t0 < budget) { if (await fn()) { seen = true; break; } await page.waitForTimeout(gap); }
  if (!seen) return false;
  await page.waitForTimeout(gap); return !!(await fn());
}
// 当前视图里可见的按钮/标签文本
const visibleLabels = () => page.evaluate(() => {
  const ok = (el) => { const r = el.getBoundingClientRect(); const s = getComputedStyle(el);
    return r.width > 0 && r.height > 0 && s.visibility !== 'hidden' && s.display !== 'none'; };
  return [...new Set([...document.querySelectorAll('button,[role="button"],[role="tab"],a,h1,h2,h3,nav')]
    .filter(ok).map((el) => (el.innerText ?? '').trim().split('\n')[0])
    .filter((t) => t && t.length < 30))];
});

await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await page.waitForTimeout(12000);

// ── 1. 左栏导航（有哪些入口） ─────────────────────────────────────
const rail = await page.evaluate(() => {
  const ok = (el) => { const r = el.getBoundingClientRect(); return r.width > 0 && r.height > 0; };
  return [...new Set([...document.querySelectorAll('nav button,nav a,[class*="sidebar"] button')]
    .filter(ok).map((el) => (el.innerText ?? '').trim().split('\n')[0]).filter(Boolean))];
});
log('1_左栏导航', rail);
log('1_是否有终端入口', rail.some((t) => /终端|Terminal/i.test(t)));

// ── 2. 技能页：本地技能 / SkillHub 两个页签 ───────────────────────
await page.goto(`${BASE}/?workdsh-view=skills`, { waitUntil: 'domcontentloaded', timeout: 120000 }).catch(() => {});
await steady(() => vis('[data-testid="workdsh-skills"]'), 900, 60000);
await page.waitForTimeout(4000);
log('2_技能页挂载', await vis('[data-testid="workdsh-skills"]'));
const tabs = await page.evaluate(() => [...document.querySelectorAll('.skill-source-tabs button')].map((b) => b.innerText.trim()));
log('2_技能来源页签', tabs);
// 点 SkillHub 页签，复现报错
const hubTab = page.locator('.skill-source-tabs button', { hasText: 'SkillHub' }).first();
if (await hubTab.isVisible({ timeout: 3000 }).catch(() => false)) {
  await hubTab.click().catch(() => {});
  await page.waitForTimeout(6000);
  const errText = await page.evaluate(() => {
    const el = [...document.querySelectorAll('[role="alert"],[class*="error"]')].find((e) => e.offsetParent !== null);
    return el ? (el.innerText ?? '').trim().slice(0, 200) : '';
  });
  log('2_点SkillHub后页面上的报错', errText || '（未捕获到可见报错文本）');
  log('2_SkillHub面板是否出现卡片', await page.evaluate(() => document.querySelectorAll('.skillhub-icon').length));
}

// ── 3. 插件页：社区插件市场入口 ───────────────────────────────────
await page.goto(`${BASE}/?workdsh-view=plugins`, { waitUntil: 'domcontentloaded', timeout: 120000 }).catch(() => {});
await page.waitForTimeout(9000);
log('3_插件页可见标签', await visibleLabels());

// ── 4. 专家·技能·连接器：连接器目录（二开） ────────────────────────
await page.goto(`${BASE}/?workdsh-view=experts`, { waitUntil: 'domcontentloaded', timeout: 120000 }).catch(() => {});
await page.waitForTimeout(9000);
log('4_专家连接器页可见标签', await visibleLabels());

// ── 5. 资料库 / 项目 ─────────────────────────────────────────────
for (const [name, view] of [['资料库', 'library'], ['项目', 'projects']]) {
  await page.goto(`${BASE}/?workdsh-view=${view}`, { waitUntil: 'domcontentloaded', timeout: 120000 }).catch(() => {});
  await page.waitForTimeout(8000);
  const labels = await visibleLabels();
  log(`5_${name}页可见标签`, labels.slice(0, 14));
}

log('9_pageerrors', pageerrors.slice(0, 5));
log('9_4xx请求去重', [...new Set(httpFail)].slice(0, 10));
await page.screenshot({ path: '/tmp/ui-audit-last.png', fullPage: false }).catch(() => {});
await browser.close();

