// ── D. 项目 ─────────────────────────────────────────────────────
log('D_点中「项目」', await openNav('项目'));
const projView = await settled();
log('D_项目正文', projView.slice(0, 400));

// ── E. 右栏页签（智能体浏览器？） ─────────────────────────────────
await page.goto(`${BASE}/`, { waitUntil: 'domcontentloaded', timeout: 120000 }).catch(() => {});
await settled();
const tabsR = await page.evaluate(() => {
  const ok = (el) => { const r = el.getBoundingClientRect(); return r.width > 0 && r.height > 0; };
  return [...new Set([...document.querySelectorAll('[role="tab"],[class*="tab"],[class*="Tab"]')]
    .filter(ok).map((el) => (el.innerText ?? '').trim().split('\n')[0]).filter((t) => t && t.length < 24))];
});
log('E_页签候选', tabsR);

// ── F. 会话文件的「打开方式」下拉（office 桥，二开） ─────────────────
log('F_正文里是否有打开方式', /打开方式/.test(await bodyText()));

log('Z_4xx去重', [...new Set(httpFail)].slice(0, 12));
await page.screenshot({ path: '/tmp/ui-audit2-last.png' }).catch(() => {});
await browser.close();

