// 第三遍：右栏「智能体浏览器」页签、终端面、连接器页签（二开）、技能市场按钮。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { readFileSync } from 'node:fs';

const TOKEN = readFileSync('/tmp/.plate-token', 'utf8').trim();
const BASE = 'http://127.0.0.1:18989';
const log = (k, v) => console.log(`RESULT ${k} = ${typeof v === 'string' ? v : JSON.stringify(v)}`);

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 900000 });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
const vis = (sel) => page.locator(sel).first().isVisible({ timeout: 2000 }).catch(() => false);
const bodyText = () => page.evaluate(() => document.body.innerText.replace(/\s+/g, ' ').trim());
async function settled(gap = 2500, budget = 90000) {
  const t0 = Date.now(); let prev = '';
  while (Date.now() - t0 < budget) {
    const cur = await bodyText();
    if (cur && cur === prev && cur.length > 40) return cur;
    prev = cur; await page.waitForTimeout(gap);
  }
  return prev;
}

await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await settled();

// ── 1. 打开一个会话，看右栏页签 ───────────────────────────────────
const sess = page.getByText('生成20字文档', { exact: true }).first();
log('1_点中会话', await sess.click({ timeout: 10000 }).then(() => true).catch(() => false));
await page.waitForTimeout(12000);
// 右栏可能收着，找展开控件
const expanders = await page.evaluate(() => [...document.querySelectorAll('button,[role="button"]')]
  .filter((e) => { const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0 && r.x > 1200; })
  .map((e) => ({ t: (e.innerText ?? '').trim().slice(0, 20), label: e.getAttribute('aria-label') ?? '', x: Math.round(e.getBoundingClientRect().x) })).slice(0, 25));
log('1_右半屏可点项', expanders);
log('1_正文是否含智能体浏览器', /智能体浏览器/.test(await bodyText()));
log('1_正文是否含等待智能体', /等待智能体打开网页/.test(await bodyText()));

// 尝试点右栏页签区（若有）
const tabEl = page.getByText('智能体浏览器', { exact: true }).first();
if (await tabEl.isVisible({ timeout: 3000 }).catch(() => false)) {
  await tabEl.click().catch(() => {});
  await page.waitForTimeout(6000);
  const t = await bodyText();
  log('1_点开后正文含等待智能体', /等待智能体打开网页/.test(t));
  log('1_点开后是否报错', /浏览器操作失败|无法读取浏览器画面/.test(t));
  log('1_片段', t.slice(0, 300));
} else {
  log('1_右栏未直接出现「智能体浏览器」文字', '（可能右栏默认收起或页签无文字）');
}

// ── 2. 终端面：左栏/右栏/设置 里找 ────────────────────────────────
const all = await bodyText();
log('2_当前正文含终端', /终端/.test(all));
// 设置页里的「终端」小节（第一遍在插件页见过）
await page.getByText('插件', { exact: true }).first().click().catch(() => {});
await settled();
const pv = await bodyText();
log('2_插件页含「终端」小节', /终端/.test(pv));
const termCtx = pv.match(/.{0,60}终端.{0,90}/);
log('2_终端上下文', termCtx ? termCtx[0] : '(无)');

