// 第六遍：每个页签用全新一次加载单独测，避免上一步切页签把后面的选择器带跑偏。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { readFileSync } from 'node:fs';

const TOKEN = readFileSync('/tmp/.plate-token', 'utf8').trim();
const BASE = 'http://127.0.0.1:18989';
const log = (k, v) => console.log(`RESULT ${k} = ${typeof v === 'string' ? v : JSON.stringify(v)}`);

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 900000 });
const bodyTextOf = (page) => page.evaluate(() => document.body.innerText.replace(/\s+/g, ' ').trim());
async function settled(page, gap = 2500, budget = 90000) {
  const t0 = Date.now(); let prev = '';
  while (Date.now() - t0 < budget) {
    const cur = await bodyTextOf(page);
    if (cur && cur === prev && cur.length > 40) return cur;
    prev = cur; await page.waitForTimeout(gap);
  }
  return prev;
}

async function openRightPane(tabName) {
  const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
  const errs = [];
  page.on('pageerror', (e) => errs.push(String(e).slice(0, 140)));
  await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
  await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
  await settled(page);
  await page.getByText('生成20字文档', { exact: true }).first().click().catch(() => {});
  await page.waitForTimeout(11000);
  await page.locator('[aria-label="打开右侧边栏"]').first().click({ timeout: 8000 }).catch(() => {});
  await page.waitForTimeout(9000);
  const el = page.getByText(tabName, { exact: true }).first();
  const visible = await el.isVisible({ timeout: 5000 }).catch(() => false);
  if (visible) { await el.click({ timeout: 8000 }).catch(() => {}); await page.waitForTimeout(11000); }
  // 右栏内文本（长文本优先，才是内容区）
  const rt = await page.evaluate(() => {
    const ok = (el) => { const r = el.getBoundingClientRect(); return r.width > 60 && r.height > 20 && r.x > 1150; };
    const cands = [...document.querySelectorAll('div,span,p,pre,textarea')].filter(ok)
      .map((e) => (e.innerText ?? '').trim()).filter((t) => t.length > 3);
    return cands.slice(0, 6);
  });
  return { visible, rt, errs };
}

for (const name of ['新建终端', '浏览器', '任务浏览器', '工作区文件']) {
  const r = await openRightPane(name);
  log(`${name}_页签可见`, r.visible);
  if (r.visible) {
    log(`${name}_右栏内容`, r.rt);
    log(`${name}_是否报错`, r.rt.some((t) => /失败|错误|无法|Error/.test(t)));
  }
  log(`${name}_pageerrors`, r.errs.slice(0, 3));
}
await browser.close();

