// 验收：技能页 → 点「SkillHub」页签 → 屏幕上真的出卡片（而不是那句 JSON 报错）。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { readFileSync } from 'node:fs';

const TOKEN = readFileSync('/tmp/.plate-token', 'utf8').trim();
const BASE = 'http://127.0.0.1:18989';
const log = (k, v) => console.log(`RESULT ${k} = ${typeof v === 'string' ? v : JSON.stringify(v)}`);

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 900000 });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
const errs = [];
page.on('pageerror', (e) => errs.push(String(e).slice(0, 180)));
const bodyText = () => page.evaluate(() => document.body.innerText.replace(/\s+/g, ' ').trim());
async function settled(gap = 2500, budget = 90000) {
  const t0 = Date.now(); let prev = '';
  while (Date.now() - t0 < budget) {
    const cur = await bodyText();
    if (cur && cur === prev && cur.length > 40) return cur;
    prev = cur; await page.waitForTimeout(gap);
  }
  return prev;
}

await page.goto(`${BASE}/?token=${TOKEN}`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await settled();

// 技能页
await page.getByText('专家 · 技能 · 连接器', { exact: true }).first().click({ timeout: 10000 }).catch(() => {});
await settled();
await page.getByText('技能', { exact: true }).first().click({ timeout: 8000 }).catch(() => {});
await page.waitForTimeout(6000);

const tabs = await page.evaluate(() => [...document.querySelectorAll('.skill-source-tabs button')].map((b) => b.innerText.trim()));
log('1_技能来源页签', tabs);

const hubTab = page.locator('.skill-source-tabs button', { hasText: 'SkillHub' }).first();
const visible = await hubTab.isVisible({ timeout: 6000 }).catch(() => false);
log('2_SkillHub页签可见', visible);
if (visible) await hubTab.click({ timeout: 8000 }).catch(() => {});
await page.waitForTimeout(14000);

const bt = await bodyText();
log('3_是否仍报JSON解析错', /Unexpected end of JSON input/.test(bt));
log('4_是否报服务不可用', /SkillHub 服务不可用/.test(bt));
const cards = await page.evaluate(() => document.querySelectorAll('.skillhub-icon').length);
log('5_SkillHub卡片数(.skillhub-icon)', cards);
const idx = bt.indexOf('SkillHub');
log('6_页面片段', bt.slice(Math.max(0, idx - 60), idx + 420));
log('7_pageerrors', errs.slice(0, 5));
await page.screenshot({ path: '/tmp/skillhub-verified.png' }).catch(() => {});
await browser.close();

