import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { readFileSync } from 'node:fs';

const BASE = 'http://127.0.0.1:18989';
const log = (k, v) => console.log(`RESULT ${k} = ${typeof v === 'string' ? v : JSON.stringify(v)}`);
const jarLine = readFileSync('/tmp/.plate-jar', 'utf8').split('\n').find((l) => l.includes('dsh-auth'));
const jp = jarLine ? jarLine.split('\t') : [];
const COOKIE = jp.length >= 7 ? { name: jp[5], value: jp[6], domain: '127.0.0.1', path: '/' } : null;

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 900000 });
const context = await browser.newContext({ viewport: { width: 1920, height: 1080 } });
if (COOKIE) await context.addCookies([COOKIE]);
const page = await context.newPage();
async function settled(gap = 2500, budget = 90000) {
  const t0 = Date.now(); let prev = '';
  while (Date.now() - t0 < budget) {
    const cur = await page.evaluate(() => document.body.innerText.replace(/\s+/g, ' ').trim());
    if (cur && cur === prev && cur.length > 40) return cur;
    prev = cur; await page.waitForTimeout(gap);
  }
  return prev;
}

await page.goto(`${BASE}/`, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
await settled();
await page.getByText('生成20字文档', { exact: true }).first().click({ timeout: 10000 }).catch(() => {});
await page.waitForTimeout(12000);
await page.locator('[aria-label="打开右侧边栏"]').first().click({ timeout: 8000 }).catch(() => {});
await page.waitForTimeout(8000);
await page.locator('[class*="_file"]').first().click({ timeout: 8000 }).catch(() => {});
await page.waitForTimeout(13000);
const btn = page.locator('.plate-open-in-plate').first();
if (await btn.isVisible({ timeout: 8000 }).catch(() => false)) await btn.click({ timeout: 8000 }).catch(() => {});
for (let i = 0; i < 40; i++) {
  if (await page.locator('.plate-editor-mode').first().isVisible({ timeout: 1500 }).catch(() => false)) break;
  await page.waitForTimeout(2000);
}
await page.waitForTimeout(6000);

const seg = await page.evaluate(() => {
  const el = document.querySelector('.plate-editor-mode');
  if (!el) return { found: false };
  const r = el.getBoundingClientRect();
  const s = getComputedStyle(el);
  return {
    found: true,
    visible: r.width > 0 && r.height > 0 && s.visibility !== 'hidden' && s.display !== 'none',
    rect: { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) },
    innerText: (el.innerText || '').replace(/\s+/g, ' ').trim(),
    ariaLabel: el.getAttribute('aria-label'),
    role: el.getAttribute('role'),
    buttons: [...el.querySelectorAll('button,[role="radio"],[role="tab"]')].map((b) => ({
      t: (b.innerText || '').trim(), aria: b.getAttribute('aria-checked') ?? b.getAttribute('aria-selected'), cls: (b.className || '').toString().slice(0, 40),
    })),
  };
});
