log('2_元素里有没有 PlateAI', JSON.stringify(seg).includes('PlateAI'));
log('3_元素里有没有 NexusAI', JSON.stringify(seg).includes('NexusAI'));
await page.screenshot({ path: '/tmp/segmented-verified.png' }).catch(() => {});
await browser.close();

