if (COOKIE) await context.addCookies([COOKIE]);
const page = await context.newPage();
async function settled(gap = 2500, budget = 90000) {
  const t0 = Date.now(); let prev = '';
  while (Date.now() - t0 < budget) {
    const cur = await page.evaluate(() => document.body.innerText.replace(/\s+/g, ' ').trim());
    if (cur && cur === prev && cur.length > 40) return cur;
