const root='/tmp/wd-verify/apps/web/';
for(const f of plan.features){
  const p=root+f.directory+'/package.json';
  const norm=require('path').resolve(p);
  console.log((fs.existsSync(norm)?'✅':'❌'), f.name.padEnd(28), f.directory, '→', norm);
}"

