input.command:
cd /tmp/wd-verify
echo "=== 修后复核（按 apps/web/ 解析）==="
node -e "
const fs=require('fs'),path=require('path');
const plan=JSON.parse(fs.readFileSync('/tmp/wd-verify/profiles/shared/workdsh-features.json','utf8'));
const root='/tmp/wd-verify/apps/web/';
let ok=0;
for(const f of plan.features){
  const p=path.resolve(root+f.directory+'/package.json');
  const good=fs.existsSync(p); if(good)ok++;
  console.log((good?'✅':'❌'), f.name.padEnd(28), '→', p.replace('/tmp/wd-verify/','<repo>/'));
}
console.log(\`\n\${ok}/\${plan.features.length} 通过\`);
"
echo
echo "=== 重跑 install-preview ==="
cd /tmp/wd-verify/apps/web
{ export WORKDSH_PREVIEW_HOME=/tmp/wd-verify/.test-runtime/preview
  export WORKDSH_PREVIEW_PACKS_HOME=/tmp/wd-verify-packs
  echo "=== $(date '+%H:%M:%S') ==="
  node scripts/install-preview.mjs; echo "INSTALLPREVIEW_RC=$?"
  echo "=== 结束 $(date '+%H:%M:%S') ==="
} > /tmp/verify-preview-install2.log 2>&1
echo "已结束"; grep -E 'RC=|===' /tmp/verify-preview-install2.log

cd /tmp/wd-verify
echo "=== 兄弟插件的 peerDependencies 版本 ==="
for m in office skills connectors experts library projects activity; do
  printf '%-12s ' "${m}"
  node -e "
    const p=require('/tmp/wd-verify/packages/plugins/${m}/package.json');
    const peers=p.peerDependencies||{};
    const dsh=Object.entries(peers).filter(([k])=>k.startsWith('@deepseek-ai/dsh'));
    const vers=[...new Set(dsh.map(([,v])=>v))];
    console.log(dsh.length? \`\${dsh.length} 条, 版本: \${vers.join('/')}\` : '(无 dsh peer)');
  " 2>/dev/null
done
echo
echo "=== plate 的 peer 版本（现状）==="
node -e "
  const p=require('/tmp/wd-verify/packages/plugins/plate/package.json');
  console.log([...new Set(Object.values(p.peerDependencies).filter(v=>typeof v==='string'))].join(', '));
  console.log('devDeps:', [...new Set(Object.entries(p.devDependencies).filter(([k])=>k.startsWith('@deepseek-ai/')).map(([,v])=>v))].join(', '));
"
echo
echo "=== 运行时版本（闸门基准）==="
node -e "console.log('apps/web overrides base:', require('/tmp/wd-verify/apps/web/package.json').pnpm.overrides['@deepseek-ai/dsh-base'])"
echo "profile 里 dsh 版本: $(node -e "console.log(require('/tmp/wd-verify/profiles/preview/node_modules/@deepseek-ai/dsh/package.json').version)" 2>/dev/null)"

cd /tmp/wd-verify/packages/plugins/plate
cp package.json /tmp/plate-pkg-before.json
node -e "
const fs=require('fs');
const f='package.json';
let s=fs.readFileSync(f,'utf8');
const before=s;
s=s.split('\"0.1.7-rc.2\"').join('\"0.2.0-rc.2\"');
s=s.split('\"0.1.7-alpha.2\"').join('\"0.2.0-rc.2\"');
if(s===before){console.log('❌ 没有任何替换发生——模式没匹配上，结论不可信');process.exit(1)}
fs.writeFileSync(f,s);
console.log('✅ 已替换');
"
echo
echo "=== 替换后核验 ==="
node -e "
const p=require('/tmp/wd-verify/packages/plugins/plate/package.json');
const peers=p.peerDependencies||{}, dev=p.devDependencies||{};
console.log('peer 版本集合:', [...new Set(Object.entries(peers).filter(([k])=>k.startsWith('@deepseek-ai/')).map(([,v])=>v))].join(', '));
console.log('dev  版本集合:', [...new Set(Object.entries(dev).filter(([k])=>k.startsWith('@deepseek-ai/')).map(([,v])=>v))].join(', '));
console.log('残留 0.1.7 次数:', (JSON.stringify(p).match(/0\.1\.7/g)||[]).length);
"
echo
echo "=== 改动行数（对照替换前）==="
diff <(node -e "console.log(JSON.stringify(require('/tmp/plate-pkg-before.json'),null,2))") <(node -e "console.log(JSON.stringify(require('/tmp/wd-verify/packages/plugins/plate/package.json'),null,2))") | grep -c '^[<>]'

