const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 900000 });
const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 } });
const page = await ctx.newPage();
const errs = [];
page.on('pageerror', (e) => errs.push(String(e).slice(0, 200)));
const bodyText = () => page.evaluate(() => document.body.innerText.replace(/\s+/g, ' ').trim());

await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 300000 }).catch(() => {});
await page.waitForTimeout(8000);

// 1) 新建会话
const before = (await bodyText()).length;
await page.getByText('新会话', { exact: false }).first().click({ timeout: 15000 }).catch(() => {});
await page.waitForTimeout(6000);
log('1_新会话后文本长度', (await bodyText()).length);
log('2_新会话前后有变化', (await bodyText()).length !== before);

// 2) 选工作区（若有下拉）
const ws = page.getByText('选择工作区', { exact: false }).first();
if (await ws.isVisible({ timeout: 5000 }).catch(() => false)) {
  await ws.click({ timeout: 8000 }).catch(() => {});
  await page.waitForTimeout(4000);
  const opts = await page.evaluate(() => [...document.querySelectorAll('[role="menuitem"],[role="option"],li')]
    .map((e) => (e.innerText || '').trim()).filter(Boolean).slice(0, 8));
  log('3_工作区选项', opts);
  if (opts.length) {
    await page.getByText(opts[0], { exact: false }).first().click({ timeout: 8000 }).catch(() => {});
    await page.waitForTimeout(5000);
  }
}

// 3) 发一条可判对错的活：要求产出确定内容
const PROMPT = '请只回复这一行，不要任何其他文字：交付校验-8241';
const box = page.locator('textarea, [contenteditable="true"]').first();
const boxOk = await box.isVisible({ timeout: 15000 }).catch(() => false);
log('4_输入框可见', boxOk);
if (boxOk) {
  await box.click({ timeout: 8000 }).catch(() => {});
  await box.fill(PROMPT).catch(async () => { await page.keyboard.type(PROMPT, { delay: 12 }); });
  await page.waitForTimeout(1500);
  await page.keyboard.press('Enter').catch(() => {});
}

// 4) 等 agent 真回话（最多 6 分钟）
let seen = false;
for (let i = 0; i < 72; i++) {
  const t = await bodyText().catch(() => '');
  if (t.includes('8241') && !t.includes(PROMPT.slice(0, 6) + '请')) { /* 仍是输入框内容则未回 */ }
  if (t.includes('交付校验-8241') && t.split('交付校验-8241').length > 2) { seen = true; break; }
  await page.waitForTimeout(5000);
}
const fin = await bodyText();
log('5_agent 回出目标串', seen);
log('6_目标串出现次数', (fin.match(/交付校验-8241/g) || []).length);
log('7_页面文本长度', fin.length);
log('8_文本尾 400', fin.slice(-400));
log('9_pageerrors', errs.slice(0, 5));
await page.screenshot({ path: '/tmp/e2e-task.png' }).catch(() => {});
await browser.close();

