page.on('response', (r) => {
  const u = r.url();
  if (u.includes('/api/') || u.includes('/plugins/')) reqs.push(`${r.status()} ${u.replace(BASE, '').slice(0, 100)}`);
});
const bodyText = () => page.evaluate(() => document.body.innerText.replace(/\s+/g, ' ').trim());
async function settled(gap = 2500, budget = 180000) {
  const t0 = Date.now(); let prev = '';
  while (Date.now() - t0 < budget) {
    const cur = await bodyText().catch(() => '');
    if (cur && cur === prev && cur.length > 40) return cur;
