// 交付级端到端：先确定性摸清「预览版说明」弹层的 DOM 与门闩，再跑任务级验产物。
// token 从文件读，绝不打印到 stdout。结果逐行增量落盘，防中途被杀丢证据。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { readFileSync, appendFileSync, writeFileSync } from 'node:fs';

const URL_FILE = '/tmp/.merged-url';
const OUT = '/tmp/e2e-full-out.txt';
writeFileSync(OUT, '');
const url = readFileSync(URL_FILE, 'utf8').trim();
const log = (k, v) => {
  const line = `RESULT ${k} = ${typeof v === 'string' ? v : JSON.stringify(v)}\n`;
  appendFileSync(OUT, line);
  console.log(line.trim());
};

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 900000 });
const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 } });
const page = await ctx.newPage();
const errs = [];
page.on('pageerror', (e) => errs.push(String(e).slice(0, 200)));
const bodyText = () => page.evaluate(() => document.body.innerText.replace(/\s+/g, ' ').trim());
const lsSnapshot = () => page.evaluate(() => {
  const o = {};
  for (let i = 0; i < localStorage.length; i++) { const k = localStorage.key(i); o[k] = String(localStorage.getItem(k)).slice(0, 120); }
  return o;
});

await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch((e) => log('A0_导航异常', String(e).slice(0, 120)));
await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 300000 }).catch(() => {});

// ---- 阶段 1：等弹层真出现（正的对照：必须先在）
const DIALOG = '[role="dialog"],[role="alertdialog"]';
const t0 = Date.now();
let appeared = false;
while (Date.now() - t0 < 150000) {
  const n = await page.locator(DIALOG).count().catch(() => 0);
  if (n > 0 && await page.locator(DIALOG).first().isVisible().catch(() => false)) { appeared = true; break; }
  const withText = await page.evaluate(() => document.body.innerText.includes('预览版说明'));
  if (withText) { appeared = true; break; }
  await page.waitForTimeout(2000);
}
log('A1_弹层出现(正对照)', appeared);
log('A2_出现耗时ms', Date.now() - t0);
log('A3_dialog节点数', await page.locator(DIALOG).count().catch(() => -1));

let dtext = '';
if (await page.locator(DIALOG).count().catch(() => 0)) {
  dtext = (await page.locator(DIALOG).first().innerText().catch(() => '')).replace(/\s+/g, ' ').trim();
}
if (!dtext) dtext = (await bodyText()).slice(0, 600);
log('A4_弹层文本', dtext.slice(0, 400));

const btns = await page.evaluate(() => [...document.querySelectorAll('button,[role="button"]')]
  .map((e) => ({ t: (e.innerText || '').trim().slice(0, 24), vis: !!(e.offsetWidth || e.offsetHeight), dis: e.disabled }))
  .filter((b) => b.t).slice(0, 25));
log('A5_可见按钮', btns);

const lsBefore = await lsSnapshot();
log('A6_localStorage键', Object.keys(lsBefore));

// ---- 阶段 2：点关闭，验「有→无」转变
let clicked = '';
const prior = ['继续', '我已知晓', '知道了', '我知道了', '确认', '开始使用', '关闭', '好的'];
const scope = (await page.locator(DIALOG).count().catch(() => 0)) ? page.locator(DIALOG).first() : page;
for (const t of prior) {
  const b = scope.getByRole('button', { name: t, exact: false }).first();
  if (await b.isVisible({ timeout: 1500 }).catch(() => false)) {
    await b.click({ timeout: 8000, force: true }).catch((e) => log('A7b_点击异常', String(e).slice(0, 80)));
    clicked = t; break;
  }
}
if (!clicked) {
  const cand = scope.locator('button:visible').last();
  if (await cand.isVisible({ timeout: 1500 }).catch(() => false)) {
    const txt = (await cand.innerText().catch(() => '')).trim();
    await cand.click({ timeout: 8000, force: true }).catch(() => {});
    clicked = `last:${txt}`;
  }
}
log('A7_点了哪个按钮', clicked);

let gone = false;
for (let i = 0; i < 15; i++) {
  await page.waitForTimeout(1000);
  const still = await page.evaluate(() => document.body.innerText.includes('预览版说明'));
  const nd = await page.locator(DIALOG).count().catch(() => 0);
  if (!still && nd === 0) { gone = true; break; }
}
log('A8_弹层已消失(负对照)', gone);
log('A9_关闭后body仍含预览版说明', (await bodyText()).includes('预览版说明'));

const lsAfter = await lsSnapshot();
const added = Object.keys(lsAfter).filter((k) => !(k in lsBefore));
const changed = Object.keys(lsAfter).filter((k) => k in lsBefore && lsAfter[k] !== lsBefore[k]);
log('A10_新增LS键', added);
log('A11_变化LS键', changed);
await page.screenshot({ path: '/tmp/e2e-full-after-dismiss.png' }).catch(() => {});
log('A12_pageerrors', errs.slice(0, 4));
await browser.close();

