// 交付级任务测试：前端发→后端算→前端渲，验「输出正确」而非「功能存在」。
// 关键控制：题面 8734 × 2917 不含答案 25477078，故页面出现该串只能是模型真算出来的。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { readFileSync, appendFileSync, writeFileSync } from 'node:fs';

const OUT = '/tmp/e2e-task2-out.txt';
writeFileSync(OUT, '');
const url = readFileSync('/tmp/.merged-url', 'utf8').trim();
const log = (k, v) => {
  const line = `RESULT ${k} = ${typeof v === 'string' ? v : JSON.stringify(v)}\n`;
  appendFileSync(OUT, line); console.log(line.trim());
};

const PROMPT = '计算 8734 乘以 2917 等于多少，只输出结果数字，不要任何其他文字';
const ANSWER = '25477078';
const BASE = 'http://127.0.0.1:18990';

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 900000 });
const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 } });
const page = await ctx.newPage();
const errs = [], reqs = [], fails = [];
page.on('pageerror', (e) => errs.push(String(e).slice(0, 200)));
page.on('response', (r) => { const u = r.url(); if (u.includes('/api/') || u.includes('/plugins/')) reqs.push(`${r.status()} ${u.replace(BASE, '').slice(0, 80)}`); });
page.on('requestfailed', (r) => fails.push(`${r.failure()?.errorText} ${r.url().replace(BASE, '').slice(0, 80)}`));
const bodyText = () => page.evaluate(() => document.body.innerText.replace(/\s+/g, ' ').trim());
const has = (t, s) => t.includes(s);

try {
  await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
  await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 300000 }).catch(() => {});

  // 关首跑弹层（正→负对照必成对）
  let seenDlg = false;
  for (let i = 0; i < 40; i++) {
    if (await page.evaluate(() => document.body.innerText.includes('预览版说明'))) { seenDlg = true; break; }
    await page.waitForTimeout(1500);
  }
  log('1_弹层出现', seenDlg);
  if (seenDlg) {
    await page.locator('[role="dialog"],[role="alertdialog"]').first()
      .getByRole('button', { name: '继续', exact: false }).first()
      .click({ timeout: 8000, force: true }).catch(() => {});
  }
  let gone = false;
  for (let i = 0; i < 15; i++) { await page.waitForTimeout(1000); if (!(await page.evaluate(() => document.body.innerText.includes('预览版说明')))) { gone = true; break; } }
  log('2_弹层已消失', gone);

  // 新建会话
  await page.getByText('新会话', { exact: false }).first().click({ timeout: 15000 }).catch(() => {});
  await page.waitForTimeout(5000);

  // 负对照：发之前页面不能已含答案
  const pre = await bodyText();
  log('3_发送前页面含答案(须false)', has(pre, ANSWER));
  log('4_发送前文本长度', pre.length);

  // 输入并发送
  const box = page.locator('textarea, [contenteditable="true"]').first();
  const boxOk = await box.isVisible({ timeout: 20000 }).catch(() => false);
  log('5_输入框可见', boxOk);
  if (!boxOk) { log('ABORT', 'no composer'); await browser.close(); process.exit(0); }
  await box.click({ timeout: 8000 }).catch(() => {});
  await box.fill(PROMPT).catch(async () => { await page.keyboard.type(PROMPT, { delay: 10 }); });
  await page.waitForTimeout(1200);
  const typed = await bodyText();
  log('6_题面已进输入框', has(typed, '8734'));
  log('7_输入框此刻含答案(须false)', has(typed, ANSWER));

  await page.keyboard.press('Enter').catch(() => {});
  await page.waitForTimeout(3000);
  let cleared = !(await page.evaluate(() => {
    const el = document.querySelector('textarea,[contenteditable="true"]');
    return el ? (el.value ?? el.innerText ?? '').includes('8734') : false;
  }));
  if (!cleared) {
    const send = page.locator('button[type="submit"], button[aria-label*="发送"], button[aria-label*="Send"]').first();
    if (await send.isVisible({ timeout: 3000 }).catch(() => false)) { await send.click({ timeout: 8000, force: true }).catch(() => {}); await page.waitForTimeout(3000); }
    cleared = !(await page.evaluate(() => { const el = document.querySelector('textarea,[contenteditable="true"]'); return el ? (el.value ?? el.innerText ?? '').includes('8734') : false; }));
  }
  log('8_消息已发出(输入框已清空)', cleared);

  // 等真答案
  let got = false, at = 0;
  const t0 = Date.now();
  for (let i = 0; i < 90; i++) {
    const t = await bodyText().catch(() => '');
    if (has(t, ANSWER)) { got = true; at = Date.now() - t0; break; }
    await page.waitForTimeout(4000);
  }
  const fin = await bodyText();
  log('9_后端真算出正确答案', got);
  log('10_答案出现耗时ms', at);
  log('11_答案出现次数', (fin.match(new RegExp(ANSWER, 'g')) || []).length);
  log('12_页面文本长度', fin.length);
  log('13_文本尾500', fin.slice(-500));
  log('14_LLM/插件请求数', reqs.length);
  log('15_请求样本', reqs.slice(-10));
  log('16_失败请求', fails.slice(0, 6));
  log('17_pageerrors', errs.slice(0, 5));
  await page.screenshot({ path: '/tmp/e2e-task2.png', fullPage: false }).catch(() => {});
} catch (e) {
  log('EXC', String(e).slice(0, 300));
}
await browser.close().catch(() => {});

