// 交付级：plate 编辑器在合并树里真能开出内容吗（不是「装上了」，是「渲染出正确内容」）。
// 若流程猜错，本探针的 dump 仍足以定位，不空跑一轮。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { readFileSync, appendFileSync, writeFileSync } from 'node:fs';

const OUT = '/tmp/e2e-plate-out.txt';
writeFileSync(OUT, '');
const url = readFileSync('/tmp/.merged-url', 'utf8').trim();
const log = (k, v) => {
  const line = `RESULT ${k} = ${typeof v === 'string' ? v : JSON.stringify(v)}\n`;
  appendFileSync(OUT, line); console.log(line.trim());
};
const BASE = 'http://127.0.0.1:18990';

const browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 900000 });
const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 } });
const page = await ctx.newPage();
const errs = [], reqs = [], fails = [];
page.on('pageerror', (e) => errs.push(String(e).slice(0, 200)));
page.on('response', (r) => { const u = r.url(); if (u.includes('/api/') || u.includes('/plugins/')) reqs.push(`${r.status()} ${u.replace(BASE, '').slice(0, 70)}`); });
page.on('requestfailed', (r) => fails.push(`${r.failure()?.errorText} ${r.url().replace(BASE, '').slice(0, 70)}`));
const bodyText = () => page.evaluate(() => document.body.innerText.replace(/\s+/g, ' ').trim());

try {
  await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
  await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 300000 }).catch(() => {});
  for (let i = 0; i < 40; i++) {
    if (await page.evaluate(() => document.body.innerText.includes('预览版说明'))) {
      await page.locator('[role="dialog"],[role="alertdialog"]').first()
        .getByRole('button', { name: '继续', exact: false }).first().click({ timeout: 8000, force: true }).catch(() => {});
      break;
    }
    await page.waitForTimeout(1200);
  }
  await page.waitForTimeout(2000);
  log('0_弹层残留', await page.evaluate(() => document.body.innerText.includes('预览版说明')));

  // 进「资料库」
  await page.getByText('资料库', { exact: true }).first().click({ timeout: 15000 }).catch((e) => log('1b_点击异常', String(e).slice(0, 80)));
  await page.waitForTimeout(7000);
  const libText = await bodyText();
  log('1_资料库视图文本', libText.slice(0, 700));
  log('2_资料库含plate迹象', /plate|Plate/i.test(libText));

  // 列出可点的文档条目
  const items = await page.evaluate(() => [...document.querySelectorAll('[role="listitem"],[role="option"],li,[data-testid]')]
    .map((e) => (e.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 60))
    .filter((t) => t && t.length > 1).slice(0, 25));
  log('3_可点条目', items);
  await page.screenshot({ path: '/tmp/e2e-plate-lib.png' }).catch(() => {});

  // 打开第一个像文档的条目
  const target = items.find((t) => /\.(docx|xlsx|pptx|plate|md|txt)|文档|报告/i.test(t)) || items[0];
  log('4_选中条目', target || '(none)');
  if (target) {
    await page.getByText(target.slice(0, 20), { exact: false }).first().click({ timeout: 10000 }).catch(() => {});
    await page.waitForTimeout(8000);
    const v = await bodyText();
    log('5_打开后视图文本', v.slice(0, 700));
    const ed = await page.evaluate(() => {
      const sels = ['[data-slate-editor="true"]', '.plate-editor', '[contenteditable="true"]', '[data-testid*="plate" i]'];
      const out = {};
      for (const s of sels) out[s] = document.querySelectorAll(s).length;
      return out;
    });
    log('6_编辑器节点计数', ed);
    const slateText = await page.evaluate(() => {
      const el = document.querySelector('[data-slate-editor="true"]');
      return el ? (el.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 300) : '';
    });
    log('7_正文内容', slateText);
    await page.screenshot({ path: '/tmp/e2e-plate-open.png' }).catch(() => {});
  }

  log('8_plate接口请求样本', reqs.filter((r) => r.includes('plate')).slice(0, 6));
  log('9_失败请求', fails.slice(0, 6));
  log('10_pageerrors', errs.slice(0, 5));
} catch (e) {
  log('EXC', String(e).slice(0, 300));
}
await browser.close().catch(() => {});

