  appendFileSync(OUT, line); console.log(line.trim());
};
const step = (s) => log('STEP', s);
const BASE = 'http://127.0.0.1:18990';
const MARK = '交付校验-5527';
const PROMPT = `请用 plate_open 打开一个标题为「交付校验」的文档，并往里写入这一行：${MARK}。写完只回「已写入」三个字。`;

let browser;
const errs = [], reqs = [], fails = [];
try {
  browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 900000 });
  const ctx = await browser.newContext({ viewport: { width: 1600, height: 1000 } });
  const page = await ctx.newPage();
  page.on('pageerror', (e) => errs.push(String(e).slice(0, 200)));
  page.on('requestfailed', (r) => fails.push(`${r.failure()?.errorText} ${r.url().replace(BASE, '').slice(0, 60)}`));
  page.on('response', (r) => { const u = r.url(); if (u.includes('/api/')) reqs.push(`${r.status()} ${u.replace(BASE, '').slice(0, 60)}`); });
  const bodyText = () => page.evaluate(() => document.body.innerText.replace(/\s+/g, ' ').trim());
  const editorText = () => page.evaluate(() => {
    const el = document.querySelector('[data-slate-editor="true"]') || document.querySelector('.plate-editor') || document.querySelector('[class*="slate-editor"]');
    return el ? (el.innerText || '').replace(/\s+/g, ' ').trim() : null;
  });

  await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
  await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
  for (let i = 0; i < 40; i++) {
    if (await page.evaluate(() => document.body.innerText.includes('预览版说明')).catch(() => false)) {
      await page.locator('[role="dialog"],[role="alertdialog"]').first()
        .getByRole('button', { name: '继续', exact: false }).first().click({ timeout: 8000, force: true }).catch(() => {});
      break;
    }
    await page.waitForTimeout(1200);
  }
  await page.waitForTimeout(2500);

  step('新会话');
  await page.getByText('新会话', { exact: false }).first().click({ timeout: 15000 }).catch(() => {});
  await page.waitForTimeout(6000);

  log('1_发送前编辑器串(须false)', (await editorText()) === null ? 'no-editor' : (await editorText()).includes(MARK));

  step('输入');
  const box = page.locator('textarea, [contenteditable="true"]').first();
  if (!(await box.isVisible({ timeout: 20000 }).catch(() => false))) throw new Error('no composer');
  await box.click({ timeout: 8000 }).catch(() => {});
  await box.fill(PROMPT).catch(async () => { await page.keyboard.type(PROMPT, { delay: 10 }); });
  await page.waitForTimeout(1200);
  step('发送');
  await page.keyboard.press('Enter').catch(() => {});
  await page.waitForTimeout(4000);

  step('等产物');
  let inEditor = false, at = 0;
  const t0 = Date.now();
  for (let i = 0; i < 100; i++) {
    const e = await editorText().catch(() => null);
    if (e && e.includes(MARK)) { inEditor = true; at = Date.now() - t0; break; }
    await page.waitForTimeout(4000);
  }
  const fin = await bodyText();
  const ed = await editorText();
  const nodes = await page.evaluate(() => ({
    slate: document.querySelectorAll('[data-slate-editor="true"]').length,
    plate: document.querySelectorAll('.plate-editor').length,
    slateAny: document.querySelectorAll('[class*="slate"]').length,
  }));
  log('2_编辑器里出现目标串', inEditor);
  log('3_耗时ms', at);
  log('4_编辑器正文', ed === null ? '(无编辑器)' : ed.slice(0, 300));
  log('5_编辑器节点计数', nodes);
  log('6_页面全串出现次数', (fin.match(new RegExp(MARK, 'g')) || []).length);
  log('7_AI已写入回执', fin.includes('已写入'));
  log('8_文本尾400', fin.slice(-400));
  log('9_plate请求', reqs.filter((r) => r.includes('plate')).slice(0, 8));
  await page.screenshot({ path: '/tmp/e2e-plate5.png' }).catch(() => {});
} catch (e) {
  log('EXC', String(e).slice(0, 250));
}
log('10_失败请求', fails.slice(0, 6));
log('11_pageerrors', errs.slice(0, 5));
try { await browser?.close(); } catch {}

