// 合并树交付级复验（前后端一起，验输出正确性）。
// 阶段1：LLM 全链路 —— 题面 6157×4839 不含答案 29793723，页面出现该串只可能是模型真算的。
// 阶段2：plate 活编辑器 —— agent plate_open/plate_edit，断言限定在编辑器 DOM 内（题面回显进不来）。
// token 只从文件读，绝不打印。每步先落盘再动作，崩了也有证据。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { readFileSync, appendFileSync, writeFileSync } from 'node:fs';

const OUT = '/tmp/e2e-merge2-out.txt';
writeFileSync(OUT, '');
const url = readFileSync('/tmp/.merged-url', 'utf8').trim();
const log = (k, v) => {
  const line = `RESULT ${k} = ${typeof v === 'string' ? v : JSON.stringify(v)}\n`;
  appendFileSync(OUT, line); console.log(line.trim());
};
const step = (s) => log('STEP', s);
const BASE = 'http://127.0.0.1:18990';

const PROMPT = '计算 6157 乘以 4839 等于多少，只输出结果数字，不要任何其他文字';
const ANSWER = '29793723';
const MARK = '合并复验-7741';
const PLATE_PROMPT = `请用 plate_open 打开一个标题为「合并复验」的文档，并往里写入这一行：${MARK}。写完只回「已写入」三个字。`;

let browser;
const errs = [], fails = [];
try {
  browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 900000 });
  const ctx = await browser.newContext({ viewport: { width: 1600, height: 1000 } });
  const page = await ctx.newPage();
  page.on('pageerror', (e) => errs.push(String(e).slice(0, 200)));
  page.on('requestfailed', (r) => fails.push(`${r.failure()?.errorText} ${r.url().replace(BASE, '').slice(0, 60)}`));
  const bodyText = () => page.evaluate(() => document.body.innerText.replace(/\s+/g, ' ').trim());
  const editorText = () => page.evaluate(() => {
    const el = document.querySelector('[data-slate-editor="true"]') || document.querySelector('.plate-editor') || document.querySelector('[class*="slate-editor"]');
    return el ? (el.innerText || '').replace(/\s+/g, ' ').trim() : null;
  });
  const has = (t, s) => t.includes(s);

  step('goto');
  await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch((e) => log('goto异常', String(e).slice(0, 100)));
  await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
  step('loadingCleared');

  // 首跑弹层（正→负对照成对）
  let seenDlg = false;
  for (let i = 0; i < 40; i++) {
    if (await page.evaluate(() => document.body.innerText.includes('预览版说明')).catch(() => false)) { seenDlg = true; break; }
    await page.waitForTimeout(1500);
  }
  log('0_弹层出现(正对照)', seenDlg);
  if (seenDlg) {
    await page.locator('[role="dialog"],[role="alertdialog"]').first()
      .getByRole('button', { name: '继续', exact: false }).first().click({ timeout: 8000, force: true }).catch(() => {});
  }
  let gone = false;
  for (let i = 0; i < 15; i++) { await page.waitForTimeout(1000); if (!(await page.evaluate(() => document.body.innerText.includes('预览版说明')).catch(() => true))) { gone = true; break; } }
  log('1_弹层已消失(负对照)', gone);
  await page.waitForTimeout(2500);

  // ================= 阶段 1: LLM =================
  step('P1 新会话');
  await page.getByText('新会话', { exact: false }).first().click({ timeout: 15000 }).catch(() => {});
  await page.waitForTimeout(6000);
  const pre = await bodyText();
  log('2_发送前页面含答案(须false)', has(pre, ANSWER));

  step('P1 输入');
  const box = page.locator('textarea, [contenteditable="true"]').first();
  if (!(await box.isVisible({ timeout: 20000 }).catch(() => false))) throw new Error('no composer');
  await box.click({ timeout: 8000 }).catch(() => {});
  await box.fill(PROMPT).catch(async () => { await page.keyboard.type(PROMPT, { delay: 10 }); });
  await page.waitForTimeout(1200);
  log('3_题面已进输入框', has(await bodyText(), '6157'));
  log('4_输入框此刻含答案(须false)', has(await bodyText(), ANSWER));
  step('P1 发送');
  await page.keyboard.press('Enter').catch(() => {});
  await page.waitForTimeout(4000);
  const cleared = !(await page.evaluate(() => { const el = document.querySelector('textarea,[contenteditable="true"]'); return el ? (el.value ?? el.innerText ?? '').includes('6157') : false; }));
  log('5_消息已发出(输入框已清空)', cleared);

  step('P1 等答案');
  let got = false, at = 0;
  const t1 = Date.now();
  for (let i = 0; i < 90; i++) {
    const t = await bodyText().catch(() => '');
    if (has(t, ANSWER)) { got = true; at = Date.now() - t1; break; }
    await page.waitForTimeout(4000);
  }
  const fin = await bodyText();
  log('6_后端真算出正确答案', got);
  log('7_答案耗时ms', at);
  log('8_答案出现次数', (fin.match(new RegExp(ANSWER, 'g')) || []).length);
  log('9_文本尾300', fin.slice(-300));
  await page.screenshot({ path: '/tmp/e2e-merge2-llm.png' }).catch(() => {});

  // ================= 阶段 2: plate =================
  step('P2 新会话');
  await page.getByText('新会话', { exact: false }).first().click({ timeout: 15000 }).catch(() => {});
  await page.waitForTimeout(6000);
  const edPre = await editorText().catch(() => null);
  log('10_发送前编辑器(须 null 或不含串)', edPre === null ? 'no-editor' : has(edPre, MARK));

  step('P2 输入');
  const box2 = page.locator('textarea, [contenteditable="true"]').first();
  if (await box2.isVisible({ timeout: 20000 }).catch(() => false)) {
    await box2.click({ timeout: 8000 }).catch(() => {});
    await box2.fill(PLATE_PROMPT).catch(async () => { await page.keyboard.type(PLATE_PROMPT, { delay: 10 }); });
    await page.waitForTimeout(1200);
    step('P2 发送');
    await page.keyboard.press('Enter').catch(() => {});
    await page.waitForTimeout(4000);

    step('P2 等产物');
    let inEditor = false, at2 = 0;
    const t2 = Date.now();
    for (let i = 0; i < 100; i++) {
      const e = await editorText().catch(() => null);
      if (e && has(e, MARK)) { inEditor = true; at2 = Date.now() - t2; break; }
      await page.waitForTimeout(4000);
    }
    log('11_编辑器里出现目标串', inEditor);
    log('12_耗时ms', at2);
    log('13_编辑器正文', (await editorText().catch(() => null)) ?? '(无编辑器)');
    log('14_编辑器节点', await page.evaluate(() => ({
      slate: document.querySelectorAll('[data-slate-editor="true"]').length,
      slateAny: document.querySelectorAll('[class*="slate"]').length,
    })));
    log('15_plate请求样本', await page.evaluate(() => 0) === 0 ? undefined : undefined);
    await page.screenshot({ path: '/tmp/e2e-merge2-plate.png' }).catch(() => {});
  } else {
    log('11_编辑器里出现目标串', false);
    log('13_编辑器正文', 'no-composer');
  }

  log('16_页面errors', errs.slice(0, 5));
} catch (e) {
  log('EXC', String(e).slice(0, 250));
}
log('17_失败请求', fails.slice(0, 6));
log('18_pageerrors总计', errs.length);
try { await browser?.close(); } catch {}

