  log('3_MCP连接器入口', has(bt, 'MCP连接器'));
  log('4_资料库入口', has(bt, '资料库'));
  log('5_专家技能连接器', has(bt, '专家') && has(bt, '技能'));
  log('6_余额/费用面板', /余额|费用明细/.test(bt));
  log('7_文本前300', bt.slice(0, 300));
  await page.screenshot({ path: '/tmp/e2e-deploy-home.png' }).catch(() => {});

  // LLM 真算
  step('新会话');
  await page.getByText('新会话', { exact: false }).first().click({ timeout: 15000 }).catch(() => {});
