  step('定位新会话按钮');
  const target = await page.evaluate(() => {
    const els = [...document.querySelectorAll('button,[role="button"],a,div')]
      .filter((e) => (e.innerText || '').replace(/\s+/g, '').startsWith('新会话'))
      .map((e) => { const r = e.getBoundingClientRect(); return { x: r.x, y: r.y, w: r.width, h: r.height, tag: e.tagName }; })
      .filter((b) => b.w > 60 && b.h > 20 && b.y < 200);
    return els.sort((a, b) => a.y - b.y)[0] || null;
  });
