  log('3_输入框可见', boxOk);
  if (!boxOk) throw new Error('no composer');
  await box.click({ timeout: 8000 }).catch(() => {});
  await box.fill(PROMPT).catch(async () => { await page.keyboard.type(PROMPT, { delay: 10 }); });
  await page.waitForTimeout(1500);
  log('4_题面已进输入框', (await bodyText()).includes('7391'));

  step('发送');
  await page.keyboard.press('Enter').catch(() => {});
  await page.waitForTimeout(3000);
  let still = await page.evaluate(composerText).catch(() => '');
  log('5_Enter后输入框是否仍留题面', still.includes('7391'));
  if (still.includes('7391')) {
    const send = page.locator('button[aria-label*="发送"], button[aria-label*="Send"], button[type="submit"]').last();
    if (await send.isVisible({ timeout: 4000 }).catch(() => false)) {
      await send.click({ timeout: 8000, force: true }).catch(() => {});
      log('6_已点发送按钮', true);
    } else { log('6_发送按钮未找到', true); }
    await page.waitForTimeout(4000);
    still = await page.evaluate(composerText).catch(() => '');
  }
  log('7_最终输入框为空(已发出)', !still.includes('7391'));

  step('等答案');
  let got = false, at = 0; const t1 = Date.now();
  for (let i = 0; i < 90; i++) {
    if ((await bodyText().catch(() => '')).includes(ANSWER)) { got = true; at = Date.now() - t1; break; }
    await page.waitForTimeout(4000);
  }
  log('8_后端真算出正确答案', got);
  log('9_耗时ms', at);
  log('10_答案出现次数', ((await bodyText()).match(new RegExp(ANSWER, 'g')) || []).length);
  log('11_文本尾300', (await bodyText()).slice(-300));
