import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { readFileSync, appendFileSync, writeFileSync } from 'node:fs';

const OUT = '/tmp/nav-survey-out.txt';
writeFileSync(OUT, '');
const url = readFileSync('/tmp/.nav-url', 'utf8').trim();
const log = (k, v) => {
  const line = `RESULT ${k} = ${typeof v === 'string' ? v : JSON.stringify(v)}\n`;
  appendFileSync(OUT, line); console.log(line.trim());
};

let browser;
try {
  browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 900000 });
  const ctx = await browser.newContext({ viewport: { width: 1600, height: 1000 } });
  const page = await ctx.newPage();
  const bodyText = () => page.evaluate(() => document.body.innerText.replace(/\s+/g, ' ').trim());
  // 主区 = 视口右侧大片区域
  const mainText = () => page.evaluate(() => {
    const el = [...document.querySelectorAll('main,[class*="content"],[class*="workspace"],[class*="page"]')]
      .map((e) => ({ e, r: e.getBoundingClientRect() }))
      .filter((x) => x.r.width > 600 && x.r.height > 300)
      .sort((a, b) => (b.r.width * b.r.height) - (a.r.width * a.r.height))[0];
    return el ? (el.e.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 420) : '(main 未定位)';
  });

  await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
  await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
  for (let i = 0; i < 24; i++) {
    if (await page.evaluate(() => document.body.innerText.includes('预览版说明')).catch(() => false)) {
      await page.locator('[role="dialog"],[role="alertdialog"]').first()
        .getByRole('button', { name: '继续', exact: false }).first().click({ timeout: 8000, force: true }).catch(() => {});
      break;
    }
    await page.waitForTimeout(1500);
  }
  await page.waitForTimeout(4000);
  log('0_侧栏全文本', (await bodyText()).slice(0, 260));

  const targets = [
    ['专家 · 技能 · 连接器', '专家'],
    ['MCP连接器', 'MCP连接器'],
    ['插件广场', '插件广场'],
  ];
  for (const [label, match] of targets) {
    const el = page.getByText(match, { exact: false }).first();
    const ok = await el.isVisible({ timeout: 6000 }).catch(() => false);
    if (!ok) { log(`面[${label}]`, '入口不可见'); continue; }
    await el.click({ timeout: 8000, force: true }).catch(() => {});
    await page.waitForTimeout(6000);
    log(`面[${label}]_主区`, await mainText());
    await page.screenshot({ path: `/tmp/nav-${match.replace(/[^\w一-龥]/g, '')}.png` }).catch(() => {});
  }

  // 设置 → 插件
  const set = page.getByText('设置', { exact: true }).first();
  if (await set.isVisible({ timeout: 6000 }).catch(() => false)) {
    await set.click({ timeout: 8000, force: true }).catch(() => {});
    await page.waitForTimeout(6000);
    log('面[设置]_主区', await mainText());
    const plug = page.getByText('插件', { exact: true }).first();
    if (await plug.isVisible({ timeout: 5000 }).catch(() => false)) {
      await plug.click({ timeout: 8000, force: true }).catch(() => {});
      await page.waitForTimeout(5000);
      log('面[设置→插件]_主区', await mainText());
    }
    await page.screenshot({ path: '/tmp/nav-settings.png' }).catch(() => {});
  }
} catch (e) {
  log('EXC', String(e).slice(0, 220));
}
try { await browser?.close(); } catch {}

