// 走应用自己的设置界面关掉「在侧边栏显示 MCP连接器」，然后刷新复核入口是否消失。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { readFileSync, appendFileSync, writeFileSync } from 'node:fs';

const OUT = '/tmp/hide-mcp-out.txt';
writeFileSync(OUT, '');
const url = readFileSync('/tmp/.nav-url', 'utf8').trim();
const log = (k, v) => {
  const line = `RESULT ${k} = ${typeof v === 'string' ? v : JSON.stringify(v)}\n`;
  appendFileSync(OUT, line); console.log(line.trim());
};
const step = (s) => log('STEP', s);

let browser;
try {
  browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 900000 });
  const ctx = await browser.newContext({ viewport: { width: 1600, height: 1000 } });
  const page = await ctx.newPage();
  const body = () => page.evaluate(() => document.body.innerText.replace(/\s+/g, ' ').trim());
  const sidebarHasMcp = () => page.evaluate(() => {
    // 只看左侧栏区域(x<280)
    return [...document.querySelectorAll('*')].some((e) => {
      const r = e.getBoundingClientRect();
      return r.x < 280 && r.width > 40 && r.height > 10 && (e.innerText || '').trim() === 'MCP连接器';
    });
  });

  await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
  await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
  for (let i = 0; i < 24; i++) {
    if (await page.evaluate(() => document.body.innerText.includes('预览版说明')).catch(() => false)) {
      await page.locator('[role="dialog"],[role="alertdialog"]').first()
        .getByRole('button', { name: '继续', exact: false }).first().click({ timeout: 8000, force: true }).catch(() => {});
      break;
    }
    await page.waitForTimeout(1500);
  }
  await page.waitForTimeout(4000);
  log('1_关之前侧栏有MCP连接器', await sidebarHasMcp());

  step('进设置');
  await page.getByText('设置', { exact: true }).first().click({ timeout: 10000, force: true }).catch(() => {});
  await page.waitForTimeout(7000);

  // 找开关文案，滚动到可见
  const label = page.getByText('在侧边栏显示 MCP连接器', { exact: false }).first();
  let found = await label.isVisible({ timeout: 8000 }).catch(() => false);
  if (!found) {
    // 逐屏滚动找
    for (let i = 0; i < 12; i++) {
      await page.mouse.wheel(0, 900);
      await page.waitForTimeout(900);
      if (await label.isVisible({ timeout: 1500 }).catch(() => false)) { found = true; break; }
    }
  }
  log('2_找到开关文案', found);
  if (!found) { log('3_设置页文本片段', (await body()).slice(0, 500)); throw new Error('toggle label not found'); }

  await label.scrollIntoViewIfNeeded().catch(() => {});
  await page.waitForTimeout(800);

  // 找该文案附近的开关控件
  const info = await page.evaluate(() => {
    const all = [...document.querySelectorAll('*')];
    const el = all.find((e) => (e.innerText || '').trim().includes('在侧边栏显示 MCP连接器'));
    if (!el) return null;
    const box = el.getBoundingClientRect();
    const cands = [...document.querySelectorAll('[role="switch"],input[type="checkbox"],button')]
      .map((c) => ({ c, r: c.getBoundingClientRect(), role: c.getAttribute('role') || c.tagName, checked: c.getAttribute('aria-checked') ?? c.checked ?? null }))
      .filter((x) => Math.abs((x.r.y + x.r.height / 2) - (box.y + box.height / 2)) < 60 && x.r.width > 0)
      .sort((a, b) => Math.abs(a.r.x - box.x) - Math.abs(b.r.x - box.x));
    return { labelY: Math.round(box.y), cands: cands.slice(0, 3).map((x) => ({ role: x.role, checked: x.checked, x: Math.round(x.r.x), y: Math.round(x.r.y), w: Math.round(x.r.width) })) };
  });
  log('3_候选控件', info);

  let clicked = false;
  if (info && info.cands.length) {
    const c = info.cands[0];
    await page.mouse.click(c.x + Math.min(c.w, 40) / 2, c.y + 8);
    clicked = true;
  }
  log('4_已点击开关', clicked);
  await page.waitForTimeout(6000);

  step('刷新复核');
  await page.reload({ waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
  await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
  await page.waitForTimeout(8000);
  for (let i = 0; i < 12; i++) {
    if (await page.evaluate(() => document.body.innerText.includes('预览版说明')).catch(() => false)) {
      await page.locator('[role="dialog"],[role="alertdialog"]').first()
        .getByRole('button', { name: '继续', exact: false }).first().click({ timeout: 8000, force: true }).catch(() => {});
      break;
    }
    await page.waitForTimeout(1500);
  }
  await page.waitForTimeout(5000);
  log('5_刷新后侧栏仍有MCP连接器', await sidebarHasMcp());
  log('6_侧栏文本', (await body()).slice(0, 200));
  await page.screenshot({ path: '/tmp/hide-mcp-after.png' }).catch(() => {});
} catch (e) {
  log('EXC', String(e).slice(0, 220));
}
