  await page.getByText('设置', { exact: true }).first().click({ timeout: 10000, force: true }).catch(() => {});
  await page.waitForTimeout(6000);

  for (const tab of ['通用设置', '模型', '内置插件', 'Agent 预设', '费用']) {
    const t = page.getByText(tab, { exact: true }).first();
    if (!(await t.isVisible({ timeout: 4000 }).catch(() => false))) { log(`页[${tab}]`, '不可见'); continue; }
    await t.click({ timeout: 8000, force: true }).catch(() => {});
    await page.waitForTimeout(6000);
    // 完整文本
    const full = await page.evaluate(() => document.body.innerText.replace(/\n+/g, ' | '));
