        const btns = [...document.querySelectorAll('button,[role="button"],li')]
          .filter((e) => /MCP/.test((e.innerText || '').slice(0, 60)));
        return btns.length;
      });
      log(`页[${tab}]_含MCP的可点元素数`, opened);
      const all = await page.evaluate(() => [...document.querySelectorAll('*')]
        .filter((e) => (e.innerText || '').trim().startsWith('MCP') && e.children.length <= 3)
        .map((e) => ({ t: (e.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 50), tag: e.tagName, x: Math.round(e.getBoundingClientRect().x) }))
        .slice(0, 8));
      log(`页[${tab}]_MCP元素`, all);
    }
  }
  await page.screenshot({ path: '/tmp/disc-settings.png' }).catch(() => {});
} catch (e) {
  log('EXC', String(e).slice(0, 200));
}
try { await browser?.close(); } catch {}

