// 为什么「项目」「专家·技能·连接器」是空的：逐页 dump + 记 API 响应与报错。
import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { readFileSync, appendFileSync, writeFileSync } from 'node:fs';

const OUT = '/tmp/why-empty-out.txt';
writeFileSync(OUT, '');
const url = readFileSync('/tmp/.chk-url', 'utf8').trim();
const log = (k, v) => {
  const line = `RESULT ${k} = ${typeof v === 'string' ? v : JSON.stringify(v)}\n`;
  appendFileSync(OUT, line); console.log(line.trim());
};

let browser;
try {
  browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 900000 });
  const ctx = await browser.newContext({ viewport: { width: 1600, height: 1000 } });
  const page = await ctx.newPage();
  const errs = [], fails = [], calls = [];
  page.on('pageerror', (e) => errs.push(String(e).slice(0, 220)));
  page.on('requestfailed', (r) => fails.push(`${r.failure()?.errorText} ${r.url().slice(-70)}`));
  page.on('response', async (r) => {
    const u = r.url();
    if (u.includes('/api/') && /expert|project|skill|connector|library/i.test(u)) {
      let b = ''; try { b = (await r.text()).slice(0, 260); } catch {}
      calls.push(`${r.status()} ${u.replace(/^https?:\/\/[^/]+/, '')} :: ${b.replace(/\s+/g, ' ')}`);
    }
  });
  const body = () => page.evaluate(() => document.body.innerText.replace(/\s+/g, ' ').trim());

  await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
  await page.waitForFunction(() => !document.body.innerText.includes('Loading plugins'), { timeout: 240000 }).catch(() => {});
  for (let i = 0; i < 20; i++) {
    if (await page.evaluate(() => document.body.innerText.includes('预览版说明')).catch(() => false)) {
      await page.locator('[role="dialog"],[role="alertdialog"]').first()
        .getByRole('button', { name: '继续', exact: false }).first().click({ timeout: 8000, force: true }).catch(() => {});
      break;
    }
    await page.waitForTimeout(1500);
  }
  await page.waitForTimeout(8000);

  // 按位置点左侧导航条目
  const clickNav = async (label) => {
    const box = await page.evaluate((t) => {
      const el = [...document.querySelectorAll('*')].find((e) => {
        const r = e.getBoundingClientRect();
        return r.x < 290 && r.width > 50 && r.height > 14 && r.height < 60 && (e.innerText || '').trim() === t;
      });
      if (!el) return null;
      const r = el.getBoundingClientRect();
      return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) };
    }, label);
    if (!box) return false;
    await page.mouse.click(box.x + box.w / 2, box.y + box.h / 2);
    await page.waitForTimeout(8000);
    return true;
  };

  for (const label of ['项目', '专家 · 技能 · 连接器', '资料库']) {
    const ok = await clickNav(label);
    log(`页[${label}]_点到`, ok);
    if (ok) {
      const t = await body();
      log(`页[${label}]_文本`, t.slice(0, 600));
      await page.screenshot({ path: `/tmp/why-empty-${label.replace(/[^\w一-龥]/g, '')}.png` }).catch(() => {});
    }
  }

  log('API调用数', calls.length);
  calls.slice(0, 10).forEach((c, i) => log(`api${i}`, c));
  log('失败请求', fails.slice(0, 6));
  log('页面错误', errs.slice(0, 6));
} catch (e) {
  log('EXC', String(e).slice(0, 200));
}
try { await browser?.close(); } catch {}

