  let ready = false;
  for (let i = 0; i < 90; i++) {
    const t = await body().catch(() => '');
    if (t.includes('资料库') && t.includes('项目')) { ready = true; break; }
    await page.waitForTimeout(5000);
  }
  log('0_侧栏就绪', ready);
  if (!ready) { log('0b_当前文本', (await body()).slice(0, 200)); throw new Error('sidebar not ready'); }
  for (let i = 0; i < 12; i++) {
    if ((await body()).includes('预览版说明')) {
      await page.locator('[role="dialog"],[role="alertdialog"]').first()
        .getByRole('button', { name: '继续', exact: false }).first().click({ timeout: 8000, force: true }).catch(() => {});
      break;
    }
    await page.waitForTimeout(1500);
  }
  await page.waitForTimeout(4000);

  const clickByLabel = async (label) => {
    const box = await page.evaluate((t) => {
      const seen = new Set(); let best = null;
      for (const e of document.querySelectorAll('*')) {
        const r = e.getBoundingClientRect();
        if (r.x > 300 || r.width < 30 || r.height < 10 || r.height > 60) continue;
        const s = (e.innerText || '').replace(/\s+/g, ' ').trim();
        if (s !== t || seen.has(s)) continue;
        seen.add(s);
        if (!best || r.y < best.y) best = { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) };
      }
      return best;
    }, label);
    if (!box) return null;
    await page.mouse.click(box.x + box.w / 2, box.y + box.h / 2);
    await page.waitForTimeout(9000);
    return box;
  };

  for (const label of ['项目', '专家 · 技能 · 连接器', '资料库']) {
    const b = await clickByLabel(label);
    log(`页[${label}]_点击坐标`, b || '(未找到)');
    if (b) {
      log(`页[${label}]_内容`, (await body()).slice(0, 700));
      await page.screenshot({ path: `/tmp/see-${label.replace(/[^\w一-龥]/g, '')}.png` }).catch(() => {});
    }
  }
  log('pageerrors', errs.slice(0, 5));
} catch (e) {
  log('EXC', String(e).slice(0, 200));
}
try { await browser?.close(); } catch {}

