// MCP stdio 握手自测：initialize → initialized → tools/list
import { spawn } from 'node:child_process';

const [cmd, ...args] = process.argv.slice(2);
const p = spawn(cmd, args, { stdio: ['pipe', 'pipe', 'pipe'] });

let buf = '';
const seen = [];
p.stdout.on('data', (d) => {
  buf += d.toString();
  let i;
  while ((i = buf.indexOf('\n')) >= 0) {
    const line = buf.slice(0, i).trim();
    buf = buf.slice(i + 1);
    if (!line) continue;
    try { seen.push(JSON.parse(line)); } catch { seen.push({ _raw: line.slice(0, 200) }); }
  }
});
let err = '';
p.stderr.on('data', (d) => { err += d.toString(); });

const send = (o) => p.stdin.write(JSON.stringify(o) + '\n');

send({ jsonrpc: '2.0', id: 1, method: 'initialize', params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'probe', version: '1' } } });
setTimeout(() => send({ jsonrpc: '2.0', method: 'notifications/initialized' }), 1500);
setTimeout(() => send({ jsonrpc: '2.0', id: 2, method: 'tools/list' }), 2500);

setTimeout(() => {
  const init = seen.find((m) => m.id === 1);
  const tools = seen.find((m) => m.id === 2);
  console.log('RESULT 1_initialize应答 =', init ? JSON.stringify({ serverInfo: init.result?.serverInfo, protocolVersion: init.result?.protocolVersion }) : '(无)');
  const list = tools?.result?.tools || [];
  console.log('RESULT 2_工具数 =', list.length);
  console.log('RESULT 3_工具名 =', JSON.stringify(list.map((t) => t.name)));
  console.log('RESULT 4_stderr前200 =', JSON.stringify(err.slice(0, 200)));
  p.kill('SIGKILL');
  process.exit(0);
}, 9000);

