  const m = t.match(/semantica[^。]{0,160}/i);
  log('5_semantica片段', m ? m[0] : '(无)');
  await page.screenshot({ path: '/tmp/verify-semantica.png' }).catch(() => {});
} catch (e) {
  log('EXC', String(e).slice(0, 200));
}
