import { chromium } from '/Users/apple/workdsh-mcp-servers/node_modules/playwright/index.mjs';
import { readFileSync, appendFileSync, writeFileSync } from 'node:fs';

const OUT = '/tmp/mcp-source-out.txt';
writeFileSync(OUT, '');
const url = readFileSync('/tmp/.sem-url', 'utf8').trim();
const log = (k, v) => {
  const line = `RESULT ${k} = ${typeof v === 'string' ? v : JSON.stringify(v)}\n`;
  appendFileSync(OUT, line); console.log(line.trim());
};

let browser;
try {
  browser = await chromium.launch({ channel: 'chrome', headless: true, timeout: 900000 });
  const ctx = await browser.newContext({ viewport: { width: 1600, height: 1000 } });
  const page = await ctx.newPage();
  const hits = [];
  page.on('response', async (r) => {
    const u = r.url();
    if (!u.includes('/api/')) return;
    try {
      const t = await r.text();
      if (t.includes('semantica') || t.includes('kp-library')) {
        hits.push({ u: u.replace(/^https?:\/\/[^/]+/, ''), hasSem: t.includes('semantica'), len: t.length,
                    semCtx: (() => { const i = t.indexOf('semantica'); return i < 0 ? '' : t.slice(Math.max(0, i - 220), i + 160).replace(/\s+/g, ' '); })() });
      }
    } catch {}
  });
  const body = () => page.evaluate(() => document.body.innerText.replace(/\s+/g, ' ').trim());

  await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 300000 }).catch(() => {});
  let ready = false;
  for (let i = 0; i < 90; i++) {
    const t = await body().catch(() => '');
    if (t.includes('资料库') && t.includes('项目')) { ready = true; break; }
    await page.waitForTimeout(5000);
  }
  log('0_加载', ready);
  for (let i = 0; i < 12; i++) {
    if ((await body()).includes('预览版说明')) {
      await page.locator('[role="dialog"],[role="alertdialog"]').first()
        .getByRole('button', { name: '继续', exact: false }).first().click({ timeout: 8000, force: true }).catch(() => {});
      break;
    }
    await page.waitForTimeout(1500);
  }
  await page.waitForTimeout(4000);

  const clickBy = async (label) => {
    const box = await page.evaluate((t) => {
      let best = null; const seen = new Set();
      for (const e of document.querySelectorAll('*')) {
        const r = e.getBoundingClientRect();
        if (r.width < 30 || r.height < 10 || r.height > 60) continue;
        const s = (e.innerText || '').replace(/\s+/g, ' ').trim();
        if (s !== t || seen.has(s)) continue;
        seen.add(s);
        if (!best || r.y < best.y) best = { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) };
      }
      return best;
    }, label);
    if (!box) return false;
    await page.mouse.click(box.x + box.w / 2, box.y + box.h / 2);
    await page.waitForTimeout(8000);
    return true;
  };
  await clickBy('专家 · 技能 · 连接器');
  await clickBy('连接器');
  await page.waitForTimeout(8000);

  log('1_命中接口数', hits.length);
  hits.slice(0, 6).forEach((h, i) => log(`1.${i}`, `${h.u} (len=${h.len}) 含semantica=${h.hasSem}`));
  const sem = hits.find((h) => h.hasSem);
  log('2_含semantica的接口', sem ? sem.u : '(没有)');
  if (sem) log('3_上下文', sem.semCtx.slice(0, 500));
} catch (e) {
  log('EXC', String(e).slice(0, 200));
}
try { await browser?.close(); } catch {}

